window.DEEP_STORIES["railways"] = {"slug":"railways","title":"Railways","emoji":"🚂","tagline":"From horse-drawn coal carts to trains that float on magnets","intro":"Imagine a world where the fastest way to travel over land was the speed of a galloping horse, and a trip across a country took weeks. Then, in about one human lifetime, iron rails and puffing steam engines changed everything. In these 20 parts you will ride the whole story: wooden wagonways in coal mines, Richard Trevithick's first steam locomotive, George and Robert Stephenson's famous Rocket, and the world's first proper intercity railway. You will learn exactly how a steam engine pushes a train and why wheels stay on the track. Then we cross continents on the transcontinental railroads, discover how trains invented time zones, plunge underground on the first subways, and switch to electric and diesel power. We will look honestly at accidents, hard labour and harm railways caused, before boarding bullet trains, floating maglevs and the trains of the future. All aboard!","outline":[{"n":1,"title":"Before the Rails","when":"Ancient times – 1500s"},{"n":2,"title":"Wooden Rails and Horse Power","when":"1600s – 1803"},{"n":3,"title":"Taming Steam","when":"1712 – around 1800"},{"n":4,"title":"Trevithick's Iron Horse","when":"1801 – 1808"},{"n":5,"title":"The Colliery Engines","when":"1812 – 1824"},{"n":6,"title":"Stockton & Darlington: A Railway for the Public","when":"1821 – 1830"},{"n":7,"title":"The Rainhill Trials and the Rocket","when":"October 1829"},{"n":8,"title":"The First Modern Railway","when":"1830 – 1840s"},{"n":9,"title":"Inside a Steam Locomotive","when":"How it works"},{"n":10,"title":"Rails, Wheels, Bridges and Tunnels","when":"How it works"},{"n":11,"title":"Rails Across America","when":"1827 – 1865"},{"n":12,"title":"Spanning Continents","when":"1863 – 1916"},{"n":13,"title":"How Trains Invented Time Zones","when":"1840 – 1918"},{"n":14,"title":"Danger, Brakes and Safety","when":"1830s – 1900s"},{"n":15,"title":"How Railways Changed Everyday Life","when":"1840s – 1930s"},{"n":16,"title":"Going Underground and Going Electric","when":"1863 – 1935"},{"n":17,"title":"Diesel Power and the End of Steam","when":"1890s – 1970s"},{"n":18,"title":"Bullet Trains","when":"1964 – today"},{"n":19,"title":"Maglev and the Trains of Tomorrow","when":"1934 – the future"},{"n":20,"title":"End of the Line? The Big Picture","when":"Then, now and next"}],"people":[["Georgius Agricola (1494–1555)","German scholar whose book De re metallica (1556) showed mine carts guided on planks"],["Huntingdon Beaumont (around 1560–1624)","English coal entrepreneur who built the Wollaton Wagonway around 1603–1604"],["Thomas Newcomen (1664–1729)","English inventor of the first practical steam engine (1712), used to pump mines"],["James Watt (1736–1819)","Scottish engineer whose separate condenser made steam engines much more efficient"],["Nicolas-Joseph Cugnot (1725–1804)","French engineer who built an early steam-powered road vehicle around 1769–1770"],["William Murdoch (1754–1839)","Scottish engineer who built a model steam carriage in the 1780s"],["Richard Trevithick (1771–1833)","Cornish engineer who built the first working railway steam locomotive (Penydarren, 1804)"],["Samuel Homfray (1762–1822)","Welsh ironmaster who backed Trevithick's Penydarren locomotive and made a bet on it"],["Matthew Murray (1765–1826)","Leeds engineer who built Salamanca (1812), the first commercially successful steam locomotive"],["John Blenkinsop (1783–1831)","mine manager who designed the rack-rail system used with Salamanca"],["William Hedley (1779–1843)","engineer of Puffing Billy at Wylam Colliery"],["Timothy Hackworth (1786–1850)","locomotive engineer; helped build Puffing Billy and built Sans Pareil for Rainhill"],["George Stephenson (1781–1848)","self-taught engineer, builder of Blücher and Locomotion, engineer of the Stockton & Darlington and Liverpool & Manchester railways; often called the 'Father of Railways'"],["Robert Stephenson (1803–1859)","George's son, chief designer of Rocket and a great railway and bridge engineer"],["Edward Pease (1767–1858)","Quaker businessman who financed the Stockton & Darlington Railway"],["Henry Booth (1788–1869)","Liverpool & Manchester Railway treasurer who suggested Rocket's multi-tube boiler"],["John Braithwaite (1797–1870) and John Ericsson (1803–1889)","builders of Novelty at the Rainhill Trials; Ericsson later designed the warship USS Monitor"],["William Huskisson (1770–1830)","British politician killed by Rocket on the Liverpool & Manchester's opening day"],["Isambard Kingdom Brunel (1806–1859)","engineer of the Great Western Railway with its broad gauge, bridges and tunnels"],["George Hudson (1800–1871)","the 'Railway King' of 1840s Railway Mania whose fraud led to his downfall"],["Peter Cooper (1791–1883)","American industrialist who built the Tom Thumb locomotive (1830)"],["Abraham Lincoln (1809–1865)","US President who signed the Pacific Railway Act in 1862"],["Theodore Judah (1826–1863)","engineer who planned the Central Pacific route over the Sierra Nevada"],["Leland Stanford (1824–1893)","Central Pacific president and one of its 'Big Four'; later founded Stanford University"],["Thomas C. Durant (1820–1885)","Union Pacific executive, later tied to the Crédit Mobilier scandal"],["Grenville Dodge (1831–1916)","Civil War general and chief engineer of the Union Pacific"],["Sandford Fleming (1827–1915)","Scottish-born Canadian railway engineer who championed worldwide standard time zones"],["George Westinghouse (1846–1914)","American inventor of the railway air brake"],["Eli Janney (1831–1912)","American inventor of the automatic knuckle coupler"],["George Pullman (1831–1897)","maker of luxury sleeping cars; his company town saw the Pullman Strike of 1894"],["A. Philip Randolph (1889–1979)","leader of the Brotherhood of Sleeping Car Porters and civil-rights activist"],["Thomas Cook (1808–1892)","English organiser of railway excursions and founder of a famous travel company"],["Werner von Siemens (1816–1892)","German inventor who showed an electric railway in Berlin in 1879"],["Frank J. Sprague (1857–1934)","American engineer of electric streetcars and multiple-unit train control"],["Rudolf Diesel (1858–1913)","German engineer who invented the diesel engine"],["Shinji Sogō (1884–1981)","president of Japanese National Railways who pushed through the first Shinkansen"],["Hideo Shima (1901–1998)","chief engineer of the first Shinkansen bullet train"],["Hermann Kemper (1892–1977)","German engineer who patented magnetic levitation for trains in 1934"],["Eric Laithwaite (1921–1997)","British engineer who developed the linear induction motor used in early maglev ideas"]],"glossary":[["wagonway","an early track of wooden (later iron) rails on which horses pulled wagons, mostly carrying coal"],["plateway","an early iron track made of L-shaped plates that guided plain wheels"],["locomotive","a vehicle with its own engine that pulls (or pushes) a train"],["gauge","the distance between the inner edges of the two rails; standard gauge is 4 ft 8½ in (1,435 mm)"],["flange","the raised lip on the inside edge of a train wheel that stops it slipping off the rail"],["boiler","the tank in a steam engine where water is heated into steam"],["firebox","the box where the fuel is burned in a steam locomotive"],["piston and cylinder","steam pushes a piston to and fro inside a cylinder, and rods turn this into wheels going round"],["blastpipe","a pipe that shoots used steam up the chimney, pulling air through the fire to make it burn hotter"],["tender","the wagon behind a steam locomotive that carries its coal and water"],["points (switches)","movable rails that steer a train from one track onto another"],["signal","a light or arm beside the track telling the driver whether it is safe to go"],["block system","a safety method that allows only one train in each section ('block') of track at a time"],["air brake","brakes worked by compressed air, which come on automatically if the train splits apart"],["standard time / time zone","a region where everyone uses the same clock time, instead of local Sun time"],["third rail / overhead line","ways of feeding electricity to an electric train, either from an extra rail or from wires above"],["pantograph","the folding arm on the roof of an electric train that touches the overhead wire"],["diesel-electric","a locomotive whose diesel engine powers a generator, which runs electric motors that turn the wheels"],["high-speed rail","trains running at about 250 km/h or more, usually on specially built tracks"],["maglev","short for 'magnetic levitation': a train lifted and pushed along by magnets instead of rolling on wheels"]],"parts":[{"n":1,"title":"Before the Rails","when":"Ancient times – 1500s","summary":"Long ago, moving heavy things over land was slow, muddy, tiring work for people and animals. Clever builders in ancient Greece cut grooves into a stone road to drag ships across land, and German miners pushed carts along wooden planks. These were the first baby steps toward the railway!","sections":[{"heading":"A World at Walking Speed","paragraphs":["Close your eyes and imagine you live five hundred years ago. You want to visit a town 50 kilometres away. There is no train, no bus, no car and no bicycle. You can walk, which takes all day and leaves your feet aching. If your family is rich, you might ride a horse. Either way, the fastest you can possibly travel over land is the speed of a galloping horse, and no horse can gallop for long. For almost all of human history, that was simply how the world worked.","Moving people was hard. Moving heavy things was much harder. For thousands of years, goods went from place to place in three main ways: on the backs of people, on the backs of animals, or in carts and wagons pulled by animals. Where there was a river or a coast, a fourth way was available, and it was often the best one: put the load in a boat and let the water carry the weight.","In Britain, a common way to move goods across hilly country was the packhorse train. A line of sturdy ponies, often 12 to 20 of them and sometimes as many as 40, walked nose to tail along narrow tracks. Each pony carried two baskets or bags called panniers, slung on either side of its back, holding about 110 kilograms in total. The lead pony often wore a bell so that anyone coming the other way would hear the train approaching and get out of the way. A good packhorse train covered about 40 kilometres a day.","Some packhorse routes were astonishingly busy. Records from northern England describe 200 to 300 loaded horses a day crossing one river ford in the 1630s, and about a thousand packhorses a day passing through the town of Clitheroe before 1750. You can still walk over old packhorse bridges in the English countryside today. They are narrow stone arches with low walls, just wide enough for a pony with bulging panniers, because nobody expected a wagon to use them.","Why not just use wagons? Because the roads were terrible. Most roads were not built at all; they were simply paths that people and animals had walked along for centuries. In dry summer weather they were bumpy and dusty. In wet weather they turned into deep, sticky mud. Heavy wheels sank in, and every passing wagon churned the mud deeper. Deep grooves called ruts formed where the wheels always ran, and in winter some roads became completely impossible for wheeled vehicles. A wagon stuck axle-deep in mud could take a whole team of horses and several men to haul out.","So whenever they could, people used water. A single boat floating on a river could carry many tons, and the water did the hard work of holding up the weight. That is why so many old towns grew up beside rivers and harbours. But rivers only go where rivers go. If your load was somewhere inland, far from water, you were stuck with the slow, muddy, expensive road."]},{"heading":"The Problem of Heavy Things","paragraphs":["Some loads are light but valuable, like spices, silk, letters or gold coins. It is worth paying a lot to move a small bag of pepper, because the pepper sells for a high price. Other loads are heavy but cheap: coal, stone, bricks, timber, grain, iron ore and lime for farmers' fields. A ton of coal was not worth very much at the mine. If it cost more to haul it a few kilometres than the coal itself was worth, then nobody would bother.","Think about what that meant for a coal mine. Coal could keep homes warm and fuel forges and furnaces, but it is extremely heavy. A family might burn several tons in a winter. A packhorse carrying about 110 kilograms would need around nine trips just to move one ton. Even a horse pulling a cart on a dry road could only manage a load of perhaps a ton or so, and on a wet, rutted road far less. Each trip needed the horse, its food, a driver, and time. All of that cost money, and the price of coal rose quickly the farther it travelled from the pit.","This was true of building stone, too. Great cathedrals and castles were often built close to quarries, or close to rivers that could float the stone to the building site. Farmers who wanted to sell grain in a distant city faced the same problem: the journey ate up the profit. In a very real way, the speed and cost of moving heavy things decided where towns grew, which industries could exist, and how big a business could become.","Here is the key point, which you will meet again and again in this story. The problem was not really the weight itself. The problem was the friction and the mud. A wheel that sinks into soft ground is always trying to climb out of a little hole that it has made in front of itself. A wheel bumping over stones wastes energy with every jolt. Take away the mud and the bumps, and the very same horse can suddenly pull a far heavier load. People had noticed this for thousands of years. The question was how to build a surface that stayed hard, smooth and in the right place."]},{"heading":"The Diolkos: Dragging Ships Across Greece","paragraphs":["One of the earliest and most impressive answers comes from ancient Greece. Look at a map of Greece and you will see a big chunk of land in the south, the Peloponnese, joined to the mainland by a narrow neck of land called the Isthmus of Corinth. At its narrowest point the isthmus is only about 6 kilometres wide. On one side is the Gulf of Corinth, leading west toward Italy. On the other side is the Saronic Gulf, leading east toward Athens and the Aegean Sea.","For a sailor, going all the way around the Peloponnese by sea meant a voyage of hundreds of kilometres, including the rocky and stormy capes at the southern tip, which had a fearsome reputation for wrecking ships. Wouldn't it be wonderful if you could simply take your ship, or at least its cargo, straight across the narrow neck of land?","Around 600 BCE, the people of Corinth did exactly that. They built the Diolkos, a name that roughly means 'haul-across'. It was a paved road made of hard limestone blocks that ran from one sea to the other, about 6 to 8.5 kilometres long depending on how its bends are measured. Archaeologists think it was built in the late 7th or early 6th century BCE, around the time when a ruler named Periander governed Corinth. The road was between about 3.4 and 6 metres wide.","The clever part was cut into the stone itself. Along long stretches of the Diolkos run two parallel grooves, about 1.6 metres apart. The wheels of a heavy wooden vehicle fitted into these grooves, which kept the vehicle on course, rather like a toy train running in the slots of a wooden track. The haulers did not have to steer. They just had to pull. Some researchers think parts of the grooves were deliberately cut, while others think some sections were simply worn down by centuries of wheels. Either way, the result was a guided path for heavy loads.","How was a ship moved? Historians cannot be completely sure, because no ancient writer left a detailed instruction manual. The most likely idea is that a ship, or its cargo, was lifted onto a wheeled cart or cradle at one end and then hauled across by teams of men, and perhaps by animals, using ropes. Machines called capstans, a kind of winch turned by people pushing on bars, may also have helped. The route had to climb over a ridge about 79 metres high, but its slope was gentle, averaging only about 1.4 percent, meaning it rose about 1.4 metres for every 100 metres travelled. The steepest parts were around 6 percent.","Most of the time the Diolkos probably carried cargo and smaller boats. But ancient writers describe warships being dragged across too. The Athenian historian Thucydides wrote that the Spartans prepared to haul ships across the isthmus in 428 BCE, and again in 411 BCE. Much later, in 220 BCE, a commander named Demetrius of Pharos is said to have taken about 50 vessels across. A modern engineering study estimated that a trireme, a long warship about 35 metres long with three banks of oars, might have weighed about 25 tonnes and needed well over a hundred people pulling hard to cross. It could be done, but it was a struggle.","The Diolkos stayed in use for a very long time, from around 600 BCE until at least the middle of the 1st century CE, more than 600 years. The ancient playwright Aristophanes even made a joke about something moving 'as fast as a Corinthian', a sign that the trackway was famous across Greece. The Roman emperor Nero later tried to dig a proper canal across the isthmus in 67 CE, but the project was abandoned.","The ship canal finally arrived in modern times: the Corinth Canal opened in 1893, running right beside the remains of the old trackway. Greek archaeologist Nikolaos Verdelis excavated the Diolkos between 1956 and 1962 and uncovered a nearly continuous stretch about 800 metres long. Sadly, the wash from passing ships has since eroded parts of it, and repair work to protect the site was carried out as recently as 2024.","Was the Diolkos a railway? Not in the modern sense. It had no rails of metal or wood, no engines, and it was a single special route rather than a network. But it shared the most important idea of all railways: a hard, fixed, guided path that makes it much easier to move a heavy load and keeps it going where you want it to go. It is one of the earliest known 'guided ways' in history."]},{"heading":"Ruts, Grooves and the Science of a Smooth Path","paragraphs":["The Diolkos was special, but grooves in the ground were not unusual in the ancient world. Wherever heavy carts travelled the same route year after year, their wheels wore tracks into the road. Walk down a street in the Roman town of Pompeii, buried by the eruption of Mount Vesuvius in 79 CE, and you can still see deep ruts worn into the big paving stones by countless cart wheels. Once ruts like these exist, they act a little like rails: a cart drops into them and tends to follow them.","On the Mediterranean island of Malta there are even stranger tracks. Pairs of parallel grooves are cut into bare rock across the countryside, sometimes crossing and branching so much that one site has been nicknamed 'Clapham Junction', after a famously busy railway junction in London. Nobody is completely sure who made them, when, or exactly how. Archaeologists still argue about whether they were worn by carts, sledges or something else, and estimates of their age vary widely. They are a good reminder that history is full of real puzzles that have not been solved yet.","Paved trackways were also built in Roman Egypt, and Roman engineers were famous for their well-built roads. A good Roman road had layers of stone and gravel underneath and a hard, cambered surface on top, so rainwater ran off instead of turning it to mud. That was the same idea from another direction: if you cannot build a groove, at least build a surface that stays hard and dry.","Why does a hard, smooth, fixed path help so much? Let's do a quick experiment in your head. Push a toy car across a thick, fluffy carpet. It slows down and stops almost at once. Now push it across a smooth wooden floor. It rolls a long way. The car and your push are exactly the same. What changed is the surface. On the carpet, the wheels squash down into the fibres and have to keep climbing over them. On the hard floor there is almost nothing in the way.","Scientists call this rolling resistance. Whenever a wheel rolls, both the wheel and the surface underneath it squash a tiny bit. The softer they are, the more they squash, and the more energy is wasted. Mud is the worst of all: a heavy wheel sinks in and is always pushing a little wall of mud in front of it. Stones and potholes are bad too, because every bump lifts the load slightly and then drops it, wasting effort and shaking the cart to pieces.","A smooth, hard track solves both problems at once. The wheels barely sink in, and there are no bumps to climb. A guided track, with grooves or raised edges, adds a third bonus: the vehicle cannot wander off sideways, so it can be pulled without anyone steering, and it always runs on the strong part of the track instead of the soft verge. Keep those three ideas in mind, hard, smooth and guided, because they are the secret recipe of every railway that came afterwards, right up to today's high-speed trains."]},{"heading":"Dogs in the Mines: Agricola's Wooden Tracks","paragraphs":["Now let's jump forward about two thousand years, to the busy mining towns of central Europe in the 1500s. In the mountains along the border of what are now Germany and the Czech Republic, miners dug deep tunnels to reach silver, copper, tin and lead. Silver from these mines was so important that a coin minted in the town of Joachimsthal (today Jáchymov in the Czech Republic) was called the Joachimsthaler, later shortened to 'thaler'. That name travelled around the world and eventually turned into the word 'dollar'.","Underground, miners had a big problem: how to move broken rock and ore along narrow, dark, uneven tunnels. Their solution was a small wooden wagon on four wheels, pushed by a person. To stop it from getting stuck or veering into the tunnel walls, they laid two wooden planks along the floor with a narrow gap between them. A peg, or guide pin, sticking down from the bottom of the wagon slid along in the gap, keeping the wagon on course. The wheels themselves were plain, with no rims to grip the planks. The guide pin did all the steering.","German miners called these wagons 'Hunde', meaning 'dogs'. One common explanation is that the rumbling, squeaking noise they made as they rattled along the planks sounded like a dog barking or growling. Whether or not that is the true reason, the nickname stuck, and mine wagons in parts of Europe were called 'dogs' for centuries.","We know about these carts mainly thanks to one remarkable man. Georg Bauer was born in 1494 in Saxony, in eastern Germany. Like many scholars of his time, he wrote in Latin and used a Latin version of his name: Georgius Agricola. Bauer means 'farmer' in German, and agricola means 'farmer' in Latin. He trained as a doctor and worked as a town physician, first in Joachimsthal and later in the mining city of Chemnitz. But he was fascinated by the mines around him. He spent years watching miners at work, asking questions and studying their tools and machines.","The result was a huge book called De re metallica, Latin for 'On the Nature of Metals'. It covered everything about mining and metal-making at the time: how to find ore, how to dig and survey tunnels, how to pump water out of mines, how to lift ore to the surface, how to wash, roast and smelt it, and much more. It was divided into twelve parts called books and filled with about 292 detailed woodcut pictures. Agricola died in 1555, and the book was finally published in Basel, Switzerland, in 1556, a year after his death. Making all those woodcuts had taken a long time.","Among its pictures is a famous image of a Hund: a small, boxy wooden wagon on planks, with the pin underneath that kept it on track. It is one of the earliest clear drawings of a wagon running on a prepared track. The book also shows enormous wooden machines driven by water wheels and by horses walking in circles, used to pump water and to lift loads out of deep shafts. These were some of the most advanced machines in the world at that time.","De re metallica was so useful that it stayed the most important book about mining in Europe for about 180 years. It was translated into German in 1557, Italian in 1563 and Spanish in 1569. The first English translation did not appear until 1912, and it was made by a husband-and-wife team, the mining engineer Herbert Hoover and the geologist Lou Henry Hoover. Herbert Hoover later became the 31st President of the United States."]},{"heading":"Tracks Begin to Spread","paragraphs":["The mines of central Europe were not the only places experimenting with tracks. High above the Austrian city of Salzburg stands Hohensalzburg Fortress, one of the largest medieval castles in Europe. To get supplies up the steep hill, its builders made a little goods line called the Reisszug. It was described in writing in 1515 by Matthäus Lang, a churchman who later became archbishop and ruler of Salzburg, though it may be even older. It used wooden rails, and its wagon was hauled up the slope by a rope made of hemp. The power came from people or animals turning a treadwheel, a large wheel that you walk inside, like a giant hamster wheel.","Amazingly, the Reisszug still exists. It is about 190 metres long and still carries goods up to the fortress, although today it has steel rails, a steel cable and an electric motor instead of wooden rails, hemp and treadwheel power. Human or animal power was used until 1910. Because of its long history, some people describe it as perhaps the oldest railway still operating in the world.","Mining know-how travelled with miners. In the 1560s, German miners were invited to work copper and lead mines in the Lake District, in north-west England, and they brought their skills with them, very likely including wheeled tubs on wooden tracks. Tracked transport at Caldbeck in Cumbria, perhaps from the 1560s, is thought to be among the earliest in Britain.","Notice something important about all these early tracks. They were short, they were mostly underground or on private land, and they were pushed by people or pulled by ropes or animals. Nobody yet imagined a track running for kilometres across open fields. And nobody imagined an engine. Engines powerful enough to move themselves were still more than two centuries in the future. But the basic idea, wheels guided along a smooth prepared path, was spreading, and in Britain it was about to meet the perfect customer: coal."]},{"heading":"The Big Idea That Runs Through This Whole Story","paragraphs":["Let's pause and look at what we have learned, because it is the key to everything that follows in all twenty parts of this story.","On a rough road, a horse struggles to pull even a modest load, because so much of its effort is wasted fighting mud, bumps and friction. Put that same horse on a hard, smooth, guided track, and the wasted effort drops dramatically. On a good track, one horse can pull many times more weight than it could on a dirt road. You will see real numbers for this in the next part, when horses begin hauling coal wagons on wooden rails in England.","That one simple fact changed the economics of heavy goods. If one horse can do the work of many, then coal, stone and iron become cheaper to move. Cheaper coal means warmer homes and more fuel for furnaces and workshops. More furnaces mean more iron. More iron means better tools and machines. Step by step, the humble track helped push forward the huge changes that historians call the Industrial Revolution.","And here is the part that will matter most later on. A smooth track does not only help horses. It helps anything that pulls. When inventors finally built engines that could move by themselves, those engines were heavy and not very powerful at first. On a muddy road they would have sunk and stalled. On a track, they could pull. The railway engine and the rail were made for each other. Without the track, the steam locomotive might never have succeeded at all.","So the railway was not invented in one flash by one genius. It grew slowly, over many centuries, from ruts in roads, grooves in stone, planks in mine tunnels and ropes on castle hills. Each idea was small. Put together, they would one day carry billions of people around the world.","Our next stop is England in the early 1600s. Coal was becoming more and more valuable as forests were cut down and wood grew scarce. In the coalfields of the English Midlands and the north-east, mine owners were looking for a better way to get their heavy black fuel from the pit to the river. And for the first time, miners were about to lay wooden rails above ground, out in the open air, stretching across the fields."]}],"deepDive":"What counts as the 'first railway'? It depends entirely on your definition, and historians use several. If a railway is any prepared path that guides wheels, then the Diolkos of Corinth, built around 600 BCE, is a strong candidate, along with grooved roads in other parts of the ancient world. If it must have rails, separate strips that the wheels run on, then the wooden planks of central European mines in the 1500s, shown in Agricola's De re metallica (1556), qualify, as does the rope-hauled Reisszug in Salzburg, first described in 1515. If it must run overland and carry goods for trade, the English wagonways of the early 1600s come next. If it must use engines, we have to wait until 1804. None of these answers is wrong; they simply answer different questions. The Diolkos itself is surrounded by debate. Its length is given as anything from about 6 to 8.5 kilometres because parts of the route have been lost and scholars disagree about its bends. The grooves, roughly 1.6 metres apart, look like a deliberate guide on some stretches, but some researchers argue the western grooves are simply wear from centuries of wheels. Nobody knows exactly how ships were mounted on the vehicles, how often warships really crossed, or whether animals helped. Engineering estimates for hauling a 25-tonne trireme range from over a hundred people to a smaller team using capstans, and the experts disagree. The excavator, Nikolaos Verdelis, died before he could fully publish his 1956–1962 findings, which is one reason these questions remain open. The physics, however, is not in doubt. A wheel's rolling resistance depends heavily on how much the wheel and surface deform. Soft ground deforms a lot, so a horse on mud spends most of its effort on squashing and climbing. Stone, wood and later iron deform very little. Add a guide that prevents sideways drift, and a vehicle can carry far more weight for the same pulling force. That principle, minimal deformation plus guidance, is the thread that connects ancient grooves to modern steel rails.","funFact":"The first English translation of Agricola's great mining book De re metallica was published in 1912 by Herbert Hoover and his wife Lou Henry Hoover, years before he became President of the United States.","check":{"q":"About when did the people of Corinth build the Diolkos, the stone trackway used to haul ships and cargo across the Isthmus of Corinth?","a":"Around 600 BCE","wrong":["Around 1556 CE","Around 79 CE","Around 1893 CE"]},"sources":[{"title":"Diolkos","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Diolkos"},{"title":"De re metallica","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/De_re_metallica"},{"title":"De Re Metallica, translated by Herbert Clark Hoover and Lou Henry Hoover","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/38015"},{"title":"History of rail transport","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_rail_transport"},{"title":"Reisszug","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Reisszug"},{"title":"Packhorse","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Packhorse"},{"title":"Wagonway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wagonway"},{"title":"Georgius Agricola","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Georgius_Agricola"}],"photos":[{"src":"img/deep/railways/01-1.jpg","alt":"The stone-paved Diolkos trackway in Greece, about 2,600 years old, running down toward the Corinth Canal.","file":"The excavated Ancient Diolkos on the Isthmus of Corinth on 22 May 2019.jpg","url":"https://commons.wikimedia.org/wiki/File:The_excavated_Ancient_Diolkos_on_the_Isthmus_of_Corinth_on_22_May_2019.jpg","author":"George E. Koronaios","license":"CC0"},{"src":"img/deep/railways/01-2.jpg","alt":"Woodcut from Agricola's De re metallica (1556): a wooden 'Hund' mine wagon, with a guide pin to run between wooden planks.","file":"De re metallica - mine wagon (125711434).jpg","url":"https://commons.wikimedia.org/wiki/File:De_re_metallica_-_mine_wagon_(125711434).jpg","author":"Georg Agricola","license":"Public domain"},{"src":"img/deep/railways/01-3.jpg","alt":"Hohensalzburg Fortress in Salzburg, with the steep track of the Reisszug goods railway climbing the hill below it.","file":"Hohensalzburg 1-2-2014 e Reißzug Stift Nonnberg.jpg","url":"https://commons.wikimedia.org/wiki/File:Hohensalzburg_1-2-2014_e_Rei%C3%9Fzug_Stift_Nonnberg.jpg","author":"Manfred Werner - Tsui","license":"CC BY-SA 3.0"}],"words":3848},{"n":2,"title":"Wooden Rails and Horse Power","when":"1600s – 1803","summary":"In England, coal miners laid wooden rails across the fields so horses could pull heavy wagons of coal much more easily. Over the next 200 years the wooden rails became iron, the tracks grew longer, and in 1807 people in Wales paid to ride a horse-drawn railway carriage by the sea. The railway was growing up, one hoofbeat at a time!","sections":[{"heading":"Coal at Strelley: The Wollaton Wagonway","paragraphs":["Picture the countryside just west of Nottingham, in the English Midlands, in the autumn of 1603. Queen Elizabeth I has died that spring, and King James I has just come to the throne. In the fields near the village of Strelley, men are digging coal from shallow pits. They have a problem. The coal is heavy, the local roads are soft and muddy, and the buyers are miles away. Every cartload costs a fortune in horses, drivers and time.","The man trying to solve that problem was Huntingdon Beaumont. He was born around 1560, the youngest of four sons of Sir Nicholas Beaumont, from a gentry family at Coleorton in Leicestershire, a county with coal mines of its own. Being a youngest son meant he would not inherit the family estate, so he had to make his own fortune, and he chose coal. He leased the coal pits at Strelley and went into partnership with Sir Percival Willoughby, the lord of the manor of Wollaton, who owned coal pits nearby. The two men agreed to work the mines as equal partners.","Between October 1603 and 1604, Beaumont built something new: a track of wooden rails running from the Strelley pits to a place called Wollaton Lane End. It was about 3 kilometres (2 miles) long. Horses pulled wagons loaded with coal along the rails. From the end of the line, most of the coal went by road to Trent Bridge and was then loaded onto barges on the River Trent. The wagonway cost £172, a large sum at the time.","Why was this so important? Because it was out in the open, crossing ordinary countryside, built specially to carry goods for sale. The mine tracks we met in Part 1 were mostly short and underground. The Wollaton Wagonway is often called the first overland wagonway in England, and it is the earliest one for which we have clear written records, such as the partnership agreement dated 1 October 1604.","We should be fair to some rivals, though. Historians have found evidence of other very early lines. Wagonways between Broseley and Jackfield in Shropshire, carrying coal down to the River Severn, were operating from October 1605 and might turn out to be just as old, or even older, than Wollaton. There are hints of a wagonway at Prescot, near Liverpool, possibly from around 1600, and of German miners using tracks at Caldbeck in Cumbria decades earlier. Researchers are still digging through old documents, and the race for 'first' is closer than it once seemed.","Sadly, Huntingdon Beaumont's story did not end happily. He took his wagonway ideas north to the coalfield around Blyth in Northumberland, but those ventures lost a great deal of money, much of it borrowed from friends and family. Some historians blame his reckless management. Others argue that he was working mines that were already nearly worn out, and that he actually kept them going far longer than anyone else could have. Either way, he ended up imprisoned for debt and died in Nottingham Gaol in 1624. The Strelley pits were worked only until about 1620, and the Wollaton Wagonway was probably abandoned after that. But the idea he helped launch would never go away."]},{"heading":"Black Gold on the River Tyne","paragraphs":["To see wagonways really take off, we need to travel north to the coalfields around Newcastle upon Tyne, in north-east England. This region had enormous amounts of coal, much of it close to the surface, and a river that led straight to the sea. London, the biggest city in Britain, was hungry for fuel. As forests shrank and wood became scarce and expensive, more and more Londoners burned coal in their fireplaces, and most of it came from the north-east by ship. Coal from Newcastle was so famous that people began to say 'carrying coals to Newcastle' to mean doing something completely pointless.","The difficulty was the short trip from the pit to the river. Many collieries (coal mines) were several kilometres inland, up on the hills. The coal had to come down to the River Tyne or the River Wear, where it could be loaded onto boats. Doing that by cart on muddy roads was slow and costly, and every landowner whose fields the carts crossed could demand a payment called a wayleave. Building a wagonway along an agreed route, with proper wayleaves, was the answer.","Beaumont brought wooden wagonways to Northumberland in the early 1600s. Over the following century, they spread across the Tyne and Wear coalfield until there was a whole web of them. The Plessey Waggonway, built around 1700, carried coal to the coast near Blyth. By the 1700s, hundreds of kilometres of wooden track were winding across the north-east countryside.","How was a wagonway built? Workers dug a level path and laid wooden cross-pieces called sleepers across it, a bit like the rungs of a ladder lying flat. On top of the sleepers they pegged long wooden rails, usually of oak or another hard wood. Many wagonways later used a clever trick: a second, thinner wooden rail was fixed on top of the main one. When the top rail wore out under the grinding wheels, workers could replace just that strip instead of the whole rail.","The wagons had wheels with a flange, a raised lip on the inside edge of the wheel, which stopped them slipping sideways off the rails. A typical north-east coal wagon, known as a chaldron wagon, carried a little over two and a half tons of coal. That is the weight of about two family cars, all moved by a single horse.","The builders were clever about slopes. Wherever possible, the line ran gently downhill from the mine to the river. A loaded wagon could then roll most of the way by itself, controlled by a brakesman who pressed a wooden brake against the wheel. The horse's hardest job was pulling the empty wagon back up the hill. Later, on some lines, the horse even rode down in a special cart behind the wagons, saving its strength for the climb home.","At the riverside, the wagons ran out onto tall wooden piers called staithes. Trapdoors in the bottom of the wagons opened, and the coal tumbled down chutes into flat-bottomed boats called keels. Teams of tough boatmen, the keelmen of the Tyne, then took the keels downriver to the big sea-going collier ships waiting near the river mouth, which sailed the coal south to London. It was a whole system, from pit to fireplace, and the wagonway was its backbone."]},{"heading":"The Causey Arch: A Bridge Built for Coal","paragraphs":["As the wagonways grew, so did their engineering. Railways like flat, gentle routes, but the hills and valleys of County Durham got in the way. One of the most impressive solutions still stands today, in a wooded valley near the town of Stanley.","Around 1720, a powerful group of coal-owning families, including the Bowes, Liddell and Montague families, joined forces. People called them the Grand Allies. Together they built a wagonway, later known as the Tanfield Wagonway, to carry coal from inland collieries to staithes on the River Tyne. Its route had to cross a deep gorge cut by a stream called the Causey Burn.","Their answer was a single, soaring stone arch. It was built by a local stonemason named Ralph Wood in 1725 and 1726, and a sundial nearby is inscribed 'Ra. Wood, mason, 1727'. The arch spans about 31 metres (102 feet) and stands about 24 metres (80 feet) above the stream, as high as an eight-storey building. When it was finished, it was the longest single-span bridge in Britain, a record it held for about 30 years, until a bridge was built at Pontypridd in Wales in 1756. The Grand Allies spent about £12,000 on the bridge and its route, a colossal amount at that time.","Two tracks ran side by side across the top of the bridge. Loaded wagons rumbled toward the Tyne on one, and empty wagons came back on the other. Accounts say that at its busiest, more than 900 horse-drawn wagons crossed it every day. Imagine standing below in the valley, hearing the endless clatter of wooden wheels and the clop of hooves high above your head.","The bridge's busy years did not last long. Tanfield Colliery was destroyed by fire in 1739, and traffic over the arch declined. But the bridge itself survived. Today it is called the Causey Arch, and it is thought to be the oldest surviving single-arch railway bridge in the world. It was restored and strengthened in the 1980s and now carries a footpath. Nearby, the Tanfield Railway still runs heritage trains along part of the old wagonway route, operated by volunteers, and it proudly claims to be one of the oldest railways in the world."]},{"heading":"From Wood to Iron","paragraphs":["Wooden rails had a weakness: they wore out. Heavy wagons grinding along every day chewed into the timber, and rain and frost made it rot. Rails had to be replaced again and again, which cost money and stopped the coal flowing. Engineers wanted something tougher.","The answer came from the iron industry, and especially from one famous place: Coalbrookdale, in the Severn valley of Shropshire. In 1709 Abraham Darby I had rebuilt a furnace there to make iron using coke, a fuel made from coal, instead of charcoal from wood. That breakthrough meant iron could be made in much larger amounts. The Coalbrookdale Company, run by Quaker families, became one of the leading ironworks in the world. Later it would oversee the building of the famous Iron Bridge across the River Severn, the world's first major cast-iron bridge, which opened in 1781.","In the 1760s, the Coalbrookdale Company began strengthening its wooden wagonway rails with iron, fixing cast-iron plates or bars along the top of them, and from 1767 it was making cast-iron rails. A story often told is that the company had more iron than it could sell at the time and laid it on the tracks as a handy way to store it. Whether or not that was the reason, the results were impressive. Iron rails lasted much longer than wood, and wagons rolled along them more easily.","Cast iron had a problem of its own, though. It is made by pouring melted iron into moulds, and it is very strong when squeezed but brittle, which means it can snap suddenly under a heavy blow or bend. Rails had to be short, often only about a metre long, and they could crack. This brittleness would cause big trouble later, when far heavier steam engines rolled onto the tracks.","Over the next few decades, engineers argued about the best shape for an iron rail. One answer was the plateway. Instead of a rail with a rounded top, a plateway used L-shaped iron plates. The flat part of the L carried the wheel, and the upright part, a raised lip along one side, kept the wheel from sliding off. That meant the wagon wheels could be plain, with no flanges at all. John Curr of Sheffield is often credited with using L-shaped plates in collieries around 1787, though historians argue about the exact date. The canal engineer Benjamin Outram, whose Butterley ironworks made rails, became a great champion of plateways, which were often laid on square stone blocks instead of wooden sleepers. Plateways became especially popular in South Wales and the Forest of Dean.","Plateways had one handy advantage: wagons with plain wheels could, in theory, roll off the track and onto an ordinary road. But they also had a big drawback. The flat plates collected stones, grit and dirt, which slowed wagons down and wore out both wheels and plates.","The other answer was the edge rail. Here the rail was a raised bar, and the wheel had the flange, just like the old wooden wagonways and just like trains today. The engineer William Jessop used iron edge rails and flanged wheels on a line opened in 1789 between Loughborough and Nanpantan in Leicestershire, built as part of a canal scheme. In the end, edge rails won, because dirt fell off them instead of piling up, and they suited faster, heavier vehicles. Almost every railway in the world today uses the edge rail and flanged wheel, a design that grew straight out of wooden wagonways."]},{"heading":"The Surrey Iron Railway: A Toll Road Made of Iron","paragraphs":["Up until now, wagonways and plateways had mostly belonged to mine owners or ironworks, carrying their own goods for their own business. The next big step was a line that anybody could use.","In 1801, Parliament passed an Act authorising the Surrey Iron Railway, south of London. It was engineered by William Jessop, with George Leather as resident engineer, the person who supervised the work on the ground. A short section near Wandsworth opened in January 1802, and on 26 July 1803 the line opened all the way from Wandsworth, on the River Thames, to Croydon, about 8¼ miles (13 kilometres) to the south, passing through Mitcham. With a branch line to Hackbridge, the system was about 9 miles long.","It was a double-track plateway, with L-shaped cast-iron plates set 4 feet 2 inches apart. The railway company did not own any wagons or horses and did not run any trains. Instead, it worked like a turnpike road: anyone could bring their own horse and wagon, pay a toll, and use the track. It was a public railway in that sense, open to all who paid.","What travelled along it? Mostly heavy, everyday goods: coal brought up the Thames by boat, building materials, lime for the soil, manure for farms, corn and seeds. A single loaded wagon could weigh up to about 3¼ tons, and one horse could pull several wagons at once on the smooth iron track, a load that would have been impossible on the rough roads of the time.","The line was soon extended. The Croydon, Merstham and Godstone Railway, opened in 1805, carried the tracks farther south to the stone and lime quarries at Merstham. But the Surrey Iron Railway was never a great money-maker. In 1809 the Croydon Canal opened, competing for the same traffic. The cast-iron plates were also too weak for heavy steam locomotives, which were then being developed. The Merstham extension closed in 1838, and the Surrey Iron Railway itself closed in 1846.","The Surrey Iron Railway is often called the world's first public railway. That is a fair description of what it was, but it may not have been the very first: the Lake Lock Rail Road near Wakefield in Yorkshire, opened in the late 1790s, also let others use its track for a fee. Today, parts of the Surrey Iron Railway's old route lie under later railways and under Croydon's modern Tramlink, so trams still glide along a path first used by horses more than 200 years ago."]},{"heading":"All Aboard the Oystermouth Railway","paragraphs":["So far, every track in our story has carried goods: coal, stone, ore, lime and manure. But in a seaside corner of Wales, someone had a bright idea. Why not carry people?","In 1804, Parliament passed an Act allowing a horse-drawn tramroad to be built around the curve of Swansea Bay, between the town of Swansea and the village of Oystermouth, near the headland called the Mumbles. It was called the Oystermouth Railway, and its job was to carry limestone from quarries near Mumbles, along with coal and iron ore, to Swansea's canal and harbour. The line was about 5½ miles (about 9 kilometres) long.","In February 1807, one of the original proprietors, a man named Benjamin French, made the company an offer. He would pay £20 instead of tolls for the right to carry passengers along the line for a whole year, starting on 25 March 1807. The company agreed. From that day, a horse pulled a specially built carriage full of paying passengers along the rails beside the sea. Guinness World Records recognises this as the world's first regular passenger railway service.","Imagine taking that ride. You climb into a wooden carriage at Swansea. A single horse leans into its collar, and you start to roll, smoothly and quietly compared with the bone-shaking coaches on the roads. To one side is the sweep of the bay and the sea; to the other, sand dunes and fields. The pace is gentle, about as fast as a horse can comfortably walk or trot, but for its passengers this was something entirely new: a ride on rails, bought with a ticket. The stop in Swansea, known as The Mount, is sometimes described as the world's first railway station, though at first it was little more than a place to wait.","Riding was not cheap. By 1813 the fare was 2 shillings, which only fairly well-off people could afford regularly. By 1823 it had been cut to 1 shilling. Then, in 1826, a new road was built between Swansea and Mumbles. Horse-drawn buses started using it, and passenger traffic on the railway dwindled, until the passenger service stopped altogether for a time.","But the line refused to die. It was carrying passengers again by the 1860s. In August 1877 steam engines arrived, and for a while horse trains and steam trains shared the same track until the horses were finally retired in the 1890s. In 1898 the line was extended to a new pier at Mumbles, and as the area became a popular holiday resort, its trains grew huge, carrying up to about 1,800 passengers at once. In 1929 it was electrified, with big double-decker electric tramcars.","Later known as the Swansea and Mumbles Railway, the line ran for more than 150 years. Its last train ran in January 1960, and buses took over the route. You can still see pieces of its history today, including parts of its tramcars, at the National Waterfront Museum in Swansea. Not bad for a line that began with one horse, one carriage and a £20 deal."]},{"heading":"The Limits of Horse Power","paragraphs":["Let's look back at how far the railway had come in two centuries. In 1604, a short wooden track carried coal across a few fields near Nottingham. By the early 1800s, Britain had hundreds of kilometres of wagonways, plateways and tramroads. Rails had changed from wood to cast iron. Engineers had argued over plates and edges. Tracks had leaped across valleys on stone arches, opened to anyone who paid a toll, and started carrying paying passengers.","And yet one thing had not changed at all. Almost everything that moved on these tracks was pulled by a horse, or rolled downhill by gravity, or was hauled by a rope. Horses are wonderful animals, but they have limits. A horse needs food, water and rest every day. It needs a stable, a groom to care for it, and a blacksmith for its shoes. It can only work for a certain number of hours before it is exhausted. It walks at a few kilometres an hour and cannot keep up a fast pace for long. Even on the best rails, there is only so much weight one horse can move.","Later in the 1800s, when horse-drawn trams filled city streets, the numbers were written down carefully, and they show just how hard horse power was to scale up. A typical tram horse worked only four or five hours a day and covered about 19 kilometres (12 miles). Many tram companies kept ten or more horses in their stables for every single tramcar, and a hard-working tram horse might last only a few years before it was worn out. The early wagonway owners faced the same arithmetic: double the traffic, and you had to double the horses, the hay, the stables and the stable hands.","Busy railways needed lots of horses, and a lot of money to look after them. And as more coal mines, ironworks and factories opened during the Industrial Revolution, the demand for moving heavy goods kept growing faster and faster.","Meanwhile, in the mines themselves, a new kind of power was already at work. For decades, enormous engines driven by steam had been pumping water out of deep mine shafts, working day and night without ever growing tired. They were huge, heavy and fixed in place, so nobody had yet put one on wheels. But engineers were starting to wonder.","What if something stronger than a horse, something that never got tired, never needed to sleep, and could keep going all day and all night, could pull the wagons?"]}],"deepDive":"Railway 'firsts' from this period are a minefield, and how you word a claim matters. The Wollaton Wagonway (1603–1604) is often called the first railway in England, but that really means the first overland wagonway with solid documentary proof. Shropshire wagonways at Broseley were running by October 1605, and a 2014 study by historians of early railways was titled, tellingly, 'Wollaton or Broseley? The gap narrows'. There are also earlier hints at Prescot and at Caldbeck. Historians reasonably disagree because the evidence consists of leases, lawsuits and account books, not photographs, and a single newly found document can shift the date. Huntingdon Beaumont's reputation is debated too. One older study blamed his ruin on reckless management, while more recent work argues that he inherited nearly exhausted coal seams and kept them productive for about twenty extra years. The 'first public railway' title is just as slippery. The Surrey Iron Railway (opened 26 July 1803) is often given it, because it was authorised by Parliament as a public toll line open to any user. But the Lake Lock Rail Road in West Yorkshire, opened in the late 1790s, also operated publicly and is sometimes described as the world's oldest public railway. Similarly, the Oystermouth Railway's 1807 service is the first known regular fare-paying passenger service, recognised by Guinness World Records, but earlier lines may occasionally have carried people informally. The technical debate is clearer in hindsight. Cast iron is strong in compression but weak in tension and brittle, so short cast rails cracked under load. Plateways put the guiding flange on the rail, letting plain wheels run, but the flat plate trapped grit and greatly increased rolling resistance. Edge rails shed dirt and allowed a smaller contact patch, so friction was lower. Once rolled wrought-iron rails arrived in 1820, long strong edge rails became practical, and the plateway faded. A simple test settles the 'horse power' question: on a level road a horse might pull around a ton, but on smooth iron rails it could pull several loaded wagons, many times more.","funFact":"The Swansea and Mumbles Railway carried passengers with horses, then steam engines, then electric trams, and kept running for more than 150 years before closing in January 1960.","check":{"q":"In which year did the Oystermouth (later Swansea and Mumbles) Railway begin carrying fare-paying passengers?","a":"1807","wrong":["1604","1725","1830"]},"sources":[{"title":"Wollaton Wagonway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wollaton_Wagonway"},{"title":"Huntingdon Beaumont","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Huntingdon_Beaumont"},{"title":"Causey Arch","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Causey_Arch"},{"title":"Surrey Iron Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Surrey_Iron_Railway"},{"title":"Swansea, Oystermouth and Mumbles Railway","publisher":"Transport for Wales","url":"https://tfw.wales/railway-200/swansea-oystermouth-mumbles-railway"},{"title":"First regular passenger railway service","publisher":"Guinness World Records","url":"https://www.guinnessworldrecords.com/world-records/114288-first-regular-passenger-railway-service"},{"title":"Mumbles Railway","publisher":"People's Collection Wales","url":"https://www.peoplescollection.wales/content/mumbles-railway"},{"title":"Horsecar","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Horsecar"}],"photos":[{"src":"img/deep/railways/02-1.jpg","alt":"Causey Arch in County Durham, the stone bridge built in 1725–26 to carry a horse-drawn wagonway over a stream.","file":"Causey Arch - geograph.org.uk - 1903494.jpg","url":"https://commons.wikimedia.org/wiki/File:Causey_Arch_-_geograph.org.uk_-_1903494.jpg","author":"Ian Knox","license":"CC BY-SA 2.0"},{"src":"img/deep/railways/02-2.jpg","alt":"A rusty piece of L-shaped cast-iron plateway rail, found at an old waggonway in Stevenston, Scotland.","file":"Stevenston - Plateway rail.JPG","url":"https://commons.wikimedia.org/wiki/File:Stevenston_-_Plateway_rail.JPG","author":"Rosser1954","license":"CC BY-SA 3.0"},{"src":"img/deep/railways/02-3.jpg","alt":"Old photograph of passengers in top hats riding a horse-drawn carriage on the Swansea and Mumbles Railway.","file":"Tram on the Swansea and Mumbles Railway in Wales, 1807.jpg","url":"https://commons.wikimedia.org/wiki/File:Tram_on_the_Swansea_and_Mumbles_Railway_in_Wales,_1807.jpg","author":"Unknown photographer","license":"Public domain"}],"words":3731},{"n":3,"title":"Taming Steam","when":"1712 – around 1800","summary":"Long before trains, people learned that boiling water makes steam strong enough to push heavy things. The first steam engines were giant, slow pumps that stood still and sucked water out of mines. Then clever inventors made them better and smaller, until one day an engine might be able to move itself.","sections":[{"heading":"A Problem Full of Water","paragraphs":["To understand why anyone bothered to invent a steam engine, you have to climb down a mine. Imagine standing at the bottom of a coal pit in the English Midlands around the year 1700. It is dark, cold and dripping. Every few minutes you hear water trickling out of the rock walls, collecting in puddles, then pools, then something closer to an underground pond. The deeper the miners dig, the more water seeps in. If nobody gets it out, the mine floods and all the coal at the bottom is lost.","By the late 1600s this was one of the biggest headaches in British industry. Coal was replacing wood as the main fuel for homes, forges and breweries, because many forests had already been cut down. Tin and copper mines in Cornwall faced the same trouble. The easy, shallow seams near the surface had been dug out long ago, so miners had to go deeper, and deeper meant wetter.","The old ways of draining a mine were slow and expensive. Teams of men turned handles. Horses walked round and round in circles, turning a big wheel called a horse gin that pulled up buckets on chains. Some mines dug long drainage tunnels, called adits or soughs, sloping gently downhill to let water run out into a valley. Where there was a fast stream, a waterwheel could drive pumps. But a big mine might need dozens of horses working in shifts, and every horse had to be fed, stabled and replaced. Some mines simply gave up.","So the question that haunted mine owners was simple: was there a tireless machine that could lift water, day and night, without eating hay? The answer would come from a pot of boiling water. And although nobody knew it yet, the machine invented to solve this underground problem would one day, about a hundred years later, start rolling along rails.","People had played with the power of steam for a very long time. Hero of Alexandria, a Greek engineer living in Roman Egypt in the first century CE, described a spinning ball pushed round by jets of steam, but it was a curiosity, not a working machine. In the 1600s scientists in Italy, Germany, France and England began experimenting seriously with air pressure and vacuums. They discovered that the air around us presses on everything with surprising force, and that if you could make an empty space, a vacuum, the outside air would push hard to fill it. That discovery was the key that unlocked the first steam engines.","One early attempt came from Thomas Savery, an English military engineer, who patented a steam pump in 1698 and nicknamed it the 'Miner's Friend'. It had no piston. Instead, steam filled a metal vessel, was cooled to make a partial vacuum, and the vacuum sucked water up a pipe. Then fresh steam pushed the water further up. It was a clever idea, but in practice it could only suck water up about 30 feet (around 9 metres), it used lots of fuel, and its joints were dangerous under pressure. A French scientist, Denis Papin, had meanwhile shown that steam condensing under a piston could make that piston move, but he never built a full-size working engine. Someone needed to combine these ideas into a machine that really worked."]},{"heading":"Newcomen's Giant Nodding Beam","paragraphs":["That someone was Thomas Newcomen, an ironmonger from Dartmouth, a small port in Devon in south-west England. We do not even know his exact birthday, only that he was born around 1664. He sold tools and iron goods, and many of his customers were tin mines in Devon and Cornwall, so he heard about their flooding problems all the time. Newcomen was a Baptist, which meant he belonged to a church outside the official Church of England, and in those days that kept people like him out of the universities. He taught himself, and he worked closely with a plumber and glazier named John Calley.","After years of trial and error, Newcomen and Calley built their first known working engine in 1712, near Dudley Castle in the English Midlands, to pump water from a coal mine. It is often called the first practical steam engine in the world. A picture of it survives: an engraving made in 1719 by Thomas Barney, showing a tall engine house with a huge wooden beam sticking out of the top like a giant seesaw.","Here is how it worked, and it is cleverer than it first looks. At the bottom of the engine house sat a boiler, a big copper or iron pot over a coal fire, making steam at hardly more than the normal pressure of the air. Above the boiler stood an upright cylinder, open at the top, with a piston inside that could slide up and down. The piston was connected by a chain to one end of the great wooden beam. The other end of the beam was connected to long, heavy pump rods hanging down the mine shaft.","Because the pump rods were heavy, their weight pulled their end of the beam down, which lifted the piston to the top of the cylinder. As the piston rose, steam from the boiler flowed in underneath it. Then came the magic moment: a jet of cold water was sprayed into the cylinder. The steam instantly turned back into a few drops of water, leaving almost empty space, a partial vacuum. Now the air outside, pressing down on the open top of the piston, shoved the piston down into the cylinder with enormous force. The beam rocked, the other end swung up, and the pump rods rose, lifting water out of the mine. Then steam was let in again, and the whole cycle repeated.","This is why Newcomen's machine is called an atmospheric engine. The steam did not really push anything. It was just a way of making a vacuum. The real muscle was the weight of the atmosphere itself, pressing down at about 1 kilogram on every square centimetre, which adds up to roughly 10 tonnes on every square metre. A big piston could feel tonnes of force.","The Dudley Castle engine nodded about 12 times a minute and is reported to have pumped around 120 gallons (about 550 litres) of water every minute. That may sound slow, but it kept going hour after hour, and it could lift water from far deeper than Savery's pump. Mine owners were thrilled. Within about 20 years, more than 120 Newcomen engines had been built in Britain and Europe, and by 1800 there were over 1,400 of them."]},{"heading":"Big, Hungry and Rooted to the Spot","paragraphs":["Newcomen's engine changed mining, but it was nothing like a train engine. For a start, it was enormous. The engine was built into its own stone engine house, several storeys tall, and the building itself was part of the machine, holding up the beam. Engines were built more like houses than like gadgets. Cylinders were cast by the same foundries that made cannons, and the rest was put together by carpenters, stonemasons and blacksmiths using traditional skills.","You can see just how big these machines were at the Science Museum in London, which displays a Newcomen-type engine built in 1791 by Francis Thompson and last used at Pentrich in Derbyshire. Together with parts of its engine house it weighs about 105 tonnes. It is a late example, with a cast-iron beam, because earlier engines used massive wooden beams. In Newcomen's home town of Dartmouth you can see a real engine dating from 1725, and the Black Country Living Museum near Dudley has built a working full-size replica of the 1712 engine, based on old engravings and records. It was completed in 1986.","The second problem was fuel. Every time cold water was sprayed into the cylinder, it cooled the cylinder walls down. Then the next puff of steam had to heat the cold metal up again before it could fill the cylinder, and much of the steam was wasted just doing that. A Newcomen engine gobbled coal. At a coal mine this did not matter much, because the engine could burn cheap, low-quality coal that nobody wanted to buy anyway. At a Cornish tin mine, where coal had to be shipped in from Wales, the fuel bill was painful.","The third problem was the most important for our story: the engine could not move. It was fixed to the ground, fixed to its building and fixed to its mine shaft. It made a slow up-and-down motion, perfect for working a pump but not for turning wheels. Nobody in 1712 imagined that such a machine might ever roll along a road. Still, Newcomen engines kept working for an astonishingly long time. Some were still pumping mines well into the 1800s, a century after the first one was built."]},{"heading":"James Watt's Walk on Glasgow Green","paragraphs":["Fifty years after Dudley Castle, the next big leap happened in Scotland. James Watt, born in 1736 in Greenock on the River Clyde, was a skilled maker of scientific instruments working at the University of Glasgow. Around 1763 to 1764, the university asked him to repair a small model of a Newcomen engine used for teaching. The model worked badly. It would run for a few strokes and then run out of steam, even though its boiler seemed big enough.","Watt did what good scientists do: he measured things. He found that the problem was the one we have just met. Most of the steam was being wasted heating up the cylinder again after each cold spray. The cylinder was being heated and cooled, heated and cooled, dozens of times a minute. Watt realised that to save fuel, the cylinder needed to stay hot all the time, while the steam still needed to be cooled to make a vacuum. Those two wishes seemed to contradict each other.","The answer came to him, according to his own later account, on a Sunday afternoon walk across Glasgow Green in May 1765. Why not cool the steam somewhere else? He imagined a separate chamber, a condenser, connected to the cylinder by a pipe and kept cold all the time. When a valve opened, the steam would rush out of the hot cylinder into the cold condenser and turn to water there, leaving a vacuum behind it in the cylinder, while the cylinder itself stayed hot. It was a simple idea, but it took years of hard work to turn it into a reliable machine.","Watt's patent for the separate condenser was granted in 1769. At first his business partner, John Roebuck, ran into money trouble and went bankrupt. Then the Birmingham manufacturer Matthew Boulton took over Roebuck's share, and in 1775 the famous partnership of Boulton and Watt was formed at Boulton's Soho works near Birmingham. That same year Parliament extended Watt's patent so that it would last until 1800. The first Boulton and Watt engines went to work in 1776, mostly pumping mines.","The results were dramatic. A Watt engine could do the same work as a Newcomen engine while burning far less coal, and some estimates say Watt's design was up to about five times as fuel-efficient. Boulton and Watt often charged mine owners a share of the money they saved on coal, which shows just how big the savings were. Cornish mines, with their expensive imported coal, quickly became some of their best customers.","Watt kept improving his engines. He added ways to make the piston push in both directions, and with his team he developed gears that turned the up-and-down motion of the beam into turning motion, so engines could drive machines in factories, mills and breweries, not just pumps. He even made popular the idea of measuring an engine's power in 'horsepower', comparing it to the number of horses it could replace. Today the scientific unit of power, the watt, is named after him. Every light bulb label that says '10 W' is a tiny tribute to James Watt.","But Watt had one firm rule. His engines worked with steam at only a little above the pressure of the air. Boilers in the 1700s were made of riveted plates of iron or copper, and they could burst. A bursting boiler sprays scalding steam and flying metal, and it can kill. Watt considered higher-pressure steam too dangerous, and he and Boulton argued against it. With his patent in force until 1800, the firm also had legal power to stop rival engineers from building engines with separate condensers. This caution made sense for a factory engine bolted to a floor. As we will see, it also helped hold back the idea of an engine that could move."]},{"heading":"Cugnot's Steam Cart","paragraphs":["While British engineers were busy pumping mines, a French army engineer was thinking about something much bolder. Nicolas-Joseph Cugnot was born in 1725 in Void, a village in Lorraine in eastern France. He served as a military engineer and wrote books about fortifications and war machines. The French army had a very practical problem: its cannons were extremely heavy, and dragging them around with teams of horses was slow and difficult. Could steam do the job instead?","Cugnot tested a small model in 1769, and in 1770 a full-size machine was built. It was called a fardier à vapeur, which means 'steam dray'. A fardier was a big, sturdy cart used for hauling heavy loads such as cannon barrels. Cugnot's version had three wheels: two at the back and one at the front. Hanging out in front of the front wheel was a large round copper boiler with a firebox under it, and two cylinders whose pistons were pushed directly by the steam. Through a ratchet mechanism, the pistons turned the single front wheel.","It was a strange-looking beast. Empty, it weighed about 2.5 tonnes. All the weight of the boiler hung over the front wheel, so steering it was very hard work, a bit like trying to push a wheelbarrow loaded with bricks round a corner. It was slow, too. It was meant to cover several kilometres in an hour, but in practice it crawled along at little more than walking pace. Worst of all, its boiler could not make steam fast enough, so every quarter of an hour or so it had to stop and wait for the pressure to build up again.","There is a famous story that in 1771 Cugnot's machine crashed into a wall in Paris, making it 'the first car accident in history'. It is a good story, but it is only a legend. Historians have found no record of it written at the time; it first appears in print decades later. What is true is that the army lost interest. Cugnot was given a pension of 600 livres a year by King Louis XV in 1772. He lost it during the French Revolution, and Napoleon restored it shortly before Cugnot died in Paris in 1804.","Cugnot's fardier still exists. Since 1800 it has been kept at the Conservatoire national des arts et métiers in Paris, and it is now displayed in the Musée des Arts et Métiers there. It is often described as the oldest surviving self-propelled land vehicle in the world. In 2010, engineering students in France built a working replica to test how it really behaved. Cugnot's steam cart never ran on rails and never carried passengers on a regular route, but it showed something important: a steam engine could be made small enough to travel along with the load it was moving."]},{"heading":"Murdoch's Little Runaway Carriage","paragraphs":["Back in Britain, one of the most talented engineers of the age was working inside the very company that disliked high-pressure steam. William Murdoch was born in 1754 in Ayrshire, Scotland, the son of a millwright. In 1777 he travelled south to Birmingham to ask for a job at Boulton and Watt. There is a popular story that he impressed Matthew Boulton by wearing a hat he had turned himself out of wood on a lathe. Nobody can prove it, but it fits his inventive character.","Boulton and Watt soon sent Murdoch to Cornwall to put up and look after their engines in the mining district around Redruth. He lived there for many years from 1779, working long hours climbing around engine houses and fixing problems. In his spare time, he built something remarkable: a small model steam carriage. In 1784 it was seen running around his living room in Redruth. It was only a model, small enough to pick up, but it moved under its own steam, using steam at higher pressure than Boulton and Watt's big engines.","A much-told tale says that one night Murdoch tested the little carriage on a dark lane near the church. It hissed off on its own, glowing and puffing, and frightened the local vicar, who thought he had met the Devil himself. Like Cugnot's crash, this is a story rather than a proven fact, and if it happened at all, it probably involved the model rather than a full-size carriage. But it shows how strange a self-moving, fire-breathing machine must have seemed to people at the time.","James Watt was not impressed. He thought steam carriages had no future, and he also worried about losing his best engineer in Cornwall. When Murdoch set off for London in 1785, intending to patent his carriage, Matthew Boulton met him on the way and persuaded him to go back to Cornwall and forget about it. Murdoch stayed loyal to the firm for the rest of his career and later became a partner. He went on to other great achievements: in the 1790s he pioneered lighting with coal gas, and he is credited with the 'sun and planet' gear that helped Watt's engines turn wheels. His model steam carriage survives today at Thinktank, Birmingham's science museum.","Redruth is only a few kilometres from Camborne, and in the 1780s a tall Cornish boy was growing up nearby among the engine houses. Some historians have wondered whether he ever saw or heard about Murdoch's little carriage. We do not know. But that boy would soon take up the idea that Watt had turned down."]},{"heading":"The Science of Steam: Why Pressure Was the Key","paragraphs":["Let us stop and look closely at the science, because it explains why the next part of our story happened. When you heat water in a kettle, the water molecules move faster and faster. At 100 degrees Celsius, at normal air pressure, they move fast enough to break away and fly off as a gas: steam. Here is the astonishing part. When water turns into steam at normal air pressure, it takes up about 1,600 times as much space. One cupful of water becomes enough steam to fill a large bucket hundreds of times over.","Now imagine trapping that steam in a closed box. The steam wants to spread out, so it presses hard on every wall of the box. If one wall of the box can move, like a piston sliding in a cylinder, the steam will push it. That is the basic idea behind every steam engine that pushes with steam: heat makes water into steam, steam presses, and the press moves a piston. You can see a tiny version of this when the lid of a saucepan rattles and jumps as the water boils underneath.","If you keep heating the water inside a strong, closed boiler, the pressure keeps rising. Higher pressure steam pushes harder on every square centimetre. And the force on a piston equals the pressure multiplied by the area of the piston. That simple rule is the whole secret. If you double the pressure, you can get the same push from a piston with half the area. If you make the pressure several times higher, you can make the whole engine much smaller and lighter while getting just as much power.","Compare two ways of making an engine. A Newcomen engine, or a low-pressure Watt engine, relied heavily on the vacuum made by condensing steam. The most force it could ever get from the air pressing on the piston was limited to about 1 kilogram per square centimetre. To get a big force, it needed a huge piston, a huge cylinder, a huge beam and a condenser fed with lots of cold water. Imagine trying to fit all that, plus a water tank and a cooling system, onto a cart. It was hopeless.","A high-pressure engine does things differently. Its boiler makes 'strong steam', at pressures several times higher than the air around it, and lets that steam push the piston directly. After the steam has done its work, it is simply let out into the open air. There is no condenser, no cooling water, no giant beam. The used steam escapes in short, sharp bursts, which is why such engines were nicknamed 'puffers'. A high-pressure engine could be small enough to sit on a cart, and powerful enough to move the cart, and its load, and itself.","There was a catch, of course: danger. A boiler full of high-pressure steam stores a great deal of energy, like a balloon blown up much too tight. If it bursts, all that energy escapes at once. So high-pressure engines needed strong boilers, carefully made, and safety devices such as safety valves, which open and let steam out if the pressure climbs too high. James Watt's fear was not silly; boilers did explode, and people were killed. But the reward for taming high-pressure steam safely was enormous: an engine light enough to move. The world needed someone brave, skilled and stubborn enough to try."]},{"heading":"Waiting for a Daring Engineer","paragraphs":["By the end of the 1700s, all the pieces were lying on the table. Newcomen had shown that steam could do heavy work, every day, for years. Watt had shown how to make engines far more efficient and how to turn their motion into turning wheels. Cugnot had shown that a steam engine could travel with its load, even if clumsily. Murdoch had shown, in a living room in Redruth, that a small high-pressure engine could drive a carriage. And the wagonways of Part 2 had shown that heavy loads glide easily along smooth rails.","Two things still stood in the way. One was a legal fence: Watt's patent on the separate condenser lasted until 1800, and Boulton and Watt defended it fiercely against anyone they thought was copying it. The other was a fence in people's minds: the belief that high-pressure steam was simply too dangerous to use. In 1800 the patent finally ran out. The legal fence was gone. Now someone had to jump the second fence.","That someone was living in Cornwall, in the mining country between Camborne and Redruth. He was very tall, famously strong, impatient with schoolwork but brilliant with machines, the son of a mine captain who had grown up surrounded by the thump and hiss of pumping engines. He had already argued with Boulton and Watt about his own engine designs. And unlike the great James Watt, he was not afraid of high-pressure steam at all. His name was Richard Trevithick."]}],"deepDive":"Historians of technology often say the steam engine was not one invention but a long chain of improvements, and Part 3 shows why. The Newcomen engine of 1712 relied on atmospheric pressure, about 101 kilopascals at sea level, acting on one side of a piston while condensing steam created a partial vacuum on the other. Because the same cylinder was alternately heated and cooled, a great deal of heat was thrown away on every stroke. Watt's separate condenser, conceived in 1765 and patented in 1769, attacked exactly this loss, and his engines are often said to have used something like a quarter to a fifth of the fuel of a comparable Newcomen engine. Even so, by modern standards these machines were wildly inefficient: early Newcomen engines turned only around 1 percent of the energy in their coal into useful work, and Watt's best engines reached only a few percent. The deeper science explaining why was not understood until the 1820s and later, when Sadi Carnot and others founded thermodynamics, partly by asking why steam engines worked as they did. Historians also debate the role of patents. Watt's patent, extended by Parliament to 1800, gave Boulton and Watt the security to invest in a risky business, but critics argue that the firm also used it to block rival designs, including high-pressure engines, for decades. Some economic historians suggest that steam engineering advanced faster after 1800, once the patent expired and engineers such as Richard Trevithick and Arthur Woolf were free to experiment. Another debate concerns 'firsts'. Cugnot's 1770 vehicle is often called the first automobile, and it is certainly the oldest surviving self-propelled land vehicle, yet it had little direct influence on later steam transport in Britain. Murdoch's 1784 model may or may not have inspired Trevithick; the two lived near each other, but there is no firm evidence of a connection. Finally, the figure of about 1,600 for the expansion of water into steam applies at normal atmospheric pressure; at higher pressures steam is denser, which is precisely why a strong boiler can store so much energy, and so much danger.","funFact":"James Watt made 'horsepower' the standard way of rating engines, so that customers could compare his machines with the horses they were replacing, and the unit of power called the watt was later named in his honour.","check":{"q":"What was James Watt's big improvement to the Newcomen steam engine?","a":"A separate condenser, so the cylinder could stay hot and much less fuel was wasted","wrong":["Putting the steam engine on wheels so it could pull carts","Using electricity to heat the water instead of coal","Replacing the wooden beam with a rope pulled by horses"]},"sources":[{"title":"Scientist of the Day: Thomas Newcomen","publisher":"Linda Hall Library","url":"https://lindahall.org/thomas-newcomen"},{"title":"Newcomen Atmospheric Engine","publisher":"Science Museum Group Collection","url":"https://collection.sciencemuseumgroup.org.uk/objects/co50900/newcomen-atmospheric-engine"},{"title":"A new age","publisher":"Science Museum Blog","url":"https://blog.sciencemuseum.org.uk/a-new-age/"},{"title":"James Watt","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/James_Watt"},{"title":"Nicolas-Joseph Cugnot","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nicolas-Joseph_Cugnot"},{"title":"William Murdoch","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Murdoch"},{"title":"Newcomen atmospheric engine","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Newcomen_atmospheric_engine"},{"title":"Horsepower","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Horsepower"}],"photos":[{"src":"img/deep/railways/03-1.jpg","alt":"1740s engraving of a Newcomen steam engine: the boiler and cylinder inside the engine house, and the great rocking beam.","file":"Engineering; a Newcomen steam-engine. Engraving, 174-. Wellcome V0024483ER.jpg","url":"https://commons.wikimedia.org/wiki/File:Engineering;_a_Newcomen_steam-engine._Engraving,_174-._Wellcome_V0024483ER.jpg","author":"Wellcome Collection","license":"CC BY 4.0"},{"src":"img/deep/railways/03-2.jpg","alt":"Nicolas-Joseph Cugnot's steam 'fardier' of about 1770, with its big round boiler at the front, in a Paris museum.","file":"Joseph Cugnot's 1770 Fardier à Vapeur, Musée des arts et métiers, Paris 2015.jpg","url":"https://commons.wikimedia.org/wiki/File:Joseph_Cugnot%27s_1770_Fardier_%C3%A0_Vapeur,_Mus%C3%A9e_des_arts_et_m%C3%A9tiers,_Paris_2015.jpg","author":"Joe deSousa","license":"CC0"},{"src":"img/deep/railways/03-3.jpg","alt":"James Watt painted in 1792 by Carl Frederik von Breda, with engine drawings on the table beside him.","file":"Watt James von Breda.jpg","url":"https://commons.wikimedia.org/wiki/File:Watt_James_von_Breda.jpg","author":"Carl Frederik von Breda","license":"Public domain"}],"words":4174},{"n":4,"title":"Trevithick's Iron Horse","when":"1801 – 1808","summary":"A tall, strong engineer from Cornwall called Richard Trevithick built steam engines small enough to move. In 1804 one of his engines pulled heavy iron wagons along a track in Wales, the first time a steam locomotive ever hauled a load on rails. It worked, but it was so heavy that it kept cracking the rails!","sections":[{"heading":"The Cornish Giant","paragraphs":["Richard Trevithick was born on 13 April 1771 at Tregajorran, in the parish of Illogan, a scattering of cottages between the mining towns of Camborne and Redruth in Cornwall. His father, also called Richard, was a mine captain, which meant he managed the men and machines of a tin or copper mine. Young Richard grew up in a landscape of engine houses, spoil heaps and pumping beams, where the thud of Newcomen and Watt engines could be heard day and night.","At school he was not a star pupil. Teachers found him stubborn and easily bored, though he could do difficult sums in his head faster than they could on paper. What he really loved was the engines. As a teenager he followed his father around the mines, and by his early twenties he was working as an engineer himself, building and repairing pumping engines.","He also became a local legend for his size and strength. He stood about 6 feet 2 inches (about 1.88 metres) tall, very tall for his time, and Cornish people called him the 'Cornish Giant'. Many stories were told about him: that he could lift enormous weights, throw a sledgehammer clean over an engine house, or write his name on a beam high above his head. Some of these tales were surely improved in the telling, but everyone agreed he was powerful, fearless and full of restless energy.","In 1797 Trevithick married Jane Harvey, whose family ran Harvey's foundry at Hayle, one of the most important engine-building works in Cornwall. That same year he became engineer at Ding Dong mine, near Penzance. Working with another engineer, Edward Bull, he began to experiment with engines that worked differently from the Boulton and Watt design. Boulton and Watt suspected these engines broke their patent on the separate condenser, and they took legal action. An injunction, a court order telling him to stop, was even pinned up at the mine. For a few frustrating years, Trevithick had to be careful.","Then, in 1800, Watt's patent finally ran out. Trevithick was free. And he had already decided which way to go: not bigger, low-pressure engines like Watt's, but small, powerful engines working with high-pressure 'strong steam'."]},{"heading":"The Puffers","paragraphs":["As we saw in Part 3, a low-pressure engine needs a big cylinder and a condenser full of cold water. Trevithick threw the condenser away. His engines let steam into the cylinder at much higher pressure than the air around it, let it push the piston directly, and then simply blew the used steam out into the air. Each blast of exhaust made a loud 'puff', so these engines became known as 'puffers' or 'puffer engines'.","Getting rid of the condenser had big advantages. The engine no longer needed a huge supply of cooling water or a tall engine house with a giant beam. It could be built compactly, with the cylinder sunk right into the boiler to keep it hot. A puffer could be much smaller and lighter than a Watt engine of similar power, cheaper to build, and quicker to put up. In the Cornish mines, Trevithick's compact engines were soon used to wind ore and men up and down shafts.","In March 1802, Trevithick and his cousin Andrew Vivian took out a patent for high-pressure steam engines, including their use to drive carriages. Trevithick had grasped something that Watt never had: an engine light and strong enough to carry its own weight could move itself. And if it could move itself, it could pull other things too.","Trevithick was also very good at boilers, which were the dangerous part. He made cylindrical boilers of wrought iron, rounded so that pressure pressed evenly on the walls, and he placed the fire inside a tube that ran through the water, so that the hot gases heated water all around them. It was a big step toward the kind of boiler that later locomotives would use."]},{"heading":"Christmas Eve on Camborne Hill","paragraphs":["Picture Camborne on Christmas Eve, 1801. It is cold and dark, and the narrow street called Fore Street climbs steeply up Camborne Hill. Out of a workshop rumbles a machine no one in the town has ever seen: a boiler on wheels, glowing at the bottom, with a chimney belching smoke and sparks and a cylinder puffing out clouds of steam. Trevithick had built a full-size steam road vehicle. Local people nicknamed it the 'Puffing Devil'.","Andrew Vivian steered, and several men climbed aboard, around six by most accounts, with others perhaps hanging on wherever they could. With a great hissing and puffing, the Puffing Devil set off up Fore Street and up Camborne Hill towards the nearby village of Beacon. Climbing a steep hill with passengers on board was a real test of power, and the machine passed it. For the first time, people in Britain had travelled in a full-size vehicle driven by steam.","The excitement inspired a Cornish folk song, known as 'Camborne Hill', which people still sing today. It celebrates the day the steam carriage went up the hill, with all its puffing and noise.","The ending, sadly, was less glorious. A few days later the engine broke down while out on the road. The story goes that Trevithick and his friends pushed it into a shelter and went off to an inn for a meal and something to drink, perhaps a Christmas roast goose, leaving the fire still burning under the boiler. With nobody watching, the water in the boiler boiled away. The empty boiler grew red hot, and the fire spread to the wooden parts of the machine and the building around it. By the time anyone came back, the Puffing Devil was a burned-out wreck.","Trevithick blamed careless operating, not his design, and he was right that a dry boiler is a disaster. But it was a lesson he never forgot. Today the Trevithick Society has built a working replica of the Puffing Devil, which has been driven through Camborne on Trevithick Day, a festival held in the town in his honour."]},{"heading":"London Streets and an Explosion at Greenwich","paragraphs":["Trevithick did not give up on road vehicles. In 1803 he and Vivian built a new machine, often called the London Steam Carriage, which looked like a tall stagecoach body perched above a steam engine and huge rear wheels. It was driven through the streets of London, carrying passengers, and it worked. But the roads were rough and full of horses, carts and people, the carriage was expensive to run, and nobody wanted to buy it. In the end the engine was sold off to power a mill. Road steam had to wait.","Around the same time, Trevithick's engines were being built elsewhere. In 1802, the Coalbrookdale Company in Shropshire, famous ironmakers, built a high-pressure engine for him, and a drawing survives of what seems to be a small rail locomotive built there. We know very little about it. It may have been tested, or it may never have run at all, so historians are careful not to claim it as the first.","Then, in 1803, came a disaster that gave Trevithick's critics just what they wanted. One of his high-pressure engines, used to pump water at Greenwich near London, exploded, killing four men. According to Trevithick's side of the story, the engine had been left in the care of an inexperienced worker, and the safety valve had been fastened down so that it could not open, so the pressure built up until the boiler burst. Boulton and Watt seized on the accident as proof that high-pressure steam was deadly.","Trevithick argued that the engine had been badly handled, not badly designed. But he took the danger seriously. On later engines he fitted two safety valves, so that if one stuck, the other would still let steam out. He also added a clever device called a fusible plug: a plug of lead set into the boiler just above the fire. If the water level fell too low, the lead would heat up and melt, letting steam rush out and put the fire out before the boiler could become dangerously overheated. Ideas like these made high-pressure steam much safer, and versions of them were used on steam locomotives for well over a century."]},{"heading":"The Great Bet at Penydarren","paragraphs":["Now our story moves to South Wales, to Merthyr Tydfil, which around 1800 was becoming one of the greatest iron-making towns in the world. Its valleys were full of blast furnaces belonging to rival ironmasters. One of them was Samuel Homfray, owner of the Penydarren ironworks. Homfray was interested in Trevithick's high-pressure engines and in 1803 he brought Trevithick to Penydarren to build engines for the works.","Merthyr at that time was a noisy, smoky, booming place. Four huge ironworks, Cyfarthfa, Dowlais, Plymouth and Penydarren, crowded into the valley, their furnaces glowing day and night and lighting up the sky. Thousands of workers had poured in from the Welsh countryside, from England and from Ireland to dig coal and iron ore and to work the furnaces. The ironmasters were fiercely competitive, always looking for an advantage over each other, which helps explain why one of them was willing to gamble on a brand-new machine.","The ironmasters of Merthyr shared a tramroad, a horse-drawn plateway made of L-shaped cast-iron plates, which carried their iron down the valley to the canal wharf at Abercynon. There the iron was loaded onto boats on the Glamorganshire Canal and taken to the port of Cardiff. The tramroad was just under 10 miles (about 16 km) long, and horses pulled wagons along it every day.","Homfray had a bold idea. Could Trevithick's engine be put on wheels and made to pull the wagons instead of horses? Another ironmaster, Richard Crawshay of the Cyfarthfa ironworks, thought the idea was nonsense. So the two men made a bet. Each put up 500 guineas, a huge sum of money at the time, enough to buy a fine house, and handed it to a third ironmaster, Richard Hill of the Plymouth ironworks, to hold. Homfray would win if a steam engine could haul 10 tons of iron along the tramroad to Abercynon and bring the empty wagons back.","Trevithick began work in the autumn of 1803 and had his locomotive ready by February 1804. It looked very different from the trains you know. It had a single large horizontal cylinder set into a round iron boiler, a long piston rod sticking out in front, and a big flywheel at the side to keep the motion smooth. Gears carried the power to the four wheels, which ran on the plates of the tramroad. A fireman fed the fire, and the chimney rose from the same end of the boiler as the fire door, because the hot gases travelled along a U-shaped tube through the water and back again, giving them more time to heat it.","On 21 February 1804, the moment came. Behind the engine were five wagons carrying about 10 tons of iron. And then, as word spread, around 70 men climbed aboard the wagons for the ride, adding several more tons. With a great puffing and clanking, the locomotive set off down the valley from Penydarren towards Abercynon, nearly 10 miles away.","It was not a smooth trip. In places the crew had to stop to cut down overhanging branches and move rocks out of the way. Even so, the engine kept going. The whole journey took a little over four hours, which works out at an average of only a couple of miles per hour, though on good stretches it went faster, reaching around 5 miles per hour. Trevithick wrote proudly to his friend Davies Giddy that the engine had worked well and that no water was added to the boiler during the trip. According to accounts of the run, the engine burned only about two hundredweight of coal on the way down, roughly 100 kilograms, a surprisingly small pile for such a heavy load. Compare that with the horses it was meant to replace: a single horse could pull perhaps a couple of tons on the tramroad, so moving 10 tons of iron plus 70 passengers in one go would have needed a whole team of animals and several trips.","Trevithick also noticed something important. The used steam from the cylinder went up the chimney, and each puff seemed to make the fire burn more fiercely, pulling air through it. He commented on this effect in his letters. It was the same principle as the blastpipe that, as we will see in Part 7, would later help Rocket win its famous trial.","Whether Homfray actually won the bet is still unclear. On the way back up the valley, a bolt sheared and the boiler leaked, so the crew had to drop the fire, and the engine did not get back to Penydarren until the next day. Crawshay argued that the terms had not been met, and nobody knows for sure if the 500 guineas were ever paid. But in the history books, 21 February 1804 is remembered as the day when, for the first known time anywhere in the world, a steam locomotive hauled a load along rails."]},{"heading":"Too Heavy for the Track","paragraphs":["There was one big problem, and it was not the engine. It was the track. The Penydarren locomotive weighed around 5 tons, far more than a loaded horse wagon. The tramroad's plates were made of cast iron, which is hard but brittle, like a biscuit. It can hold a steady weight well, but sudden knocks and heavy pounding make it snap. As the locomotive rumbled along, the plates cracked and broke under its wheels.","After a few more trips, the ironworks decided the engine was causing more damage than it was worth. The wheels were taken off, and the engine was put to work standing still, driving machinery at the ironworks, including a forge hammer. Horses went back to pulling the wagons along the tramroad.","In 1981, the National Museum of Wales built a full-size, working reconstruction of the Penydarren locomotive, based on the evidence that survives. When it was run on a short track, it too broke the rails, a perfect demonstration of Trevithick's problem nearly 180 years later. The replica has been steamed each year at the National Waterfront Museum in Swansea, where visitors can see and hear it in action.","Trevithick tried again in the north of England. In 1804 and 1805, a locomotive to his design was built at Gateshead, on the River Tyne, by his agent John Whitfield, for Christopher Blackett, the owner of Wylam Colliery. It may have been the first locomotive with flanged wheels, designed to run on edge rails rather than plates. But Wylam's track was made of wood, and once again the engine was far too heavy for it. Blackett never used it on his wagonway, and it ended up as a stationary engine. Still, the people of Wylam had seen what a locomotive could be, and as Part 5 will show, they would not forget."]},{"heading":"Catch Me Who Can","paragraphs":["In 1808 Trevithick decided to show off his invention to the people of London, the biggest and richest city in Britain. He had a new locomotive built by the engineers John Hazledine and John Urpeth Rastrick at their foundry in Bridgnorth, Shropshire. It weighed about 8 tons, and it had a cheeky name: 'Catch Me Who Can'.","Trevithick set up what was called a 'steam circus' on open ground in Bloomsbury, close to where Euston Square is today. Land here is now covered by buildings of University College London. He laid a circular track about 100 feet (around 30 metres) across and surrounded it with a tall wooden fence, so that people had to pay to come in. Trial runs began in July 1808. For one shilling, visitors could watch the engine running round and round, or even ride in an open carriage pulled behind it.","Imagine the scene: Londoners in top hats and long dresses paying their shilling, stepping through the gate, and climbing into a carriage behind a hissing iron machine. Then, with a puff and a jolt, they are off, rattling around the ring faster than many of them had ever travelled. Reports say the engine reached about 12 miles per hour on the tight circle, and Trevithick believed it could manage 20 miles per hour on a straight track. A ticket card from the circus survives, with a picture of the engine and the slogan 'Mechanical Power Subduing Animal Speed'.","Sadly, the circus was a short-lived show. The ground was soft, and the iron rails kept breaking under the heavy engine. Trevithick replaced them with thick timber beams, but within about two months a broken rail caused the engine to come off the track. Visitor numbers had been disappointing anyway, and Trevithick could not afford to repair everything. The steam circus closed. Catch Me Who Can was the last railway locomotive he ever designed."]},{"heading":"Why the Pioneer Never Got Rich","paragraphs":["You might expect the man who built the world's first railway locomotive to have become rich and famous. Trevithick did not. Part of the reason was the track: until rails strong enough for heavy engines were made, his locomotives broke more than they saved. Part of it was his own restless character. He was full of ideas, but once he had shown that something could be done, he often lost interest and rushed on to the next project, without the patient business sense needed to make money from it.","And there were plenty of other projects. From 1805 he worked on a tunnel under the River Thames at Rotherhithe, digging a small trial passage beneath the river. In December 1807 and January 1808 the river burst in, and Trevithick nearly drowned. The project was abandoned. He designed steam dredgers to clear rivers, iron tanks for storing water on ships, and even engines for boats. In 1810 he fell seriously ill with typhoid, and in February 1811 he and his business partner Robert Dickinson were declared bankrupt.","Then came the greatest adventure of all. Silver mines high in the Andes mountains of Peru, around Cerro de Pasco, were flooded, and their owners wanted Trevithick's compact high-pressure engines to pump them out. In October 1816 he sailed from Penzance to South America, hoping to make his fortune. For a while it seemed he might. But wars of independence were sweeping the continent, and mines and machinery were wrecked in the fighting. Trevithick even served for a time with the army of the revolutionary leader Simón Bolívar. He later explored for minerals in Costa Rica and struggled through jungles and rivers in search of a route home.","In 1827, in the port of Cartagena in what is now Colombia, penniless and exhausted, Trevithick met by chance another British engineer: Robert Stephenson, the young son of George Stephenson, who was on his way home from mining work in South America. Robert Stephenson gave Trevithick 50 pounds to pay for his passage. Trevithick arrived in Falmouth, Cornwall, in October 1827 with almost nothing but the clothes he wore. He had been away for eleven years.","He spent his last years still inventing, and asking the government for a reward for his work, without success. He died of pneumonia on 22 April 1833 at the Bull Inn in Dartford, Kent, where he had been working on a new engine. He had no money, and no family were at his bedside. Workers from the local engineering works where he had been employed paid for his funeral and carried his coffin. He was buried in an unmarked grave in Dartford, where a plaque now remembers him.","Today Trevithick is far better remembered. A bronze statue of him stands in Camborne, holding a model of his engine. Merthyr Tydfil has a monument to the 1804 journey. A memorial window in Westminster Abbey honours him. And every year Camborne celebrates Trevithick Day with steam engines puffing through the streets. Railway historians agree that, whatever came later, Richard Trevithick built the first locomotive to run on rails."]},{"heading":"Proof That It Could Be Done","paragraphs":["Let us count up what Trevithick achieved between 1801 and 1808. He proved that a high-pressure steam engine could be made light and strong enough to move itself. He proved that it could carry people up a steep hill, and pull 10 tons of iron and 70 men along a track. He worked out safety devices to tame dangerous high-pressure boilers. He noticed how exhaust steam could fan the fire. And he showed thousands of Londoners that riding behind a steam engine was possible, and even fun.","What he had not done was make it work every day. His engines were too heavy for the brittle cast-iron plates and wooden rails of the time, and they were not yet reliable enough to replace horses year after year. Those were problems of track, grip, cost and patient improvement.","Trevithick had shown it could be done. Now, in the coalfields of northern England, around Leeds and Newcastle, colliery engineers with heavy loads to shift, plenty of cheap coal, and short tracks of their own were about to take his idea and make it work, day after day, in all weathers."]}],"deepDive":"Historians agree that the Penydarren locomotive of 21 February 1804 is the first steam locomotive known for certain to have hauled a load on rails, but the details reward careful reading. Different sources give the distance as about 9 to 9.75 miles and the time as roughly four hours, which implies an average of only about 2.4 mph; higher figures of close to 5 mph refer to the engine's speed on good stretches, not the whole trip, which included stops to clear the line. The Coalbrookdale engine of 1802 complicates the 'first' question: a drawing and a letter suggest a small locomotive was built, but there is no firm evidence it ever ran, so most historians credit Penydarren. Equally debated is why Trevithick's breakthrough did not catch on immediately. The usual answer is the track. His engines weighed about 5 to 8 tons, while cast-iron plateways had been designed for horse wagons of a few tons, and cast iron is strong when squeezed but weak when bent or struck. Only when stronger rails appeared, especially rolled wrought-iron rails from 1820, did heavy locomotives become practical. A second factor is economics. During the Napoleonic Wars horse fodder became very expensive, which later made locomotives attractive to colliery owners; in 1804 horses were still cheap enough. Third, Trevithick's own business choices mattered: he patented his high-pressure engine in 1802 but did not build a business around locomotives, preferring new challenges. Some historians also stress his contribution to stationary power, arguing that his high-pressure 'Cornish' boiler and engine work were even more important to industry than his locomotives. Finally, there is the question of the blastpipe. Trevithick clearly noticed that exhaust steam sent up the chimney increased the draught, but whether he deliberately designed a blastpipe or simply observed the effect is still debated, and several engineers, including Timothy Hackworth and George Stephenson, later developed the idea further.","funFact":"A replica of Trevithick's Penydarren locomotive built in 1981 cracked its rails just like the original did in 1804, proving that the problem really was the track and not the storytellers.","check":{"q":"What happened on 21 February 1804 at Penydarren in South Wales?","a":"Trevithick's steam locomotive hauled about 10 tons of iron and about 70 men along a tramroad, the first known locomotive to haul a load on rails","wrong":["George Stephenson's Rocket won a race against a horse","The first underground railway opened beneath Merthyr Tydfil","Trevithick's Puffing Devil burned down after being left unattended"]},"sources":[{"title":"Richard Trevithick's steam locomotive","publisher":"People's Collection Wales","url":"https://www.peoplescollection.wales/content/richard-trevithicks-steam-locomotive"},{"title":"Richard Trevithick","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_Trevithick"},{"title":"Puffing Devil","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Puffing_Devil"},{"title":"Catch Me Who Can","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Catch_Me_Who_Can"},{"title":"Andrew Vivian","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Andrew_Vivian"},{"title":"Penydarren","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Penydarren"}],"photos":[{"src":"img/deep/railways/04-1.jpg","alt":"Working replica of Trevithick's 1804 Penydarren locomotive, with its huge flywheel, at the National Waterfront Museum, Swansea.","file":"Replica of Trevithick's Penydarren locomotive - 2022-08-22.jpg","url":"https://commons.wikimedia.org/wiki/File:Replica_of_Trevithick%27s_Penydarren_locomotive_-_2022-08-22.jpg","author":"The wub","license":"CC BY-SA 4.0"},{"src":"img/deep/railways/04-2.jpg","alt":"Ticket picture of Trevithick's 'Catch me who can' (1808): 'Mechanical Power Subduing Animal Speed', with handwritten notes.","file":"WP Catch Me Who Can - Eintrittskarte.jpg","url":"https://commons.wikimedia.org/wiki/File:WP_Catch_Me_Who_Can_-_Eintrittskarte.jpg","author":"unbekannter Grafiker, definitiv vor über 70 Jahren verstorben","license":"Public domain"},{"src":"img/deep/railways/04-3.jpg","alt":"The bronze statue of Richard Trevithick outside the library in Camborne, Cornwall, his home town.","file":"Statue of Richard Trevithick, Camborne (9625246249).jpg","url":"https://commons.wikimedia.org/wiki/File:Statue_of_Richard_Trevithick,_Camborne_(9625246249).jpg","author":"Tim Green from Bradford","license":"CC BY 2.0"}],"words":3827},{"n":5,"title":"The Colliery Engines","when":"1812 – 1824","summary":"In the coal mines of northern England, engineers built the first steam engines that worked every single day. One climbed along a track with teeth, one called Puffing Billy proved smooth wheels could grip smooth rails, and a young man who learned to read at 18 built his first engine. Their names were Salamanca, Puffing Billy and Blücher.","sections":[{"heading":"Why the Coal Mines Came First","paragraphs":["Imagine standing beside a muddy wagonway in Yorkshire in the spring of 1812. Coal wagons creak past on rails, each one pulled by a tired horse with steam rising from its back. A boy walks beside each horse. Behind you are the pits, where men and children dig coal out of the dark. Ahead, a few miles away, is the busy town of Leeds, where every kitchen fire, every forge and every new factory steam engine is hungry for coal. The horses plod back and forth all day, and every one of them has to be fed.","Richard Trevithick had already shown, back in 1804, that a steam locomotive could pull a load along rails. But his engines broke the track and never settled into regular work. The next big step happened in a very particular kind of place: the coal mines of northern England. There were good reasons for that, and they are worth looking at one by one, because they explain why railways were born in coalfields and not in big cities.","First, coal mines already had tracks. As you saw in Part 2, wagonways had been carrying coal on wooden and then iron rails for two hundred years. A mine owner who wanted to try a locomotive did not have to buy land, ask Parliament for permission or build a brand-new route. The track was already there, running from the pit to a river or canal.","Second, the loads were heavy and they went the same way every day. A mine might send hundreds of tons of coal down the same few miles of track, from the same pit to the same riverbank. That is the perfect job for a machine. A locomotive does not need to be clever or fast. It just needs to be strong and to keep going.","Third, the fuel was free, or nearly free. A steam engine eats coal, and a coal mine has mountains of it, including small broken pieces that were hard to sell. The locomotive could burn the mine's own leftovers.","Fourth, mines had skilled engine men. Collieries had used big stationary steam engines to pump out water since the days of Thomas Newcomen. Every big pit had an engine-wright, a mechanic in charge of the engines, plus blacksmiths and fitters who knew how to mend boilers, pistons and valves.","And fifth, horses had become very expensive. From 1803 to 1815 Britain was at war with Napoleon's France. Armies needed huge numbers of horses, and the price of horses and of the oats and hay to feed them shot up. A mine with dozens of horses was spending a fortune every week. Suddenly a machine that ate cheap coal instead of costly oats looked very attractive."]},{"heading":"Salamanca and the Railway with Teeth","paragraphs":["The first place where steam locomotives went to work and stayed at work was the Middleton Railway, which carried coal from the pits at Middleton to the edge of Leeds. It was already an old and special line. In 1758 the mine owner Charles Brandling got an Act of Parliament to protect his wagonway, making Middleton the first railway in the world to be given powers by an Act of Parliament. For more than fifty years horses did all its work.","The mine's manager, or agent, was a man named John Blenkinsop. He knew about Trevithick's locomotives and he knew their big weakness. People in those days believed that if you put smooth iron wheels on smooth iron rails, the wheels would simply spin, like a car's tyres on ice, and the engine would go nowhere with a heavy load behind it. They thought you would have to make the engine very heavy to press the wheels down hard enough to grip, and a very heavy engine would smash the brittle cast-iron rails. Trevithick had seen exactly that happen.","Blenkinsop came up with a clever answer, which he patented in 1811. Along one side of the track he laid a special rail with teeth sticking out of it, like a long straight comb. On the locomotive there would be a big cog wheel, a wheel with teeth around its edge, which would mesh with the toothed rail. As the cog turned, its teeth pushed against the teeth on the rail, so the engine pulled itself along like a gear wheel climbing a ladder. It could not slip, and it did not need to be heavy. This idea is called a rack and pinion: the rack is the toothed rail and the pinion is the cog.","To build the engine, Blenkinsop turned to Matthew Murray, one of the finest engineers in Leeds. Murray ran a works at Holbeck, in partnership with others, that made steam engines and textile machinery. His locomotive, built in 1812, was named Salamanca, after the Duke of Wellington's victory over the French at the Battle of Salamanca in Spain that same year. Naming a new machine after a famous battle was a way of making it feel exciting and patriotic.","Salamanca weighed only about 5 tons. It had a single boiler with a flue running through the middle to carry the hot gases from the fire, and it was the first locomotive to have two cylinders instead of one. The two cylinders sat on top of the boiler, each 8 inches across, and they drove the big cog wheel through cranks. With two cylinders working one after the other, the push was smoother and the engine could always start, whatever position its cranks had stopped in. The cog was on the left side of the engine and the rack rail ran along the outside of the track. The ordinary wheels just rolled along to carry the weight.","Salamanca started work in 1812, and this time it was not a demonstration or a fairground ride. It went to work hauling coal, day after day, and the mine saved money doing it. That is why historians call Salamanca the first commercially successful steam locomotive: the first one that earned its keep in regular business. Four locomotives of this type were eventually built for the Middleton Railway, and some of them worked for many years. Much later, in 1829, one locomotive on the line was recorded pulling thirty loaded coal wagons weighing about 140 tons.","There were sad moments too. Around 1818 Salamanca's boiler exploded. George Stephenson later told a committee of Parliament that the driver had tampered with the safety valve, the device that lets out steam when the pressure gets too high. Holding a safety valve shut to get a little more power was a deadly habit in the early days, and you will meet it again in later parts of this story.","The rack idea did not become the normal way to run a railway, because toothed rails were expensive to make and wore out. But it never disappeared. Today rack railways climb steep mountains all over the world, in Switzerland, in Wales up Snowdon, and elsewhere, using the same basic idea as Blenkinsop. And the Middleton Railway itself is still running. Since 1960 volunteers have operated it as a heritage railway, so you can still ride trains along the route where Salamanca once worked."]},{"heading":"Puffing Billy and the Great Grip Question","paragraphs":["About 80 miles north of Leeds, on the banks of the River Tyne west of Newcastle, lay the village of Wylam and its coal mine. Wylam Colliery belonged to Christopher Blackett, a wealthy and curious man who had actually ordered a locomotive from Trevithick's designs years earlier, though it was never used on his line. His wagonway ran about five miles from the pit to the river at Lemington, where the coal was loaded onto boats. Blackett had already replaced the old wooden rails with iron plate rails, which gave him a stronger track to experiment on.","Blackett's colliery viewer, meaning the manager who looked after the running of the mine, was William Hedley, born in 1779 at nearby Newburn. Hedley was not willing to simply accept what everybody said about smooth wheels. Did iron wheels on iron rails really slip uselessly, or had nobody actually measured it properly? He decided to find out.","Hedley built a test carriage, a wagon whose wheels could be turned by men working handles, like a giant hand-cranked toy. He loaded it with different weights and coupled loaded coal wagons behind it, then watched carefully to see when the wheels would slip and when they would grip. His experiments showed something wonderful: as long as the engine itself was heavy enough, the friction between plain iron wheels and plain iron rails was enough to pull a useful train of wagons. This grip is called adhesion. Hedley did not need teeth, cogs or any other complicated trick. He just needed a properly weighted engine with all its wheels driven.","Now Hedley needed a real locomotive. He worked with two highly skilled men from the colliery: Jonathan Forster, the engine-wright, and Timothy Hackworth, the foreman blacksmith, who was born in Wylam in 1786. Historians today think Hackworth did a great deal of the hands-on engineering, though Hedley usually gets the main credit as the designer. Between 1813 and 1814 the three of them built the engine that became famous as Puffing Billy.","Puffing Billy looks strange to modern eyes. It has a fat, round boiler lying on its side, and two tall upright cylinders standing on either side, with long beams rocking up and down above them like the arms of a see-saw. Those beams worked rods that turned a crankshaft, and a set of gear wheels passed the power to the road wheels, so that all of them were driven. The engine weighed about 8 tons without its tender, and the boiler worked at a pressure of about 50 pounds per square inch. Its top speed was only about 5 mph (8 km/h), around the speed of a brisk walk, but speed was not the point. Strength was.","Its weight caused trouble, just as Trevithick's had. The cast-iron plates of the Wylam wagonway kept cracking. Hedley's solution was to spread the load over more wheels. The engines were rebuilt to run on eight wheels, so each wheel pressed down less hard on the brittle plates. Around 1830, when the wagonway was relaid with stronger edge rails, Puffing Billy went back to running on four wheels, which is how you can see it today.","Puffing Billy kept working until 1862, almost fifty years. That year it was lent to the Patent Office Museum in South Kensington, London, which later grew into the Science Museum, and the museum later bought it for £200. It is the oldest surviving steam locomotive in the world, and it stands in the Science Museum in London today. There is even a suggestion that the old English phrase 'puffing like Billy-o', meaning puffing very hard, might come from this engine's name, though nobody can prove that for certain."]},{"heading":"The Boy Who Learned to Read at Eighteen","paragraphs":["Right beside that same Wylam wagonway stood a small stone cottage. On 9 June 1781 a baby named George Stephenson was born there. His father, Robert, worked as a fireman for a colliery pumping engine, stoking its fire for very low pay. Neither of George's parents could read or write, and the family was too poor to send him to school. As a small child he would have seen horses pulling coal wagons right past his front door.","George started work while still a young boy, first minding cows, then picking stones out of coal. As he grew, he moved up to jobs around the colliery engines: helping his father, then working as an engineman and as a brakesman, the person who controlled the winding engine that lifted men and coal up and down the mine shaft. He loved machines. He took engines apart in his spare time to understand exactly how each part worked, and he could often spot a problem that puzzled other men.","But George had a problem of his own. At 17 he still could not read. He realised that the newest ideas about engines were written down in books, and he could not open them. So, at about 17 or 18, he paid out of his own small wages for night classes in reading, writing and arithmetic, sitting with much younger children to learn his letters. Imagine being a strong, grown young man who works hard all day at the pit, then going to school in the evening to learn the alphabet. It took real courage and determination.","In 1802 he married Frances Henderson, and in 1803 their son Robert was born at Willington Quay on the Tyne. To earn extra money George mended shoes and repaired clocks and watches in the evenings. Then tragedy struck: Frances died of tuberculosis in 1806. George was left to bring up little Robert, and he was determined that his son would get the education he had missed. Robert was later sent to a good school in Newcastle, and he would often read books and bring knowledge home to share with his father. The two of them became an extraordinary team, as you will see in the next few parts.","George's big break came at Killingworth, a group of collieries north of Newcastle. The pumping engine at one pit, called High Pit, could not keep the water out, and the experts could not fix it. Stephenson offered to try. After he rebuilt and adjusted it, the engine pumped the pit dry. The owners were so impressed that around 1811 or 1812 they made him engine-wright for all of their collieries, in charge of every engine they owned. The illiterate teenager had become one of the most trusted mechanics in the coalfield."]},{"heading":"Blücher: Stephenson's First Locomotive","paragraphs":["At Killingworth, Stephenson studied every locomotive he could. He knew about Trevithick's work, he went to see Blenkinsop's engines, and he knew what was happening at Wylam, a few miles from where he grew up. The owners of Killingworth, a partnership of wealthy coal owners known as the Grand Allies, agreed to pay for him to build a 'travelling engine', as locomotives were often called then.","His first famous locomotive was named Blücher, after the Prussian general Gebhard von Blücher, who was fighting against Napoleon alongside Britain. It first ran on 25 July 1814 on the Killingworth wagonway. Some recent historians think an earlier Stephenson engine, called My Lord, may have run slightly before it, but Blücher is the engine people remember.","Blücher worked by adhesion, like Puffing Billy, with no rack or cog. It could pull a train of loaded wagons weighing about 30 tons up a gentle slope at about 4 mph (6.4 km/h). That was not dramatic, but it was useful work. Like other early engines, its two cylinders were set into the boiler, and it used gears to pass the power to the wheels.","Stephenson kept improving. One thing he did was to send the used steam from the cylinders up the chimney. As the steam rushed out, it dragged air through the fire, making it burn hotter so the boiler made more steam. Other engineers, including Trevithick, had noticed this effect too, and who should get credit for the best version of this blastpipe is a story for Part 7. In 1815 Stephenson, with a partner, patented a way to connect the cylinders' rods more directly to the wheels, getting rid of most of the noisy gears.","Stephenson's reputation grew. In 1822 he engineered the Hetton colliery railway in County Durham, about 8 miles (13 km) long. It was the first railway designed from the start to work without any animal power at all. On the flat sections, Stephenson locomotives pulled the wagons. On the steep hills, fixed steam engines at the top hauled wagons up on ropes. On some downhill stretches, called self-acting inclines, the heavy loaded wagons rolling down pulled the empty wagons back up, using nothing but gravity. It opened on 18 November 1822 and showed that an entire railway could run on machines and gravity alone."]},{"heading":"Iron That Bends Instead of Breaking","paragraphs":["By now you will have noticed a pattern. Trevithick's engine cracked the rails at Penydarren. Puffing Billy cracked the plates at Wylam and had to be given extra wheels. Every early locomotive builder ran into the same wall: the track was too weak for the engines. If railways were ever going to carry heavy locomotives every day, they needed better rails.","The trouble was the kind of iron. Most early rails were made of cast iron, which is iron melted until it is runny and poured into a mould shaped like the rail. Cast iron is cheap and easy to shape, and it is very strong when you squash it. But it contains a lot of carbon, which makes it brittle. Give it a sharp knock or bend it, and instead of bending it snaps, a bit like a biscuit. Each cast rail was also short, usually only about 3 or 4 feet long, because longer castings were more likely to break. That meant a joint every few steps, and every joint was a bump that hammered the wheels and the rail ends.","There was another kind of iron, called wrought iron, meaning 'worked' iron. It is made by heating iron and hammering, stirring and rolling it to squeeze out most of the carbon and slag. Wrought iron is tough and a little bendy. If you hit it hard, it dents or bends instead of shattering. Blacksmiths had always used it for horseshoes, chains and tools. The problem was making it in long, rail-shaped pieces.","The answer came from Bedlington Ironworks in Northumberland, not far from Killingworth. There, an engineer named John Birkinshaw worked out how to make rails by passing red-hot wrought iron between rollers with specially shaped grooves, squeezing it into the right cross-section. In 1820 he patented this method. His rails came in lengths of about 15 feet, four or five times longer than typical cast rails, so there were far fewer joints. They were also made in a 'fish-bellied' shape, deeper in the middle between supports where the bending force is greatest, and shallower at the ends, so that the metal was put exactly where it was needed most.","George Stephenson saw at once how good these rails were, and he recommended them for the next big railway he worked on, even though he himself held a share in a patent for cast-iron rails and would earn money if cast iron were chosen. That honest choice cost him money and, it is said, upset his business partner in the cast-iron patent. But he knew that wrought iron was the future. Birkinshaw's invention has been called a vital breakthrough for the young railways, because from then on track could grow stronger as engines grew heavier. Later in the century, wrought iron would itself be replaced by steel, which is tougher still."]},{"heading":"Two Lamps and a Dangerous Gas","paragraphs":["Locomotives were not the only thing George Stephenson invented at Killingworth. In the same busy years he also designed a safety lamp for miners, and the story of that lamp shows how hard it can be to say who invented something first.","Deep coal mines contain a gas that miners called firedamp. It is mostly methane, the same gas used in many kitchen cookers today. Firedamp seeps out of the coal, and when it mixes with air in the right amount, a single flame can make it explode. In those days the only light underground came from candles and open-flamed lamps, so every miner was carrying a possible spark into a possible bomb. On 25 May 1812, an explosion at Felling Colliery near Gateshead killed 92 people, including boys as young as 8. The disaster shocked the country. A group of local clergy, doctors and mine owners formed the Sunderland Society to find ways of preventing such accidents, and one of their big hopes was a lamp that could not set off firedamp.","Stephenson had been experimenting carefully for years, holding candles near places where gas leaked out in the mine and watching how the flame behaved. He noticed that if the air reaching a flame came in only through very narrow passages, a flame could not travel back out through them. In 1815 he had a lamp made to his design. It was delivered on 21 October, and he bravely tested it in the mine where firedamp was present. He improved it with small tubes at the base to let air in, tested new versions in November, and showed it to the Literary and Philosophical Society of Newcastle on 5 December 1815. His lamp had a glass chimney around the flame, which let out plenty of light. If the gas became too strong, the lamp simply went out.","At the very same time, in London, the famous chemist Sir Humphry Davy was working on the same problem. Davy studied flames scientifically and found that a fine metal gauze, a mesh of thin wire, would let air in but cool any flame trying to pass through it so much that it could not ignite the gas outside. His Davy lamp, also from 1815, surrounded the flame with a cylinder of this gauze.","A fierce argument followed. Davy was a celebrated scientist, and he and his supporters believed that a self-taught colliery mechanic could not possibly have worked out the principle on his own, so Stephenson must have heard of Davy's ideas. Stephenson's supporters pointed to his earlier tests and to the dates. A committee in Newcastle looked into Stephenson's claims and cleared him of copying, and he was given a reward of £1,000. Davy received about £2,000 worth of silver from a public collection, plus a medal from the Royal Society. Much later, in 1833, a committee of the House of Commons decided that Stephenson had an equal claim to the invention. Davy, it is said, died believing he had been copied.","The fair way to tell this story is that two people, working separately with different methods, arrived at similar answers in the same year. That happens surprisingly often in the history of invention, because when a problem is urgent and the tools are ready, more than one clever mind goes looking for the solution. Stephenson's lamp, later improved with some of Davy's gauze, became known as the Geordie lamp and was used in the mines of north-east England for most of the nineteenth century. Some people think the nickname 'Geordie', used today for people from Tyneside, may be linked to the miners who used Stephenson's lamp, but that is only one of several ideas and nobody knows for sure."]},{"heading":"What the Colliery Engines Proved","paragraphs":["Step back and look at what happened between 1812 and the early 1820s. In about ten years, a handful of engineers in coal-mining districts turned the steam locomotive from a risky experiment into an everyday working machine. Salamanca proved that a locomotive could earn money in regular work. Puffing Billy and Hedley's tests proved that plain wheels on plain rails had enough grip, so railways would not need expensive toothed rails. Stephenson's Killingworth engines proved that a self-taught engine-wright could keep improving the design, year after year, and Hetton proved that a whole line could run without horses. Birkinshaw's rolled wrought-iron rails gave the engines a track strong enough to carry them.","By the early 1820s, then, the question was no longer 'Can a steam locomotive work?' It was 'Could locomotives work on a long railway, open to everyone, connecting towns?' Some people had a very practical reason to want the answer to be yes. About 30 miles south of the Tyne, in the market town of Darlington, a careful Quaker businessman named Edward Pease was studying maps and sums. Coal from the rich pits of south-west Durham was trapped inland, and getting it down to the River Tees at Stockton by horse and cart was slow and costly. Pease was looking for a cheaper way to move that coal to the river, and he was about to find George Stephenson."]}],"deepDive":"Why did so many engineers believe smooth wheels would slip? The physics of adhesion explains both the fear and the answer. The pulling force a driven wheel can transmit before it slips is roughly the weight pressing on it multiplied by the coefficient of friction between wheel and rail. For clean, dry iron or steel on iron or steel, that coefficient is usually around 0.2 to 0.3, falling much lower when the rail is wet, greasy or covered in leaves. A locomotive with 8 tons resting on its driving wheels can therefore exert a pull of perhaps 1.6 to 2.4 tons before slipping. But the resistance of a wagon rolling on rails is tiny, only a few kilograms of force per ton on level track, so even that modest pull can move many tens of tons on the flat. Hedley's experiments in effect measured this balance. The trouble came on slopes, where gravity adds about 10 kilograms of resistance per ton for every 1 per cent of gradient, which is why early railways were laid as level as possible and why steep sections were handled by rope haulage or rack. Blenkinsop's rack sidestepped the problem by using positive engagement, the same principle as a gear, so the pull no longer depended on weight; that let Salamanca be light enough, at around 5 tons, not to break cast-iron rails. Hedley and Stephenson took the other path: make the engine heavy enough to grip, couple all the wheels together so all of the engine's weight counts, and then demand stronger track. That second path required a materials revolution. Cast iron, with roughly 2 to 4 per cent carbon, is strong in compression but weak and brittle in tension; a rail bending under a wheel load has its lower edge in tension, exactly where cast iron cracks. Wrought iron, with very little carbon and fibres of slag, could flex and deform without sudden failure, and Birkinshaw's rolling process produced it in long uniform lengths. Historians still debate credit in this period. Hackworth's role in Puffing Billy is probably under-recognised, Stephenson's early engines owed much to visits to Wylam and Leeds, and the Davy-Stephenson lamp quarrel was coloured by class prejudice against a self-taught mechanic. The safety lamp story also carries an uncomfortable lesson: by making some dangerous seams seem safer, safety lamps encouraged deeper and gassier workings, and explosions did not stop.","funFact":"Puffing Billy kept hauling coal at Wylam until 1862, by which time trains on main lines were already running at more than ten times its top speed of about 5 mph.","check":{"q":"What did William Hedley's experiments at Wylam show?","a":"That smooth iron wheels on smooth iron rails had enough grip to pull loaded wagons, if the engine was heavy enough","wrong":["That locomotives could only move using a toothed rack rail","That wooden rails were stronger than iron rails","That steam engines worked best when pulled by horses"]},"sources":[{"title":"'Puffing Billy' Locomotive with Tender and Rails","publisher":"Science Museum Group Collection","url":"https://collection.sciencemuseumgroup.org.uk/objects/co8247941"},{"title":"Salamanca (locomotive)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Salamanca_(locomotive)"},{"title":"Middleton Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Middleton_Railway"},{"title":"Puffing Billy (locomotive)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Puffing_Billy_(locomotive)"},{"title":"George Stephenson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Stephenson"},{"title":"John Birkinshaw","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Birkinshaw"},{"title":"Geordie lamp","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Geordie_lamp"},{"title":"Felling mine disasters","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Felling_mine_disasters"}],"photos":[{"src":"img/deep/railways/05-1.jpg","alt":"Puffing Billy (built 1813–14), the world's oldest surviving steam locomotive, with its upright cylinders and beams, Science Museum, London.","file":"Puffing Billy Side view London Science Museum.jpg","url":"https://commons.wikimedia.org/wiki/File:Puffing_Billy_Side_view_London_Science_Museum.jpg","author":"Slashme","license":"CC BY-SA 4.0"},{"src":"img/deep/railways/05-2.jpg","alt":"Drawing of Blenkinsop and Murray's 1812 rack locomotive: its toothed cog wheel grips teeth on the side of the rail.","file":"Blenkinsop's rack locomotive, 1812 (British Railway Locomotives 1803-1853).jpg","url":"https://commons.wikimedia.org/wiki/File:Blenkinsop%27s_rack_locomotive,_1812_(British_Railway_Locomotives_1803-1853).jpg","author":"1829 author unknown","license":"Public domain"},{"src":"img/deep/railways/05-3.jpg","alt":"Old book engraving: Davy's safety lamp (left) next to George Stephenson's safety lamp and its holed metal cover.","file":"Stephenson-safety-lamp.jpg","url":"https://commons.wikimedia.org/wiki/File:Stephenson-safety-lamp.jpg","author":"Samuel Smiles","license":"Public domain"}],"words":4383},{"n":6,"title":"Stockton & Darlington: A Railway for the Public","when":"1821 – 1830","summary":"In 1825 a puffing engine called Locomotion pulled a long, wobbly train full of coal and cheering people across the north of England. It was the first public railway to use steam engines. Thousands of people lined the track to watch, and the price of coal dropped so much that ordinary families could keep warmer.","sections":[{"heading":"Coal Trapped Inland","paragraphs":["In the early 1800s, south-west County Durham was sitting on a treasure. Around places like Witton Park, Etherley and West Auckland there were rich seams of coal. The trouble was getting it out to the world. The nearest good place to load coal onto ships was Stockton, on the River Tees, more than 20 miles away. From there, ships could carry it down the coast to London and other big markets. But between the pits and the river lay hills, farmland and rough roads, and moving coal by horse and cart was painfully slow and expensive. By the time a cartload reached Stockton, the cost of the journey had made the coal pricey.","People had been trying to fix this problem for a long time. In 1767 and again around 1815 there were plans for a canal, a man-made waterway on which horses could tow heavy barges. Canals were the great transport invention of the 1700s, and a single horse could pull a barge carrying many tons of cargo. But canals are hard to build through hilly country, because water must be kept level, so they need locks, the gated steps that lift boats up and down. The canal plans kept running out of money or support.","A new idea started to win people over: a railway. Horses could pull loaded wagons along a smooth iron track almost as efficiently as along a canal, and a track could climb hills that a canal could not. The engineer George Overton, who had built horse tramroads in South Wales, surveyed a route and recommended one.","The man who did more than anyone to make it happen was Edward Pease of Darlington. Born in 1767, Pease ran a family woollen business and was a member of the Religious Society of Friends, usually called Quakers. Quakers were known for plain clothes, plain speaking, honesty in business and a strong sense of duty. Many Quaker families in Darlington were bankers and merchants who trusted one another and invested together. At a public meeting in Darlington on 13 November 1818, Pease spoke up for the railway and promised investors a five per cent return on their money. He put in £7,000 of his own money, a very large sum then, and so many Quaker families followed him that the line became known as 'the Quaker line'."]},{"heading":"Parliament Says Yes, Stephenson Steps In","paragraphs":["In Britain, you could not build a long railway across other people's land just because you wanted to. You needed an Act of Parliament, a special law giving a company the right to buy the land it needed, even from owners who did not want to sell. Getting an Act meant months of argument in London, expensive lawyers and plenty of opponents.","The first attempt, in 1819, failed. Some powerful landowners did not want a railway across their estates (one nobleman, the story goes, was mainly worried about his fox-hunting grounds), and the bill was defeated by just 13 votes. The promoters changed the route to avoid the angriest landowners and tried again. This time there was no serious opposition, and the Stockton and Darlington Railway Act received royal assent, the monarch's formal approval, on 19 April 1821.","What the Act said is surprising. It treated the railway rather like a toll road. Anyone with suitable wagons could use the track, as long as they paid a toll, a fee charged per ton of goods per mile. That is why we call it a public railway: it was open to all, not just to one mine owner's wagons. And the Act did not mention steam locomotives at all. The planners imagined horses doing the pulling, as they had done for two hundred years.","There is a well-known story that on the very day the Act was passed, George Stephenson and his friend Nicholas Wood, a mining engineer from Killingworth, walked to Darlington to meet Pease at his home and offer their help. The details may have grown in the retelling over the years, but it is certain that Pease met Stephenson around this time and was deeply impressed by this plain-spoken engine-wright from the Tyne. Stephenson was sure that steam locomotives, not horses, were the future, and he invited Pease to come and see his engines for himself.","By July 1821 the company had decided two important things. First, the line would use edge rails, the kind where flanged wheels ride on top of the rail, rather than the L-shaped plates of a plateway. Second, George Stephenson would resurvey the route. A survey means walking every yard of the land with measuring chains and instruments, working out the heights of hills and valleys, and planning where to dig and where to build up so that the track stays as level as possible. Stephenson's 18-year-old son Robert worked alongside him, carrying instruments, taking measurements and doing calculations.","On 22 January 1822 the shareholders officially made George Stephenson the railway's Engineer, at a salary of £660 a year, a handsome income for a man who had once picked stones out of coal for pennies. Overton played no further part. A few months later, on 23 May 1822, there was a ceremony at St John's Well in Stockton, where the first rail of the line was laid.","In the summer of 1822 Edward Pease travelled north to Killingworth to see Stephenson's locomotives at work for himself. He came away convinced. Stephenson argued strongly for steam, and the company went back to Parliament. A new Act, which received royal assent on 23 May 1823, approved some changes Stephenson had made to the route and, importantly, allowed the company to use 'loco-motives or moveable engines'. For the first time, a public railway had legal permission to run steam locomotives.","Stephenson made another brave choice about the rails, which you met at the end of Part 5. He recommended John Birkinshaw's tough, rolled wrought-iron rails, even though he owned a share in a patent for cast-iron rails. In the end both kinds were used: most of the line was laid with wrought-iron rails weighing 28 pounds per yard, while about 4 miles, mostly at junctions where the shapes were complicated, used heavier cast-iron rails."]},{"heading":"The Width That Conquered the World","paragraphs":["One of Stephenson's decisions on the Stockton and Darlington would echo around the planet for the next two hundred years: the gauge, the distance between the inner edges of the two rails.","Stephenson did not sit down and calculate a perfect width. He simply used what he knew. The colliery wagonways of north-east England, including his own Killingworth line and the Hetton railway, were laid about 4 feet 8 inches apart, to fit the coal wagons, called chaldron wagons, that the mines already used by the thousand. Building to the same gauge meant those wagons and the skills of the men who worked them could fit straight onto the new line. So the Stockton and Darlington opened with a gauge of 4 ft 8 in (about 1,422 mm).","Soon afterwards, on his next big railway, the Liverpool and Manchester, Stephenson added an extra half inch, making 4 ft 8½ in (1,435 mm). The extra space gave the wheels a little more freedom to move sideways, so they were less likely to bind and jam on curves. The Stockton and Darlington eventually changed to the new measurement too. Because Stephenson and his pupils built so many of Britain's early railways, his gauge spread everywhere. When Parliament settled a fierce battle between gauges in 1846, a story you will hear in Part 8, it chose 4 ft 8½ in as the law for new passenger lines in Great Britain. Today it is called standard gauge, and it is used by about half or more of all the world's railways, from Britain to China and North America.","You may have heard a popular story that the standard gauge comes from the width of Roman chariots, so that a modern train is somehow measured by the backsides of two Roman horses. It is a fun tale, but it is a myth. The real chain is much shorter and simpler. Stephenson took the gauge from the north-east colliery wagonways he worked on. Those wagonways had grown up to suit carts that a horse could pull between its shafts, and wheeled carts in many times and places ended up roughly that width because of the size of a horse, not because anybody copied Roman ruts."]},{"heading":"Building a Railway from Scratch","paragraphs":["The main line ran about 25 to 26 miles (roughly 40 km) from the collieries near Witton Park and Etherley in the west, past Shildon and Darlington, to the quay at Stockton, with short branch lines to places like Darlington town and Yarm. It was a single track, but with four passing places, called loops, in every mile, so that wagons going in opposite directions could get past each other.","Look closely at the track and you would notice something odd. There were no long wooden sleepers running across from rail to rail as there are today. Each rail sat on its own separate square block, so that horses could walk down the middle of the track without tripping. West of Darlington the blocks were made of stone; to the east, they were oak. The builders were clearly still expecting plenty of horses.","The western end of the line crossed two big hills, and here Stephenson used the trick he had used at Hetton. At the top of each hill, at Etherley and at Brusselton, stood a stationary steam engine, a fixed engine in an engine house. A long rope wound around a huge drum hauled the wagons up one side of the hill, and then they were lowered carefully down the other side. Locomotives worked only on the flatter sections further east.","Rivers needed bridges. Over the little River Gaunless, Stephenson designed one of the earliest iron railway bridges. At Darlington, the architect Ignatius Bonomi designed a handsome stone bridge over the River Skerne. The Skerne Bridge still carries trains today and is thought to be the oldest railway bridge in the world that has been in continuous use. A picture of it even appeared on the back of Bank of England £5 notes from 1990 to 2002.","Building all this cost far more than anyone had estimated, which is a habit railway projects have kept ever since. By September 1825, just before opening, the company had borrowed £60,000 in short-term loans to keep going, and the following year Edward Pease had to lend money twice so that the workers could be paid."]},{"heading":"The World's First Locomotive Factory","paragraphs":["If the railway was going to use locomotives, someone had to build them. Until now, locomotives had been one-off machines, made by colliery blacksmiths or general engineering workshops in between other jobs. In 1823, George Stephenson, his son Robert, Edward Pease and another Quaker, Thomas Richardson, set up a new firm in Forth Street, Newcastle upon Tyne. They called it Robert Stephenson and Company, after the 19-year-old son, and it was the first company in the world set up specifically to build railway engines. Putting Robert's name on the door was a sign of how much faith his father had in him.","Then, in June 1824, Robert sailed away. He took a three-year job running mines for a British mining company in Colombia, in South America. Historians still wonder whether he wanted adventure, wanted to step out of his famous father's shadow, or both. While he was away, others managed the works, including for a time Timothy Hackworth, the brilliant mechanic from Wylam. On his way home in 1827, waiting for a ship in Cartagena, Robert met a ragged, penniless traveller who turned out to be Richard Trevithick, the pioneer of Part 4. Robert gave him £50 to help pay for his voyage home. The man who built the first railway locomotive was rescued by the son of the man who would make railways famous.","The first engine to roll out of Forth Street for the Stockton and Darlington was originally to be named Active, but it became famous as Locomotion, later called Locomotion No. 1. It was a 0-4-0, meaning it had no small front wheels, four driving wheels, each about 4 feet across, and no small rear wheels. It weighed about 6.5 tons and could reach about 15 mph. Its boiler had just one big flue, a single wide tube carrying the fire's heat through the water, which was a weakness, since it could not make steam very quickly. But it had one important new feature: it is believed to be the first locomotive to use coupling rods, the long bars on the outside that link the driving wheels together so they all turn at once. Coupling the wheels made it much less likely to slip. Locomotion left the works on 16 September 1825, just eleven days before the line was due to open."]},{"heading":"Opening Day: 27 September 1825","paragraphs":["Imagine the scene early on Tuesday 27 September 1825, near the bottom of Brusselton bank. Huge crowds have walked in from the countryside, some having set off in darkness. Men on horseback trot alongside the track. A train of wagons loaded with coal and a wagon full of sacks of flour has been hauled over the hills, partly by horses and partly by the stationary engine at Brusselton. Now, at Shildon, the star joins it: Locomotion, hissing and puffing, with George Stephenson himself at the controls.","Behind Locomotion came a long, extraordinary train. There were the coal wagons. There was a single passenger carriage, a boxy coach named Experiment, for the company's directors and important guests. And there were 21 brand-new coal wagons that had been fitted with simple seats for the public. The directors had planned room for about 300 passengers. Instead, people clambered on wherever they could, even sitting on top of the coal, and somewhere between 450 and 600 people rode. According to accounts of the day, a man on horseback carrying a flag rode in front of the engine at the start, to warn people out of the way.","The train set off towards Darlington. On a downhill stretch it reached perhaps 10 to 12 mph, faster than most passengers had ever travelled in their lives. Not everything went smoothly. One wagon lost a wheel and had to be left behind, and the train stopped for about 35 minutes while the locomotive was repaired. Still, about 10,000 people were waiting to cheer when it arrived at Darlington. The 8½ miles from Shildon had taken about two hours, including the stops. Six wagons of coal were handed out free to the poor of the town.","After a pause, the train set off again at about half past twelve for Stockton, now made up of 31 vehicles carrying around 550 people, with music and cheering along the way. Along the flat ground east of Darlington the heavily loaded train was slow, but near Stockton, where the track ran beside a road, it picked up speed to about 15 mph. It arrived at Stockton 3 hours and 7 minutes after leaving Darlington, greeted by more crowds and celebrations. That evening, 102 guests sat down to a grand celebration dinner in Stockton Town Hall.","The day was not perfect for everyone. One man was badly hurt when his foot was crushed between vehicles. And according to some accounts, the Pease family stayed away from the celebrations because they were in mourning after a death in the family. If so, the man who had done most to create the railway spent its greatest day in mourning."]},{"heading":"How the Line Really Worked","paragraphs":["It would be easy to imagine that after opening day, steam trains ran up and down the Stockton and Darlington just as they do on railways today. The reality was much messier, and much more interesting.","Remember that the line was a toll road for wagons. In its early years it was a mix of three kinds of power. Stationary engines hauled wagons over the hills at Etherley and Brusselton. Steam locomotives pulled some coal trains on the flatter parts. And horses, lots of horses, did much of the rest, pulling wagons owned by the company and by independent carriers who simply paid their tolls. The company even introduced a clever invention called the dandy wagon in 1828: a little cart hitched behind the coal wagons, in which the horse could ride downhill while gravity did the work, munching its hay. From late 1828 dandy wagons were compulsory, and people said the horses soon learned to jump in by themselves.","Passengers mostly travelled by horse, not steam. Regular passenger service began on 10 October 1825, with the coach Experiment pulled along the rails by a horse between Stockton and Darlington, at a fare of one shilling. Soon local innkeepers and businessmen were running their own coaches on the line, a little like stagecoaches on rails, cutting the journey to about 1 hour 15 minutes. Between July 1826 and June 1827, somewhere between 30,000 and 40,000 passengers rode the line. Regular steam-hauled passenger trains on the Stockton and Darlington did not arrive until the 1830s.","The locomotives themselves struggled at first. Locomotion broke a wheel soon after the opening and was not back at work until mid-October. A second engine, Hope, arrived in November 1825, and two more similar engines followed in 1826. They often broke down, and some of the directors began to wonder whether horses would have been cheaper after all. Then, in 1828, two boilers exploded, killing both drivers, after safety valves had been fixed down. One of them was Locomotion itself, whose boiler burst on 1 July 1828 at Aycliffe Lane, killing its driver, John Cree.","The person who rescued steam on the line was Timothy Hackworth, who became its locomotive superintendent in 1825 and lived at Shildon. In 1827 he built a much more powerful engine named Royal George, with six coupled wheels and an improved blastpipe that sent the exhaust steam straight up the chimney to make the fire roar. Royal George could haul far heavier trains than the earlier engines, and it helped prove that locomotives were worth it. In 1828 the company reported that steam was saving it about 30 per cent compared with horses.","Most important of all, the railway did what Pease had promised: it made coal cheaper. In the months after opening, the line carried about 10,000 tons of coal. The price of coal in Stockton fell from about 18 shillings a ton to 12 shillings, and by early 1827 to about 8 shillings and sixpence. Ordinary families could afford to heat their homes better, and factories could run their engines more cheaply. Coal shipped from Stockton rose from about 18,500 tons in the year to June 1827 to more than 52,000 tons the next year."]},{"heading":"A Town Born from a Railway","paragraphs":["Success brought growing pains. The quay at Stockton was too far up the twisting River Tees for big ships. So the company planned an extension further downstream, to a spot where there were just a few farm buildings, called Middlesbrough. The line opened on 27 December 1830, crossing the Tees on a suspension bridge. The bridge turned out to be too weak, its cast-iron plates splitting during a test, so trains had to cross in small groups of four wagons linked by chains. Hackworth's engine Globe hauled the first passengers across to new coal-loading staiths at a place called Port Darlington.","What happened next was astonishing. Before the railway, Middlesbrough had only a handful of houses. A year after the extension opened, more than 2,000 people lived there. Within a few decades it was a large industrial town making iron and steel. It was one of the first towns in the world created by a railway, and many more would follow.","So what was the Stockton and Darlington's place in history? It was not the first railway; wagonways were two hundred years old. It was not the first to carry fare-paying passengers; the Swansea and Mumbles had done that, with horses, since 1807. It was not the first to use steam locomotives in daily work; the Middleton Railway had done that since 1812, and Hetton had run without horses since 1822. What made it special was the combination. It was the first public railway, open to anyone and approved by Parliament, to use steam locomotives. It also showed businessmen everywhere that a railway could be a profitable investment, and it trained a whole generation of engineers and drivers. In 2025, its 200th anniversary was celebrated across north-east England, and a working replica of Locomotion made a journey to Stockton to mark the occasion. The original Locomotion is preserved too, and in recent years it has been shown at museums in both Shildon and Darlington.","News of the line travelled fast. More than 100 miles away, on the other side of England, two great cities were watching closely. Liverpool was a booming port, full of ships bringing raw cotton from America. Manchester, about 35 miles inland, was full of mills spinning that cotton into cloth. Moving goods between them by canal was slow, and the canal owners charged high fees. Merchants in Liverpool and Manchester decided to build a railway of their own, bigger and bolder than anything before it, and they hired George Stephenson to build it. But a hard question remained. Should their trains be pulled by locomotives, or by stationary engines and ropes? To decide which engine was best, they would hold a contest."]}],"deepDive":"Historians argue about how to label the Stockton and Darlington Railway, because almost every 'first' attached to it needs a qualifier. It was neither the first railway, nor the first passenger railway, nor the first to use locomotives, nor even the first designed to run without horses (Hetton, 1822). Its claim is the first public railway, built under an Act of Parliament and open to all users on payment of tolls, to use steam locomotives. Its business model was closer to a canal or turnpike than to a modern railway: the company owned the track and charged tolls capped by the 1821 Act at fractions of a penny per ton-mile, while private carriers ran their own horse-drawn wagons and coaches. That mixed traffic caused constant friction, because slow horse trains and faster locomotive trains shared a single line with passing loops and no signals, and it took until the 1830s for the company to take full control of operations. The economics are telling. The line's original purpose was to cut the cost of moving coal from the south-west Durham field to the Tees, and coal prices at Stockton fell by more than half in about eighteen months. Locomotives were not obviously better at first. Early engines like Locomotion had single-flue boilers with small heating surfaces and frequently ran short of steam, and two fatal boiler explosions in 1828 resulted from fixed-down safety valves. Hackworth's Royal George, with six coupled wheels and an effective blastpipe, shifted the balance, and the company's reported saving of about 30 per cent over horse haulage in 1828 suggests that by then steam was cheaper per ton-mile. Some later writers, including Hackworth's son, claimed the directors kept locomotives mainly because Pease and Richardson owned shares in the Stephenson works; the historians Tomlinson and Rolt considered this unfounded, pointing to evidence of genuine cost savings. The gauge story matters too. The line opened at 4 ft 8 in, inherited from local chaldron wagons, and the half inch was added on the Liverpool and Manchester to give extra play on curves. Network effects then did the rest: once enough track and rolling stock existed at one gauge, switching became too expensive, a classic case of an early technical choice being 'locked in' for centuries.","funFact":"The Skerne Bridge in Darlington carried the very first Stockton and Darlington train in 1825 and still carries trains today, making it probably the oldest railway bridge in continuous use in the world.","check":{"q":"On the early Stockton and Darlington Railway, how did most passengers travel?","a":"In coaches pulled along the rails by horses","wrong":["In steam-hauled express trains with sleeping cars","In electric trams powered by overhead wires","In carriages pulled by ropes from a canal boat"]},"sources":[{"title":"Stockton and Darlington Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Stockton_and_Darlington_Railway"},{"title":"Stockton and Darlington Railway","publisher":"Co-Curate, Newcastle University","url":"https://co-curate.ncl.ac.uk/stockton-and-darlington-railway"},{"title":"Locomotion No. 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Locomotion_No._1"},{"title":"Robert Stephenson and Company","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Stephenson_and_Company"},{"title":"Standard-gauge railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Standard-gauge_railway"},{"title":"Edward Pease (railway pioneer)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Edward_Pease_(railway_pioneer)"},{"title":"Robert Stephenson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Stephenson"},{"title":"Skerne Bridge","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Skerne_Bridge"}],"photos":[{"src":"img/deep/railways/06-1.jpg","alt":"The real Locomotion No. 1 of 1825, with its tall chimney, on display at the Head of Steam museum in Darlington.","file":"Stockton & Darlington Railway 0-4-0 No. 1 'Locomotion' (1825) Head of Steam, Darlington 30.06.2009 P6300119 (10192855826).jpg","url":"https://commons.wikimedia.org/wiki/File:Stockton_%26_Darlington_Railway_0-4-0_No._1_%27Locomotion%27_(1825)_Head_of_Steam,_Darlington_30.06.2009_P6300119_(10192855826).jpg","author":"Gillett's Crossing from Bristol, United Kingdom","license":"CC BY 2.0"},{"src":"img/deep/railways/06-2.jpg","alt":"John Dobbin's painting of the 1825 opening: crowds watch the first train cross the Skerne Bridge in Darlington.","file":"StocktonDarlingtonOpening.jpg","url":"https://commons.wikimedia.org/wiki/File:StocktonDarlingtonOpening.jpg","author":"John Dobbin","license":"Public domain"},{"src":"img/deep/railways/06-3.jpg","alt":"The stone Skerne Bridge in Darlington today, built in 1825 and one of the oldest railway bridges still in use.","file":"Skerne Bridge, Darlington, October 2014 01.JPG","url":"https://commons.wikimedia.org/wiki/File:Skerne_Bridge,_Darlington,_October_2014_01.JPG","author":"Edgepedia","license":"CC BY-SA 4.0"}],"words":3940},{"n":7,"title":"The Rainhill Trials and the Rocket","when":"October 1829","summary":"In 1829 a railway company held a race to find the best engine, and thousands of people came to watch. A horse on a treadmill, a speedy little engine called Novelty and a few others all broke down or dropped out. Only one locomotive, the yellow-and-black Rocket, finished every test and won the prize.","sections":[{"heading":"A Railway That Might Not Have Used Locomotives","paragraphs":["By the spring of 1829, a brand-new railway was creeping across the countryside of north-west England. It would link Liverpool, the great port where ships brought in raw cotton from across the Atlantic, with Manchester, the booming factory town about 30 miles inland where that cotton was spun and woven into cloth. Merchants had grown tired of paying high prices to the canal companies, whose barges were slow and whose owners knew they had little competition. A railway, they hoped, would be faster and cheaper. George Stephenson, fresh from the Stockton and Darlington, had been hired as its engineer.","But there was one enormous question that nobody had yet settled. What would actually pull the trains? Today that sounds like a silly question, because of course trains have locomotives. In 1829 it was not silly at all. Locomotives were still new, rare and unreliable. The few that existed in the coalfields broke down often, rattled along at a walking pace, and sometimes damaged the track. Many sensible engineers thought they were an interesting toy that would never be trusted with a busy main line.","There was a serious rival idea: stationary engines. Instead of putting a steam engine on wheels, you could build big steam engines in engine houses beside the line, every mile or two. Each engine would turn a huge drum that wound in a long rope or chain, and that rope would haul the wagons along to the next engine house, where they would be handed on to the next rope, like a relay race. This was called cable haulage, and it was a proven technology. Stationary engines had been hauling coal wagons up slopes for years, including on the Stockton and Darlington itself. On the Hetton colliery line in County Durham, which Stephenson himself had built, stationary engines and ropes did much of the hauling over the hills.","The directors of the Liverpool and Manchester Railway were split. Some backed Stephenson, who was absolutely certain that the moving locomotive was the future. Others worried that locomotives were too weak and too unreliable, and that the public was frightened of them. While the company had been asking Parliament for permission to build the line, it had quietly played down the idea of steam locomotives, because so many landowners and townspeople were alarmed by the thought of fire-breathing machines rushing past their homes.","To help them decide, the directors asked two experienced engineers, James Walker and John Urpeth Rastrick, to visit the railways of the north-east and report back. Their report, delivered in early 1829, did not give the clear victory Stephenson wanted. It weighed up costs and suggested that stationary engines might do the job well, though locomotives might improve in future. Stephenson argued back fiercely. A cable system, he pointed out, had a fatal weakness: if one engine or one rope failed, the whole line stopped, like a chain of people passing buckets where one person drops out. A locomotive that broke down could simply be replaced by another.","So the directors came up with a bold and very public solution. They would hold a competition. If inventors believed a locomotive could do the job, let them build one and prove it on the line, in front of judges and the whole watching world."]},{"heading":"The Rules of the Great Contest","paragraphs":["In April 1829 the directors announced a prize of 500 pounds for the best locomotive that met their conditions. That was a lot of money, roughly the cost of a substantial house at the time, and many tens of thousands of pounds in today's money. Even more valuable than the prize was what it might lead to: the winner could expect orders for many more engines from the railway.","The rules were strict, because the directors wanted a machine that could do real, everyday work, not just put on a show. Here are the main ones, as reported in accounts of the trials. The engine had to burn its own smoke, so it would not cover the countryside in soot; in practice this meant burning coke, a cleaner fuel made by baking coal. Its boiler pressure must not be more than 50 pounds per square inch, and it had to have two safety valves, one of which the driver could not tamper with. It had to stand on springs, and it could weigh no more than six tons, or four and a half tons if it ran on only four wheels. The finished engine had to cost no more than 550 pounds.","Then came the test itself. A flat, straight stretch of the new line at Rainhill, roughly 9 or 10 miles east of Liverpool, was chosen as the race track. Each engine would be weighed and then given a load of wagons equal to three times its own weight, counting its tender. It had to start with a cold boiler and no fire, so the judges could see how quickly it raised steam. Then it had to run up and down a measured course of one and three-quarter miles, which included an eighth of a mile at each end for speeding up and slowing down.","Ten trips made 35 miles, a little more than the distance from Liverpool to Manchester. The engine had to average at least 10 miles per hour. After the first ten trips it could stop to take on fuel and water, and then it had to do another ten trips, for a total of 70 miles. In other words, the directors were asking each engine to prove it could make a return journey between the two cities, pulling a heavy load, without falling to pieces.","Three judges would watch everything and record the times, the fuel used and the water used. They were John Rastrick, one of the authors of the report that had favoured stationary engines; Nicholas Wood, a mining engineer from Killingworth who knew Stephenson's early locomotives well; and John Kennedy, a Manchester cotton spinner who supported the railway. It was a fair mix: one doubter, one expert, and one businessman."]},{"heading":"A Day Out at Rainhill","paragraphs":["Imagine standing on a grassy bank beside the line at Rainhill on Tuesday 6 October 1829. It is a cool autumn morning. Thousands of people have come from Liverpool, Manchester and the villages around, by carriage, on horseback and on foot. Some estimates put the crowd at between 10,000 and 15,000 people over the most popular days. Grandstands have been put up for ladies and gentlemen. A band is playing. Men in top hats peer through telescopes, and engineers scribble figures in notebooks. Children perch on their fathers' shoulders to get a better view.","Many in the crowd have never seen a locomotive before. Newspapers have been printing stories about the contest for weeks, and reporters from London and abroad are there. Nobody quite knows what will happen. Will the engines explode? Will they work at all? Will a horse-drawn coach still be faster? It is part science experiment, part sporting event and part fairground.","The trials were supposed to last a few days, but breakdowns, repairs and arguments stretched them out from 6 to 14 October. Ten machines had been entered in all, but only five were ready to compete when the contest opened. Some never left their workshops. One was a carriage powered by two men, which plainly could not meet the rules. The five that did arrive were very different from one another, and each told a story about the different ideas engineers had about how a locomotive should be built."]},{"heading":"Meet the Contestants","paragraphs":["Rocket came from Newcastle upon Tyne, built at Robert Stephenson and Company, the locomotive factory the Stephensons had set up in 1823. It was a small, bright machine painted yellow and black, with a tall white chimney at the front and a barrel-shaped boiler lying behind it. Two cylinders were mounted on its sides at a steep angle, driving one pair of large front wheels, each about 4 feet 8 and a half inches across, with a pair of small wheels at the back. It weighed only about four and a quarter tons. To reach Rainhill, it was carried in pieces by horse-drawn wagons across northern England to Carlisle, then shipped down the coast to Liverpool and put back together.","Novelty was the surprise of the contest. It was built in London in a hurry by John Braithwaite, an engineer who made fire engines, and John Ericsson, a brilliant young Swedish inventor. It looked more like a neat little cart than an iron horse. It carried its water in a tank on its own frame instead of in a separate tender, which makes it the first known tank locomotive. Instead of a tall chimney, it used bellows, worked by the engine itself, to blow air into its fire. It was light, low and handsome, and the crowd loved it at once. Ericsson later moved to the United States, where he designed the famous ironclad warship USS Monitor during the American Civil War.","Sans Pareil, French for 'without equal', was built by Timothy Hackworth, the experienced locomotive superintendent of the Stockton and Darlington Railway. Hackworth had helped build Puffing Billy years before and knew more about running locomotives every day than almost anyone. His engine was sturdy and powerful, with a boiler in which the fire's hot gases travelled along a U-shaped flue, there and back, before escaping up the chimney. It was built at the Stockton and Darlington's workshops at Shildon, in whatever spare time Hackworth had, and some of its parts were made by outside firms, including, as it happened, Robert Stephenson and Company.","Perseverance was built by Timothy Burstall of Edinburgh. It had an upright boiler and was more like a steam road carriage than a railway engine. Sadly for Burstall, it was damaged on the long journey from Scotland to Rainhill, and he spent the first days of the trials repairing it.","Cycloped was the strangest of all. Built by Thomas Shaw Brandreth of Liverpool, it was not a steam engine at all. A horse stood on a moving platform, a kind of treadmill made from a belt, inside the machine. As the horse walked, the belt turned, and gears passed that motion to the wheels. It was a clever idea, but it broke the spirit of the contest, which was meant to find a locomotive engine. It did not last long either: during one run the horse burst through the floor of the machine, and Cycloped became the first entry to drop out."]},{"heading":"Nine Days of Drama","paragraphs":["Rocket was ready first and set the standard. Over the days of the trials it ran its first set of trips at a steady pace and then, after refuelling, its second set, averaging roughly 12 miles per hour including all the stops and starts at each end of the course. That comfortably beat the required 10 miles per hour. On its fastest stretches it reached about 30 miles per hour, and when it was running without its load of wagons, it was reported going even faster. Most people in 1829 had never travelled faster than a galloping horse. To see a machine do it, all by itself, was astonishing.","Rocket's careful records impressed the judges as much as its speed. A report in The Times said it covered its first 35 miles in about 3 hours 10 minutes and the second 35 miles in about 2 hours 52 minutes, burning less than half a ton of coke over the whole 70 miles. It did not break down once. Between runs, the Stephensons even gave the crowd a show, sending Rocket back and forth along the line with a carriage full of passengers.","Novelty was the crowd's darling. On its first runs it shot along at about 28 miles per hour, faster than anything people had seen, and many spectators were sure it would win. But it was not built for hard, long work. A pipe in its boiler failed. Braithwaite and Ericsson worked through the night to repair it, and Novelty ran again, but more failures followed, including trouble with its bellows and boiler joints, and in the end it had to be withdrawn. Its light, clever design had simply not been tested enough before the great day.","Sans Pareil had trouble before it even started. When it was weighed, it turned out to be over the weight limit, by about 300 pounds (about 140 kilograms). The judges allowed it to run anyway, but made it clear it could not win the prize. It completed eight of its trips, burning a great deal of fuel, until one of its cylinders cracked and it had to stop. Hackworth was bitterly disappointed, and some of his supporters later claimed that the cracked cylinder was poor work by the Stephensons' factory, which had cast it. Historians cannot prove this either way.","Perseverance, after Burstall's days of repairs, finally ran on the sixth day, but it could only manage about 5 or 6 miles per hour, well short of the target. Burstall withdrew. The judges were kind enough to award him 25 pounds for his efforts, a consolation prize for perseverance indeed.","So when the dust settled on 14 October 1829, only one engine had done everything the rules asked: Rocket. The judges declared it the winner. Shortly afterwards it went on to show it could climb too, pulling loaded wagons up the slope at Whiston near Rainhill, which helped answer critics who said locomotives could only work on flat ground."]},{"heading":"Inside Rocket: Three Clever Ideas","paragraphs":["Why did Rocket succeed where the others failed? It was not because it was the most powerful engine ever built. Rather, it combined three good ideas in one small, light machine, and those ideas fitted together so well that they became the basic recipe for steam locomotives for the next 130 years.","The first idea was the multi-tubular boiler. Earlier locomotives, like Puffing Billy and Locomotion, used a boiler with one or two big flues, wide pipes that carried the hot gases from the fire through the water. Think of trying to warm a bath with one hot pipe running through it. Only the water touching the pipe gets heated quickly. Rocket's boiler, about 6 feet long and a little over 3 feet across, had 25 narrow copper tubes, each about 3 inches wide, running from end to end. The hot gases from the fire rushed through all 25 tubes at once. Because there were so many tubes, the total hot surface touching the water was much bigger, so the boiler could turn water into steam far faster. More steam, more power, for a boiler that was still small enough for a light engine to carry.","The second idea was the separate firebox. Rocket's fire burned in its own box at the back, bolted onto the end of the boiler. The firebox had double walls with water between them, a 'water jacket'. This meant the heat glowing out from the burning coke warmed the water in the jacket directly, instead of being wasted, and the walls of the firebox were kept cool enough not to burn through. The burning gases then left the firebox and entered the tubes.","The third idea was the blastpipe. When steam had done its job pushing the pistons, it was not simply let out into the air. Instead, a pipe directed this used, or exhaust, steam straight up the chimney in sharp puffs. Each puff dragged air up the chimney behind it, which pulled fresh air in through the fire grate, just like blowing on a campfire makes it blaze. The faster Rocket ran, the more often it puffed, and the harder its fire burned, so it automatically made more steam exactly when it needed it most. This is also where the famous 'chuff, chuff' sound of a steam train comes from.","There was a clever partnership between these ideas. A strong blast through a single big flue could suck the fire out of the chimney as sparks and waste. But a blast pulling through 25 narrow tubes was evened out, drawing the fire hard without throwing it away. The tubes needed the blast, and the blast worked best with the tubes.","Rocket also had cylinders that drove the wheels directly by rods, with no gears, and it sat on springs for a smoother ride. Its cylinders at first sloped at a steep angle of about 38 degrees, which made it rock as it ran. Within a year or two, engineers lowered them to almost horizontal, a layout that later locomotives followed."]},{"heading":"Who Really Designed Rocket?","paragraphs":["It is often called 'Stephenson's Rocket', and many people imagine George Stephenson designing it alone. The real story is more interesting, and fairer to several people.","In 1829 George was extremely busy acting as chief engineer of the Liverpool and Manchester Railway, overseeing tunnels, cuttings and bridges on the line. The daily work of designing and building Rocket happened in Newcastle under his son, Robert Stephenson, who was only 25 years old. Robert had trained as an engineer, studied for a time at the University of Edinburgh, and spent three years working on mines in South America before coming home to run the factory. Father and son wrote to each other often, and George surely gave advice, but most historians agree that Robert deserves the credit for most of Rocket's design and for solving the many practical problems of building it.","The idea of using many small tubes in the boiler was suggested to the Stephensons by Henry Booth, the treasurer of the Liverpool and Manchester Railway. Booth was not a trained engineer, but he was a thoughtful, inventive man. He became a partner in the entry, and when Rocket won, the prize money was shared between Booth and the Stephensons. At almost the same time, a French engineer named Marc Seguin was building locomotives with multi-tube boilers for a railway near Lyon in France, so the idea was 'in the air' in more than one country.","The blastpipe also had a longer history. Richard Trevithick had noticed back in 1804 that turning his engine's exhaust steam up the chimney made the fire burn more fiercely. George Stephenson used exhaust steam in the chimney on his early colliery engines, and Timothy Hackworth also used a strong blastpipe, including on Sans Pareil. Who 'invented' it is still argued about. What Rocket did was combine the blastpipe with the multi-tube boiler so that each made the other work better.","This is how most great inventions really happen. One person rarely creates everything. Instead, a team brings together ideas, some new and some borrowed or improved, and builds them into something that works better than any of the parts alone."]},{"heading":"Victory, and What Happened to Rocket","paragraphs":["Rainhill settled the great argument. The directors of the Liverpool and Manchester Railway dropped the idea of stationary engines and ropes for the main line. Locomotives would pull their trains, and Robert Stephenson and Company won the contract to build them. The railway even bought Sans Pareil from Hackworth, and it worked for them for a couple of years before being hired out to another line.","Rocket was soon put to work. Just after Christmas, on 28 December 1829, it carried about 40 passengers across the newly finished section over the bog of Chat Moss, a crossing you will read about in the next part. But locomotive design was racing ahead. Within a year, Robert Stephenson's factory was building bigger and better engines, such as Northumbrian and Planet, and Rocket was soon rebuilt and left behind. After working on the Liverpool and Manchester for a few years, it was sold in 1837 to a small coal railway near Brampton in Cumberland, in the far north of England, and was laid aside around 1840 as too light for heavy mineral trains.","Happily, it was not scrapped. In 1862 its owners gave what remained of Rocket to the Patent Office Museum in London, which later became the Science Museum. It stayed there for about 150 years, battered and incomplete but treasured, seen by millions of visitors. In 2018 and 2019 it made a tour of the north, including a visit to Manchester, close to the old Liverpool Road station where its railway once ended, and it is now cared for at the National Railway Museum in York. Working replicas built in 1979 still give rides today, so people can hear what that first winning 'chuff' sounded like.","But in the autumn of 1830, Rocket was not yet a museum piece. The Liverpool and Manchester Railway was almost finished, and an opening ceremony was being planned, grander than anything the railway world had seen. The Prime Minister himself, the Duke of Wellington, was coming. Rocket was being polished and prepared to take its place in the great procession of engines on 15 September 1830, a day that would bring triumph to the railway, and also tragedy."]}],"deepDive":"Rainhill is often told as a simple race, but historians see it as a carefully designed engineering trial, and a political one. The Walker and Rastrick report of 1829 had compared the costs of locomotives and fixed engines with ropes and judged the question still open; the directors used the trials partly to win over doubters on their own board and in the public. The rules, with a load of three times the engine's weight, a cold start, limits on pressure and weight, and a 70-mile endurance test, rewarded reliability and fuel economy more than raw speed. That is why Novelty, the fastest engine on its first day, did not win. A 2002 restaging with replicas, shown in a 2003 BBC Timewatch programme, found Novelty and Sans Pareil each failed about half their runs, while calculations suggested Rocket would still have come out ahead. Experiments showed that Novelty's fire could become choked by clinker, the melted ash that forms when coke burns very hot. The science of Rocket's success lies in heat transfer. Rocket's heating surface was about 15 square metres, of which the 25 tubes supplied about 13. Spreading the hot gas through many narrow tubes greatly increases the area of metal that passes heat into the water, and the blastpipe increases the rate at which air is drawn through the fire. The result is that steam production rises naturally with speed, a self-regulating loop that remained the heart of steam locomotive design until the end of steam. There are still lively debates about credit. Robert Stephenson led the design, Henry Booth proposed the tubes, Marc Seguin was developing multi-tubular boilers in France at the same time, and claims for the blastpipe go back to Trevithick, George Stephenson and Hackworth. Supporters of Hackworth also argued that his cylinder failure came from a faulty casting supplied by the Stephensons' own factory, a claim that cannot now be proved. Finally, Rocket itself was a short-lived design. It was rebuilt within about 18 months, and later engines such as Planet, with horizontal cylinders under the smokebox, became the real pattern for the future.","funFact":"Rocket's single pair of driving wheels were 4 feet 8 and a half inches across, exactly the same as the width of the standard gauge track it ran on.","check":{"q":"Which locomotive was the only one to complete all the tests at the Rainhill Trials in 1829?","a":"Rocket","wrong":["Novelty","Sans Pareil","Cycloped"]},"sources":[{"title":"Rainhill trials","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rainhill_trials"},{"title":"Stephenson's Rocket","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Stephenson%27s_Rocket"},{"title":"Stephenson's Rocket (object record)","publisher":"Science Museum Group Collection","url":"https://collection.sciencemuseumgroup.org.uk/objects/co26704"},{"title":"Rocket in our collection","publisher":"Science and Industry Museum, Manchester","url":"https://blog.scienceandindustrymuseum.org.uk/rocket-in-our-collection"},{"title":"The Rainhill Trials","publisher":"Historic UK","url":"https://www.historic-uk.com/HistoryUK/HistoryofBritain/Rainhill-Trials/"},{"title":"Stephenson's Rocket","publisher":"World History Encyclopedia","url":"https://www.worldhistory.org/Stephenson%27s_Rocket/"},{"title":"Liverpool and Manchester Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Liverpool_and_Manchester_Railway"},{"title":"Sans Pareil","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sans_Pareil"}],"photos":[{"src":"img/deep/railways/07-1.jpg","alt":"The original Rocket in the Science Museum, London, in its later form with its cylinders moved lower down.","file":"Stephenson's Rocket Science Museum 2017-02-27.jpg","url":"https://commons.wikimedia.org/wiki/File:Stephenson%27s_Rocket_Science_Museum_2017-02-27.jpg","author":"Les Chatfield","license":"CC BY 2.0"},{"src":"img/deep/railways/07-2.jpg","alt":"Crowds and a grandstand at the 1829 Rainhill Trials, with Rocket, Sans Pareil and Novelty, from the Illustrated London News.","file":"Rainhill Trials in the Illustrated London News.jpg","url":"https://commons.wikimedia.org/wiki/File:Rainhill_Trials_in_the_Illustrated_London_News.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/railways/07-3.jpg","alt":"A working replica of Braithwaite and Ericsson's Novelty at the Museum of Science and Industry, Manchester.","file":"Novelty Replica 05-09-17 86.jpeg","url":"https://commons.wikimedia.org/wiki/File:Novelty_Replica_05-09-17_86.jpeg","author":"A.M.Hurrell","license":"CC BY 2.5"}],"words":3822},{"n":8,"title":"The First Modern Railway","when":"1830 – 1840s","summary":"In 1830 the Liverpool and Manchester Railway opened, the first railway where steam trains carried people between two big cities on a timetable. Builders even floated the track across a squishy bog! Soon everyone in Britain wanted railways, and a fight broke out over how wide the tracks should be.","sections":[{"heading":"Carving a Path Between Two Cities","paragraphs":["The Stockton and Darlington had been a coal railway that also carried some passengers. The Liverpool and Manchester Railway was meant to be something much bolder: a railway built from the start to carry both people and goods, quickly and regularly, between two big, busy cities. To do that, George Stephenson wanted a line that was as flat and straight as possible, because even the best locomotives of the time struggled on hills. That meant the land itself had to be reshaped.","Getting permission was a battle in its own right. Canal owners, stagecoach companies and powerful landowners, including aristocrats who did not want noisy engines crossing their estates, fought the plan in Parliament. The railway's first attempt to win an Act of Parliament failed in 1825, partly because Stephenson's early survey contained mistakes that opposing lawyers pounced on. The company had the route surveyed again more carefully, steering it away from some of the hostile estates, and the Act finally passed in 1826. Work could begin.","At the Liverpool end, the railway needed to reach the docks, which lay far below the higher ground east of the town. So the engineers dug the Wapping Tunnel, about 2,250 yards (around 2 kilometres) long, running under the streets of Liverpool from Edge Hill down to the docks. It is thought to be the first tunnel ever bored beneath a city. Its walls were whitewashed and lit by gas lamps so that early visitors could walk through and admire it. Interestingly, the locomotives did not work the steep tunnels at first. Wagons ran down by gravity and were hauled back up by ropes from stationary engines at Edge Hill, so the rival technology from Rainhill still had a small job to do after all.","Just east of Edge Hill came the Olive Mount cutting. Rather than climb over a ridge of solid sandstone, the line went straight through it, in a man-made canyon about 2 miles (3 kilometres) long and up to about 70 feet (21 metres) deep. It was dug almost entirely by hand, with picks, shovels, gunpowder for blasting, and horses and carts to haul the rock away. The men who did this heavy work were called navvies, short for 'navigators', a name first given to the labourers who dug Britain's canals. Much of the stone they removed was reused to build bridges and walls along the line.","Further east, the railway had to cross the valley of the Sankey Brook, which also carried a canal. The canal company insisted that its boats, flat-bottomed sailing barges called Mersey flats, must still be able to pass underneath with their masts up. So Stephenson designed the Sankey Viaduct: nine great arches of brick and sandstone, each spanning 50 feet (15 metres), carrying the track about 60 to 70 feet (around 20 metres) above the valley. It cost about 45,000 pounds, a huge sum. It is often called the world's earliest major railway viaduct, it is protected today as a Grade I listed structure, and trains still rumble across it, nearly two centuries later.","Altogether the line needed 64 bridges and viaducts, almost all of brick or stone. In Manchester, the line crossed Water Street on an early cast-iron bridge, and ended at a modest station on Liverpool Road. That building still stands. It is thought to be the oldest surviving railway terminus in the world, and today it is part of the Science and Industry Museum."]},{"heading":"Floating Across Chat Moss","paragraphs":["The hardest problem of all lay only a few miles west of Manchester. It was a vast, wobbly peat bog called Chat Moss, covering about 10 square miles (27 square kilometres). Its peat, made of dead plants soaked in water, was in places around 24 to 30 feet deep. In wet weather it was so soft that a person could sink into it, and it was said that a stick pushed into it could disappear completely. Some engineers had told Parliament that building a railway across it was impossible.","Stephenson's first idea was simple: pour in enough earth and rubble to reach the solid ground underneath and build an embankment on top. At one especially bad spot, known as Blackpool Hole, gangs of workers tipped load after load of spoil into the bog for weeks on end, and it simply vanished, sinking or squeezing out sideways into the soft peat. The bog seemed to swallow everything.","So Stephenson changed his approach, with advice from Robert Stannard, a man with long experience of working on marshland. Instead of trying to reach the bottom, they decided to float the railway on top, rather like a raft. Workers laid down great mats, or hurdles, made of heather and brushwood (bundles of branches) bound together. On top of these they spread layers of earth, rubble and cinders, and then laid the track on wooden sleepers in a herringbone pattern, which spread the weight of a train over a wide area. Ditches were dug along both sides to drain water away, and old tar barrels were used to line the drains. Where the bog was deepest, the line rested on this floating mat, which bent slightly as a train passed but did not sink.","It took time, patience and enormous amounts of material, but it worked. The crossing, about 4 and three-quarter miles (7.6 kilometres) long, was finished by the end of 1829. On 28 December that year, Rocket crossed it pulling a carriage of about 40 passengers, taking around 17 minutes. Amazingly, the floating foundation, strengthened over the years, still supports the main line between Liverpool and Manchester today, carrying trains far heavier than anything Stephenson could have imagined."]},{"heading":"A Grand Opening, 15 September 1830","paragraphs":["Picture Liverpool on the morning of Wednesday 15 September 1830. Huge crowds pack the streets near the Edge Hill area, where the trains will start. Flags flutter, bands play, cannon are fired, and the people who have paid for tickets settle into their carriages in their finest clothes. Eight locomotives built by Robert Stephenson and Company stand ready, among them Northumbrian, Phoenix, North Star, Rocket, Dart, Comet, Arrow and Meteor, each pulling a train of carriages. It is the grandest railway event the world has ever seen.","The guest of honour was the Duke of Wellington, the Prime Minister and the hero who had defeated Napoleon at Waterloo 15 years earlier. He rode in a special, richly decorated carriage, pulled by the newest and best engine, Northumbrian, with George Stephenson himself at the controls. The Duke's train ran on one of the two tracks, the southern line. The other seven trains followed on the northern track, so that they could run alongside and pass the Duke's train, letting their passengers see and cheer him.","Because this was the first railway with two tracks all the way, trains could travel in both directions at once, or pass each other, without waiting. That seems normal today, but it was new in 1830, and it shaped the day in ways nobody planned.","The trains set off eastwards towards Manchester, cheered by crowds lining the cuttings and fields. Passengers were thrilled by the speed and by the views from the Sankey Viaduct. Some had already tasted this new sensation. Before the line opened, the famous young actress Fanny Kemble had been given a ride on the footplate by George Stephenson during a test run. In a letter she compared the engine to a living animal, a snorting little horse, and wrote warmly of Stephenson himself. Many of the guests on opening day felt the same mixture of excitement and wonder.","Halfway along the line, at a place called Parkside, near Newton, the trains stopped so the engines could take on water. That short stop would become one of the most famous moments in railway history."]},{"heading":"Tragedy at Parkside","paragraphs":["Among the guests in the Duke of Wellington's train was William Huskisson, the Member of Parliament for Liverpool. He was about 60 years old, an important politician who had served as President of the Board of Trade and had championed freer trade, which mattered greatly to a port city like Liverpool. He had been a strong supporter of the railway. He was not in good health, and a royal doctor had even advised him to cancel his engagements, but he came anyway.","Huskisson and Wellington had quarrelled two years earlier, when Huskisson resigned from Wellington's government. Many people hoped the opening day might be a chance to make peace. While Northumbrian was taking on water at Parkside, a number of passengers ignored instructions to stay in their seats and climbed down onto the track to stretch their legs. Huskisson walked over to the Duke's carriage, and the Duke reached out to shake his hand.","At that moment, Rocket, driven by the young engineer Joseph Locke, came steaming along the other track. People shouted warnings. There was very little space between the two lines, and Huskisson, who was not quick on his feet, tried to climb into the Duke's carriage. But its door had not been fastened, and it swung open, leaving him hanging in Rocket's path. He fell onto the rails, and Rocket ran over his leg, injuring it terribly. Locke had tried to stop, but early locomotives had no proper brakes on their wheels; reversing the engine took several seconds to have any effect.","George Stephenson acted fast. He uncoupled Northumbrian from the Duke's train, attached a single carriage, and Huskisson was laid on a door taken from a nearby building and lifted aboard. Stephenson then drove as fast as he dared to the town of Eccles, more than 10 miles further along the line towards Manchester, to find doctors. Some accounts say Northumbrian reached around 35 miles per hour on this desperate run, faster than people had ever travelled, though such early speed figures are hard to check. Sadly, the doctors could do little. Huskisson was carried to the vicarage at Eccles, where he was cared for by the vicar's wife and joined by his wife, Emily. He was able to make his will, and he died at about 9 o'clock that evening.","Huskisson was not the first person ever killed by a railway. Workers and bystanders had already been hurt and killed on earlier lines. But his death, in front of the Prime Minister and hundreds of the most important people in the country, was one of the first railway passenger deaths reported far and wide. Newspapers everywhere carried the story. It was a shocking lesson that these powerful new machines, so quiet compared to their speed, needed new rules: stay inside the train, and never stand on the track.","The rest of the day was gloomy. The Duke of Wellington wanted to turn back, but the organisers persuaded him to go on to Manchester, where huge crowds were waiting. Wellington was very unpopular in parts of Manchester, where many working people were angry about poverty and the lack of votes for ordinary people. Some of the crowd booed and threw things at his carriage. The Duke stayed in his seat and soon headed back towards Liverpool. Some of the trains did not get home until late at night, in the rain."]},{"heading":"Why It Was the First Modern Railway","paragraphs":["Despite that sad start, the Liverpool and Manchester Railway opened to the public the very next day and quickly proved its worth. Historians often call it the first truly modern railway, because it brought together, for the first time, almost all the features we expect a railway to have.","It joined two big cities, rather than a mine and a river. It had double track the whole way, a little over 30 miles (about 50 kilometres) from Liverpool to Manchester, so trains could run in both directions at once. Every train on the main line was pulled by a steam locomotive; there were no horse-drawn coaches mixed in, as there had been on the Stockton and Darlington. It was run by the company itself, which owned the engines and carriages, employed the drivers, and ran trains to a published timetable, so passengers knew when to turn up. Passengers bought tickets for their journey, with different classes of carriage at different prices. And it carried both people and goods: passengers from the start, and freight from December 1830, once the more powerful locomotive Planet had arrived.","The journey between the two cities took about two hours. That might not sound fast to us, but the railway was quicker, smoother and more reliable than the stagecoaches that bumped along the roads, and much faster than the canal barges. Early passenger trains averaged around 16 miles per hour and goods trains about 8.","Then came the biggest surprise. The railway's founders had expected to make most of their money from cotton and other goods. Instead, people flocked to ride the trains. Within a few weeks of opening, the Manchester station was handling around 800 passengers a day, and on some days as many as 2,500 travellers. Within a short time, most of the stagecoach services between Liverpool and Manchester simply closed down; there was no point competing. The railway also began carrying mail, and ran special excursion trains for people simply wanting a day out.","The canal companies fought back by cutting their prices, and a price war followed, which was good news for merchants. Even so, the railway made healthy profits. Over its 15 years as an independent company, shareholders received an average dividend, or yearly payout, of about 9.5 percent of their investment. Bankers and businesspeople all over Britain took notice. If a railway could do this well between Liverpool and Manchester, why not between every pair of big towns in the country?","Engineers took notice too. Visitors came from America, France, Germany and beyond to study the line. Railways soon followed linking London with Birmingham, Birmingham with Liverpool and Manchester, and many more. By the late 1830s, Britain was building a network."]},{"heading":"Railway Mania","paragraphs":["By the mid-1840s, railway fever had gripped Britain. The economy was recovering after hard times, interest rates were low, and people with savings were looking for something exciting to invest in. Railways seemed like the perfect choice: they were new, they were clearly useful, and the early lines like the Liverpool and Manchester had paid well. Newspapers filled up with advertisements for new railway companies, each promising to build a line somewhere and pay rich rewards. This frenzy is known as Railway Mania.","To build a railway in Britain, a company needed its own Act of Parliament, giving it the right to buy land along its route. In 1846 alone, at the peak of the mania, Parliament passed 263 Acts setting up new railway companies, with plans for about 9,500 miles (15,300 kilometres) of track. Many Members of Parliament were themselves investors in railways, so there was little appetite to slow things down. Some schemes were sensible. Others were wildly unrealistic, proposing lines between small villages, or competing lines that duplicated each other almost side by side.","Like many booms, it ended in a bust. In late 1845 the Bank of England raised interest rates, borrowing money became more expensive, and investors began to panic. Share prices tumbled. Thousands of people, from wealthy gentlemen to shopkeepers and widows who had put in their savings, lost money, sometimes everything. About a third of the railways that had been authorised were never built at all. Bigger, stronger companies bought up struggling ones cheaply.","Yet the mania left something lasting behind. About 6,220 miles (10,000 kilometres) of railway were eventually built from the schemes approved between 1844 and 1846. That is more than half the length of Britain's whole railway network today. The country ended up with railways reaching almost every town, even if many investors paid dearly for them. Historians still compare Railway Mania with later investment bubbles, such as the dot-com boom of the late 1990s, when people rushed to invest in new internet companies.","Parliament did try to set some rules. A law of 1844, pushed through by William Gladstone, who was then in charge of the Board of Trade, required every railway company to run at least one cheap train a day each way along its lines, in covered carriages, stopping at every station, for a fare of no more than one penny a mile. These 'parliamentary trains' meant that even poorer people could afford to travel by rail."]},{"heading":"The Railway King","paragraphs":["The most famous figure of Railway Mania was George Hudson. Born in 1800 to a farming family in Yorkshire, he became a draper, a cloth merchant, in the city of York. After he came into a large inheritance, he began investing in railways, and he turned out to be a brilliant and ruthless dealmaker.","Hudson saw that many small railway companies would be stronger joined together. He chaired the York and North Midland Railway, helped create the Midland Railway in 1844 by merging three companies, and went on to control a large share of the lines in the north and middle of England. He turned York into one of Britain's great railway junctions, served several times as Lord Mayor of York, and became a Member of Parliament for Sunderland. In 1844 the writer Sydney Smith gave him the nickname that stuck: 'the Railway King'.","But Hudson's empire had a rotten secret. To keep shareholders happy and share prices high, he paid out generous dividends. Some of that money did not come from profits at all, but from new capital, the money investors had just put in to build more railways. In effect, he was paying old investors with new investors' money, and keeping misleading accounts to hide it. When the mania collapsed, investors started asking hard questions. Inquiries in 1849 exposed his methods. Hudson lost his positions, was declared bankrupt, and spent years living abroad to avoid being imprisoned for debt. He returned to England only after imprisonment for debt was abolished in 1870, and died in London in 1871.","Hudson's story shows both sides of the railway boom. He really did help build a more connected network, and some of his mergers made good sense. But his dishonesty hurt many ordinary people, and it helped persuade later governments that big companies needed proper accounts and closer checks."]},{"heading":"Brunel and the Battle of the Gauges","paragraphs":["While northern railways copied Stephenson's 4 feet 8 and a half inch gauge, one brilliant engineer in the west of England decided to do things differently. Isambard Kingdom Brunel was only in his late twenties when he became engineer of the Great Western Railway, planned to run from London to Bristol. Brunel thought big. He believed a much wider track would let trains run faster and more smoothly, with bigger carriages, larger wagons and room for large wheels and boilers. Having watched carriages swaying on the Stockton and Darlington, he chose a broad gauge of 7 feet and a quarter of an inch (about 2,140 millimetres), more than half as wide again as Stephenson's.","The Great Western's first section, from Paddington in London to Maidenhead, opened to the public on 4 June 1838, and the whole line to Bristol was ready by 30 June 1841. It was a superb railway, laid out with very gentle slopes and curves, and its broad-gauge trains were among the fastest in the world. Many travellers agreed they were smoother and more comfortable too.","The trouble came where the two systems met. At Gloucester, broad-gauge trains from the Great Western met standard-gauge trains from the Midlands. Passengers had to get off with their luggage and change trains, and every sack, crate and parcel had to be unloaded by hand from one wagon and loaded into another, which could take hours. Newspapers and cartoonists mocked the chaos on the platforms. This messy meeting point was called a 'break of gauge', and as both networks grew, the arguments between their supporters became known as the Gauge War.","In 1845 the government set up a Royal Commission to decide what to do. Both sides staged speed trials. A broad-gauge engine called Ixion averaged about 53 miles per hour between Paddington and Didcot, carrying heavier loads than its rival, while a standard-gauge engine trying to match it on the line between Darlington and York came off the rails. The broad gauge clearly performed better, but by then there were far more miles of standard-gauge track. Changing all of those would cost a fortune. The commission decided that having one gauge mattered more than having the best one.","So in 1846 Parliament passed the Gauge Act, which said that new railways for passengers in Great Britain must be built to 4 feet 8 and a half inches, unless they were extensions of the existing broad-gauge network. (Ireland, a separate system, settled on its own gauge of 5 feet 3 inches.) The Great Western kept its broad gauge for decades and added a third rail to many lines, creating 'mixed gauge' track that both kinds of trains could use. But step by step it gave in. Brunel died in 1859, and conversion began in the 1860s. Finally, in a huge operation in May 1892, thousands of workers converted the last broad-gauge main line, through Devon to Penzance in Cornwall, in about two days. By 21 May 1892 the broad gauge was gone, and its engines were towed away to Swindon to be scrapped.","In just over 60 years, from Rainhill to the end of the Gauge War, the railway had gone from an experiment to a nationwide system that changed how Britain lived and worked. But what really happens inside one of these puffing machines? In the next part, it is time to climb up onto the footplate, the platform where the driver and fireman stand, and see exactly how a steam locomotive works."]}],"deepDive":"Why do historians call the Liverpool and Manchester Railway the first modern railway, when the Stockton and Darlington opened five years earlier? The answer is the combination of features: double track throughout, steam traction only on the main line, a company that operated its own trains rather than charging tolls to independent carriers, scheduled services, ticketing, and both passengers and freight. Its economics surprised everyone. The promoters had planned around cotton and goods, but passenger traffic became a major source of income, and stagecoach services between the two cities collapsed. The line averaged a dividend of about 9.5 percent over 15 years, a figure that helped trigger later investment waves. There are a few points of debate and uncertainty. Figures for the line's length vary from about 30 to 35 miles depending on which termini and branches are counted; the main route from Liverpool to Manchester was a little over 30 miles. Opening-day speeds are also uncertain: the often-quoted figure of about 35 mph for Northumbrian's emergency run to Eccles comes from witnesses without precise timing. Huskisson's death is sometimes called the first railway fatality, but that is not true; it was among the first widely reported passenger deaths. Railway Mania is studied by economists as a classic speculative bubble. In 1846, 263 Acts authorised about 9,500 miles of new line, yet about a third was never built, while some 6,220 miles were eventually completed from the 1844 to 1846 approvals. Economists debate whether the bubble was wasteful or whether, like the late-1990s fibre-optic boom, it left behind valuable infrastructure that society would not otherwise have funded. The Gauge War raises a classic question in technology: the 'better' standard does not always win. Brunel's broad gauge offered stability and space, but the network effect of the larger standard-gauge system, and the cost of converting it, decided the outcome. Similar battles happened later with videotape formats, plugs and charging connectors.","funFact":"The track across the Chat Moss bog, floated on mats of heather and brushwood in 1829, still carries trains between Liverpool and Manchester today.","check":{"q":"Which politician was fatally injured by Rocket on the opening day of the Liverpool and Manchester Railway in 1830?","a":"William Huskisson","wrong":["The Duke of Wellington","George Hudson","Isambard Kingdom Brunel"]},"sources":[{"title":"Liverpool and Manchester Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Liverpool_and_Manchester_Railway"},{"title":"William Huskisson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Huskisson"},{"title":"Chat Moss","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chat_Moss"},{"title":"Sankey Viaduct","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sankey_Viaduct"},{"title":"Liverpool Road railway station (Manchester)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Liverpool_Road_railway_station_(Manchester)"},{"title":"Railway Mania","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Railway_Mania"},{"title":"George Hudson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Hudson"},{"title":"Brunel gauge","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Brunel_gauge"}],"photos":[{"src":"img/deep/railways/08-1.jpg","alt":"Workers dig the deep Olive Mount rock cutting as a train passes, a coloured print after Thomas Talbot Bury, 1831.","file":"Excavation of Olive Mount, from Bury's Liverpool and Manchester Railway, 1831 - artfinder 76057.jpg","url":"https://commons.wikimedia.org/wiki/File:Excavation_of_Olive_Mount,_from_Bury%27s_Liverpool_and_Manchester_Railway,_1831_-_artfinder_76057.jpg","author":"Henry Pyall / Thomas Talbot Bury","license":"Public domain"},{"src":"img/deep/railways/08-2.jpg","alt":"Isaac Shaw's drawing of opening day, 15 September 1830: crowds and decorated carriages at Liverpool's Moorish Arch.","file":"Isaac Shaw - Opening of the Liverpool and Manchester Railway - B1981.25.2698 - Yale Center for British Art.jpg","url":"https://commons.wikimedia.org/wiki/File:Isaac_Shaw_-_Opening_of_the_Liverpool_and_Manchester_Railway_-_B1981.25.2698_-_Yale_Center_for_British_Art.jpg","author":"Isaac Shaw","license":"CC0"},{"src":"img/deep/railways/08-3.jpg","alt":"George Hudson (1800-1871), the 'Railway King' who built a railway empire and later fell into disgrace.","file":"George Hudson (1b).JPG","url":"https://commons.wikimedia.org/wiki/File:George_Hudson_(1b).JPG","author":"Joseph Tatlow (1851-1929)","license":"Public domain"}],"words":3927},{"n":9,"title":"Inside a Steam Locomotive","when":"How it works","summary":"A steam engine is like a giant kettle on wheels. A fire boils water, the steam pushes pistons back and forth, and rods turn the big wheels round. Every puff you hear is used steam rushing up the chimney to make the fire burn even hotter!","sections":[{"heading":"On the Footplate: Crew and Firebox","paragraphs":["Imagine climbing a set of steep iron steps on a cold morning and stepping into the cab of a big steam locomotive. Railway people call this open-backed space the footplate. The first thing you notice is the heat. In front of you is a small round or oval door, and when it swings open you see a roaring orange fire so bright you have to squint. The second thing you notice is the noise: hissing pipes, a gentle roar from the fire, the clank of metal and, somewhere above your head, the rumble of boiling water.","Two people normally work here, and they have very different jobs. The driver (called the engineer in North America) is in charge of the train. The driver opens and closes the steam supply, decides how hard the engine should work, watches the signals beside the track and puts on the brakes. The fireman looks after the fire and the water. That sounds simple, but it is one of the hardest jobs ever done on a railway. The fireman shovels coal into the fire, keeps the right amount of water in the boiler, watches the steam pressure gauge and helps look out for signals on his side of the cab.","Every steam locomotive starts with a fire. In Britain the fuel was nearly always coal, but early American engines mostly burned wood until about 1870, and some later engines burned oil sprayed in as a fine mist. The fire burns inside a box called the firebox, at the back of the engine, right next to the cab. The floor of the firebox is a grate: a set of iron bars with gaps between them. Coal sits on the bars, air comes up through the gaps from underneath, and ash falls down through the gaps into a tray called the ashpan. On many engines a sloping shelf of fireproof bricks, called the brick arch, sits above the fire. It makes the hot gases take a longer path, so more of the smoke burns up and more heat stays inside the engine.","Firing was a real skill, not just brute strength. The fireman did not simply hurl coal into the middle of the fire. He spread it in a careful pattern, often thicker at the back corners and thinner at the front, so that the whole grate burned evenly. A shovelful thrown in the wrong place could make a hole in the fire, letting cold air rush through and cool the boiler. On a long, fast run with a big express engine, a fireman could shovel several tonnes of coal in a single shift, all while the cab swayed and bounced at high speed. Some very large engines, especially in America, later used a mechanical stoker, a screw conveyor that carried coal from the tender to the fire, because no human could shovel fast enough to feed them.","The firebox itself was a box inside a box. The inner box, where the fire burned, was usually made of copper in Britain and steel in America. The outer box was made of steel. In between was a narrow space filled with water. The two walls were held together by hundreds of short metal rods called stays, because the steam pressure was always trying to push them apart. This water jacket did two jobs at once. It soaked up heat from the fire, and it stopped the metal of the firebox from getting so hot that it went soft.","The most dangerous place in the whole engine was the top of the inner firebox, called the crown sheet. It sat right above the hottest part of the fire, and it stayed safe only as long as water covered it. If the water level fell too low, the crown sheet could overheat, weaken and give way under pressure, causing a terrible boiler explosion. To guard against this, many boilers had a fusible plug screwed into the crown sheet. It was a metal plug with a core made of a metal that melts at a low temperature. While water covered it, the plug stayed cool. If the water dropped below it, the core melted and a jet of steam blew down into the firebox, warning the crew and damping the fire. The idea is credited to Richard Trevithick, who came up with it in 1803 after one of his boilers exploded because a worker let the water run low. He shared the idea freely instead of patenting it."]},{"heading":"The Boiler: A Giant Kettle Full of Tubes","paragraphs":["In front of the firebox stretches the long, round barrel that makes a steam locomotive look the way it does. This is the boiler, and it is mostly full of water. If the boiler were just a big empty tank with a fire at one end, it would take ages to heat up, like trying to boil a bathtub with a candle. The clever trick, which made Rocket so successful at Rainhill in 1829, is the fire-tube.","Running from the front wall of the firebox all the way to the front of the boiler are dozens, or on big engines more than a hundred, metal tubes. The hot gases from the fire do not go straight up a chimney. Instead they are pulled forward through these tubes. Each tube is completely surrounded by water. That means the heat has an enormous area of metal to pass through. Rocket had 25 copper tubes; a large twentieth-century engine might have well over a hundred small tubes plus a few much bigger ones.","As the water boils, the steam collects in the space above the water. When water turns into steam at normal air pressure, it expands to roughly 1,600 times its volume, so a single litre of water can become well over a cubic metre of steam. Inside a boiler, though, the steam cannot escape, so instead of spreading out it builds up pressure. Early engines like Rocket worked at about 50 pounds per square inch. By the twentieth century many express engines worked at 200 to 250 pounds per square inch or more. That is more than ten times the pressure of the air around us, pressing on every square centimetre of the boiler from the inside. This is why boilers had to be made of thick steel plates joined with thousands of rivets, and why they were tested and inspected so carefully.","Many boilers have a dome on top, like a little hat. The highest point in the boiler is the best place to collect steam, because it is furthest from the splashing water, and the steam taken from there is drier. Water droplets are a nuisance: they carry no useful energy and can damage the cylinders. To get even better steam, most later engines added a superheater. After the steam leaves the boiler, it is sent back through thin pipes placed inside some of the larger fire-tubes, where the hot gases heat it far above its boiling point. This makes the steam completely dry and gives it more energy. The German engineer Wilhelm Schmidt developed the first practical superheaters in the 1880s and 1890s, and one British railway's tests in 1915 found that engines using superheated steam burned nearly a fifth less coal per mile. During the early twentieth century, superheaters spread to most new main-line engines.","The boiler also needs a steady supply of fresh water, and that is harder than it sounds. You cannot just pour water into a tank that is already pressed full of high-pressure steam; it would blast straight back out at you. The answer was the injector, invented by the French engineer Henri Giffard and patented in 1858. It uses a jet of steam, shot through cone-shaped nozzles, to push a stream of water into the boiler against the boiler's own pressure. It works because the jet of fast-moving steam condenses into the water and gives it a huge push. The fireman also kept a close eye on the gauge glasses: thick glass tubes on the back of the boiler in which he could see the actual water level bobbing up and down."]},{"heading":"Regulator, Cylinders and Pistons: Turning Steam Into Motion","paragraphs":["So far we have a boiler full of hot, high-pressure steam. Now we need to turn that pressure into movement. The driver does this with the regulator, which drivers in America call the throttle. It is a valve, usually tucked up inside the dome, worked by a long handle in the cab. When the regulator is closed, the steam stays in the boiler. When the driver eases it open, steam rushes along a big pipe toward the front of the engine and into the cylinders.","A cylinder is a strong metal tube, closed at both ends, with a close-fitting metal disc inside it called a piston. The piston can slide from one end of the cylinder to the other. When steam is let in at one end, its pressure pushes the piston toward the other end. Then steam is let in at the other end, and the piston is pushed back again. Because steam pushes on both sides in turn, railway engineers call this double-acting. Most locomotives have two cylinders, one on each side near the front, though some powerful engines had three or four.","A rod called the piston rod sticks out of the cylinder and is joined to a sliding block called the crosshead, which runs along a guide bar so that it moves perfectly straight. From the crosshead, a long, heavy rod called the connecting rod reaches back to a crank pin fixed to one of the big wheels, a little way out from the centre. As the piston moves back and forth, the connecting rod pulls and pushes on the crank pin, and the wheel turns round. It is the same idea as your legs pushing the pedals of a bicycle: a straight push becomes a turning motion.","There is a problem with just one cylinder, though. When the piston is right at the end of its stroke, the connecting rod is lined up straight with the centre of the wheel. Pushing on it then would be like pushing a door exactly on its hinges: nothing would turn. Engineers call this point dead centre. The solution is to set the cranks on the two sides of the engine a quarter of a turn (90 degrees) apart. Whenever one side is at dead centre, the other side is halfway through its stroke and pushing hard. With two double-acting cylinders, the engine gets four pushes for every turn of the driving wheels, which is why a steam engine starting slowly makes four distinct chuffs per wheel turn.","Most engines have more than one pair of driving wheels. The extra pairs are joined to the first by coupling rods, the long rods you can see swinging along the side of a steam engine, so that all the driving wheels turn together and share the work of gripping the rails. More driving wheels means more grip, which helps for heavy freight trains. Bigger driving wheels mean more distance covered per turn, which helps for fast passenger trains. A fast express engine might have driving wheels taller than an adult, about 2 metres across, while a slow, powerful freight engine might have smaller wheels but more of them."]},{"heading":"Valve Gear: The Engine's Clever Timekeeper","paragraphs":["Something has to decide when the steam goes into each end of the cylinder and when the used steam is let out. That job belongs to the valves, and the rods and links that move them are called the valve gear. If you watch a steam engine moving slowly, the valve gear is the busy tangle of smaller rods that dance alongside the big connecting and coupling rods. It may look complicated, but its job can be described simply.","Above or beside each cylinder is a small chamber called the steam chest, with a sliding valve inside it. As the valve slides one way, it opens a port to let fresh steam into the front of the cylinder while opening another port to let the old steam out of the back. As it slides the other way, it does the opposite. The valve gear is driven by the turning wheels themselves, so the valves always move in perfect step with the pistons, however fast or slow the engine goes.","Valve gear also lets the driver go backwards. By moving the reversing lever, or turning a reversing screw, the driver changes the timing of the valves so that steam pushes the pistons at the opposite moments, and the wheels turn the other way. There were many different designs. In the nineteenth century the most common was Stephenson valve gear, which used two off-centre discs called eccentrics on the driving axle and a curved slotted link to choose between them. It was usually hidden between the frames under the boiler. Later engines very often used Walschaerts valve gear, devised in Belgium by Egide Walschaerts. It was mounted outside the wheels, where it was much easier for the crew to oil and repair.","The cleverest thing about valve gear is something called cutoff. The driver does not have to let steam into the cylinder for the whole length of the piston's stroke. He can let it in for, say, the first half and then shut it off. The trapped steam keeps on pushing as it expands, a bit like a spring uncoiling, and it gives up much more of its energy before it is let out. When starting a heavy train, the driver uses a long cutoff, perhaps 75 percent of the stroke, to get the biggest possible push. Once the train is rolling fast, the driver winds the reverser back toward the middle so that steam is cut off after only about 15 or 20 percent of the stroke, or even less. Drivers called this notching up, and it saved a great deal of coal and water."]},{"heading":"Chuff, Roar and Whistle: The Blastpipe and Safety Valve","paragraphs":["After the steam has done its work in the cylinders, it still has a job to do. Instead of being thrown away at the side of the track, it is piped forward into the smokebox and shot upward through a nozzle called the blastpipe, straight up the chimney. Every time a cylinder lets out its used steam, a strong puff blasts up the chimney. That is the famous chuff, chuff, chuff of a steam train.","Each blast of steam does something very useful on the way. As it rushes up the chimney, it drags the air and smoke in the smokebox along with it, leaving behind a partial vacuum. To fill that gap, hot gases are pulled forward from the firebox through the boiler tubes, and fresh air is sucked in through the grate from below. In other words, the engine's own exhaust works like a pair of bellows, fanning the fire. Rocket used this idea at Rainhill in 1829, though, as you read in Part 7, the idea of blasting exhaust up the chimney had been tried by earlier engineers.","The best part is that this system adjusts itself. When the engine is working hard, up a hill or pulling a heavy train, it uses steam faster and the blasts come harder and quicker. That pulls more air through the fire, which burns hotter and makes steam faster, exactly when it is most needed. When the engine is coasting, the blast is gentle and the fire calms down. Engineers spent more than a century improving the shape of blastpipes and chimneys. Many later engines used double chimneys or special multiple nozzles, which let the exhaust escape more easily while still drawing the fire strongly. Mallard itself was fitted with a double chimney and blastpipe.","On top of the boiler sits the most important safety device of all: the safety valve. It is held shut by a strong spring. If the pressure inside rises above the boiler's safe working limit, the steam pushes the valve open and roars out with a deafening hiss until the pressure falls again. In 1875 the American George Richardson designed a type of safety valve that opened fully at the set pressure and closed cleanly once it had dropped, and designs based on it came into use almost everywhere. A good fireman tried to keep his engine just below the point where the safety valves lifted, because every blowing-off sent precious water and coal straight into the sky. Finally there is the whistle, a simple pipe blown by steam, which the driver sounded as a warning before tunnels and level crossings and to send signals to other railway staff."]},{"heading":"Thirsty Giants: Tenders, Water Stops and Troughs","paragraphs":["A steam locomotive is incredibly thirsty. Every puff that goes up the chimney is water that has been boiled and thrown away, and it never comes back. Most steam locomotives do not recycle their steam at all. That means they use far more water than coal, often several times as much by weight. A big express engine working hard could boil away thousands of litres of water every hour.","That is why the biggest engines pulled a tender, a separate wagon coupled permanently behind the cab. A typical tender was built around a large U-shaped water tank, with a coal space in the middle. Smaller engines, used for short trips and shunting, carried their water in tanks along the sides of the boiler or over the top of it, and are called tank engines. Engineers usually designed a tender so that the engine would need to stop for water about twice as often as it stopped for coal, because water was much easier to find than fuel.","The giants of America needed giant tenders. The Union Pacific Big Boy engines, built from 1941 to 1944 to haul heavy freight over the mountains of Wyoming and Utah, had tenders that held about 24,000 to 25,000 US gallons of water, roughly 91,000 to 95,000 litres, enough to fill a large swimming pool, plus 28 short tons of coal. With its tender, a Big Boy was over 40 metres long and weighed more than 500 tonnes. Even so, it still had to stop regularly for water on its long climbs.","Along every main line, railways built water towers and tall metal arms called water columns or water cranes. When a train stopped, the fireman climbed onto the tender, swung the leather hose of the water column over the filler hole and opened the valve. Thousands of litres gushed in within minutes.","In Britain, an engineer found a clever way to fill up without stopping at all. John Ramsbottom, chief mechanical engineer of the London and North Western Railway, wanted to speed up the Irish Mail, the important train carrying letters from London toward Holyhead and the ferry to Ireland. In 1860 he laid the first water troughs at Mochdre on the North Wales coast. A water trough is a long, shallow metal channel laid between the rails and kept full of water. As a train raced over it, the fireman wound down a scoop under the tender. The speed of the train forced water up the scoop and into the tank. Ramsbottom found that at only 15 mph the water was lifted more than 2 metres, and at higher speeds it shot up with tremendous force.","A typical British trough was about half a kilometre long, and an engine could pick up thousands of litres in a few seconds. Picking up water at speed was exciting and sometimes very wet. Troughs were laid on nearly all of Britain's main lines, and American railways such as the Pennsylvania and the New York Central used them too, calling them track pans."]},{"heading":"Where Does All the Energy Go?","paragraphs":["Here is the steam engine's biggest weakness. If you could measure all the energy stored in the coal shovelled into the firebox, and then measure how much of it ended up actually pulling the train, the answer would be disappointing. A typical steam locomotive turned only about 5 to 10 percent of its fuel's energy into useful pulling work. The very best, carefully designed and run engines did a little better, but even they threw away almost nine-tenths of their energy. So where did it all go?","Some of the energy never even got into the water. Part of the coal fell through the grate unburned, or was blown out of the chimney as sparks and cinders by the strong draught. Hot gases still left the chimney at high temperatures, carrying heat straight into the sky. The boiler and firebox also lost heat through their outer walls, even though they were wrapped in insulation, and on a cold, windy day that loss was larger.","The biggest loss of all was the exhaust steam. When the used steam is shot up the chimney, it is still hot and still carries most of the energy that was needed to turn water into steam in the first place. That energy, the heat needed just to make water boil into vapour, is enormous. Big stationary steam engines in factories and power stations could save much of it by cooling the used steam in a condenser, the idea James Watt patented in 1769. But a condenser is big and heavy and needs lots of cooling water, so almost all locomotives simply threw their steam away, accepting the loss in exchange for a simple engine and the fire-fanning blast from the chimney.","Remember these weaknesses, because they matter later in the story. In Part 17, you will meet engines that turned several times more of their fuel's energy into useful work, did not need water stops, could be started in minutes and needed far less daily care. Those advantages, more than anything, are why steam power eventually left the main lines of the world, even though so many people still love it."]},{"heading":"Mallard: Steam at Full Speed","paragraphs":["Even with all those weaknesses, steam locomotives could be astonishing machines. The most famous proof came on Sunday 3 July 1938, on a long, gentle downhill stretch of the East Coast Main Line called Stoke Bank, south of Grantham in Lincolnshire.","The engine was Mallard, a blue streamlined locomotive of the London and North Eastern Railway's A4 class. It had been designed by the LNER's chief mechanical engineer, Sir Nigel Gresley, built at Doncaster Works and had entered service only four months earlier, in March 1938. The A4s had a sleek, wedge-shaped front end that was tested in a wind tunnel, so that air would flow smoothly over the engine and lift the smoke away from the driver's view. Mallard also had the improved double chimney and blastpipe you read about earlier.","That day, Mallard was officially out on brake tests, pulling a train of seven coaches. One of them was a dynamometer car, a special carriage packed with instruments that measured the train's speed and pulling force and recorded them on a roll of paper. The driver was Joseph Duddington, a very experienced engine man, and his fireman was Thomas Bray. Coming over the top of Stoke Bank, Duddington opened the engine up and let it run. Mile after mile, the speed climbed. Near the bottom of the slope, the instruments recorded a peak of 126 mph, about 203 km/h. At the time, the LNER announced the record cautiously as 125 mph.","The run came at a cost. The bearing at the big end of the middle cylinder's connecting rod overheated under the strain, and Mallard had to limp onward at reduced speed and be taken back to Doncaster Works for repairs. But the record stood, and it still stands today: no steam locomotive has ever been officially proven to go faster. There have been claims for other engines, especially in the United States and Germany, but none was measured as carefully.","But there is one more mystery to solve. The engine can push with enormous force and run at incredible speed. Yet the whole heavy train runs on just two thin strips of steel, each only a few centimetres wide on top. So what keeps it on the rails, even around curves, and how can a single engine pull such a massive load at all?"]}],"deepDive":"Why was steam so inefficient? Physics puts a hard ceiling on any heat engine. The French engineer Sadi Carnot showed in 1824 that the maximum possible efficiency depends on the difference between the hottest and coolest temperatures in the cycle. A locomotive boiler at around 15 bar makes saturated steam at roughly 200 degrees Celsius, and superheating might raise it to 350 or 400 degrees, but because the exhaust is thrown out of the chimney at about 100 degrees rather than cooled further in a condenser, the theoretical ceiling is already modest. Real losses then pile on top: incomplete combustion, sparks and unburned coal carried up the chimney by a fierce draught, hot flue gases, heat leaking from the boiler, friction in rods and bearings, and above all the latent heat locked in the exhaust steam. Measured figures vary with how power is defined. Engineers distinguish indicated power (measured inside the cylinders), drawbar power (measured at the coupling behind the tender, which is what actually pulls the train), and the net figure after the engine's own weight is moved. American studies suggest that typical mid-twentieth-century steam averaged roughly 6 to 8 percent from coal to drawbar. The French engineer Andre Chapelon rebuilt Paris-Orleans locomotives in the 1920s and 1930s with larger steam passages, better exhausts and high superheat, and these are usually reported as reaching about 12 percent, a figure that enthusiasts still debate. Compound engines, which used steam twice in high- and low-pressure cylinders, were another route to economy, popular in France but less so in Britain and America because they were more complicated to build and maintain. By comparison, a mid-century diesel-electric typically delivered around 25 to 30 percent or more. Historians therefore argue that the end of steam was less about speed or power than about running costs: water treatment and supply, daily servicing, crew labour, and fuel. It is also worth noting that the Mallard record is not completely without debate. The 126 mph figure comes from the peak reading of the dynamometer car trace; some analysts argue the speed sustained over a measured distance was a little lower, which is partly why the LNER first announced 125 mph. Either way, it remains the highest properly recorded speed for a steam locomotive.","funFact":"When a steam train scoops water from a trough at speed, it can pick up thousands of litres in a few seconds without stopping, a system first used in 1860 at Mochdre in North Wales.","check":{"q":"What does the blastpipe do on a steam locomotive?","a":"It shoots used steam up the chimney, pulling air through the fire to make it burn hotter","wrong":["It lets the driver make the train go backwards","It pumps fresh water into the boiler","It stops the boiler from bursting when the pressure gets too high"]},"sources":[{"title":"Steam locomotive","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Steam_locomotive"},{"title":"LNER Class A4 4468 Mallard","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mallard_(locomotive)"},{"title":"Water trough","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Water_trough"},{"title":"Valve gear","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Valve_gear"},{"title":"Superheater","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Superheater"},{"title":"Fusible plug","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fusible_plug"},{"title":"Union Pacific Big Boy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Union_Pacific_Big_Boy"},{"title":"Tender (rail)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tender_(rail)"}],"photos":[{"src":"img/deep/railways/09-1.jpg","alt":"Diagram of a steam locomotive, outside and cut open, showing the glowing firebox, boiler tubes, smokebox and driving wheels.","file":"Steam locomotive scheme new.png","url":"https://commons.wikimedia.org/wiki/File:Steam_locomotive_scheme_new.png","author":"Panther","license":"CC BY-SA 3.0"},{"src":"img/deep/railways/09-2.jpg","alt":"The blue streamlined LNER A4 No. 4468 Mallard, the fastest steam locomotive ever, at the National Railway Museum, York.","file":"LNER Class A4 4468 Mallard National Railway Museum (1).jpg","url":"https://commons.wikimedia.org/wiki/File:LNER_Class_A4_4468_Mallard_National_Railway_Museum_(1).jpg","author":"BWard 1997","license":"CC BY 3.0"},{"src":"img/deep/railways/09-3.jpg","alt":"On the footplate of Black Five No. 44871: the fire glows through the open firebox door, below the regulator and gauge glasses.","file":"On the footplate of LMS Stanier Black Five locomotive 44871 - geograph.org.uk - 6235644.jpg","url":"https://commons.wikimedia.org/wiki/File:On_the_footplate_of_LMS_Stanier_Black_Five_locomotive_44871_-_geograph.org.uk_-_6235644.jpg","author":"Walter Baxter","license":"CC BY-SA 2.0"}],"words":4378},{"n":10,"title":"Rails, Wheels, Bridges and Tunnels","when":"How it works","summary":"Train wheels are not flat like a toy car's. They are shaped like slightly sloping cones, and that clever shape keeps the train steering itself along the rails. Railway builders also dug giant tunnels and built amazing bridges so trains could travel on gentle, smooth paths.","sections":[{"heading":"Steel on Steel: The Secret of Easy Rolling","paragraphs":["Try this experiment in your head. Push a heavy shopping trolley across a thick carpet, then across a smooth shop floor. On the carpet it feels sluggish, as if something is holding it back. On the smooth floor it glides. The difference is called rolling resistance: the force that tries to slow down anything that rolls. Railways are, above all, a way of making rolling resistance as small as possible.","When a rubber car tyre rolls along a road, it squashes flat where it touches the ground and then springs back as it rolls on. Rubber is not a perfect spring. Each time it squashes and recovers, a little energy is lost as heat. That is one reason tyres get warm on a long drive. A steel wheel on a steel rail behaves very differently. Steel is extremely hard and stiff, so the wheel and rail squash only a tiny amount where they meet. The patch where a train wheel touches the rail is only about the size of a small coin, even though it may be carrying ten tonnes or more.","Engineers measure rolling resistance with a number called the coefficient of rolling resistance. For a car tyre on asphalt it is roughly 0.01, which means that for every 100 kilograms of weight, about 1 kilogram's worth of force is needed just to keep it rolling on the level. For a steel railway wheel on a steel rail it is commonly about 0.001 to 0.002, and in ideal conditions even lower. In other words, a train wheel rolls roughly five to ten times more easily than a car tyre. That is the same big idea from the very beginning of our story, when miners found that a horse could pull far more on a smooth wooden track than on a muddy road.","This is why a single locomotive can haul a freight train weighing several thousand tonnes, something no lorry could ever do. It is also why railways are so energy-efficient for moving heavy things a long way. But low friction has a downside too. The same smoothness that lets a train roll easily also means its wheels have less grip than tyres on a road. A train needs a long distance to stop, and it struggles to climb steep hills, because the driving wheels simply slip. Keep that in mind, because it shapes almost everything about how railways are built."]},{"heading":"The Clever Cone: How Wheels Steer Themselves","paragraphs":["Most people think train wheels stay on the rails because of the flanges, the raised lips on the inside edge of each wheel. Flanges are important, but they are not the main thing doing the steering. The real secret is much more elegant, and you can see it if you look closely at a train wheel. The part that rests on the rail, called the tread, is not flat like a cylinder. It is very slightly sloped, like a slice from a cone, getting a little narrower toward the outside edge. A common slope is about 1 in 20. The rails themselves are usually tilted slightly inward to match.","The second part of the secret is that a pair of train wheels is fixed solidly to one axle. Together they make a single unit called a wheelset. The two wheels cannot turn at different speeds, the way the wheels of a car can. Whatever one wheel does, the other must do exactly the same.","Now imagine the wheelset drifts a little to the left. The left wheel now rests on its wider part, nearer the flange, so it has a bigger rolling circle. The right wheel rests on its narrower part, with a smaller rolling circle. Because both turn at the same rate, the bigger left wheel travels a bit further with each turn than the smaller right one. That makes the wheelset curve back toward the right, toward the middle of the track. If it drifts right, the same thing happens in reverse. The wheelset keeps gently steering itself back to the centre, without the flanges ever needing to touch the rail.","The cone shape works even better on curves. Going round a bend, the outer rail is longer than the inner rail, so the outer wheel has further to go. As the train enters the curve, the wheelset naturally slides a little toward the outside. The outer wheel then rolls on its larger diameter and the inner wheel on its smaller one, so the outer wheel covers more ground with each turn, exactly what is needed. On gentle curves, a well-shaped wheelset steers round almost entirely by itself.","So what are flanges for? They are the safety backup. On sharp curves, at points where trains change track, or if something knocks the train sideways, the flange presses against the side of the rail and stops the wheel from climbing off. When flanges do grind against the rail, you often hear it as a loud, high squeal on tight curves. The BART metro system around San Francisco was built with flat, cylinder-shaped wheel treads, and after years of passenger complaints about squealing it began reshaping its wheels into cones in 2016.","The self-steering cone has one quirk. Because the wheelset always overshoots the centre a little, it gently swings from side to side in a long, smooth wave as it travels. At normal speeds this is harmless. But above a certain speed, the swaying can grow instead of dying away, making the vehicle shake violently from side to side. Engineers call this hunting. It was first noticed in the late nineteenth century as trains got faster, and taming it with better suspension and carefully chosen wheel shapes was one of the keys to the high-speed trains you will meet in Part 18."]},{"heading":"Building the Track: Gauge, Sleepers, Ballast and Points","paragraphs":["A railway track looks simple: two steel rails, a row of crossbeams and a bed of stones. But every piece has a job. The distance between the inner edges of the two rails is called the gauge. As you saw in Part 6, George Stephenson used 4 feet 8 and a half inches, or 1,435 millimetres, the width of the colliery wagonways he knew, and this standard gauge spread to much of the world. Other countries chose broader or narrower gauges, which is why some borders still have stations where passengers change trains or where special equipment changes the wheels.","The rails rest on crossbeams called sleepers in Britain and ties in North America. Sleepers hold the two rails exactly the right distance apart and spread the weight of passing trains over a wider area. The very first railways often used separate stone blocks under each rail, which left a clear path for horses to walk between them. But heavy locomotives pushed the blocks apart, so wooden sleepers took over. Wood, usually soaked in a tar-like preservative called creosote to stop it rotting, is still the most common material in North America. Many modern main lines, especially in Europe and Asia, use heavy sleepers of prestressed concrete, which hold the track very steady. On a North American main line there can be about 2,000 wooden ties in every kilometre.","Under and around the sleepers is the ballast: a deep bed of crushed stone with sharp, jagged edges. The edges lock together, holding the sleepers firmly so the track cannot shift sideways or lengthways. The gaps between the stones let rainwater drain away quickly, so the ground underneath does not turn to mud, and the stony bed makes it hard for plants to grow. Ballast is usually at least 15 centimetres deep, and on high-speed lines it can be up to about half a metre. The word comes from the stones once used in the bottom of ships to keep them steady.","To move a train from one track to another, railways use points, called switches in North America. A set of points has two movable, tapered rails called switch blades lying against the fixed outer rails. Move the blades one way and the wheel flanges are guided onto the straight track. Move them the other way and the wheels are steered onto the branching track. Further along, where one rail of the new route has to cross a rail of the old one, there is a V-shaped piece called the frog, with short guard rails beside it to keep the wheels on the right path through the gap.","Points have a long history. A mining engineer named John Curr described a simple single-blade design in 1797, and Charles Fox patented an improved sprung design in 1838. Early points were thrown by hand with a lever beside the track. Today most are moved by electric, air-powered or hydraulic motors controlled from a distant signalling centre. The motors have built-in electrical checks: if the blades are not fully moved and locked, the signal for that route stays at red. In snowy countries, points are fitted with gas or electric heaters so that ice cannot jam them."]},{"heading":"Gentle Slopes, Wide Curves and Cog Wheels","paragraphs":["Remember that steel wheels on steel rails have little grip. On level track that does not matter much, but on a slope, a heavy train is constantly trying to roll backwards. Even a gentle hill makes a huge difference. At a slow speed, pulling a heavy train up a slope of just 1 percent, meaning 1 metre up for every 100 metres along, can take roughly five to ten times as much force as pulling it on the flat. Railway engineers often write slopes as ratios: 1 in 100 is the same as 1 percent.","So railway builders worked very hard to keep their lines nearly level. Most main lines keep their slopes below about 2 percent, and many are far gentler. Brunel laid much of the Great Western Railway's main line from London so flat that some stretches climbed only 1 in 1,320, which earned it the nickname Brunel's billiard table. The steepest slope on a line, which decides how heavy a train each engine can pull, is called the ruling gradient. Curves are a problem too. A sharp curve slows trains down and wears out wheels and rails, so main lines use wide, sweeping curves wherever they can.","To keep a railway level across hilly country, engineers moved mountains of earth and rock. Where the land rose, they dug cuttings, deep trenches with the track running along the bottom. Where it fell, they built embankments, long raised banks of earth, often using the very rock and soil dug out of the nearby cuttings. To cross deep valleys and rivers they built viaducts, long bridges on rows of arches, like the Sankey Viaduct with its nine arches that you met in Part 8. Where a hill was too high to cut through, they built tunnels. In high mountains, some lines even loop round in complete circles inside the mountainside, in spiral tunnels, climbing a little with every lap.","What about really steep mountains? A normal train held only by friction cannot climb much more than about 10 percent. A few city tramways do better, such as a famous tram line in Lisbon that climbs nearly 14 percent, but that is close to the limit. For steeper climbs, engineers went back to an idea from the very first commercial steam engine, Salamanca of 1812: the rack, or cog, railway. A toothed rail called a rack is laid between the running rails, and a cogwheel under the train meshes with it, so the train climbs like a gear climbing a ladder and cannot slip back.","The Mount Washington Cog Railway in New Hampshire, USA, built by Sylvester Marsh, opened to the public in 1868 and still climbs one of the highest peaks in the north-eastern United States. In Switzerland, Niklaus Riggenbach opened the Vitznau to Rigi railway in 1871, the first mountain rack railway in mainland Europe. Later inventors improved the rack. Carl Roman Abt designed a cheaper version in 1882, and Eduard Locher created a rack with teeth on its sides for the Pilatus Railway near Lucerne, opened in 1889. Pilatus is still the steepest rack railway in the world, climbing slopes of up to 48 percent. Rack trains are slow, usually 9 to 25 km/h, but they can reach places no ordinary train ever could."]},{"heading":"Brunel's Box Tunnel: Digging by Candlelight","paragraphs":["One of the boldest tunnels of the early railway age lies between Bath and Chippenham in the west of England. Isambard Kingdom Brunel wanted his Great Western Railway from London to Bristol to be as straight and level as possible, and a large hill called Box Hill stood in the way. Instead of going round it, he decided to go straight through.","Work began in December 1838. Shafts were sunk down from the hilltop so that teams of workers could dig outward in several directions at once, as well as inward from both ends. The workers, called navvies, broke the rock with picks, shovels and gunpowder. The only light deep underground came from candles, and the job was said to burn through about a tonne of candles every week, and about the same weight of gunpowder. Water constantly poured in through cracks in the rock and had to be pumped out. Parts of the tunnel were lined with more than 30 million bricks, while some sections through solid stone were left as bare rock.","The work was dangerous. About 100 navvies are thought to have died building the tunnel, many in blasting accidents and floods. When the Box Tunnel opened on 30 June 1841, it was about 2.95 km long and was then the longest railway tunnel in the world. It is perfectly straight and slopes down at a steady 1 in 100. Some people at the time feared that passengers would be harmed by rushing through such a long, dark tunnel, but trains have used it safely ever since.","There is a famous story that Brunel lined the tunnel up so that the rising sun shines straight through it on his birthday, 9 April. It is a lovely legend, but it is probably not true. Calculations suggest the sun lines up best a few days earlier, around 6 or 7 April, and checks in recent years found that on 9 April it does not shine fully through."]},{"heading":"The Forth Bridge: A Red Steel Giant","paragraphs":["In the east of Scotland, a wide sea inlet called the Firth of Forth cut off Edinburgh from the lands to the north. Trains had to stop and passengers crossed by ferry. A bridge was planned, but the plan was dropped after another Scottish railway bridge, over the River Tay, collapsed in a storm in 1879, a disaster you will read about in Part 14. Whatever was built across the Forth now had to be, and look, completely safe.","The engineers Sir John Fowler and Sir Benjamin Baker chose a design called a cantilever. Three huge diamond-shaped towers of steel tubes stand in the water, each with arms reaching out on both sides. Shorter girders hang between the tips of the arms, joining them together. To show the public how it worked, they staged a famous demonstration in 1887. Two men sat on chairs with their arms stretched out, gripping poles that pushed against their chairs, and a third man, the Japanese engineer Kaichi Watanabe, sat on a plank hanging between them. The two outer men were the towers, their arms were the cantilevers, and bricks piled behind them acted as anchors. When weight was put in the middle, everyone could see which parts were being pulled and which were being squashed.","The numbers are enormous. The bridge is about 2.5 km long, and each of its two main spans stretches about 520 metres, which made them the longest bridge spans in the world when it opened. It used around 55,000 tonnes of steel, one of the first great structures built mainly of steel instead of iron, and about 6.5 million rivets. Thousands of people worked on it, and many died in falls and accidents. Records are incomplete, but modern research has found that at least 78 workers lost their lives.","The bridge was opened on 4 March 1890 by the Prince of Wales, the future King Edward VII, who drove in the last rivet. Over 130 years later it still carries up to about 200 trains a day. Its red paint is so famous that painting the Forth Bridge became a British saying for a job that never ends. In 2015 it was named a UNESCO World Heritage Site."]},{"heading":"Under the Alps: The Gotthard Tunnel","paragraphs":["The Alps, the great mountain wall of Switzerland, stood between northern Europe and Italy. In the 1870s, engineers set out to drive a railway tunnel right under the Gotthard Pass, from the village of Göschenen in the north to Airolo in the south, a distance of about 15 km. No railway tunnel anywhere was so long.","The project was led by the Swiss engineer Louis Favre. Two teams dug toward each other from opposite ends, guided by careful surveying over the mountains. It was one of the first projects to use dynamite on a huge scale, invented by Alfred Nobel only a few years earlier. Drills driven by compressed air bored holes in the rock face, the holes were packed with dynamite, and after each blast the broken rock was carted away. The compressed air also helped to ventilate the tunnel, but conditions deep inside were terrible: hot, wet, dusty and full of fumes.","The human cost was very high. Around 200 workers, most of them from Italy, are thought to have been killed, mostly in accidents, and many more fell ill, including from a hookworm infection that spread in the filthy tunnel. In 1875 workers went on strike over their conditions, and the strike was put down by force, leaving four of them dead. Favre himself died of a heart attack inside the tunnel in July 1879, months before his teams met. On 29 February 1880 the two bores broke through to each other, lined up with great accuracy.","The tunnel opened to trains in 1882. To reach its entrances, the line climbs the steep valleys on both sides using looping spiral tunnels, so that passengers see the same church on the hillside from three different heights as the train climbs. The Gotthard became one of the most important railway links in Europe, and the even longer Gotthard Base Tunnel you will meet in Part 18 now runs far below it."]},{"heading":"Signals and the Block: One Train at a Time","paragraphs":["A train is very heavy and has little grip, so it cannot stop quickly. A driver who sees another train ahead may not be able to stop in time. Keeping trains apart is therefore the most important safety job on any railway. On the earliest lines, men called railway policemen stood beside the track and used hand signals and flags. They used a method called time-interval working: once a train passed, they waited a set number of minutes before letting the next one go. But if the first train broke down or slowed, the second could run straight into it.","The answer came with the electric telegraph. In 1842, William Fothergill Cooke described a better way in his book Telegraphic Railways: divide the line into sections, called blocks, and allow only one train in each block at a time. Each block has a signal box at its entrance, linked to the next box by telegraph wire. Before a train can enter, the signalman must ask the box ahead whether the line is clear, using a code of rings on a bell. Only when the box ahead replies that the line is clear can the signal be cleared, and only when the train has passed out of the section can the next one be sent. This is called the absolute block system.","Railways adopted the block system gradually through the 1850s and 1860s. By 1872 it covered almost half of Britain's lines, and in 1889, after a terrible accident at Armagh in Ireland, a new law made it compulsory on passenger lines. Signal boxes were also fitted with interlocking, a frame of levers mechanically linked so that a signalman could not clear a signal unless the points were set correctly for that route, an idea you will learn more about in Part 14.","The signals themselves changed over time too. Early signals were boards, discs or flags. The most common type became the semaphore, a pivoting arm on a tall post: arm straight out meant stop, arm angled meant go. At night, lamps behind coloured glass showed the same message. At first white light meant clear and red meant danger, but a white light could be confused with an ordinary lamp, so green took over for clear. Today, most main lines use coloured light signals and electrical track circuits that detect where every train is automatically, but the basic rule is the same as in 1842: one train, one block.","So now you know the secret of the railway. Smooth steel, cone-shaped wheels, gentle slopes and clever signals let one engine pull an enormous load safely over long distances. In crowded Britain, these ideas were squeezed into a small island. But across the Atlantic was a young country with vast open spaces, huge distances and almost no good roads, and it was hungry for railways."]}],"deepDive":"Why does a coned wheelset steer itself, and why can it go wrong? Suppose the tread slopes with a conicity k, the wheel radius is r and the distance between the two rolling contact points is d. If the wheelset shifts sideways by a distance y, one wheel's rolling radius grows by about ky and the other's shrinks by the same amount. Because both wheels are locked to one axle, the wheelset must yaw toward the centre, and the geometry gives a curving path whose wavelength, worked out by the German engineer Klingel in 1883, is about 2 pi times the square root of rd divided by 2k. For a standard-gauge wheelset with a 1-in-20 cone, that wavelength is around 15 to 20 metres: the axle wanders gently from side to side every few lengths of a carriage. Klingel's simple model ignores forces. In reality, the wheel and rail meet at a tiny elastic contact patch where they slightly creep against each other, and the wheelset has mass and inertia. Below a critical speed the side-to-side wandering dies away; above it, inertia makes the motion overshoot more each time and it grows into hunting, which can hammer the flanges into the rails and even cause derailment. Engineers raise the critical speed with stiffer yaw restraint, yaw dampers, longer wheelbases and gentler cones; Japanese Shinkansen engineers chose less conical wheels to run above 200 km/h. There is a trade-off: a gentle cone is stable at speed but steers less well round tight curves, which is why metro trains and high-speed trains use different wheel profiles, and why worn wheels are regularly re-turned on lathes to restore their shape. Rolling resistance is another field with careful numbers. Commonly quoted coefficients are about 0.001 to 0.002 for a loaded rail wagon, versus roughly 0.006 to 0.015 for car tyres on asphalt. Yet trains do not win on every measure: an old, heavy passenger train with few riders can use more energy per passenger than a full car, while a modern lightweight high-speed train carrying hundreds of people is far more efficient. Historians also debate engineering safety culture. The Box Tunnel, the Forth Bridge and the Gotthard all show that nineteenth-century construction deaths were treated as a normal cost of progress, and death tolls were poorly recorded. Recent research on the Forth Bridge has raised its known toll from 57 in early accounts to at least 78, a reminder that the heroic engineering stories leave out many of the people who did the work.","funFact":"In 1887, to explain how the Forth Bridge would work, its engineers sat a Japanese engineer, Kaichi Watanabe, on a plank hung between two men who acted as human cantilevers.","check":{"q":"What mainly keeps a train's wheelset centred on the rails on straight track?","a":"The cone-shaped (sloped) wheel treads on a solid axle","wrong":["The flanges rubbing against the rails all the time","Magnets in the rails","The driver steering with a wheel in the cab"]},"sources":[{"title":"Wheelset (rail transport)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wheelset_(rail_transport)"},{"title":"Hunting oscillation","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hunting_oscillation"},{"title":"Rolling resistance","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rolling_resistance"},{"title":"Rack railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rack_railway"},{"title":"Box Tunnel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Box_Tunnel"},{"title":"Forth Bridge","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Forth_Bridge"},{"title":"Gotthard Rail Tunnel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gotthard_Rail_Tunnel"},{"title":"Absolute block signalling","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Absolute_block_signalling"}],"photos":[{"src":"img/deep/railways/10-1.jpg","alt":"The red Forth Bridge in Scotland: its approach viaduct leads to the giant steel cantilevers across the Firth of Forth.","file":"Forth Bridge 20140319.jpg","url":"https://commons.wikimedia.org/wiki/File:Forth_Bridge_20140319.jpg","author":"Suicasmo","license":"CC BY-SA 4.0"},{"src":"img/deep/railways/10-2.jpg","alt":"The 'living model' of the Forth Bridge: two men act as cantilevers holding up engineer Kaichi Watanabe in the middle.","file":"Cantilever bridge human model.jpg","url":"https://commons.wikimedia.org/wiki/File:Cantilever_bridge_human_model.jpg","author":"Unknown photographer for Benjamin Baker.","license":"Public domain"},{"src":"img/deep/railways/10-3.jpg","alt":"Rows of railway wheelsets: two flanged wheels fixed to each solid axle, with axle-box bearings on the ends.","file":"Wheelsets of rail vehicles with fitted journals.jpg","url":"https://commons.wikimedia.org/wiki/File:Wheelsets_of_rail_vehicles_with_fitted_journals.jpg","author":"Ural-66","license":"CC BY-SA 4.0"}],"words":3949},{"n":11,"title":"Rails Across America","when":"1827 – 1865","summary":"America was huge, and horses were slow, so Americans built railroads of their own. A tiny engine called Tom Thumb raced a horse (and lost when a belt slipped!), and soon American trains had cowcatchers, bells and swivelling wheels for curvy tracks. During the Civil War, trains carried soldiers, and President Lincoln signed a law to build a railroad all the way to the Pacific.","sections":[{"heading":"A Huge Country, a Slow Way to Cross It","paragraphs":["Picture the United States in the 1820s. It was a young country, only about fifty years old, and it was enormous. Most Americans lived near the Atlantic coast, but settlers were pushing west across the Appalachian Mountains towards the Ohio River and the great valley of the Mississippi. Between the farms of the west and the ports of the east lay hundreds of miles of forest, hills and rough dirt roads.","Moving things across that distance was painfully slow. A farmer in Ohio could grow a fine crop of wheat or corn, but hauling it east by wagon could cost more than the crop was worth. For most of history, the speed of a journey over land had been set by the speed of a horse.","Then, in 1825, the State of New York opened the Erie Canal, a man-made waterway about 580 km (363 miles) long that joined the Hudson River to the Great Lakes. Suddenly, goods from the west could float all the way to New York City cheaply. New York boomed. Other port cities watched with alarm. If all the trade of the west poured into New York, what would happen to them?","One of the most worried cities was Baltimore, in Maryland. Baltimore was a busy port, but it had no easy water route to the west, because mountains stood in the way and a canal over them would be fantastically difficult. Some Baltimore merchants had been reading news from England, where the Stockton and Darlington Railway had opened in 1825 and engineers were arguing about locomotives. Perhaps, they thought, a railway could do what a canal could not.","Americans were watching British experiments closely. In 1829 an engineer named Horatio Allen ran a British-built locomotive called the Stourbridge Lion on a coal company track at Honesdale, Pennsylvania. It was one of the first steam locomotives ever to run in America, but it was too heavy for the light wooden track, and it never went into regular service.","So America began by borrowing British ideas. But very soon, American engineers would discover that their country needed trains of its own design. Their land was wider, wilder and cheaper; their money was scarcer; and their tracks would have to wiggle around hills instead of tunnelling straight through them. The story of American railways is the story of taking a British invention and reshaping it for a whole continent."]},{"heading":"A First Stone on the Fourth of July","paragraphs":["In February 1827 the State of Maryland granted a charter, a legal permission to exist and to build, to a brand new company: the Baltimore and Ohio Rail Road. Virginia agreed a few weeks later. The plan was breathtakingly bold. The company would build a railway all the way from Baltimore over the Appalachian Mountains to the Ohio River, hundreds of miles away. At the time, nobody in America had ever built anything like it.","The founders chose a very special day to start. On 4 July 1828, the 52nd birthday of the United States, a huge crowd gathered in Baltimore for a parade with bands, banners and marching tradesmen. The guest of honour was a man of about 90 named Charles Carroll of Carrollton. Carroll was the last living person who had signed the Declaration of Independence in 1776. He lifted a spade and helped set the first stone of the new railroad. He is said to have remarked that he considered this one of the most important acts of his life, second only to signing the Declaration. Whether he used exactly those words is hard to prove, but the meaning of the day was clear: the old revolution was handing the future to a new one.","Building the line was slow and expensive. The B and O's engineers had very little experience, so they learned as they went. Some of the early track was made of stone blocks or wooden rails topped with thin strips of iron. Workers dug cuttings, built embankments and put up handsome stone bridges. One of them, the Thomas Viaduct at Relay, Maryland, was finished in 1835. Its graceful curve of stone arches made it the longest bridge in the United States at the time, and amazingly it still carries trains today.","The first section of line opened on 24 May 1830. It ran about 13 miles (21 km) west from Baltimore to Ellicott's Mills, a mill town on the Patapsco River now called Ellicott City. Passengers could ride there and back for a day out. But here is a surprise: those first B and O trains were pulled by horses. The company was not yet sure that steam locomotives would work on its sharply curving track, and some directors even experimented with a car pushed by a sail and with a horse walking on a treadmill inside a car.","The B and O kept pushing west for more than twenty years. It finally reached the Ohio River in 1852 and the city of Wheeling, in what is now West Virginia, on 1 January 1853. By then it had become one of the most important railroads in America. But in 1830, the company still had to be convinced that steam was the answer. That job fell to a small, noisy engine with a funny name."]},{"heading":"Tom Thumb and the Great Race","paragraphs":["Peter Cooper was a New York businessman and inventor who had bought land in Baltimore and badly wanted the railroad to succeed. Many experts claimed that locomotives could never manage the B and O's tight curves. Cooper believed they were wrong, and in 1829 he decided to prove it by building a little locomotive himself.","He called it Tom Thumb, after the tiny hero of an old English fairy tale, because it was so small. Cooper had to improvise with whatever parts he could find. His boiler stood upright, rather than lying on its side as in British engines, and according to the well-known story its boiler tubes were made from old rifle barrels. A single vertical cylinder drove the wheels. To make the fire burn hot enough in such a small boiler, Cooper added a fan, called a blower, that was turned by a belt from the wheels and blasted air into the fire. Tom Thumb was built as a demonstration machine, never meant to carry paying passengers day after day.","In the summer of 1830 Tom Thumb pulled an open car crowded with B and O directors out to Ellicott's Mills and back. Then came the most famous moment in its short life. On the return trip, at a place called the Relay House, a stagecoach company had brought a fine grey horse pulling a car on the parallel track. A race was arranged back towards Baltimore, a run of about 8 miles (13 km). Most historians date it to late August 1830, though old sources disagree about the exact day.","At first the horse jumped ahead, because a horse can reach full speed in a few strides while a steam engine needs time to build up. But once Tom Thumb got going it caught up, drew level and pulled ahead while the passengers cheered. Then disaster struck. The belt that drove the blower slipped off its pulley. Without the fan, the fire died down, the boiler lost pressure and the little engine slowed to a crawl. The horse trotted past and won the race.","So the horse won. But the people watching understood what they had seen. A tiny, home-made engine had outrun a strong horse until a simple belt failed, and a belt is easy to fix. The B and O's leaders were convinced. In 1831 the company held its own contest for American-built locomotives, and soon afterwards it stopped using horses on its main line. The original Tom Thumb did not survive, but in 1927 the B and O built a working replica for its 100th birthday celebration, the Fair of the Iron Horse. That replica can still be seen at the B and O Railroad Museum in Baltimore."]},{"heading":"The Best Friend of Charleston","paragraphs":["While Baltimore argued about horses and steam, another port city in the South was making its own move. Charleston, in South Carolina, was worried that cotton from inland farms was being shipped down rivers to rival ports instead of coming to its own wharves. So its merchants backed the South Carolina Canal and Rail Road Company, which planned a line inland to the town of Hamburg on the Savannah River.","This company made a bold decision right from the start: it would use steam locomotives, not horses. For its first engine it ordered a locomotive from the West Point Foundry in New York City. The engine arrived in Charleston by ship in October 1830 and was given a wonderful name: the Best Friend of Charleston. It is widely regarded as the first locomotive built entirely in the United States for regular, paying service.","On Christmas Day, 25 December 1830, the Best Friend pulled its first run with passengers aboard, and soon it was running a regular service on the first few miles of the line, about 6 miles (10 km) of track. This was the first regularly scheduled steam-powered passenger train service in the United States. The engine could pull several cars at around 15 to 25 miles per hour (about 25 to 40 km/h), faster than any horse could keep up for long. For the people of Charleston, a ride behind the puffing machine was a thrilling new adventure.","Sadly, the Best Friend's career was short. On 17 June 1831 its boiler exploded. According to accounts of the accident, the fireman, the worker who tended the fire, was annoyed by the hiss of steam escaping from the safety valve. The safety valve is the part that lets out steam when pressure gets too high, so that the boiler cannot burst. The fireman is said to have held the valve shut, or tied it down, to stop the noise. With nowhere to escape, the pressure rose and rose until the boiler blew apart. The fireman was badly injured and died; the engineer, Nicholas Darrell, survived.","It was the first locomotive boiler explosion in the United States, and it taught a hard lesson. Safety devices only work if nobody interferes with them. The railroad brought in stricter rules about who could touch the engine's controls. It also came up with a clever way to calm nervous passengers: for a while, a flat wagon piled with bales of cotton was placed between the locomotive and the passenger cars, as a cushion in case of another explosion.","The Best Friend's surviving parts were used to build a new engine with a very fitting name: the Phoenix, after the mythical bird that rises again from the ashes. And the railroad kept growing. When its line to Hamburg was finished in 1833, it ran about 136 miles (219 km), which made it, for a short time, one of the longest railways in the world. A replica of the Best Friend, built in 1928, still exists today, and Charleston has a small museum telling its story."]},{"heading":"Making the Locomotive American","paragraphs":["British railways were built like fortresses. Britain was a small, crowded and wealthy country, so its engineers could afford heavy rails, gentle curves, deep cuttings, long tunnels and fences along the line. American railroads had the opposite situation: endless distances, very little money and plenty of cheap land and timber. So American builders laid light track as fast and cheaply as they could, let it curve sharply around hills instead of cutting through them, and often left it unfenced. British-style locomotives, with their wheels fixed rigidly in a stiff frame, found such track very hard going. They bumped, rocked and sometimes jumped the rails.","The answer was one of the most important railway inventions ever made: the swivelling front truck, also called a bogie. In 1832 John B. Jervis, chief engineer of the Mohawk and Hudson Railroad in New York, built a locomotive called the Experiment whose front end rested on a small four-wheeled cart that could pivot underneath it. When the track curved, the little truck turned first and guided the rest of the engine smoothly into the bend, a bit like the front wheels of a shopping trolley swinging around a corner. The truck also spread the engine's weight over more wheels, which was gentler on flimsy rails. Locomotives with a four-wheel front truck and one pair of big driving wheels became known as the Jervis type, and the swivelling truck soon spread everywhere. Look under almost any train carriage today, anywhere in the world, and you will see bogies.","The John Bull shows the transformation clearly. It was built by Robert Stephenson and Company in Newcastle in 1831, shipped across the ocean in crates to the Camden and Amboy Railroad in New Jersey, and put together by a young mechanic named Isaac Dripps without any instructions. The Camden and Amboy Railroad's mechanics added a leading truck to help it cope with rough track. Isaac Dripps also fitted it with a pilot, a frame of sloping bars sticking out at the front. Its nickname tells you what it was for: the cowcatcher. On unfenced American lines, cattle, deer, fallen branches and other obstacles often wandered or tumbled onto the track. The pilot was shaped to push anything it hit upwards and sideways, out of the way, instead of letting it slide under the wheels and derail the train. The British mathematician Charles Babbage had suggested a similar device in England, but Dripps is usually credited with the first practical one, in 1833.","Other American features followed. Trains often ran through the night across dark countryside, so locomotives gained big headlamps at the front, at first burning oil and later lit by electricity. Large brass bells on top of the boiler, along with steam whistles, warned people and animals at the many level crossings where roads crossed the tracks with no gates. Over time the John Bull itself was given a cab to shelter the crew, a bell and a headlight.","Because America had vast forests and, in many places, little coal, early American engines often burned wood. Burning wood throws out showers of glowing sparks that could set fields and forests on fire, so many American locomotives wore huge balloon-shaped or funnel-shaped chimneys containing screens to catch the sparks. Put all these features together, the pilot, the swivelling truck, the bell, the big lamp and the fat chimney, and you have the classic look of an American locomotive from cowboy films. By the 1850s the most common design was called the American type, with four small wheels in front and four large driving wheels behind. It was simple, sturdy and flexible, and thousands were built.","The results were spectacular. By 1840 the United States had roughly 3,000 miles of railroad, by most counts more than all of Europe combined, and by 1860 it had around 30,000 miles. Railroads stitched together towns and farms, especially in the North and the Midwest, and cities like Chicago grew at astonishing speed as railway lines met there. But those same rails were about to be tested in the most terrible way of all."]},{"heading":"Rails at War","paragraphs":["In April 1861 the American Civil War began. Eleven Southern states had broken away to form the Confederacy, largely to protect slavery, and the Northern states, the Union, fought to bring them back. It was the first major war in which railways played a central part, and generals on both sides quickly learned that whoever controlled the tracks could move soldiers and food faster than the enemy could march.","Here the North had a huge advantage. Historians usually estimate that in 1861 the Northern states had roughly 22,000 miles of railroad, while the Southern states had only about 9,000. The North also had most of the factories that made rails and locomotives. Southern railroads had mostly been built for short hauls, carrying cotton from plantations to the nearest river or port, and many of them did not even join up with each other. Some used different track gauges, so in certain towns cargo had to be unloaded from one train, carried across the streets by horse and cart, and loaded onto another. When Southern locomotives wore out, there were few workshops to repair them or build new ones, and by the last year of the war the Confederate railroad system was close to collapse.","Early in 1862 the US Congress gave President Abraham Lincoln the power to take over railroads and telegraph lines for military use, and the government created the United States Military Railroad. It was run by Daniel McCallum, a former manager of the Erie Railroad, while a brilliant engineer from the Pennsylvania Railroad, Herman Haupt, took charge of construction and repairs in Virginia. Haupt's crews became famous for rebuilding wrecked bridges in days using timber cut from nearby forests. When the war began, the Military Railroad ran just 7 miles of line; by the end it controlled more than 2,000 miles and had bought, built or captured over 400 locomotives.","Armies also used trains to move troops astonishing distances. In autumn 1863, after a Union defeat at Chickamauga in Georgia, more than 20,000 Union soldiers were rushed by rail from Virginia to the area around Chattanooga, a journey of about 1,200 miles (about 2,000 km) completed in under two weeks. Marching that far would have taken months.","Because railroads were so valuable, they became targets. Soldiers tore up track, burned bridges and wrecked engines. Union troops in Georgia heated rails over bonfires and twisted them around tree trunks so they could never be reused; people called them 'Sherman's neckties', after General William T. Sherman. One of the war's most exciting episodes was the Great Locomotive Chase of 12 April 1862. A band of Union volunteers led by a civilian scout named James Andrews stole a Confederate locomotive called the General in northern Georgia and raced north, trying to wreck the line behind them. The train's conductor, William Fuller, chased them on foot, then on a handcar, then on a series of locomotives, finally steaming backwards in an engine called the Texas. After about 87 miles (140 km) the General ran out of fuel and the raiders fled into the woods. All of them were captured within about two weeks, and Andrews and several others were executed. Some of the survivors became the very first people ever awarded the US Medal of Honor. The General and the Texas both survive in museums in Georgia today."]},{"heading":"The Underground Railroad: A Railroad That Wasn't","paragraphs":["Before and during these years, Americans talked about another 'railroad', and it is important to be very clear about it. The Underground Railroad was NOT a real railway. It had no tracks, no tunnels and no locomotives. It was a secret network of brave people, Black and white, free and formerly enslaved, who helped enslaved people escape from the Southern states to freedom in the North, in Canada, and sometimes in Mexico or the Caribbean.","The name appeared in print in 1842 and became popular in the 1840s, just as real railroads were the most exciting new thing in the country. The man who first printed it, an abolitionist named Thomas Smallwood, said it came from a Baltimore constable who joked that escapers vanished so completely they must have travelled by 'underground rail-road'. Whatever its exact origin, the idea caught on, because railway words made a perfect secret code. People who guided escapers were called 'conductors'. Safe houses where they could hide, eat and rest were 'stations' or 'depots', and the people who ran them were 'station masters' or 'stationmasters'. The escaping people themselves were sometimes called 'passengers' or 'cargo'. Canada, where slavery was illegal, was nicknamed the 'Promised Land', and the Ohio River, the border between slave states and free states, was the 'River Jordan'.","Most freedom seekers travelled on foot, often at night, following rivers or the North Star, hiding in barns, cellars, attics and swamps. The most famous conductor was Harriet Tubman, who escaped from slavery in Maryland herself and then went back about 13 times, leading around 70 people, including members of her own family, to freedom. In Philadelphia, a free Black man named William Still helped hundreds of people and secretly kept careful records of their stories, which he later published in 1872.","Sometimes real trains did play a part. In September 1838 a young man named Frederick Douglass escaped from slavery in Baltimore by boarding a northbound train, dressed in a sailor's uniform and carrying papers borrowed from a free Black sailor. With the help of Anna Murray, the free woman he would soon marry, he reached New York in less than a day. He went on to become one of the greatest speakers and writers in American history.","Nobody knows exactly how many people escaped this way, because the whole network depended on secrecy. One estimate suggests around 100,000 people had escaped by 1850. Escaping became even more dangerous after the Fugitive Slave Act of 1850, which forced officials in free states to help catch escapers, and many freedom seekers then pushed on all the way to Canada. The Underground Railroad borrowed the language of the railway age, but its engine was courage."]},{"heading":"A Railroad to the Pacific","paragraphs":["By the 1850s America stretched all the way to the Pacific Ocean. California had joined the United States in 1850, just after the Gold Rush brought tens of thousands of fortune-seekers west. But getting there was an ordeal. Travellers could spend four to six months bumping across plains, deserts and mountains in a covered wagon, or sail for months around the tip of South America, or take a ship to Panama, cross its jungles and catch another ship north. Many people dreamed of a Pacific railroad that would join the two coasts.","The problem was not just mountains. It was politics. In 1853 Congress paid for army surveys of several possible routes, but Northern and Southern politicians could not agree. A Northern route would help Northern cities and spread free states westward; a Southern route would help the South and might spread slavery. Year after year, the arguments went nowhere.","The Civil War broke that deadlock. When the Southern states left the Union, their members of Congress left too, and the remaining lawmakers could choose a central route. On 1 July 1862, in the middle of the war, President Abraham Lincoln signed the Pacific Railway Act. Lincoln had worked as a lawyer for railroad companies in Illinois before becoming president, and he strongly believed a railroad would help hold the country together.","The Act gave the job to two companies. The Central Pacific Railroad, already set up in California, would build eastward from Sacramento. A brand new company, the Union Pacific Railroad, would build westward from the Missouri River. Because nobody would risk building through empty plains and mountains without help, the government offered huge rewards. For every mile of track, each company received grants of public land in a checkerboard pattern on both sides of the line, about 6,400 acres per mile, which it could sell to settlers. It also received government bonds, a kind of loan, worth $16,000 for every mile on flat ground, $32,000 in the hilly country and $48,000 per mile in the high mountains. Of course, that land was not really empty. It was home to many Native American nations, a part of the story we will face honestly in the next chapter.","So the stage was set for one of the greatest building contests in history. On one side, in California, a company whose route led straight into the granite walls of the Sierra Nevada. On the other, far away on the banks of the Missouri River near Omaha, a company facing a thousand miles of open plains and the Rocky Mountains beyond. Each was paid by the mile, so each wanted to build as fast as it possibly could. Two railroads, one starting in California and one on the Missouri River, were about to race towards each other to meet somewhere in the middle."]}],"deepDive":"Why did American railways look and behave so differently from British ones? Economic historians point to the price of things. In Britain, land and labour were expensive but capital (money for investment) was relatively plentiful, so engineers built for the long term: heavy rails, gentle curves, solid stone viaducts and long tunnels, paid for up front. In the United States the situation was reversed. Land and timber were cheap, skilled labour and capital were scarce, and distances were vast. It made sense to build quickly and cheaply, accept sharp curves and steep grades, and improve the line later once traffic paid for it. That choice shaped the machines. Swivelling leading trucks (Jervis, 1832), equalising levers that spread weight across wheels on uneven track, and the flexible 4-4-0 American type were all answers to poor track rather than ideal track. Historians also debate how important railroads really were to American growth. In 1964 the economist Robert Fogel famously argued that if the US had never built railroads and had relied on canals and wagons instead, its national income in 1890 would have been only a few percent lower. His 'counterfactual' method was hugely influential and helped win him a share of the 1993 Nobel Prize in economics, but many historians replied that railroads also changed things that are hard to measure: where cities grew, how businesses were organised, and how fast people and information could move. The Civil War offers another debate. The North's roughly 22,000 miles of track versus the South's roughly 9,000 are often quoted, but historians stress that quality mattered as much as quantity. Southern lines used several gauges, were poorly connected, and depended on Northern or foreign factories for rails and engines. Once the blockade cut off imports, the South could not replace worn-out equipment, while Union railroad managers such as Daniel McCallum pioneered organised timetables, repair crews and chains of command that later influenced how large American corporations were run. Finally, a note on 'firsts': the Baltimore and Ohio is often called America's first common-carrier railroad (open to anyone who paid), the Best Friend of Charleston ran the first scheduled steam passenger service, and the Stourbridge Lion made one of the first locomotive runs. Each claim is true in its own carefully worded way.","funFact":"The first stone of the Baltimore and Ohio Railroad was laid on 4 July 1828 with the help of Charles Carroll, who had signed the Declaration of Independence 52 years earlier.","check":{"q":"Why did Peter Cooper's Tom Thumb lose its 1830 race against a horse?","a":"The belt driving its fire blower slipped off, so the engine lost power","wrong":["It ran out of water in the first mile","The horse took a shortcut across a field","A cow wandered onto the track and blocked it"]},"sources":[{"title":"Baltimore and Ohio Railroad","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Baltimore_and_Ohio_Railroad"},{"title":"Tom Thumb (locomotive)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tom_Thumb_(locomotive)"},{"title":"Best Friend of Charleston","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Best_Friend_of_Charleston"},{"title":"John Bull (locomotive)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Bull_(locomotive)"},{"title":"John B. Jervis","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_B._Jervis"},{"title":"United States Military Railroad","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/United_States_Military_Railroad"},{"title":"Underground Railroad","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Underground_Railroad"},{"title":"Pacific Railroad Acts","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pacific_Railroad_Acts"}],"photos":[{"src":"img/deep/railways/11-1.jpg","alt":"A replica of Peter Cooper's tiny Tom Thumb locomotive, with its upright boiler, pulling an open passenger car.","file":"Peter Cooper's Tom Thumb LCCN89716086.jpg","url":"https://commons.wikimedia.org/wiki/File:Peter_Cooper%27s_Tom_Thumb_LCCN89716086.jpg","author":"Miscellaneous Items in High Demand, PPOC, Library of Congress","license":"Public domain"},{"src":"img/deep/railways/11-2.jpg","alt":"The John Bull locomotive of 1831, with its pilot (cowcatcher) in front, at the Smithsonian in Washington, DC.","file":"John Bull locomotive at the National Museum of American History in Washington, DC. - January 2009.jpg","url":"https://commons.wikimedia.org/wiki/File:John_Bull_locomotive_at_the_National_Museum_of_American_History_in_Washington,_DC._-_January_2009.jpg","author":"Kurt Raschke","license":"CC BY 2.0"},{"src":"img/deep/railways/11-3.jpg","alt":"Herman Haupt's tall timber military railroad bridge over Potomac Creek, Virginia, photographed during the Civil War.","file":"Potomac Creek Bridge 1863.jpg","url":"https://commons.wikimedia.org/wiki/File:Potomac_Creek_Bridge_1863.jpg","author":"Andrew J. Russell","license":"Public domain"}],"words":4373},{"n":12,"title":"Spanning Continents","when":"1863 – 1916","summary":"Two railroad companies raced towards each other across America, one blasting through snowy granite mountains with thousands of Chinese workers, the other speeding across the plains. They met in Utah in 1869, where a golden spike was tapped in and the word 'DONE' flashed across the country. Canada and Russia built giant railways too, but the new tracks also brought great harm to Native American peoples and the bison.","sections":[{"heading":"Crazy Judah and the Big Four","paragraphs":["Every great project needs someone stubborn enough to believe in it when others laugh. For the first railroad across the United States, that person was an engineer named Theodore Judah. Born in Connecticut in 1826, Judah had built railways in the eastern states before moving to California in 1854 to become chief engineer of the Sacramento Valley Railroad, the first railroad in California. He became obsessed with one huge idea: a line all the way across the continent. He talked about it so constantly that some people nicknamed him 'Crazy Judah'.","The great barrier was the Sierra Nevada, a wall of granite mountains rising more than 2,100 metres (7,000 feet) along California's eastern edge. Many people thought no railroad could ever cross it. Judah spent months tramping through the mountains with his instruments, measuring slopes and searching for a route. He found one: a long, steady ridge that climbed past a mining town called Dutch Flat and over Donner Pass, named after a group of pioneers who had been trapped there by snow in the terrible winter of 1846 to 1847.","Judah needed money, and he found it among a group of Sacramento shopkeepers. In 1861 they formed the Central Pacific Railroad, with Judah as chief engineer. Four of these businessmen became known as the 'Big Four': Leland Stanford, a grocer and politician who soon became Governor of California; Collis Huntington and Mark Hopkins, partners in a hardware store; and Charles Crocker, a dry-goods merchant who took charge of construction. None of them knew anything about building railroads, but they were tough, ambitious and very good at raising money. Judah then went to Washington and lobbied Congress so effectively that he helped get the Pacific Railway Act passed in 1862.","On 8 January 1863, in the pouring rain, the Central Pacific held a groundbreaking ceremony in Sacramento, with Governor Stanford shovelling the first earth. But Judah would not see his dream come true. He and the Big Four quarrelled bitterly over money and control, and in 1863 he sailed for New York, hoping to find investors to buy them out. Crossing Panama on the way, he caught yellow fever, a disease spread by mosquitoes, and he died on 2 November 1863, aged just 37. Today a mountain near Donner Pass, Mount Judah, is named after him.","The Central Pacific faced an extra problem that is hard for us to imagine. Almost everything it needed, rails, spikes, locomotives and tools, had to be made in factories in the eastern states. Because the Civil War was raging and there was no railroad across the country yet, all of it had to be shipped by sea, either all the way around the southern tip of South America or via Panama. A single locomotive could take months to arrive, and prices soared during the war. The company crawled forward. After two years it had laid only a few dozen miles of track and was approaching the steepest mountains. It also had a desperate shortage of workers, because many men in California preferred to try their luck in the gold and silver mines."]},{"heading":"Into the Granite: The Chinese Workers","paragraphs":["In 1865 Charles Crocker and his tough construction superintendent, James Strobridge, tried something new. They hired a crew of about 50 Chinese workers. Strobridge was doubtful at first and claimed they were too small for heavy work, but Crocker reportedly pointed out that Chinese workers had built the Great Wall of China. The new crew worked so hard and so well that the company soon hired thousands more.","Most of these men came from Guangdong province in southern China, especially from a group of country districts near the Pearl River Delta, not far from Hong Kong. Poverty, floods and civil war had made life very hard there, and news of the California Gold Rush had drawn many young men across the Pacific to a place they called Gold Mountain. By early 1867, according to researchers at Stanford University, about 90 percent of the Central Pacific's workforce was Chinese. Historians estimate that around 10,000 to 15,000 Chinese workers were on the job at the busiest times, and many more over the whole project.","They were treated unfairly. At first Chinese workers were paid about $26 a month and had to buy and cook their own food, while white workers received meals as well as higher wages. In June 1867 around 3,000 Chinese workers went on strike, only days after an explosion killed several workers, demanding $40 a month, a ten-hour working day and shorter shifts in the dangerous tunnels. The company cut off their food supplies, and after about eight days the strike ended, but the workers had shown they were not powerless, and pay rose over time. Many Chinese workers brought their own cooks and ate a varied diet of rice, dried fish, vegetables and tea. Because they boiled water for tea, they may have suffered less from illnesses carried by dirty water.","Their work was astonishing. To cross the Sierra, the Central Pacific had to drill a string of tunnels through solid granite, several of them packed close together near Donner Summit. The longest, the Summit Tunnel, was about 1,660 feet (around 500 metres) long. Workers attacked the rock with hand drills, hammers and black powder, and at first they could advance less than about 30 cm (one foot) a day at each rock face. To speed up, the engineers cut a vertical shaft down into the middle of the mountain so crews could dig outward from the centre as well as inward from both ends, giving four rock faces at once. They also began using nitroglycerin, a powerful but dangerously unstable liquid explosive, mixed on site by Chinese workers. Progress rose to more than 1.5 feet a day, but accidents with explosives killed workers.","The winters were brutal. In the winter of 1866 to 1867, storm after storm dumped huge amounts of snow on the mountains. Workers lived and worked in tunnels dug through the snow drifts, and avalanches swept away camps and men. To protect the finished line, the company later built about 37 miles of wooden snow sheds, long roofed tunnels of timber that kept snow off the track. Crews finally broke through the Summit Tunnel in 1867, and by June 1868 passenger trains were running through it.","Nobody knows how many Chinese workers died building the Central Pacific, because the company did not keep records of their deaths. Estimates range widely, from dozens to well over a thousand. What is certain is that the line over the Sierra Nevada could not have been built without them, and for over a century their part in the story was often left out."]},{"heading":"Across the Plains: The Union Pacific","paragraphs":["Meanwhile, far to the east, the Union Pacific was getting started. It held a groundbreaking ceremony in Omaha, Nebraska, on the west bank of the Missouri River, in December 1863, but serious construction did not begin until July 1865, after the Civil War had ended.","The man running the company was Thomas C. Durant, a clever and ruthless financier who cared more about money than about trains. He hired Grenville Dodge, a Union general and experienced railway surveyor, as chief engineer. Dodge chose much of the route across Nebraska and Wyoming and over the Rocky Mountains, and he once discovered a key pass through the Laramie Mountains while being chased by a war party, or so he later claimed. The actual track-laying was led by two brothers, Jack and Dan Casement, who ran their crews almost like an army.","And in a way it was an army. Many of the Union Pacific's workers were veterans who had just come home from the Civil War, from both the Union and the Confederate sides. Thousands more were Irish immigrants, many of whom had fled the terrible Irish famine of the 1840s. There were also freed African Americans, German and other European immigrants, and, in Utah, Mormon workers hired under contracts.","Laying track across the open plains became an amazing routine. A work train carried the crews, with bunk cars, dining cars and a blacksmith's shop, and it moved forward as the track grew. Wagons brought up wooden ties, which were set in place on the graded earth. Then teams of men grabbed iron rails weighing hundreds of kilograms, ran forward and dropped them into position, while others came behind to fix them and hammer in the spikes, about three blows to a spike and hundreds of spikes to every mile. On good days the Union Pacific laid several miles of track. In 1867 it built about 270 miles, and in 1868 almost 360.","As the railhead crept west, temporary towns sprang up wherever the workers camped, full of tents, saloons and gambling halls. People called them 'Hell on Wheels', because they were rough, lawless places, and when the track moved on, many of them were simply packed onto trains and set up again further west. A few, like Cheyenne in Wyoming, survived and grew into real cities.","There was also something rotten at the top. Durant and other Union Pacific leaders set up a construction company called Crédit Mobilier of America and then paid it hugely inflated prices to build the railroad, pocketing the profits while the railroad itself sank into debt. They also handed out shares to members of Congress. When the scheme was exposed in 1872, it became one of the biggest political scandals of the century."]},{"heading":"Ten Miles in a Day and a Golden Spike","paragraphs":["By 1868 the Central Pacific had finally burst out of the mountains into the flat deserts of Nevada, and now both companies raced. Each was paid by the mile, so every mile mattered. For a while the two sets of graders even passed each other in Utah, building parallel embankments side by side, until Congress stepped in and chose a meeting place: Promontory Summit, north of the Great Salt Lake in Utah Territory.","Charles Crocker of the Central Pacific was so confident in his crews that he reportedly bet Thomas Durant $10,000 that they could lay ten miles of track in a single day, something nobody had ever done. On 28 April 1869 they tried. The materials were carefully lined up in advance. Chinese workers raced ahead setting ties, and a team of eight Irish rail handlers lifted and placed the rails, about 1,000 tons of iron between them. By evening they had laid just over 10 miles (about 16 km) of track, a record that has never been broken by hand. A sign was later put up beside the line to mark the spot.","Then came 10 May 1869. At Promontory Summit, two locomotives rolled up nose to nose: the Central Pacific's Jupiter, a wood-burner with a big funnel chimney, and the Union Pacific's No. 119, a coal-burner. Railway officials, workers, soldiers and a few onlookers crowded round. A last tie of polished California laurel wood was laid, and several ceremonial spikes were tapped into pre-drilled holes, including the famous golden spike, made of 17.6-carat gold and weighing about 14 troy ounces (about 430 grams). It had been the idea of a San Francisco businessman named David Hewes.","A telegraph wire had been connected so that the whole nation could 'hear' the final blows as clicks on telegraph sounders. Leland Stanford raised a silver-headed maul, swung at the final spike and, according to many accounts, missed. The telegraph operator sent the signal anyway. Then a one-word message flashed down the wires to both coasts: 'DONE'. In cities across the country, crowds celebrated with cannon salutes, bells and parades.","Here is an important detail. The golden spike is NOT still in the track. It was pulled out right after the ceremony, to stop it from being stolen, and replaced with an ordinary iron spike. The golden spike was later given to Stanford University, and today it is displayed at the university's Cantor Arts Center in California. A famous photograph by Andrew J. Russell shows the two engines and a crowd of men shaking hands and holding up bottles. Very few Chinese workers appear in it, even though a Chinese crew had laid the final rail on the Central Pacific side. In 2019, at the 150th anniversary, descendants of Chinese railroad workers gathered at Promontory to restage the photograph and make sure their ancestors were remembered.","The site is now the Golden Spike National Historical Park, where working replicas of the Jupiter and No. 119 steam towards each other on summer days."]},{"heading":"A Continent Shrinks","paragraphs":["Before 1869, a journey from the east coast to California could take around six months by wagon, or weeks by ship and land via Panama. After the railroad opened, the trip from New York to San Francisco took about a week. By 1876 a special express train, the Transcontinental Express, did it in a record 83 hours and 39 minutes, less than four days. The whole line from the Missouri River at Omaha and Council Bluffs to Sacramento was about 1,900 miles (about 3,000 km), and a short extra line soon linked Sacramento to the shores of San Francisco Bay.","Freight became far cheaper too. Experts estimate that the railroad moved goods across the country for something like a tenth of the cost of wagons. Californian fruit, wine and wheat could travel east, while factory goods, books and machines flowed west. Mail that once went by stagecoach or Pony Express now went by train. Towns grew up all along the route, and the government's land grants were sold to settlers who poured onto the plains, often lured by railroad advertising.","The railroads also made enormous fortunes, sometimes unfairly. Leland Stanford became one of the richest men in America, and after his only son died young, he and his wife Jane founded Stanford University in his memory. Meanwhile the Crédit Mobilier scandal showed how close railroad money had come to politics. The government loans to the two companies were eventually paid back with interest by 1899.","Most of the Chinese workers who had built the Central Pacific went on to other jobs. Some went home to China, while others farmed, built levees, mined, or worked on dozens of other railroads in the American West and in Canada. Yet in 1882, the United States passed the Chinese Exclusion Act, which banned almost all new Chinese workers from coming to the country. The people who had helped join the nation together were being shut out of it."]},{"heading":"The Cost for Native American Nations","paragraphs":["The railroad crossed the homelands of many Native American nations, including the Lakota, Cheyenne, Arapaho, Pawnee, Shoshone and others. To them it was not an empty wilderness waiting to be crossed, but home: hunting grounds, sacred places and the lands of their ancestors. The 'free' land the government handed to the railroads had been taken from them, often in ways that broke treaties the United States itself had signed.","Some nations fought back against the survey parties and construction crews, and the US Army was sent to protect the line, with generals such as William T. Sherman and Philip Sheridan directing the campaigns. The railroad then allowed soldiers, weapons and supplies to move quickly onto the plains, which made it much harder for Native nations to resist. Settlers followed the tracks, fencing land, ploughing grassland and building towns.","The deepest wound was the destruction of the bison, also called buffalo. At least 25 million bison once roamed North America, and some estimates are far higher. For nations of the Great Plains, bison provided almost everything: meat, hides for clothing and tipis, bones for tools, and a central place in religion and culture. The railroads helped to wipe them out. Railroad lines across Kansas and Colorado split the animals into a northern and a southern herd. Railroad companies hired hunters to feed their workers. Some passengers even shot at bison from train windows for fun.","Worst of all, trains made it easy to ship bison hides east, where factories turned them into leather, including belts for driving machines. In the winter of 1872 to 1873 alone, more than 1.5 million bison hides were loaded onto trains. Professional hunters slaughtered the animals by the hundreds of thousands. Some army officers openly said that killing the bison would force Native nations onto reservations, and in 1874 President Ulysses S. Grant declined to sign a bill that would have protected the herds. By the late 1880s, only a few hundred bison survived in the United States, and fewer than a hundred lived in the wild.","For the Plains nations, the loss was a catastrophe. Without the bison, many families went hungry and were forced to depend on government rations on reservations. A Crow leader named Plenty Coups later described it this way: when the buffalo went away, 'the hearts of my people fell to the ground'. Today, thanks to conservation efforts and many Native nations working to restore herds, bison have come back from the brink, but the story reminds us that one group's great achievement can be another's great loss."]},{"heading":"Canada's Ribbon of Steel","paragraphs":["North of the border, Canada faced a similar challenge. In 1871 the colony of British Columbia, on the Pacific coast, agreed to join the new country of Canada, but only on one condition: a railway must be built to connect it with the east. It was a gigantic promise for a country of only a few million people. The line would have to cross the rocky, lake-filled wilderness north of Lake Superior, the vast prairies, and several ranges of mountains, including the Rockies and the Selkirks.","The project started badly. In 1873 Prime Minister John A. Macdonald's government was caught in the 'Pacific Scandal', in which railway promoters had given large sums of money to his party, and the government fell. Some government-built sections were started in the 1870s, but the work only really took off after the Canadian Pacific Railway company was formed in 1881. An energetic American manager named William Cornelius Van Horne was hired the next year and drove the work forward at an incredible pace.","Through British Columbia, the hardest and most dangerous work was done by about 17,000 Chinese workers, many recruited from China and many from California. They were paid less than white workers, given the riskiest jobs such as blasting tunnels on cliffs above the Fraser River, and many fell ill in harsh camps. Historians estimate that hundreds of them died, perhaps 600 to 800, though exact numbers are unknown. When the line was nearly done, Canada imposed a 'head tax' on new Chinese immigrants to discourage them from coming.","On 7 November 1885, at a place called Craigellachie in the mountains of British Columbia, a company director named Donald Smith drove the last spike, a plain iron one. A famous photograph shows him bending with his hammer as a crowd of men in hats looks on. The first passenger train left Montreal on 28 June 1886 and reached Port Moody, near Vancouver, on 4 July. The railway helped hold Canada together, but on the prairies it also helped push aside the Métis and First Nations peoples, much as in the United States."]},{"heading":"Across Siberia, and a Puzzle About Time","paragraphs":["The greatest railway of all was built in Russia. Russia stretched from Europe all the way to the Pacific Ocean, but Siberia, the huge eastern part, had almost no roads that wheeled vehicles could use. Its rivers mostly flowed north into the frozen Arctic Ocean, not east to west. To defend its Pacific coast, to move troops and settlers, and to trade with China, the Russian government decided to build a railway across the whole of Siberia.","Construction was announced in March 1891, and in May that year the heir to the throne, the future Tsar Nicholas II, helped start the work at Vladivostok on the Pacific coast. Work then went forward in sections at the same time, from both ends and in the middle. At times tens of thousands of workers laboured on the line, including soldiers and convicts, through scorching summers, swarms of mosquitoes and winters that could fall below minus 40 degrees.","The biggest obstacle was Lake Baikal, the deepest lake in the world, surrounded by steep cliffs. At first, trains were carried across the lake on giant icebreaking ferries, the Baikal and the Angara, which took about four hours to cross. The Angara survives today as a museum ship in the city of Irkutsk. In winter, when the ice became too thick even for icebreakers, passengers and goods crossed the frozen lake on sleighs, and according to accounts from 1904 the Russians even laid temporary rails across the ice for a short time. A railway around the southern end of the lake, the Circum-Baikal line, with dozens of tunnels, was finally completed in 1904.","To save time, Russia also built a shortcut through Manchuria in China, the Chinese Eastern Railway. But after Russia lost a war with Japan in 1904 to 1905, it wanted a route entirely on its own soil. That last section, along the Amur River, was finished in 1916, completing the Trans-Siberian Railway as we know it. Between 1906 and 1914 alone, the railway carried around four million peasant settlers east to new farms in Siberia.","Today the main Trans-Siberian route runs about 9,289 km (5,772 miles) from Moscow to Vladivostok, the longest railway line in the world. A through train takes about a week and the line spans eight time zones, so passengers keep changing their watches as they go.","But the long lines also created an odd new problem. When the transcontinental railroad opened, every town along the way still set its clocks by the Sun. When the Sun was highest in the sky, it was noon. Because the Earth turns, noon arrives a little later as you travel west, about four minutes later for every degree of longitude. So Omaha's noon was not Sacramento's noon, and the clocks of Chicago, Salt Lake City and every little station in between all disagreed. Imagine trying to write a timetable for a train crossing a whole continent when every station keeps its own time.","So here is the puzzle. If a train leaves one town at 12 noon, what time is it when it pulls into the next town? Nobody could agree, and with fast trains sharing the same tracks, that confusion could be dangerous. The answer, it turned out, would be invented not by astronomers or kings, but by the railways themselves."]}],"deepDive":"Historians today tell the transcontinental story very differently from the triumphant version of 1869. One big shift concerns the Chinese workers. For about a century, official histories and celebrations largely ignored them; the famous Promontory photograph barely includes them. Since the 2010s, the Chinese Railroad Workers in North America Project at Stanford University has gathered archaeological finds from work camps, company payroll records and family histories, because almost no letters or diaries written by the workers themselves survive. Its researchers estimate that 10,000 to 15,000 Chinese workers were employed at peak, making up roughly 90 percent of the Central Pacific's workforce by 1867, but they stress that the number who died is genuinely unknown: the company recorded no deaths, and newspaper reports from 1870 about bones shipped home to China contradict each other, with figures ranging from about 50 to 1,200. That is why careful writers avoid giving a single death toll. Wages are also debated, because sources compare different things (monthly versus daily pay, with or without food). What is clear is that Chinese workers usually cost the company noticeably less than white workers. A second debate concerns money and efficiency. Because the government paid the companies by the mile, with triple payments in mountains, both sides had reasons to build fast and sometimes poorly, and stretches had to be rebuilt soon afterwards. The Crédit Mobilier scandal showed how insiders could profit from construction while the railroad itself carried the debt. Economic historians such as Richard White have argued that the transcontinentals were built before there was enough traffic to justify them, and that their political influence did lasting harm; others reply that they knitted the nation together and repaid their federal loans by 1899. Finally, historians of the American West now treat the destruction of the bison as a central part of the railroad story. Rail lines split the herds, carried hunters in and hides out (more than 1.5 million in the winter of 1872 to 1873 alone), and let the army move quickly, so the loss of the bison and of Native lands cannot be separated from the engineering triumph.","funFact":"The famous golden spike was only in the track for a few minutes: it was pulled out straight after the 1869 ceremony and is now on display at Stanford University's Cantor Arts Center.","check":{"q":"Where did the Central Pacific and Union Pacific railroads meet on 10 May 1869?","a":"Promontory Summit, Utah","wrong":["Omaha, Nebraska","Donner Pass, California","Craigellachie, British Columbia"]},"sources":[{"title":"First transcontinental railroad","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/First_transcontinental_railroad"},{"title":"FAQs - Chinese Railroad Workers in North America Project","publisher":"Stanford University","url":"https://chineserailroadworkers.stanford.edu/faqs/"},{"title":"Golden spike","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Golden_spike"},{"title":"Theodore Judah","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Theodore_Judah"},{"title":"Bison hunting","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bison_hunting"},{"title":"Canadian Pacific Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Canadian_Pacific_Railway"},{"title":"Trans-Siberian Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Trans-Siberian_Railway"},{"title":"History and Culture - Golden Spike National Historical Park","publisher":"US National Park Service","url":"https://www.nps.gov/gosp/learn/historyculture/index.htm"}],"photos":[{"src":"img/deep/railways/12-1.jpg","alt":"Promontory Summit, May 10, 1869: crowds and the locomotives Jupiter and No. 119 meet as the railroad is finished.","file":"East and West Shaking hands at the laying of last rail Union Pacific Railroad - Restoration.jpg","url":"https://commons.wikimedia.org/wiki/File:East_and_West_Shaking_hands_at_the_laying_of_last_rail_Union_Pacific_Railroad_-_Restoration.jpg","author":"Andrew J. Russell / Adam Cuerden","license":"Public domain"},{"src":"img/deep/railways/12-2.jpg","alt":"Engraving of Chinese workers waving as a Central Pacific train passes snow sheds and a tunnel in the Sierra Nevada.","file":"Chinese railroad workers sierra nevada.jpg","url":"https://commons.wikimedia.org/wiki/File:Chinese_railroad_workers_sierra_nevada.jpg","author":"\"B&H\", illustrator; sketch by Joesph Becker (1841-1910)","license":"Public domain"},{"src":"img/deep/railways/12-3.jpg","alt":"Donald Smith drives the last spike of the Canadian Pacific Railway at Craigellachie, November 7, 1885.","file":"Donald A. Smith driving the Last Spike to complete the Canadian Pacific Railway, 1885.jpg","url":"https://commons.wikimedia.org/wiki/File:Donald_A._Smith_driving_the_Last_Spike_to_complete_the_Canadian_Pacific_Railway,_1885.jpg","author":"Alexander Ross","license":"Public domain"}],"words":4075},{"n":13,"title":"How Trains Invented Time Zones","when":"1840 – 1918","summary":"Long ago, every town set its clocks by the Sun, so noon in one town was a few minutes different from noon in the next. That was fine for horses, but fast trains got hopelessly muddled. So the railways got everyone to share one time, and that is why the world has time zones today!","sections":[{"heading":"A World Full of Different Noons","paragraphs":["Imagine it is the year 1835 and you are standing in the market square of Bristol, in the west of England. The church clock strikes twelve. A traveller who has just ridden in from London pulls out his pocket watch and frowns. His watch, set in London that morning, says it is already about ten minutes past twelve. Neither clock is broken. Both are perfectly right for their own town. Welcome to the world of local 'sun time'.","For thousands of years, people told the time by the Sun. When the Sun reached its highest point in the sky, it was noon. Sundials showed it, and town clockmakers set their clocks to match. This worked beautifully as long as nobody travelled very fast. But the Earth is a spinning ball, and the Sun does not reach its highest point everywhere at the same moment. It sweeps across the sky from east to west, so towns further east get their noon a little earlier, and towns further west get it a little later.","Here is the simple maths behind it. The Earth turns all the way round, 360 degrees, in 24 hours. Divide 360 by 24 and you get 15 degrees every hour. That means each degree of longitude (the imaginary north–south lines that measure how far east or west you are) is worth 4 minutes of time. Bristol lies roughly two and a half degrees west of London, so its noon arrives about 10 minutes after London's. Plymouth, further west still, was around 16 minutes behind London. Norwich, in the east, was a little ahead.","Astronomers had a name for this kind of time: local mean time. 'Mean' means average. The real Sun runs slightly fast or slow at different times of year, because Earth's orbit is not a perfect circle and its axis is tilted. So astronomers worked out an average, smoothed-out version of sun time that ticked at a steady rate. Every town that cared about accuracy used its own local mean time, worked out from its own position on the globe.","For a farmer, a shopkeeper or someone travelling by stagecoach at perhaps 10 miles an hour, a difference of 10 minutes between towns hardly mattered. The journey from London to Bristol by coach took the best part of a day, and the coach guard could simply nudge his watch along as he went. Nobody noticed a few minutes slipping away among the bumps and horse changes.","Then the railways arrived. Suddenly a train could cover in a couple of hours what a coach covered in a day. Trains ran to printed timetables, set off at exact minutes and had to fit together with other trains on the same lines. A world with hundreds of slightly different noons was about to become a serious problem.","Think about what a timetable actually is. It is a promise: this train will leave this station at this time, and reach that station at that time. But whose time? If a train left London at 10:00 London time and the timetable said it reached Bristol at 12:30, did that mean 12:30 by the Bristol church clock, or 12:30 by London time? A passenger who guessed wrong could arrive on the platform to watch their train disappearing, or wait for ages on a cold bench.","Confusion for passengers was annoying. Confusion for the railway staff was dangerous. In the early days, many lines had only one or two tracks, and trains running in opposite directions or following one another had to be kept safely apart. Much of this safety depended on timing. A station might be told that one train must pass before another set off, or that trains should run a set number of minutes apart. If two workers on the same stretch of line were counting time from different clocks, a gap that should have been 10 minutes might really be zero. On a line where a heavy train took a long way to stop, that could mean a collision.","The railway guards carried special watches, and the companies needed every watch along a route to show exactly the same time. That meant the railways needed one single time, shared by everyone working on the line, all the way from one end to the other. The question was which time to choose, and how to get the same exact time to dozens of stations spread across hundreds of miles, in an age without radio, phones or the internet."]},{"heading":"Railway Time Comes to Britain","paragraphs":["The first railway to tackle the problem head-on was the Great Western Railway, the line engineered by Isambard Kingdom Brunel to link London with Bristol. In November 1840 the Great Western began running all its trains by London time, which was the same as Greenwich Mean Time, the time kept by the Royal Observatory at Greenwich on the edge of London. Historians describe this as the first recorded example of separate local times being replaced by one standard time across a whole system.","How did the guards on a Great Western train know London time when they were far away in the west? At first they carried chronometers, extra-accurate portable clocks. A chronometer would be set to London time before the journey, carried on the train, and used to check the clocks at stations along the line. It was a little like passing a precious message down the line by hand.","Other railways soon saw how sensible this was. In 1842 the British railway companies had set up the Railway Clearing House, an organisation that sorted out how to share fares when a passenger travelled over several companies' lines. On 22 September 1847, the Clearing House recommended that every railway station should adopt Greenwich time as soon as the General Post Office allowed it. Two big companies, the London and North Western Railway and the Caledonian Railway in Scotland, switched on 1 December 1847, and by the end of that year almost all of Britain's railways were running on what people began to call 'railway time'.","One of the best places to see this change happening is in the pages of Bradshaw's. George Bradshaw, a Manchester printer and engraver, published his first railway timetable in 1839, and his guides grew into thick monthly books listing the trains of almost every company in Britain. They became so famous that 'Bradshaw' was simply the word people used for a railway guide. In January 1848 Bradshaw's listed which railways had switched to London time. Imagine trying to plan a long journey through all those companies without one shared time. Bradshaw's could only work because the railways now spoke the same language of hours and minutes.","Towns did not all follow happily. Some people thought it was wrong for a railway company to tell a town that its own Sun was 'wrong'. In Bristol, the clock on the Exchange building in Corn Street was given a second minute hand. One hand showed Bristol time and the other showed London, or railway, time, about 10 minutes ahead. You can still see that clock with its two minute hands today. Bristol finally accepted railway time as its main time in September 1852. Other cities made similar compromises: clocks at Exeter Cathedral and at Tom Tower in Oxford also showed two times for a while.","Bit by bit, convenience won. By 1855 about 98 per cent of public clocks in Great Britain were set to Greenwich Mean Time. Yet for decades this was simply custom, not law. Strangely, a court could still decide that a legal deadline meant local sun time. That gap was finally closed by an Act of Parliament, the Statutes (Definition of Time) Act, which received royal assent on 2 August 1880. From then on, 'time' in British law meant Greenwich Mean Time. The railways had led the way; the law followed about 40 years later."]},{"heading":"Sending Time Down a Wire","paragraphs":["Choosing one time was only half the job. Every station needed to know exactly what that time was, to the second if possible. Clocks of the 1840s were good, but even good clocks slowly drift. A clock that gained a few seconds a day would be minutes out within a few weeks. The railways needed a way to check and correct their clocks often, from one trusted source.","The perfect tool appeared right alongside the tracks. The electric telegraph sends messages as pulses of electricity along a wire. Railways were among the very first users of the telegraph, because a wire could be strung on poles beside the line and used to warn stations that a train was coming. Part of the Great Western was fitted with a telegraph in 1839, one of the earliest working telegraphs in the world. Since electricity races along a wire almost instantly, a signal sent from London would arrive at a distant station at practically the same moment it was sent. That made the telegraph ideal for sharing the exact time.","The source of 'true' time in Britain was the Royal Observatory at Greenwich, founded in 1675 to help sailors find their longitude at sea. Astronomers there timed the stars as they crossed an exact line in the sky, and used those observations to keep their master clocks precisely right. Since 1833 a large red ball on a mast on top of the observatory had been dropped every day at exactly 1 p.m., so ships on the River Thames could check their chronometers by watching it fall.","In 1852 the Observatory installed a new electric master clock, made by the clockmaker Charles Shepherd, which could send electrical time signals down telegraph wires. From around August 1852, Greenwich time signals were travelling to London Bridge station and beyond. By 1855 time signals from Greenwich were being sent along railway telegraph wires across much of Britain. Every day, at a fixed hour, a signal would click into telegraph offices, and station staff would check and adjust their clocks. The railway network had become a giant clock-setting machine for the whole country.","The same idea spread in North America. In 1869 the Allegheny Observatory near Pittsburgh, directed by the astronomer Samuel Langley, began sending regular time signals by telegraph to railroads and cities. Historians call it one of the first systematic time-distribution services, and by 1870 its time service stretched over more than 2,500 miles of telegraph lines, reaching about 300 telegraph offices. Observatories at Harvard, Yale and the US Naval Observatory in Washington also sent out time signals. A railroad that bought this service could set every clock along its line from the same exact tick."]},{"heading":"America's Tangle of Times","paragraphs":["Britain is a fairly narrow island, so a single time worked well: even its westernmost places were at most about half an hour behind Greenwich by the Sun. The United States was a completely different puzzle. From the Atlantic coast to the Pacific, the country stretches across about 58 degrees of longitude. At 4 minutes per degree, the Sun reached noon in San Francisco about three and a half hours after it did in Boston. One single time for the whole country would have meant clocks saying noon in the middle of the night or at dawn in some places.","So, by the middle of the 1800s, American towns kept their own local times, and there were well over 300 of them. Each railroad company, meanwhile, chose its own standard time, usually the local time of its headquarters or of a big city on its line. Railroads running out of the same city could use different times. Historians often say there were dozens of different railroad times in use before 1883, with figures of around 50 commonly quoted.","Picture a busy junction station where several railroads met, such as in Pittsburgh or Buffalo. Some stations hung up a row of clocks, one for each railroad, all showing slightly different times. A traveller had to know which clock belonged to which company before deciding whether they were early or late. Timetables printed long tables of conversions. Mistakes were common, and on single-track lines, where trains coming from opposite directions had to wait for each other in passing places, a misunderstanding about time could cause a collision.","People had been suggesting a fix for years. In 1870 Charles F. Dowd, the head of a girls' school in Saratoga Springs, New York, proposed dividing the country into time zones, each an hour apart. His first plan was based on the meridian through Washington, DC; in 1872 he changed it to count from Greenwich instead. The railroads did not take up his exact scheme, but the idea of hour-wide zones was now in the air. The scientist Cleveland Abbe, who worked on weather forecasting, also pushed hard for standard time, partly because weather reports from different cities needed to be compared at the same moment.","The man who finally made it happen was William F. Allen, an engineer who edited the Official Railway Guide, America's equivalent of Bradshaw's, and served as secretary of the General Time Convention, a group of railroad managers who met to agree on timetables. Allen knew the tangle better than anyone, because his guide had to print it all. He also worried that if the railroads did not sort themselves out, the government might step in and force a system on them. Allen drew up a plan using hour-wide zones based on meridians measured from Greenwich, with the boundaries bent to follow places where railroads already changed crews or companies, so that the change would cause as little disruption as possible.","On 11 October 1883, railroad leaders meeting at the Grand Pacific Hotel in Chicago voted to accept Allen's system. They set a date for the switch only about five weeks away. It was a bold decision, made not by Congress or the President but by private railroad companies."]},{"heading":"The Day of Two Noons","paragraphs":["The big day was Sunday, 18 November 1883. A Sunday was chosen because fewer trains were running. The plan used four main zones across the United States and Canada, which we still know today: Eastern, Central, Mountain and Pacific. Each zone's time was based on a meridian a whole number of hours from Greenwich: 75, 90, 105 and 120 degrees west. A planned fifth zone for the far east of Canada was not used that year, because the Intercolonial Railway there chose to use Eastern time instead.","Here is how the switch worked. In each town, the clocks would be reset at noon to the new standard time. The signal came by telegraph from the Allegheny Observatory near Pittsburgh, marking the exact moment of noon by the new Eastern time, and railroads in the other zones set their clocks exactly one, two or three hours behind it. Across the continent, telegraph operators, jewellers and railway clerks waited at their clocks for the click.","Now think about what that meant for a town that lay east of its zone's central meridian. Its own sun time was ahead of the new standard time. So when the Sun said noon, the people stopped their clocks, or moved the hands back, by however many minutes they needed, and then let noon arrive a second time by the new standard time. In those places, the church bells could ring for noon twice on the same day. That is why 18 November 1883 became known as 'the Day of Two Noons'. In towns west of their zone's central meridian, it went the other way: the clocks jumped forward and a few minutes simply vanished.","Newspapers loved the story. Some people grumbled that the railroads were meddling with God's time or the Sun's time, and a few cities refused to switch for years. Detroit, which sits near the border between the Eastern and Central zones, kept its own local time for a long time and argued about it for decades, only settling firmly on Eastern time by a city decision in 1915 that was confirmed by voters in 1916. But most people quickly found the new system easier. Within about a year, around 85 per cent of American cities with more than 10,000 people had adopted standard time.","Remember that none of this was the law. There was no national government rule saying what time it was. The whole system was a private agreement among railroad companies, which towns and businesses decided to follow because it made life simpler. This is one of the most important points in the whole story of time zones: the railways created standard time first, and governments caught up later."]},{"heading":"Sandford Fleming and the Clock for the Whole World","paragraphs":["While American railroads were sorting out their own continent, a Canadian railway engineer was thinking even bigger: one system of time for the entire planet.","Sandford Fleming was born on 7 January 1827 in Kirkcaldy, Scotland, and moved to Canada as a teenager. He became a surveyor and engineer and helped plan some of Canada's great railways. He was chief engineer for the surveys of the Canadian Pacific Railway's route across the country in the 1870s and explored the Yellowhead Pass through the Rocky Mountains. He was there, as a director of the Canadian Pacific, when the railway's last spike was driven on 7 November 1885. He even designed Canada's very first postage stamp in 1851, the Threepenny Beaver.","According to a story Fleming's biographers like to tell, his interest in time began with a missed train. In 1876, while travelling in Ireland, he turned up at a station only to find his train had gone: the printed timetable had muddled 'a.m.' and 'p.m.' Whether or not that annoyed evening was the true spark, in that same year he wrote a paper called 'Terrestrial Time', proposing a single 24-hour clock for the whole world.","Fleming's idea had two parts. First, there would be one universal time, the same everywhere on Earth at the same instant, which he called 'Cosmopolitan Time' and later 'Cosmic Time'. It would run on a 24-hour dial, so there would be no more confusing a.m. and p.m. Second, for everyday life, the world would be divided into 24 time zones, each 15 degrees of longitude wide and exactly one hour apart. He even gave the zones letters of the alphabet, from A to Y, leaving out J.","In February 1879, Fleming presented papers on his plan to the Canadian Institute in Toronto, now suggesting that the world's starting line be linked to Greenwich. The British government sent copies to governments in eighteen other countries. Fleming wrote letters, gave talks and argued tirelessly with scientists and officials. He was not the only person with such ideas. An Italian mathematician, Quirico Filopanti, had described hourly zones in a book in 1858, but almost nobody noticed. Fleming's great contribution was his energy in persuading people that standard time was a practical, worldwide need.","For his many services, Queen Victoria knighted him in 1897, and he became Sir Sandford Fleming. He died in Halifax, Nova Scotia, on 22 July 1915, aged 88. He is often called 'the father of standard time', although, as we have seen, the honour really belongs to many people, from the Great Western Railway's managers to William Allen."]},{"heading":"Choosing the Starting Line: Washington, 1884","paragraphs":["Time zones need a starting line. Before you can say a zone is five hours behind, you have to say behind what. Mapmakers face the same problem with longitude: the lines of latitude have a natural starting point at the Equator, but there is no natural zero line running from pole to pole. In the 1800s, many countries measured longitude from their own capital or observatory: the French from Paris, others from places such as Cadiz, Naples, Washington or Berlin. Sailors had to convert between them.","To settle this, the United States invited the nations of the world to a meeting in Washington, DC, known as the International Meridian Conference. It opened on 1 October 1884. Forty-one delegates attended, representing 26 countries. Sandford Fleming was there, representing Canada as part of the British delegation.","The big vote came on 13 October 1884. The conference proposed that the meridian passing through the Transit Instrument at the Royal Observatory in Greenwich should be the world's prime meridian, longitude zero. Twenty-two countries voted yes. One, San Domingo (today's Dominican Republic), voted no. Two, France and Brazil, abstained, meaning they chose not to vote either way. France had hoped for a more neutral line that did not pass through any great nation's capital.","Why Greenwich? A practical reason was that most of the world's ships were already using sea charts based on Greenwich, because Britain had the largest merchant fleet and the Admiralty published excellent charts. The United States had also already based its new railroad zones on Greenwich. Choosing Greenwich meant the least change for the most people.","The conference also agreed on a 'universal day', a mean solar day beginning at midnight at Greenwich, to be used for science and other purposes where it was helpful. Fleming hoped for more: he and another delegate proposed that every nation adopt standard time based on the new meridian. Other delegates argued that how each country set its own clocks was outside the conference's job, so no vote was taken. The conference did not create the world's time zones. It gave the world a shared zero line, and countries then adopted time zones based on it, one by one, over the following decades.","Not everyone hurried. France kept Paris as its starting point for many years, and only switched its legal time to one based on Greenwich in 1911. Even then, rather than mentioning Greenwich by name, the French law described it as Paris time slowed by 9 minutes and 21 seconds, which comes to exactly the same thing."]},{"heading":"From Railway Rule to the Law of the Land","paragraphs":["In the United States, the railroads' zones worked well for more than 30 years without any national law at all. Then, in the middle of the First World War, Congress finally acted. The Standard Time Act, also called the Calder Act after Senator William Calder of New York, was signed by President Woodrow Wilson on 19 March 1918. It was the first federal law to set up standard time in the United States. It created five time zones (the four railroad zones plus one for Alaska) and gave the Interstate Commerce Commission, the government body that already regulated railroads, the job of deciding exactly where the zone boundaries ran.","The same law also introduced daylight saving time, moving clocks forward an hour in summer to save fuel during the war. That part was so unpopular with farmers that it was repealed in 1919, even though President Wilson tried to veto the repeal. Daylight saving came back nationally during the Second World War and has been argued about ever since.","Around the world, other countries joined the system at different speeds. New Zealand was actually ahead of everyone: it had adopted a single standard time for the whole colony back on 2 November 1868, set 11 and a half hours ahead of Greenwich. By about 1900 almost every inhabited place had some kind of standard time, though many still used the time of a local observatory rather than a neat number of hours from Greenwich. By 1929 most countries used whole-hour zones, with a few, such as India, choosing half-hour offsets. Nepal was the very last country to settle on a standard offset, in 1986, choosing 5 hours and 45 minutes ahead of Greenwich.","There was another side to all this precision, though. Trains were now running faster, more often and to tighter timetables than ever before. A busy main line might have dozens of trains a day thundering along the same pair of rails, all relying on clocks, signals and human judgement to keep them apart. When something went wrong, at high speed and with heavy trains full of people, the results could be terrible. As the timetables grew tighter, inventors, engineers and lawmakers began a long race to make the railways safer. That race, and the disasters that drove it, is the next stop on our journey."]}],"deepDive":"Historians sometimes describe standard time as one of the first great acts of global 'synchronisation', and the railways sit at its centre. But it is worth separating three different things that are often blurred together. First, standard time within a region: a railway or country choosing one clock time for all its places. The Great Western Railway did this in 1840, British railways mostly by the end of 1847, and North American railroads on 18 November 1883. Second, a shared prime meridian: the 1884 International Meridian Conference chose Greenwich by 22 votes to 1, with France and Brazil abstaining, but it deliberately did not order countries to adopt time zones. Third, legal time: Britain defined Greenwich Mean Time in law in 1880, while the United States waited until the Standard Time Act of 19 March 1918. In each case the private, practical system came first and the law came later. Who deserves credit is debated. Charles Dowd, Quirico Filopanti and Sandford Fleming all proposed hourly zones; Cleveland Abbe pushed scientific bodies to support standard time; William F. Allen designed the zone boundaries that railroads actually used. Fleming's worldwide 24-zone scheme, with lettered zones, was never adopted in the exact form he proposed, yet his campaigning helped make standard time seem normal rather than eccentric. There is also a fascinating technical story. Local mean time differs by 4 minutes for each degree of longitude, because the Earth turns 15 degrees per hour. To share one time, you need a trusted master clock and a fast way to send its ticks. Observatories provided the first, timing star transits to keep their clocks right, and the telegraph provided the second. Observatories such as Allegheny turned this into a service, and time signals became a product that railroads and cities paid for. Later, radio time signals replaced telegraph ticks, and today atomic clocks and satellite signals keep phones accurate to tiny fractions of a second. Finally, notice the resistance. People in Bristol, Detroit and elsewhere felt that local sun time was natural and that railway time was imposed by distant companies. Debates about who controls time continue today in arguments over daylight saving time and in countries that change time zones for political reasons.","funFact":"The clock on the Exchange building in Bristol, England, still has two minute hands, one showing Bristol's own sun time and one showing Greenwich time, a reminder of the days when the city was about 10 minutes behind London.","check":{"q":"Why was 18 November 1883 called 'the Day of Two Noons' in parts of North America?","a":"Railroads switched to standard time zones, so in some towns clocks were set back and noon happened twice","wrong":["The Sun was seen in the sky twice because of an eclipse","Congress passed a law making every day have two lunch breaks","Trains ran on both British and American time that day"]},"sources":[{"title":"Railway time","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Railway_time"},{"title":"Standard time","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Standard_time"},{"title":"Time zone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Time_zone"},{"title":"International Meridian Conference","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/International_Meridian_Conference"},{"title":"Sandford Fleming","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sandford_Fleming"},{"title":"Standard Time Act","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Standard_Time_Act"},{"title":"Time in the United States","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Time_in_the_United_States"},{"title":"Allegheny Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Allegheny_Observatory"}],"photos":[{"src":"img/deep/railways/13-1.jpg","alt":"The Corn Exchange clock in Bristol has two minute hands, about ten minutes apart: Bristol time and London time.","file":"Corn Exchange clock in Bristol.jpg","url":"https://commons.wikimedia.org/wiki/File:Corn_Exchange_clock_in_Bristol.jpg","author":"Chris Mitchell","license":"CC BY-SA 4.0"},{"src":"img/deep/railways/13-2.jpg","alt":"Sandford Fleming, the Canadian engineer who pushed for worldwide standard time, photographed in Ottawa in 1883.","file":"Sandford Fleming - Sheldon & Davis - btv1b8449804c (1 of 2).jpg","url":"https://commons.wikimedia.org/wiki/File:Sandford_Fleming_-_Sheldon_%26_Davis_-_btv1b8449804c_(1_of_2).jpg","author":"Sheldon & Davis (Ottawa). Photographe","license":"Public domain"},{"src":"img/deep/railways/13-3.jpg","alt":"An 1883 map of the new railway time zones in the United States, with a clock dial for each zone.","file":"PSM V26 D162 Standard railway time vs greenwich mean time.jpg","url":"https://commons.wikimedia.org/wiki/File:PSM_V26_D162_Standard_railway_time_vs_greenwich_mean_time.jpg","author":"Unknown author","license":"Public domain"}],"words":4361},{"n":14,"title":"Danger, Brakes and Safety","when":"1830s – 1900s","summary":"Early trains were exciting, but they could be dangerous: brakes were weak, signals were simple and workers got hurt joining wagons together. After some terrible accidents, clever inventors created air brakes, automatic couplers and signal boxes that stopped mistakes. Today trains are one of the safest ways to travel, thanks to the lessons learned long ago.","sections":[{"heading":"Fast, Heavy and Hard to Stop","paragraphs":["Here is a simple experiment you can try in your head. Imagine pushing an empty shopping trolley and then letting go. It rolls a little and stops. Now imagine a trolley loaded with bricks. Once it is moving, it is much harder to stop. A railway train is that loaded trolley multiplied thousands of times. A Victorian express might weigh well over 100 tonnes; a long freight train could weigh many hundreds of tonnes. The same low friction that lets a train glide so easily along steel rails also means it needs a very long distance to stop. Steel wheels on steel rails do not grip like rubber tyres on a road.","On the earliest railways, the brakes were feeble. The locomotive had a brake, and the tender often had a hand brake turned by a wheel. Some carriages and wagons had brake vans, where a guard or brakeman turned a big wheel to press wooden or iron blocks against the wheels. On a long train, the driver had to whistle a signal and hope the brakemen heard it and acted in time. Each brake was worked separately, by a different person, so stopping a fast train could take a frighteningly long distance.","In America, many freight trains had brakes that could only be applied from wheels on top of each car. Brakemen had to climb up and run along the roofs of moving wagons, jumping from car to car, in rain, snow and darkness, turning each brake wheel in turn. It was so dangerous that brakemen were killed or badly hurt in large numbers every year, and it limited how long a train could safely be.","There were other dangers too. Steam locomotive boilers held water and steam under great pressure. If the metal was weak, the water ran too low, or someone tied down the safety valve, a boiler could burst with enormous force. Bridges built of cast iron, which is strong when squeezed but can snap when bent or shaken, sometimes failed. And there was the everyday risk of collisions, when one train ran into another that was stopped or moving more slowly ahead.","In the early days, trains on the same line were kept apart mainly by time. Railway policemen stood at intervals along the track with watches. If a train had passed less than a set number of minutes ago, they would signal the next train to slow down or stop; if more time had passed, they would wave it on. The trouble was obvious: the policeman had no idea whether the first train had actually got safely ahead, or had broken down just around the next bend. Accidents caused by this 'time interval' system were common.","Over the following 70 years, railways would solve these problems one by one, with better brakes, couplers, signals, bridges and rules. Sadly, many of the improvements only came after disasters showed, in the hardest possible way, what could go wrong. To understand why our trains are so safe today, we need to visit some of those dark days, calmly and respectfully, and see what people learned."]},{"heading":"The Night the Tay Bridge Fell","paragraphs":["The River Tay in eastern Scotland is wide and windy where it meets the sea near the city of Dundee. For years, travellers going north had to cross it by ferry. Then, in 1878, the North British Railway opened a new bridge, designed by the engineer Thomas Bouch. It was one of the longest bridges in the world, a slender line of iron lattice girders standing on iron piers, stretching about two miles across the water. Its tallest section, called the 'high girders', let ships pass underneath. The bridge opened to passengers on 1 June 1878, and Bouch was knighted for his achievement.","On the evening of Sunday 28 December 1879, a violent storm swept down the Tay. The wind was blowing almost straight across the bridge, at gale or even hurricane strength. At around 7:15 in the evening, a passenger train from Burntisland to Dundee, with a locomotive, five carriages and a luggage van, steamed out onto the bridge. Watchers on the shore saw its lights moving through the darkness, then a flash of sparks, and then nothing. The high girders had collapsed, and the whole train had fallen into the river.","There were no survivors. Because the exact number of passengers was never certain, historians give slightly different figures: 59 people are known to have died, and the total may have been as high as about 75. Only 46 bodies were ever recovered. It remains one of the worst railway disasters in British history.","A Court of Inquiry examined what had gone wrong, and its findings shocked the engineering world. Bouch had made no proper allowance for the pressure of strong wind on the bridge and on a train crossing it. The cross-bracing that was meant to stop the piers from swaying was too weak, and the small iron tabs, called lugs, that held the bracing were cast as part of the iron columns and could crack. Workers at the foundry had used poor-quality castings and sometimes filled defects instead of rejecting faulty parts. Maintenance had been poor, with loose tie bars rattling as trains passed. Some witnesses said trains often went faster than the bridge's speed limit of 25 mph.","The official report blamed the collapse on the gale overwhelming badly designed and badly made bracing. One member of the inquiry, Henry Rothery, wrote a separate report that placed the blame mainly on Bouch. Bouch's reputation was ruined, and he died less than a year later. His design for a great railway bridge across the Firth of Forth, near Edinburgh, was abandoned, and a completely new, much stronger design was chosen instead.","The disaster changed engineering rules. Bridge designers in Britain now had to calculate wind loads carefully, allowing for winds pushing with up to 56 pounds on every square foot of surface. A new, sturdier Tay Bridge was built right beside the stumps of the old one and opened in 1887; you can still see the old piers poking out of the water today. Remarkably, the locomotive was later hauled out of the river, repaired and put back to work, and railwaymen nicknamed it 'The Diver'. It kept running until 1919."]},{"heading":"Armagh, 1889: Why Brakes Must Work by Themselves","paragraphs":["Ten years after the Tay Bridge fell, an accident in Ireland showed that weak brakes could be just as deadly as weak bridges. On the morning of 12 June 1889, the Methodist Sunday school in Armagh, now in Northern Ireland, ran a day trip to the seaside town of Warrenpoint. Families and children were excited; tickets sold well. In the end, about 940 people squeezed into a train of 15 carriages run by the Great Northern Railway of Ireland.","Soon after leaving Armagh, the line climbed a steep hill. The locomotive was not powerful enough for such a heavy train, and the train stalled near the top. The crew decided to split the train in two: they would take the front part over the top, leave it at the next station, and come back for the rest. That meant uncoupling the rear ten carriages and leaving them standing on the steep slope.","Here is where the brakes mattered. The train had a vacuum brake, a system in which the brakes were worked by sucking air out of a pipe that ran the length of the train. But this was a 'simple', non-automatic vacuum brake. When the pipe was disconnected, the brakes on the rear carriages did not come on by themselves. The only thing holding those ten crowded carriages was the hand brake in the guard's van, helped by some stones placed behind the wheels. When the front part of the train was moved, it bumped the rear part slightly. The rear carriages began to roll backwards down the hill, faster and faster, and crashed into the next train coming up the line behind them.","Eighty people died and around 260 were injured. About a third of those killed were children. It was the worst railway accident in Ireland's history and the deadliest railway accident anywhere in the United Kingdom in the 19th century. The inquiry blamed the lack of brake power on the rear carriages, the decision to divide the train on a slope, the use of an engine that was too weak for the load and the inexperience of the driver.","This time the government acted fast. Within about two months, Parliament passed the Regulation of Railways Act 1889. It gave the Board of Trade, the government department that inspected railways, the power to order railway companies to fit three key safety measures to passenger lines. First, continuous automatic brakes: brakes on every carriage, controlled by the driver, that would come on by themselves if the train split apart. Second, the block system of signalling, so only one train could be in each section of line at a time. Third, interlocking of points and signals, so that a signalman could not set up a dangerous route. Many historians see this law as the start of modern railway safety in Britain.","The key word was 'automatic'. A brake that only worked when everything went right was not good enough. Railways needed brakes that switched themselves on when something went wrong. An American inventor had already shown how to do it."]},{"heading":"George Westinghouse and the Brake That Fails Safe","paragraphs":["George Westinghouse was born on 6 October 1846 in Central Bridge, New York, the son of a man who made farm machinery. As a teenager he served in the American Civil War, first in the Union army and then as an engineer in the navy. After the war he started inventing, and one day, the story goes, he was travelling by train when his journey was held up by a wreck ahead: two trains had run into each other on the same track. Their drivers had seen each other coming, but with hand brakes there was no way to stop in time. Westinghouse decided there must be a better way.","His answer was to use compressed air, air squeezed into a small space so it pushes hard to escape. In 1869, at the age of just 22, he demonstrated his air brake in Pittsburgh and received his first patent for it on 13 April 1869. That same year he founded the Westinghouse Air Brake Company. In his first system, called a 'straight air' brake, a pump on the locomotive squeezed air into a tank, and when the driver opened a valve, the compressed air flowed down a pipe along the train into brake cylinders on every car. Each cylinder pushed a piston that pressed brake shoes against the wheels. For the first time, the driver could apply the brakes on the whole train at once.","But there was a dangerous weakness. If a hose burst, or the train broke apart, the air escaped and the brakes simply did not work. Westinghouse realised the system needed to be turned upside down. In 1872 he introduced his automatic air brake, and it is one of the cleverest safety ideas in railway history.","Here is how it works. A pipe, called the brake pipe, runs the whole length of the train and is kept filled with compressed air. Under each car there is a reservoir, a small air tank, and a clever valve called the triple valve. While the brake pipe is at full pressure, the triple valve lets air flow into the reservoir to fill it up and keeps the brakes off. When the driver wants to slow down, he lets some air out of the brake pipe. The pressure drops, and each triple valve responds by letting air from its own reservoir into its brake cylinder, putting the brakes on. To release the brakes, the driver raises the pipe pressure again.","Now think about what happens if the train accidentally splits apart, or a hose bursts. The brake pipe loses all its pressure in an instant. Every triple valve sees the drop and applies the brakes as hard as possible, using the air already stored on each car. The broken train stops itself. Engineers call this 'fail-safe': when something goes wrong, the system falls into the safe condition, not the dangerous one. That is exactly what the rear carriages at Armagh had lacked.","Westinghouse's automatic air brake, improved many times over the years, was adopted on railways almost everywhere. Some British railways preferred an automatic vacuum brake, which works on the same fail-safe idea but uses suction instead of pressure; Britain's railways switched over to air brakes in the diesel age of the 1960s. Westinghouse went on to receive about 360 patents in his lifetime. In 1881 he founded the Union Switch and Signal Company to make railway signals and switches, and later he became famous for promoting alternating-current electricity. But the air brake, which let trains become longer, faster and far safer, was the invention that made his name."]},{"heading":"Fingers, Pins and Janney's Knuckle","paragraphs":["Brakes were not the only deadly problem, especially on American freight lines. Every time wagons were joined together, someone had to do it by hand. For much of the 1800s, most American cars used a link-and-pin coupler. Each car had a socket at the end. To couple two cars, a brakeman stood between them, held a heavy iron link in one socket, and waited as the engine pushed the cars together, guiding the link into the other socket and then dropping an iron pin through to lock it.","If the brakeman's timing was a fraction of a second off, his hand could be crushed between the cars. If he slipped, he could fall beneath the wheels. Railroad workers sometimes said you could tell an experienced brakeman by his missing fingers. Between 1877 and 1887, about 38 per cent of accidents to American railway workers involved coupling cars. In the 1880s, working on the railroad was one of the most dangerous jobs in the country.","The solution came from Eli Janney, a Virginian who had served as an officer in the Confederate army during the Civil War and later worked as a clerk in a dry goods store in Alexandria, Virginia. Legend says he worked out his idea by whittling wooden models during his lunch breaks. Whether or not that is exactly true, in 1873 he received a US patent for a new kind of automatic coupler.","Janney's coupler works a bit like two hands clasping. On the end of each car is a hinged metal jaw called a knuckle. When two cars are pushed together, the open knuckles meet, swing shut around each other and lock automatically with a pin that drops into place. Nobody has to stand between the cars. To uncouple, a worker pulls a lever, called a cut lever, from the side of the car, which lifts the locking pin and lets the knuckles open. The worker never needs to step into the deadly gap.","Adoption was slow at first, because many different couplers were being invented and railroads did not want to buy expensive new equipment. In 1888 the Master Car Builders' Association, a group of railway engineers, chose a slightly modified version of Janney's design as the standard shape, so that couplers made by different companies would always fit together. That kind of agreement on a shared standard is one of the quiet heroes of railway history.","Even so, railroads moved slowly until the law pushed them. A former Iowa railroad commissioner named Lorenzo Coffin spent years travelling, writing and lobbying, almost single-handedly, to force the railroads to change. Finally, on 2 March 1893, in the last days of President Benjamin Harrison's term, Congress passed the Safety Appliance Act. It required trains to have power brakes, such as air brakes, so the driver could control the train's speed without brakemen running on roofs, and automatic couplers that joined on impact without anyone going between the cars. It also required secure grab irons, the handholds on the ends and sides of cars. Railroads were given a grace period, and the law came fully into force in 1900. The results were dramatic. Coupling accidents fell from 11,710 in 1893 to 2,256 in 1902, even though there were more trains running. Knuckle couplers based on Janney's design are still used on freight trains in North America today."]},{"heading":"Signal Boxes, Blocks and Clever Levers","paragraphs":["Strong brakes help a train stop. But the best accident is the one that never starts, and that is the job of signalling. Remember the old 'time interval' system, where a policeman with a watch could only guess whether the line ahead was clear. The electric telegraph, which we met sending time signals along the line, offered something far better.","With the telegraph, a railway could be divided into sections called blocks, with a signalman at each end. When a train left one block and entered the next, the signalman ahead could send a message back by bell code saying 'train out of section'. Only then would the signalman behind let another train into that block. This is the absolute block system: never more than one train in a section at a time. It is based on distance, not time, so a broken-down train is always protected, because the next train simply is not allowed in. The block system spread across British railways during the 1850s and 1860s and was made compulsory on passenger lines by the 1889 Act.","Signals themselves changed too. Early railways used flags, lamps, boards and balls hoisted on poles. By the 1840s, semaphore signals, with a moving arm on a tall post, were appearing: arm straight out meant stop, arm lowered meant go, with coloured lamps for night. Signals were worked by levers in a small building beside the track, the signal box, connected to the signals and points by long wires and metal rods.","Even with a block system, a signalman could make a mistake. He might set the points to send a train into a siding while showing a 'clear' signal for the main line, or clear signals for two trains whose paths would cross. The cure was interlocking. An early form appeared at Bricklayers Arms Junction in south London in 1843, and in 1856 the engineer John Saxby patented an improved system. In an interlocking frame, the levers are linked underneath by a grid of sliding metal bars. Pull one lever, and its bar slides across and physically blocks any lever that would set up a conflicting route. A signal for a route simply cannot be cleared until the points for that route are set correctly. It is a mechanical puzzle that makes the most dangerous mistakes impossible. Interlocking became so popular that by 1873 the London and North Western Railway alone had about 13,000 interlocked levers.","Weather taught another lesson. On 21 January 1876, during a blizzard at Abbots Ripton in Huntingdonshire, England, the Flying Scotsman express from Edinburgh ran past signals that were showing 'clear' even though the signalman had set them to danger: snow and ice had stuck the semaphore arms and their wires. The express hit a coal train, and a second express then ran into the wreckage. Thirteen people died. Afterwards, railways changed their practice so that signals normally rested at danger and were only cleared when a train was expected, and the Great Northern Railway introduced a new 'somersault' signal arm, pivoted in the middle so snow could not easily jam it.","Little by little, a thinking machine was being built around the trains: blocks, bells, interlocked levers and fail-safe brakes. Each piece was designed so that if a person slipped up or a part failed, the system would stop trains rather than send them into danger."]},{"heading":"Lives on the Line: Workers, Unions and the Pullman Strike","paragraphs":["Behind every train were the people who ran it: drivers and firemen on the footplate, guards and brakemen, signalmen, track workers, shunters and station staff. Their work was hard and often dangerous. Shifts were very long, sometimes far more than 12 hours, and tired workers make mistakes. Pay could be cut whenever business was bad, and an injured worker might lose his job with little or no help.","To protect themselves, railway workers formed some of the earliest big trade unions, groups of workers who bargain together with employers. In the United States, the Brotherhood of Locomotive Engineers was founded in 1863, followed by unions for firemen, conductors and trainmen. In 1877, after wage cuts, railroad workers walked off the job in what became known as the Great Railroad Strike, spreading from West Virginia to many cities. It was put down with the help of soldiers and armed militias, and many people were killed.","The most famous railway strike of the century began in 1894 in Pullman, a company town on the edge of Chicago built by George Pullman, maker of luxury sleeping cars. Pullman's workers lived in houses owned by the company and paid rent to the company. When trade slumped in 1893 and 1894, the company cut wages by roughly a quarter or more, but did not lower the rents. On 11 May 1894, about 4,000 Pullman factory workers went on strike.","They were supported by the American Railway Union, a new union led by Eugene V. Debs, which was open to all kinds of railway workers rather than just one trade. From 26 June, union members across the country refused to handle any train that included a Pullman car. At its height, around 250,000 workers in 27 states took part, and much of the nation's railway traffic, especially in the West, came to a halt.","The railroad companies and the federal government fought back. Courts issued an injunction, a legal order, banning the union from interfering with trains carrying the US mail. President Grover Cleveland sent about 12,000 army troops to Chicago in early July, even though the Governor of Illinois objected. There was rioting, burning of railway cars and violence, and dozens of people were killed. The strike collapsed by 20 July 1894. Debs was jailed for six months for disobeying the court order, and the American Railway Union fell apart. Only days before the troops arrived, Cleveland had signed a law making Labor Day a national holiday in the United States, on 28 June 1894.","Workers' campaigns did slowly bring change. In 1907, the United States passed the Hours of Service Act, which limited how long train crews could be made to work without rest, usually to 16 hours at a time. Safety laws, unions and better machines together made railway work less deadly in the 20th century, although it remained a tough job.","So far we have looked at the railway from the dangerous end: the footplate, the signal box and the gap between two wagons. But most people who rode the trains never saw any of that. They sat in a carriage, watched fields flash by, and found that their whole lives were changing. In the next part, we will step off the footplate and into a passenger carriage, to see how railways transformed food, holidays, newspapers, cities and everyday life."]}],"deepDive":"Railway safety history is a classic example of what engineers call learning from failure. Early railways relied on human vigilance: watchmen timing trains, brakemen turning wheels, signalmen remembering which points were set. Accidents revealed that any system depending on people never making a mistake would eventually fail. The great inventions of this period all replace vigilance with design. Westinghouse's automatic air brake (patented in 1869, with the automatic triple-valve version in 1872) makes loss of pressure apply the brakes, so a broken pipe or a divided train stops itself. Interlocking frames make conflicting signal settings physically impossible. The absolute block system replaces time intervals with space intervals, so a stopped train is protected however long it stands. Janney's knuckle coupler removes the need to stand between moving cars. Historians also debate why change was so slow. Railway companies argued that new brakes and couplers were costly, that rival designs were not yet proven, and that standards were needed before investing. Many reforms therefore came only after high-profile disasters and long campaigns: the 1889 Regulation of Railways Act followed Armagh within about two months, while the US Safety Appliance Act of 1893 followed years of lobbying by Lorenzo Coffin and gave railroads until 1900 to comply. The numbers show the effect: US coupling accidents fell from 11,710 in 1893 to 2,256 in 1902. The Tay Bridge disaster raises a different question, about engineering knowledge. Bouch was not simply careless; wind loading on large structures was poorly understood, and he relied on earlier advice. Yet the inquiry also found poor castings and supervision. Modern analyses have argued about how much each factor mattered, and some researchers have suggested the bridge may have been weakened by fatigue or by fast trains before the storm. Death tolls are also uncertain: 59 known victims, perhaps up to about 75, because no exact passenger list existed. Similarly, death figures for the 1894 Pullman Strike vary between sources. Good history keeps these uncertainties visible rather than choosing the most dramatic number.","funFact":"The locomotive that plunged into the River Tay in the 1879 bridge disaster was hauled out of the water, repaired and kept working for about 40 more years, earning the nickname 'The Diver'.","check":{"q":"What made George Westinghouse's 1872 automatic air brake 'fail-safe'?","a":"If the brake pipe lost pressure, for example when the train split apart, the brakes came on by themselves","wrong":["It used extra-strong rubber tyres instead of steel wheels","Brakemen ran along the roofs to turn every brake wheel faster","It only worked when the train was going downhill"]},"sources":[{"title":"Tay Bridge disaster","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tay_Bridge_disaster"},{"title":"Armagh rail disaster","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Armagh_rail_disaster"},{"title":"Railway air brake","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Railway_air_brake"},{"title":"George Westinghouse","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_Westinghouse"},{"title":"Janney coupler","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Janney_coupler"},{"title":"Safety Appliance Act","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Safety_Appliance_Act"},{"title":"Interlocking","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Interlocking"},{"title":"Pullman Strike","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pullman_Strike"}],"photos":[{"src":"img/deep/railways/14-1.jpg","alt":"The fallen iron girders of the first Tay Bridge lying in the river after the collapse of December 1879.","file":"Fallen girders, Tay Bridge.jpg","url":"https://commons.wikimedia.org/wiki/File:Fallen_girders,_Tay_Bridge.jpg","author":"Creator:Great Britain. Board of Trade","license":"Public domain"},{"src":"img/deep/railways/14-2.jpg","alt":"George Westinghouse, inventor of the railway air brake, in a 1906 photograph.","file":"George westinghouse portrait 1906.jpg","url":"https://commons.wikimedia.org/wiki/File:George_westinghouse_portrait_1906.jpg","author":"Joseph Gaylord Gessford","license":"Public domain"},{"src":"img/deep/railways/14-3.jpg","alt":"Eli Janney's drawing of his knuckle coupler: two hooked 'knuckles' that lock together automatically when cars bump.","file":"Janney coupler drawing.png","url":"https://commons.wikimedia.org/wiki/File:Janney_coupler_drawing.png","author":"Eli H. Janney","license":"Public domain"}],"words":4165},{"n":15,"title":"How Railways Changed Everyday Life","when":"1840s – 1930s","summary":"Trains did not just carry coal. They brought fresh milk to breakfast tables, letters overnight and whole families to the seaside for the day. They also carried soldiers to war, shaped empires, and inspired painters, poets and songwriters.","sections":[{"heading":"Breakfast Came by Train","paragraphs":["Picture a big city in about 1820. Thousands of people need milk every morning, but milk goes sour within a day or so, and the fastest way to bring it in from the countryside is a horse and cart bumping along a muddy road. So many cities kept their own cows, crammed into dark sheds in back streets, fed on brewery leftovers and milked right there in town. The milk was often thin, dirty or watered down. Fresh fish was a luxury far from the coast, and fruit and vegetables had to be grown close by or arrive half rotten.","Railways changed the menu. A train could bring milk from farms 50 or even 100 miles away in a few hours, and by the middle of the 1800s 'milk trains' were part of daily life in Britain and the United States. Farmers rolled tall metal milk churns (big cans with lids) to the nearest country station early in the morning. A slow train stopped at station after station, picking up churns, and arrived in the city before most people were awake. Milk trains ran so early, and stopped so often, that 'the milk train' became a joke for any train that was very slow or left at an unbelievably early hour. Later, glass-lined tank wagons carried milk in bulk, a bit like a giant thermos flask on wheels.","Fish travelled the same way. Fishing ports on the coast sent their catch packed in ice on fast overnight trains, so that a fish landed one evening could be sold in an inland market the next morning. In Britain this helped turn fish and chips into a cheap, popular meal for working families in towns far from the sea. Strawberries from Kent, flowers from the Scilly Isles and Cornwall, and early potatoes from the south could all be in London shops within a day.","In the United States the distances were much bigger, and so was the challenge. Huge herds of cattle were raised on the western plains, but most of the people who wanted to eat beef lived in eastern cities. At first, live animals were packed into stock cars and shipped east, which was cruel to the animals and wasteful, since much of each animal could not be eaten. The meat-packer Gustavus Swift had a better idea: butcher the cattle in Chicago and send only the meat east. The problem was keeping it cold for a journey of several days.","In 1878 Swift hired an engineer named Andrew Chase to design a well-insulated, ventilated railway car. The 'refrigerator car', or 'reefer', worked like an icebox on wheels. Big bins called ice bunkers at the ends of the car were packed with blocks of ice, often mixed with salt to make it even colder. Cold air is heavier than warm air, so it sank down from the bunkers and flowed through the meat, while warmer air rose back up to the ice. The ice itself was cut from frozen lakes in winter and stored for months in thick-walled ice houses packed with sawdust and hay.","Railroads were not keen. They earned good money hauling live cattle and did not want to lose it, so Swift paid for the first cars himself and found a Canadian line, the Grand Trunk Railway, willing to haul them. The first car was delivered in 1880, and within about a year Swift had nearly 200. Other companies copied the idea. There were roughly 1,300 refrigerator cars in the United States in 1880 and around 68,500 by 1900, and the national fleet peaked at about 183,000 in 1930.","A long journey meant stopping to top up the ice, roughly once a day, at icing stations along the line where workers shovelled fresh blocks into the bunkers from raised platforms. The Pacific Fruit Express, set up in 1907 by the Union Pacific and Southern Pacific railroads, began with more than 6,000 refrigerator cars and ran its own ice plants; its plant at Roseville, California, could make about 1,200 short tons of ice a day. Thanks to reefers, oranges from California and Florida, lettuce, grapes and peaches could be eaten in New York or Boston in the middle of winter. The way whole countries ate had changed, and the change ran on rails."]},{"heading":"Letters and Newspapers Overnight","paragraphs":["Before railways, a letter from London to Edinburgh went by mail coach, a horse-drawn coach that changed horses every few miles and still took well over a day. On 11 November 1830, just weeks after it opened, the Liverpool and Manchester Railway carried mail for the first time. Britain's Parliament soon saw that railways were the future of the post, and the Railways (Conveyance of Mails) Act of 1838 required railway companies to carry the mail when asked.","The Post Office then had a clever thought. Why should mail sit in sacks doing nothing during a long train journey? Why not sort it while the train was moving? The result was the Travelling Post Office, or TPO: a railway carriage fitted out as a small post office, with rows of pigeon-holes, sorting tables and clerks working through the night as the train rocked along. By the time the train arrived, letters were already sorted for delivery in the towns ahead.","TPOs even collected and dropped off mailbags without stopping. Beside the track stood tall posts with arms that held leather mailbags. As the train thundered past, a net swung out from the side of the carriage and snatched the bag off the post, while another bag was dropped into a net at the trackside to be collected by the local postman. Doing this at full speed in the dark took great skill and good timing. By 1914 Britain had 126 travelling post office carriages, and many other countries copied the idea.","The most famous celebration of these trains is a short film called Night Mail, made in 1936 by the General Post Office's own film unit. It followed the overnight postal train from London to Scotland, and it ended with a poem by W. H. Auden whose rhythm imitated the beat of the wheels on the rails. British TPOs carried on until January 2004, when the last ones ran and sorting moved to big machines on the ground.","Newspapers rode the rails too. Before railways, a London newspaper might reach a northern town days late. With fast early-morning newspaper trains, a paper printed in the middle of the night could be in shops hundreds of miles away by breakfast. This helped create truly national newspapers, read on the same day across a whole country. People in Cornwall and Cumbria could now argue about the same headlines at the same time, which made a country feel more connected, and helped political ideas, sports results and fashions spread far faster than ever before."]},{"heading":"A Shilling to Loughborough: The Day Trip Is Born","paragraphs":["In June 1841 a young printer and preacher named Thomas Cook was walking from Market Harborough to Leicester, about 15 miles, on his way to a temperance meeting. The temperance movement wanted people to give up alcohol, which was causing a great deal of misery in poor families at the time. As he walked, Cook had an idea: what if the new railway could carry a big crowd of supporters to a meeting in another town?","He persuaded the Midland Counties Railway to hire him a whole train. On 5 July 1841, about 485 members of the Leicester Temperance Society climbed aboard at Leicester's Campbell Street station and travelled to Loughborough and back, roughly 11 miles each way. The fare was one shilling each. Many of them had probably never been on a train before. There was a band, crowds waved them off, and the day was a huge success.","Cook realised that ordinary working people would happily pay for a day out if someone made it simple and cheap. He began organising more excursions, and soon his trips were not only for temperance meetings. In 1851 he arranged travel for about 165,000 people to visit the Great Exhibition in London's Crystal Palace, a gigantic show of inventions from around the world. In 1855 he led his first tour to mainland Europe, and in the 1870s he even organised a journey around the world. The business he started, Thomas Cook and Son, became one of the most famous travel companies in history.","Cook was not the only person running excursion trains, but he showed how much people wanted to travel just for fun. Seaside towns felt the effect most. Places such as Blackpool, Brighton, Scarborough and Skegness had been small fishing villages or quiet resorts for the rich. Once cheap trains arrived, thousands of factory and mill workers could reach the sea in a few hours. In the cotton towns of Lancashire, whole factories closed for a week each summer (called 'Wakes Weeks'), and entire streets of families boarded trains for Blackpool together. Britain's Bank Holidays Act of 1871 created new public holidays, and on those days stations were packed.","To serve the crowds, seaside towns built piers, promenades, boarding houses, theatres and amusement parks. Blackpool Tower, opened in 1894, was inspired by the Eiffel Tower in Paris. Without the railway, almost none of this would have existed. The same pattern happened in other countries: Americans took trains to Coney Island and Atlantic City, and the French to Normandy beaches and the Riviera.","Railways also changed where people lived. Before trains, most people had to live within walking distance of work, so cities were crowded and packed tight. With regular trains, a clerk could live in a leafy suburb and ride into the city each morning with a season ticket. This daily journey is called commuting. Around London, railway companies actively encouraged it. The Metropolitan Railway even invented a name, 'Metro-land', in 1915 for the countryside along its line north-west of London, and in 1919 it set up a separate company to build housing estates there. Pinner grew from about 3,000 people to around 23,000 in the first three decades of the 1900s. Many of the suburbs where people live today began as fields next to a new railway station."]},{"heading":"Hotels on Wheels and the Porters Who Ran Them","paragraphs":["Early railway carriages were not comfortable. Third-class passengers in the 1830s sometimes rode in open wagons with no roof, and even better carriages were cramped, cold and hard. On long American journeys that lasted days, travellers had to sit up all night and dash off the train at stations to grab food in a few minutes.","George Pullman, a businessman from New York State who had moved to Chicago, set out to change that. His first sleeping coach was built in 1859 in the workshops of the Chicago and Alton Railroad at Bloomington, Illinois, and in 1862 he started the company that became the Pullman Company. Pullman's cars had seats that folded down into beds at night, with upper berths that swung down from the ceiling, curtains for privacy, carpets, polished wood, fine fittings and, from the late 1860s, dining cars where passengers could eat a proper meal while the countryside rolled past. At its height the company reportedly carried around 26 million passengers a year and was sometimes described as 'the largest hotel in the world', because so many people slept in its cars every night.","Railway companies did not usually own these cars. Instead the Pullman Company owned and staffed them and rented them out, so passengers paid extra for a Pullman berth. And the people who made the whole system work were the Pullman porters. From 1868 the company hired mainly Black men, many of them formerly enslaved or the sons of formerly enslaved people, to make up the beds, carry bags, shine shoes, serve drinks and look after passengers through the night. By the 1920s around 12,000 porters worked for the company, making it one of the largest employers of Black Americans.","The job brought travel, respect in their own communities and a steady income, but the conditions were deeply unfair. Pay was low, so porters depended heavily on tips. Many passengers did not bother to learn their names and simply called every porter 'George', after George Pullman himself, as though they were his servants. According to figures from 1934, porters on regular runs worked more than 73 hours a week on average. They had to pay for their own meals, uniforms and lodging, which could eat up a large share of their wages, and they were not allowed to be promoted to conductor, a job kept for white men.","In August 1925, at a meeting in Harlem in New York City, about 500 porters launched a union, the Brotherhood of Sleeping Car Porters. Their leader was A. Philip Randolph, a writer, speaker and campaigner who was not a porter himself, which made it harder for the company to fire him. The Pullman Company fought back hard, spying on members and firing men who joined. It took twelve years of struggle, but in 1937 the company finally signed an agreement with the union, giving higher pay and a shorter working month. It is often described as the first major labour agreement between a large American company and a union led by Black workers.","Porters had another, quieter influence. Because they travelled the whole country, they carried news, books and Black-owned newspapers such as the Chicago Defender from northern cities into the South, where such papers were hard to find. They told families about jobs and better lives in the North, which helped encourage the Great Migration, when millions of Black Americans moved north in the early and middle 1900s. A. Philip Randolph went on to become one of the great leaders of the civil rights movement and helped organise the 1963 March on Washington, where Martin Luther King Jr. gave his 'I Have a Dream' speech. A story that began with folding beds on a train ended in one of the most important days in American history."]},{"heading":"Railways and Empire: India's First Train","paragraphs":["In the 1800s Britain ruled a huge empire, and railways became one of its most important tools. The largest example is India. On 16 April 1853 a train of about 14 carriages, carrying roughly 400 invited passengers, steamed out of Bori Bunder in Bombay (today's Mumbai) towards Thane (then spelled Thana), about 34 kilometres (21 miles) away. It was pulled by three steam locomotives, traditionally named Sahib, Sindh and Sultan. The day was declared a public holiday, a 21-gun salute was fired, and crowds lined the route to watch. The journey took about 57 minutes.","The line was built by the Great Indian Peninsula Railway, a private company based in Britain. To persuade British investors to put up the money, the colonial government gave free land and promised a guaranteed profit of 5 per cent a year, paid out of Indian taxes even if the railway lost money. The routes were chosen mainly to serve British interests: to carry raw materials such as cotton from the interior to ports like Bombay, from where they were shipped to factories in Britain, and to move soldiers quickly to keep control of the country. Most of the locomotives, rails and steel were made in Britain, so British industry profited as well. Indian historians and economists have long pointed out that Indians paid for much of the system but had little say in how it was built.","The engineering was spectacular. Just beyond Bombay rose the steep Western Ghats mountains. Climbing them took years of work on zig-zag lines, tunnels and viaducts; the route up the Bhor Ghat to Poona (Pune) was not completed until 1863, and the other big climb, the Thal Ghat, in 1865. Building such lines was dangerous, and many Indian labourers died from accidents and disease, though exact numbers were never properly recorded. By 1870 a line connected Bombay to Calcutta (Kolkata), right across the subcontinent. In Jules Verne's adventure novel Around the World in Eighty Days, published in 1872, the hero Phileas Fogg crosses India by train, a sign of how famous these new lines had become.","Yet something unexpected happened. The railways, built mainly for the empire, became part of everyday Indian life. Millions of Indian passengers crowded into cheap third-class carriages to visit relatives, look for work, or go on pilgrimages to holy places that had once taken weeks to reach on foot. Mohandas Gandhi travelled third class across India to see how ordinary people lived, and railway journeys helped people from different regions meet, trade and share ideas, including the idea of an independent India. Today Indian Railways is one of the biggest railway systems on Earth and one of the largest employers in the world, carrying billions of passengers a year.","India was not alone. Railways were built across Africa, South-East Asia and elsewhere, often by colonial powers that used them to carry minerals, rubber, cotton and crops to the coast for export. These lines frequently ran from mines and plantations to ports rather than between the towns where local people lived, a pattern that still affects some countries' transport today. As with the transcontinental railroads in North America, railways brought both new possibilities and real harm, and historians try to look honestly at both."]},{"heading":"Trains Go to War","paragraphs":["As you read in Part 11, the American Civil War (1861 to 1865) showed that railways could decide wars. The North had far more track and factories to make engines and rails, and it used trains to move troops and supplies quickly, while the South's network gradually wore out and fell apart. Generals in Europe studied these lessons carefully.","By the time the First World War began in the summer of 1914, the great powers of Europe had detailed railway timetables ready for war. Germany, France, Russia and Austria-Hungary had each planned, down to the minute, how thousands of trains would carry millions of soldiers, horses, guns and supplies to their borders. Military planners worried that if their rivals mobilised (got their armies ready) faster, they would lose, so these railway plans made it harder to slow down once a crisis began. Some historians argue that the rigid timetables helped push Europe into war; others think this idea is exaggerated. Either way, trains were at the heart of the plans.","In Britain, the government took control of the main railway companies when war broke out, running them through a committee of railway managers so that the whole network worked as one. Trains carried soldiers to the ports, coal for warships, and enormous amounts of shells and supplies. In the United States, President Woodrow Wilson put the railroads under government control on 26 December 1917, creating the United States Railroad Administration to untangle traffic jams of freight and make the system work as a single network until 1920.","Near the front lines in France and Belgium, big trains could not go close to the trenches, because their smoke and steam gave away their position to enemy artillery. So both sides built small 'trench railways' with track only 60 centimetres (about 2 feet) apart. These light railways could be laid quickly and carried ammunition, food, building materials and water up to the front, and brought wounded soldiers back. France had developed this gauge, made popular by the Decauville company, and the British, Americans and Germans used the same size. Britain needed so many small engines that it ordered 495 from the American company Baldwin. Horses and mules still did a huge amount of carrying, and hay and oats for them were the single largest type of cargo Britain shipped to France during the war.","Railways also carried the wounded. Ambulance trains, with beds, medical staff and small operating areas on board, took injured soldiers from the battlefields to hospitals and to ships waiting at the Channel ports. Over the course of the war, ambulance trains carried many hundreds of thousands of wounded soldiers away from the fighting. For many soldiers, a train was the last thing they saw before the front and the first sign that they were on their way home."]},{"heading":"Big Business, Wires Alongside the Track, and Trains in Art","paragraphs":["Railways did not only change daily life. They changed how the modern world was organised. Running a railway was unlike running a farm or a small workshop. A big American railroad in the late 1800s had thousands of miles of track, tens of thousands of workers, hundreds of stations and trains running day and night. Nobody could simply keep an eye on everything personally. So railway managers invented new ways to run huge organisations: departments with clear jobs, written rules, timetables, regular reports sent to head office, careful accounting of costs per mile, and chains of managers. Historians often say that railways created the modern big company, and other businesses, from steel makers to department stores, copied their methods.","The size of it all was astonishing. The United States had about 9,000 miles of railroad in 1850. By 1900 it had roughly 190,000 to 200,000 miles, and the total peaked in 1916 at around 254,000 miles, more than enough to wrap around the Earth ten times. Around 1920 American railroads employed about 2 million people. Railway shares were bought and sold on stock exchanges, and railway companies became some of the first businesses owned by thousands of shareholders.","Railways also pushed industry towards standard parts and shared rules. Engines and wagons from different companies had to be able to run on each other's tracks, so gauges, couplings and brakes gradually became standard. In the American South, many lines used a 5-foot gauge, and in 1886 most of them were converted to standard gauge in a gigantic coordinated effort over just a couple of days, with gangs of workers shifting one rail inward along thousands of miles of track. The telegraph followed the railway too. Telegraph wires were strung on poles beside the tracks, so the railway's right of way became a highway for messages as well as trains, carrying news, business orders and the time signals you met in Part 13.","Artists noticed that the world had changed. In 1844 the British painter J. M. W. Turner showed a painting called Rain, Steam and Speed: The Great Western Railway. It shows a dark locomotive with a glowing firebox racing towards the viewer across Brunel's bridge at Maidenhead, blurred by rain and mist, and Turner sneaked in a small hare running ahead of the train. Some people read the hare as a race between nature and machine. In 1877 the French painter Claude Monet painted a whole series of pictures of the smoky, sunlit Gare Saint-Lazare station in Paris.","Writers and musicians joined in. Edith Nesbit's 1906 children's book The Railway Children is about three children who move from London to a house in the countryside, where their lives revolve around the railway line nearby. Americans sang ballads about Casey Jones, an engine driver who died in a crash in 1900 while trying to stop his train in time, and about the steel-driving man John Henry, a figure of legend who raced a steam drill while digging a railway tunnel. Blues musicians copied the rhythm and whistle of trains on guitar and harmonica. Luxury trains such as the Orient Express, which began running from Paris in 1883, became settings for mystery novels. Railways had become part of how people imagined the world.","By the early 1900s, cities had grown so big, partly because of railways, that their streets were jammed with horses, carts, buses and people. The trains themselves could not squeeze any further into the crowded city centres. So engineers began to look in a new direction: down. Our next stop is underground, in the smoky tunnels beneath London, where a new problem needed a new kind of power."]}],"deepDive":"Historians have argued for decades about how much railways really mattered to economic growth. In 1964 the American economist Robert Fogel published a famous study asking a 'counterfactual' question: what would the US economy of 1890 have looked like if railways had never been built, and goods had travelled by canal, river and wagon instead? His answer surprised many people. He estimated that the direct savings from railways for moving farm goods in 1890 were only a few per cent of the nation's total income, and that canals and roads could have done much of the job, more slowly. Fogel later shared the 1993 Nobel Prize in economics, partly for this kind of number-crunching history. Critics replied that his method missed the bigger effects: railways shaped where cities grew, created national markets, pushed the steel and coal industries, invented modern management and moved people as well as goods. Speed itself had value that is hard to count. Most historians now accept that railways were enormously important, while agreeing with Fogel that no single invention is ever truly 'indispensable'. The debate about railways and empire is even sharper. Supporters of the British Raj once pointed to India's railways as a gift of modern technology. Many Indian economists and historians answer that the system was paid for largely by Indian taxpayers, built with guaranteed profits for British investors, designed to move raw materials to ports and troops to trouble spots, and stocked with British-made equipment. Some studies suggest the railways did help reduce the impact of local food shortages by letting grain move between regions, while others note that grain could also flow out of hungry areas towards richer markets. Both effects can be true at once. Finally, social historians stress that the railway changed experiences of time and space. A worker in Leicester in 1841 could, for the first time, see the sea and be back home the same day. Ice-cooled meat from Chicago meant a family in Boston no longer depended only on local butchers. These everyday changes are harder to measure than miles of track, but they may be the railway's most lasting legacy.","funFact":"Many Pullman passengers called every sleeping-car porter 'George', after the company's founder George Pullman, whether that was the porter's name or not.","check":{"q":"Where did Thomas Cook's first railway excursion go on 5 July 1841?","a":"From Leicester to Loughborough, for a temperance meeting","wrong":["From London to Brighton, for a seaside holiday","From Liverpool to Manchester, for a football match","From Leicester to Paris, for the World's Fair"]},"sources":[{"title":"Thomas Cook","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Cook"},{"title":"Refrigerator car","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Refrigerator_car"},{"title":"Travelling Post Office","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Travelling_Post_Office"},{"title":"Brotherhood of Sleeping Car Porters","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Brotherhood_of_Sleeping_Car_Porters"},{"title":"Pullman Company","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pullman_Company"},{"title":"Great Indian Peninsula Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Great_Indian_Peninsula_Railway"},{"title":"Trench railways","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Trench_railways"},{"title":"Metro-land","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Metro-land"}],"photos":[{"src":"img/deep/railways/15-1.jpg","alt":"J. M. W. Turner's 1844 painting Rain, Steam and Speed: a Great Western Railway train rushes through a storm.","file":"Turner - Rain, Steam and Speed - National Gallery file.jpg","url":"https://commons.wikimedia.org/wiki/File:Turner_-_Rain,_Steam_and_Speed_-_National_Gallery_file.jpg","author":"J. M. W. Turner","license":"Public domain"},{"src":"img/deep/railways/15-2.jpg","alt":"A Pullman sleeping-car porter in his uniform cap at Union Station, Chicago, photographed by Jack Delano.","file":"PullmanPorter.jpg","url":"https://commons.wikimedia.org/wiki/File:PullmanPorter.jpg","author":"Jack Delano","license":"Public domain"},{"src":"img/deep/railways/15-3.jpg","alt":"A Pacific Fruit Express ice-cooled refrigerator car (reefer), built 1957, now at a railroad museum in California.","file":"Pacific Fruit Express Displayed in Western Pacific Railroad Museum - Portola, CA - August 2010.jpg","url":"https://commons.wikimedia.org/wiki/File:Pacific_Fruit_Express_Displayed_in_Western_Pacific_Railroad_Museum_-_Portola,_CA_-_August_2010.jpg","author":"David Brossard","license":"CC BY-SA 2.0"}],"words":4290},{"n":16,"title":"Going Underground and Going Electric","when":"1863 – 1935","summary":"London's streets were so jammed that engineers put a railway in a tunnel underneath, first with smoky steam engines. Then inventors learned to run trains on electricity, with no smoke at all. Soon cities from Budapest to New York to Moscow had trains rumbling beneath their feet.","sections":[{"heading":"A City Too Crowded to Move","paragraphs":["Imagine London in the 1850s. It is the biggest city in the world, with well over two million people. Railways from all over Britain now bring passengers into the capital, but Parliament has not allowed the main lines to push into the crowded centre, so their stations, such as Paddington, Euston and King's Cross, sit around the edge. Every morning thousands of passengers pour out and try to cross town to their offices in the City of London. The streets are choked with horse-drawn buses, cabs, carts and pedestrians. A trip of a couple of miles could take longer than the whole train journey that came before it.","A London lawyer named Charles Pearson had a bold answer: put a railway underneath the streets. He spent years campaigning for the idea, and the engineer John Fowler was put in charge of designing it. Many people thought it was mad. Who would want to ride through a dark tunnel, breathing smoke, under the houses of London? Some newspapers joked about it, and some people worried the tunnels would collapse or that being underground was simply unhealthy. Pearson sadly died in September 1862, just a few months before his dream opened.","The new line was called the Metropolitan Railway. It was built mostly by a method called 'cut-and-cover'. Workers dug an enormous trench down the middle of a street, built the railway in the bottom, lined the sides with brick walls, covered the top with a brick arch or iron girders, and then rebuilt the road on top. It was quick compared with real tunnelling, but it turned streets into building sites for months, and houses that stood in the way sometimes had to be knocked down. Where possible, the route followed the line of existing roads, such as the New Road (today's Marylebone Road and Euston Road), so that fewer buildings had to be demolished.","After a grand opening ceremony on 9 January 1863, the Metropolitan Railway opened to the public on 10 January 1863. It ran about 3.75 miles (6 km) from Paddington (Bishop's Road) to Farringdon Street, near the City. It was the world's first underground railway. About 38,000 passengers rode it on the very first day, so many that extra trains had to be borrowed, and around 9.5 million people used it in its first year. The doubters had been wrong: Londoners loved it."]},{"heading":"Steam in the Tunnels","paragraphs":["There was one big problem. In 1863 the only practical way to pull a train was a steam locomotive, and steam locomotives burn coal, make smoke and puff out steam. In the open air, the smoke just blows away. In a tunnel, it has nowhere to go.","The engineers had tried to plan for this. The track was laid with three rails so that both broad-gauge trains of the Great Western Railway and standard-gauge trains could use it, and the first trains were pulled by special Great Western tank engines. Later the Metropolitan used its own locomotives fitted with 'condensing' equipment: instead of blasting used steam up the chimney, the engine sent it back into its water tanks, where it cooled and turned back into water. Drivers were also told to burn coke or smokeless fuel in the tunnels and to stoke the fire hard only in the open sections between them.","It helped, but not enough. The original line had very little ventilation, because it had been designed hoping that smokeless engines would be found. Stations and carriages were often hazy with sulphurous smoke, and the air tasted of soot. Passengers rode in gas-lit wooden carriages, and on busy days the atmosphere could be choking. Over the years, the company opened up vents and gaps in the roof to let smoke out, sometimes to the annoyance of people living above. Some people of the time even claimed the sulphur-filled air was good for chest complaints, which almost certainly was not true.","Even so, the 'sub-surface' network kept growing, linking up to form what eventually became the Circle line. But it was obvious that underground railways needed a cleaner way to move. If only you could have an engine that produced no smoke at all. The answer was already being tested in workshops and exhibitions across Europe: electricity."]},{"heading":"Sparks in Berlin and Brighton","paragraphs":["Electric motors had existed since the 1830s, but early ones were weak and depended on batteries, which were expensive and quickly ran down. By the 1870s that changed. Engineers built powerful dynamos, machines that turn movement into electricity, and the same machine run in reverse could work as a motor. Now electricity could be made in large amounts and sent along wires.","The German inventor Werner von Siemens, whose company Siemens and Halske was a leader in telegraphs and electrical machines, saw the chance. At the Berlin trade exhibition of 1879 he presented a little electric locomotive on 31 May. It ran on a loop of track about 300 metres long, with a gauge of just 490 millimetres, pulling three small open cars that each seated six people. It trundled along at about 7 kilometres per hour, not much faster than a brisk walk. Electricity at 150 volts reached it through the two running rails and a separate iron strip laid between them, and the locomotive picked up power with sliding contacts. By 30 September 1879 it had carried 86,398 riders, who were thrilled to be pulled along by an engine with no fire and no smoke. It is often called the world's first electric passenger train.","Siemens kept going. In May 1881 his company opened the world's first electric tram service in Gross-Lichterfelde, a suburb of Berlin. Trams (called streetcars or trolleys in North America) are lighter railways that run along city streets. Before electricity, most of them were pulled by horses, which were expensive to feed, got tired, fell ill and left the streets covered in manure. Electric trams spread quickly from the 1880s onwards and soon replaced horse trams in cities around the world.","Meanwhile, in the English seaside resort of Brighton, an inventor named Magnus Volk opened a tiny electric railway along the beach in August 1883. The first section was only about a quarter of a mile long, ran on track 2 feet (610 millimetres) wide, and used just 50 volts of electricity. Volk was already known locally for his electrical experiments, including early attempts at electric lighting in the home. His railway was extended and rebuilt over the years, and it is still running today along about a mile of seafront. That makes Volk's Electric Railway the oldest electric railway in the world that still operates, even though it was not the first one ever built.","Volk was full of ideas. In 1896 he opened a strange railway that ran through the shallow sea itself. Its carriage stood on long legs about 7 metres high, so it rolled along rails on the seabed while passengers rode above the waves. People nicknamed it 'Daddy Long Legs'. It closed around 1900, after only a few years, but it shows how excited and inventive people were about the new power."]},{"heading":"Into the Deep: The First Electric Tube","paragraphs":["Cut-and-cover had a serious limit. It only worked a few metres below the surface, under wide streets, and it tore up the city while it was being built. To go under buildings, under the River Thames and deep beneath the crowded City of London, engineers needed to bore real tunnels through the London clay, far below the cellars and sewers.","The key tool was the tunnelling shield, improved by the engineer James Henry Greathead. Picture a giant steel tube, a little wider than the tunnel, pushed forward into the clay by powerful hydraulic jacks. Men worked inside the front of the shield, digging out the clay, while the shield protected them from collapses. As it inched forward, workers bolted rings of curved cast-iron segments together behind it to form the tunnel lining. Ring after ring, the tunnel grew, perfectly round and strong. Greathead had already used this method on a small tunnel under the Thames, and now he used it for a full railway.","That railway was the City and South London Railway. It was first planned to work like San Francisco's cable cars, with carriages gripping a moving cable pulled by engines at the ends of the line. But in 1888 the company supplying the cable system went bankrupt, and the railway's chairman, Charles Grey Mott, made a brave decision: use electricity instead. Nobody had ever run a deep underground railway on electric power before.","The line was officially opened by Edward, Prince of Wales, on 4 November 1890, and it opened to the public on 18 December 1890. It ran about 3.2 miles (5.1 kilometres) from Stockwell, south of the river, under the Thames to King William Street in the City, with six stations. This was the first deep-level 'tube' railway worked by electric trains, the ancestor of today's Northern line.","Riding it was an adventure. Small electric locomotives built by the firm Mather and Platt pulled the trains, taking power at 500 volts from an extra rail beside the track. The tunnels were only about 3.1 metres (10 feet 2 inches) across, so the carriages were small, with high-backed benches and only narrow slits of windows near the roof, since there was nothing to see in a tunnel anyway. Each carriage held about 32 passengers, and people nicknamed them 'padded cells'. There were no tickets and no first or third class: everyone paid a flat fare of two pennies at a turnstile. Since the stations were deep underground, passengers went down in hydraulic lifts.","The little line was slow and cramped, and its locomotives struggled at first, but it proved that deep electric railways worked. More tubes followed. The Central London Railway opened in 1900 and was nicknamed the 'Twopenny Tube' because of its flat two-penny fare. Within a few years, the old smoky Metropolitan Railway also switched to electricity: electric trains began running in 1905, and by 1907 they worked most of its services. The age of steam underground was coming to an end.","Building tubes was hugely expensive, and much of the money for the next wave came from an American businessman, Charles Tyson Yerkes, who had made his fortune with streetcar lines in Chicago. His group finished three new deep tubes in just two years: the line nicknamed the Bakerloo (from Baker Street and Waterloo) in 1906, the Piccadilly line in 1906, and the Hampstead line, part of today's Northern line, in 1907. The different railway companies were rivals at first, but they began to advertise together, and from 1908 their stations carried the same big word 'UNDERGROUND'. The famous red circle with a blue bar, known as the roundel, became the network's symbol, and the companies were finally brought together under one public body, London Transport, in 1933.","That same year, a young engineering draughtsman named Harry Beck produced a new kind of map for the Underground. Instead of showing where the lines really ran, with all their bends and true distances, he drew them as straight lines running only up, down, across or at neat 45-degree angles, with stations evenly spaced, rather like an electrical circuit diagram. Passengers did not need to know exact distances underground; they needed to know which line to take and where to change. Beck's diagram was a huge success, and almost every metro map in the world today follows his idea."]},{"heading":"Frank Sprague: Climbing Hills and Coupling Motors","paragraphs":["Across the Atlantic, one of the most important figures in electric railways was Frank J. Sprague, a former United States Navy officer who had studied at the Naval Academy. In 1883 he went to work for the famous inventor Thomas Edison, but he left after about a year to start his own company making electric motors. Edison himself later praised Sprague's motor as the most practical one available.","Sprague's big test came in Richmond, Virginia. He agreed to electrify a whole city streetcar system there, the Richmond Union Passenger Railway, which was a risky promise because Richmond is very hilly and the motors of the time often overheated or failed on steep slopes. There were breakdowns and frantic repairs, and the job is said to have cost Sprague far more than he was paid, but on 2 February 1888 passenger service began. It is widely seen as the first large, successful electric street railway system. Cities across America noticed. Within just a few years, hundreds of towns had switched from horse cars to electric streetcars, and horse-drawn trams almost disappeared.","Sprague's second great idea was even more important for trains. Early electric trains were usually pulled by one locomotive, just like steam trains. A locomotive has to be heavy to grip the rails, and all the pulling force comes from one place. Sprague asked: why not put motors under many carriages and control them all from a single driving cab? This is called multiple-unit control.","Here is how it works. Each motor carriage has its own traction motors and its own set of switches. Thin control wires run the whole length of the train, linking all the carriages. When the driver moves the controller in the front cab, signals go down those wires and every carriage's switches respond together, so all the motors start, speed up or slow down at the same moment. One driver can control a long train with dozens of motors as if it were a single machine.","Sprague first tried his system on the South Side Elevated Railroad in Chicago in 1897. The advantages were huge. Because the motors were spread along the train, more wheels were driven, so trains gripped the rails better and could speed up quickly, which is perfect for city lines with stations every few hundred metres. Trains could be made longer or shorter simply by coupling or uncoupling carriages. If one motor failed, the others kept the train moving. And with a driving cab at each end, a train could reverse at the end of the line without the driver needing to move a locomotive around. Almost every metro and suburban electric train in the world today, and many high-speed trains, still use this idea. Sprague also built electric lifts (elevators), which helped make tall city buildings practical, so he changed how people moved both sideways and up and down."]},{"heading":"How an Electric Train Works","paragraphs":["A steam locomotive carries its own power station on board: fire, boiler and water. An electric train is different. Its energy is made somewhere else, at a power station, and delivered to the train while it moves. That is why an electric train makes no smoke where it runs, which is exactly what tunnels and crowded cities needed. (The power station may still burn fuel and make pollution, but it is far away from passengers, and today more and more electricity comes from wind, solar, hydro and nuclear power.)","There are two main ways to feed electricity to a moving train. The first is a third rail: an extra rail laid on insulated supports beside or between the running rails. A metal 'shoe' sticking out from the train slides along the top or side of this rail and picks up the current, and the current returns through the wheels and running rails, completing the circuit. Third rails usually carry direct current at fairly low voltages, typically up to about 750 volts. They fit neatly inside small tunnels, which made them perfect for subways. London's Underground uses a fourth rail as well, in the middle of the track, to carry the return current, which protects the old metal tunnel linings from slowly corroding. Because a live rail lies close to the ground, it is dangerous to touch, which is why people must never walk on railway tracks.","The second way is an overhead line: wires hung above the track on poles or gantries. On the train's roof sits a pantograph, a folding, springy metal frame that pushes a contact strip up against the wire. (The name comes from an old drawing instrument with a similar folding shape.) Overhead lines can safely carry much higher voltages, such as 25,000 volts alternating current on many modern main lines, because the wire is far above people's heads. Higher voltage means fewer power substations are needed along the route and more power can reach fast, heavy trains, so overhead wires are used for most high-speed railways. Third rails are usually limited to slower trains, roughly up to 160 kilometres per hour.","Once the electricity is on board, it goes to the traction motors, electric motors mounted near the axles that turn the wheels through gears. Inside a motor, electric current flowing through coils of wire creates magnetic forces that push against each other and make a shaft spin. Electric motors have a great strength: they produce strong turning force (called torque) right from a standstill, so electric trains can pull away quickly and smoothly. They are also simpler than steam engines, with far fewer moving parts, no fire to tend and no water to refill.","Many modern electric trains can even run their motors backwards as generators when slowing down. This is called regenerative braking: the train's movement is turned back into electricity and fed into the wires to help power other trains, instead of being wasted as heat in the brakes. A steam engine, which you saw in Part 9 wasted most of its fuel's energy, could never do anything like that."]},{"heading":"Subways Spread Around the World","paragraphs":["Once London had shown the way, other great cities dug in. In Budapest, the capital of Hungary, a short underground line opened on 2 May 1896 for celebrations marking a thousand years since the Magyars (Hungarians) arrived in the region. It was opened by Emperor Franz Joseph and ran for about 5 kilometres under the elegant Andrássy Avenue to the city park. It was electric from the start, and it is the oldest electric underground railway on mainland Europe. Its small yellow trains still run, and the line has been part of a UNESCO World Heritage Site since 2002. In the same year, Glasgow in Scotland opened its own subway, at first pulled by cables.","On 1 September 1897 Boston opened the Tremont Street Subway, the oldest subway tunnel in North America. It was not a railway for heavy trains but a tunnel for streetcars, built to clear trams off the city's jammed streets. Bostonians crowded in to ride, and parts of the tunnel are still used today, more than 125 years later.","Paris opened Line 1 of its Métro on 19 July 1900, while the city was hosting a huge world's fair, the Exposition Universelle. It ran from Porte Maillot to Porte de Vincennes, right across the city. The engineer Fulgence Bienvenüe, often called the 'father of the Métro', helped plan the whole system as a connected network from the beginning, and the architect Hector Guimard designed beautiful station entrances of curving green ironwork in the Art Nouveau style, looking a bit like strange plants. Eighty-six of them still survive and have become symbols of Paris.","New York had been arguing about subways for more than twenty years. Finally, the Interborough Rapid Transit Company, founded by the financier August Belmont Jr., opened the city's first subway line on 27 October 1904. It ran from City Hall in lower Manhattan up to 145th Street at Broadway. Huge crowds lined up to ride, and the fare was a nickel, five cents. Unlike London's early tubes, New York's subway had separate express tracks so that fast trains could skip local stations. It grew into one of the largest subway systems on Earth.","One of the most famous of all opened on 15 May 1935 in Moscow, the capital of the Soviet Union. Its first line was about 11 kilometres long with 13 stations. The Soviet government wanted the Metro to show off the power of its system, so many stations were built like underground palaces, with marble walls, chandeliers, mosaics and statues, and some were described as bringing an 'artificial underground sun' to the workers. It was built very quickly by huge teams of workers, often in difficult and dangerous conditions. Today the Moscow Metro carries more than two billion passengers a year.","By the 1930s, underground and elevated electric railways had become the beating heart of big cities. Today more than 150 cities around the world have metro systems, from Tokyo and Shanghai to Mexico City and Cairo, nearly all of them electric and nearly all using Sprague's idea of motors spread along the train. Yet out on the long main lines across the countryside, where stringing up wires for thousands of miles was very expensive, the steam locomotive still ruled. Above ground, an engine invented by a German engineer named Rudolf Diesel was about to challenge the mighty steam locomotive."]}],"deepDive":"Why did electricity take so long to win, if it was so much cleaner? Part of the answer is cost. An electric railway needs a whole hidden system before a single train moves: power stations, cables, substations to convert or step down the voltage, and either a third rail or overhead wires along every metre of track. For a busy city line carrying trains every few minutes, that investment pays off quickly. For a country line with a few trains a day, it often does not. That is why cities electrified first, while many main lines kept steam and later switched to diesel. Another debate was over which kind of electricity to use. Early systems used direct current (DC), which suited the motors of the time well and is still used on most metros, usually at 600 to 750 volts, or at 1,500 or 3,000 volts on some main lines. But DC is hard to send long distances, because low voltage means high current, and high current wastes energy as heat in the wires. Alternating current (AC) can be stepped up to high voltage with transformers for efficient transmission, then stepped down on the train. After the Second World War, improved equipment made 25,000-volt AC at 50 hertz (the same frequency as the public power grid in many countries) the favourite for new main lines, starting with experiments in France. Some countries, such as Germany, Austria, Switzerland, Sweden and Norway, use 15,000 volts at a special lower frequency of 16.7 hertz, a choice made in the early 1900s when motors could not cope with higher frequencies. Historians also debate 'firsts'. Siemens's 1879 exhibition loop carried passengers but was a demonstration; Volk's 1883 line is the oldest still running; the Gross-Lichterfelde tram of 1881 was the first regular public electric tram; and the City and South London of 1890 was the first deep-level electric tube. There were also important early electric experiments in the United States, by inventors such as Leo Daft and Charles Van Depoele, before Sprague's Richmond success in 1888. As with steam, electric traction grew out of many inventors improving one another's work, rather than a single genius.","funFact":"Volk's Electric Railway in Brighton opened in 1883 and still carries passengers along the seafront today, making it the oldest operating electric railway in the world.","check":{"q":"What was the world's first underground railway, and when did it open to the public?","a":"London's Metropolitan Railway, on 10 January 1863","wrong":["The Paris Métro, on 19 July 1900","The New York subway, on 27 October 1904","The Budapest Metro, on 2 May 1896"]},"sources":[{"title":"Metropolitan Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Metropolitan_Railway"},{"title":"City and South London Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/City_and_South_London_Railway"},{"title":"Siemens locomotive of 1879","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Siemens_locomotive_of_1879"},{"title":"Volk's Electric Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Volk%27s_Electric_Railway"},{"title":"Frank J. Sprague","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Frank_J._Sprague"},{"title":"Multiple unit","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Multiple_unit"},{"title":"Third rail","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Third_rail"},{"title":"Budapest Metro","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Budapest_Metro"}],"photos":[{"src":"img/deep/railways/16-1.jpg","alt":"Baker Street station on the Metropolitan Railway around 1863, with a steam train arriving in the gas-lit underground tunnel.","file":"Metropolitan Railway, Baker Street Station.jpg","url":"https://commons.wikimedia.org/wiki/File:Metropolitan_Railway,_Baker_Street_Station.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/railways/16-2.jpg","alt":"Werner von Siemens's little electric locomotive pulling a trainload of passengers at the Berlin trade exhibition, 1879.","file":"First electric locomotive, built in 1879 by Werner von Siemens.jpg","url":"https://commons.wikimedia.org/wiki/File:First_electric_locomotive,_built_in_1879_by_Werner_von_Siemens.jpg","author":"Siemens","license":"Public domain"},{"src":"img/deep/railways/16-3.jpg","alt":"Hector Guimard's Art Nouveau \"Metropolitain\" entrance with its glass canopy at Abbesses station, Paris.","file":"Paris (75018) Métro Abbesses Édicule Guimard.jpg","url":"https://commons.wikimedia.org/wiki/File:Paris_(75018)_M%C3%A9tro_Abbesses_%C3%89dicule_Guimard.jpg","author":"Alexander Baranov from Montpellier, France","license":"CC BY 2.0"}],"words":3818},{"n":17,"title":"Diesel Power and the End of Steam","when":"1890s – 1970s","summary":"A German engineer named Rudolf Diesel invented an engine that lit its fuel just by squeezing air until it was super hot. Shiny new diesel trains raced across countries, and one by one the smoky steam engines were sent to museums. But then cars and planes stole many passengers, and railways had to find new ways to stay useful.","sections":[{"heading":"Rudolf Diesel's Red-Hot Air","paragraphs":["Imagine pumping up a bicycle tyre very fast. Put your hand on the pump afterwards and it feels warm. That warmth is a clue to one of the most important engines ever invented. When you squash air quickly into a smaller space, it gets hotter. Squash it hard enough and it becomes hot enough to set fuel on fire, with no flame and no spark at all.","The man who turned that simple clue into a world-changing machine was Rudolf Diesel. He was born in Paris on 18 March 1858 to parents from Bavaria in southern Germany, and he grew up to become a brilliant, stubborn engineer. As a student in Munich he learned a shocking fact from his teacher, the refrigeration expert Carl von Linde: steam engines, the mighty machines that powered factories, ships and trains, turned only about 6 to 10 percent of the heat in their fuel into useful work. All the rest drifted away as wasted heat. Diesel decided he would build something far better.","In 1892 he received a German patent (an official document saying an invention belongs to its inventor) for a new kind of 'heat engine', and in 1893 he published a book explaining his theory, with the grand title Theory and Construction of a Rational Heat Motor. A big machine-building company in Augsburg, the firm that later became MAN, agreed to help him build a test engine, along with the steelmaker Krupp.","It was not easy. During one high-pressure test a cylinder head burst, and Diesel was lucky not to be badly hurt. Earlier in his career another experimental engine, which used ammonia vapour, had exploded and nearly killed him. Year after year he and the Augsburg workers rebuilt, tested and improved. In 1895 one prototype reached an efficiency of about 16.6 percent. Then, in early 1897, a new single-cylinder engine was officially tested and turned about 26 percent of its fuel's energy into work. That was several times better than a typical steam engine, and the world took notice.","So how does a diesel engine work? Inside a metal cylinder there is a piston that slides up and down. First the piston moves down and sucks in plain air. Then it moves up and squeezes that air into a tiny space, often 15 to 23 times smaller than before. Engineers call this the compression ratio. Squeezed so hard, the air heats up to several hundred degrees Celsius. At exactly the right moment, a fine spray of fuel is squirted in. The fuel meets the scorching air and bursts into flame on its own. The hot gases expand with tremendous force, shoving the piston down. Finally the piston pushes the used gases out, and the four-step cycle starts again.","Because the fuel lights itself, a diesel engine needs no spark plug. Because it squeezes the air so hard, it gets far more work out of each drop of fuel than most other engines. Diesel engines could also burn heavy, cheap oils. Diesel himself experimented with many fuels, and at the Paris World's Fair of 1900 a small diesel engine was shown running on peanut oil.","Rudolf Diesel's own story ended in mystery. On 29 September 1913 he boarded the steamer Dresden in Antwerp, Belgium, to cross to England. During the night he vanished from the ship. Days later a body was found in the sea and identified from his belongings. Nobody knows for certain what happened, and people still argue about it today. He never saw his engine pull a main-line train, but within a few decades it would change railways everywhere."]},{"heading":"Why a Diesel Train Is Secretly Electric","paragraphs":["Early diesel engines were huge and heavy, built for factories and ships, so at first nobody was sure they belonged on rails. People still tried. In 1912 the Prussian State Railways in Germany received a 95-tonne locomotive in which a diesel engine drove the wheels through gears and rods. Tests in 1913 showed lots of problems, and the First World War stopped the experiment.","The trouble was a basic fact about engines. A car engine, a lorry engine and a diesel engine all like to spin within a certain range of speeds. They cannot push hard while barely turning, and they cannot start a heavy load from a dead stop on their own. In a car, a clutch and gearbox solve the problem. But imagine building a gearbox and clutch strong enough to start a train weighing more than a thousand tonnes. It would have to be enormous, and it would wear out quickly.","The clever answer was to put electricity in the middle. In a diesel-electric locomotive, the diesel engine never touches the wheels at all. Instead, it spins a generator, a machine that turns spinning motion into electricity. Cables carry that electricity to traction motors, which are powerful electric motors mounted next to the axles. The traction motors turn the wheels. In other words, a diesel-electric locomotive is really a travelling power station joined to an electric train.","This trick has big advantages. Electric motors can push extremely hard when they are turning slowly, which is exactly what you need to get a long, heavy train rolling. The diesel engine can keep humming at its most comfortable speed while the electrical controls decide how much power the motors receive. In 1914 an engineer named Hermann Lemp, working for the American company General Electric, designed a control system that let a driver manage the whole thing with a single handle. His idea became the model for diesel-electric controls for decades.","The driver of a diesel-electric locomotive moves a throttle lever through a series of steps called notches. Each notch tells the engine to run a bit faster and the generator to send more power to the motors. Many diesel-electric locomotives can also use dynamic braking: when slowing down, the traction motors are switched to work as generators, which makes them resist the turning wheels. The electricity they produce is turned into heat in large grids of resistors and blown away by fans, saving wear on the ordinary brakes.","The first diesel-electric railcars ran in the German kingdom of Saxony in 1914. By 1925 small diesel-electric 'boxcab' locomotives were working in American freight yards. These were switchers, or shunters, the little engines that push wagons around yards to sort them into trains. Diesels were perfect for this job. A steam shunter had to keep its fire burning all day, even while waiting for its next small task. A diesel could simply idle, using very little fuel, and be ready the moment it was needed.","There was one more advantage that would matter enormously. Thanks to Frank Sprague's multiple-unit idea, which you met with electric trains, several diesel-electric locomotives could be coupled together and controlled by one crew in the front cab. Need more power for a heavy train or a steep hill? Just add another unit. With steam, every extra locomotive needed its own driver and fireman."]},{"heading":"Silver Streaks: The Streamliners","paragraphs":["In the early 1930s the world was in the Great Depression, a time when many businesses failed and millions of people lost their jobs. Railways were losing passengers to cars and buses. They needed something exciting to win people back. Their answer was the streamliner: a sleek, smooth train shaped to slip through the air, often powered by diesel engines.","Germany struck first. In 1932 the national railway, the Deutsche Reichsbahn, ordered a two-car diesel train from a factory in Görlitz. It had two 12-cylinder Maybach diesel engines, each driving its own generator, together producing about 810 horsepower. Its rounded nose and smooth sides had been carefully shaped to cut air resistance. Regular service began on 15 May 1933 between Berlin and Hamburg, about 286 kilometres apart. The journey took 138 minutes, an average of about 124 km/h, with a top speed of 160 km/h. It was one of the fastest scheduled train services in the world, and people nicknamed it the Fliegender Hamburger, the 'Flying Hamburger'. Inside it carried 98 seated passengers plus a tiny four-seat buffet. Its success led to a whole fleet of similar fast diesel trains linking German cities.","Across the Atlantic, the Chicago, Burlington and Quincy Railroad, usually called the Burlington, had a president named Ralph Budd who loved new ideas. He worked with the Budd Company of Philadelphia (no relation, despite the matching name) to build a train unlike anything Americans had seen. It was made of stainless steel, so it gleamed silver and never needed painting. The pieces were joined by a special electric welding method called shotwelding. The three cars were linked together on shared sets of wheels, making the train light and low. Its diesel engine came from the Winton Engine Company, part of General Motors, and produced about 660 horsepower. The train was named Zephyr, after Zephyrus, the Greek god of the gentle west wind.","On 26 May 1934 the Zephyr set out to prove what it could do. The plan was audacious: run non-stop from Denver, Colorado, to Chicago, Illinois, a distance of about 1,015 miles (1,633 km), all in daylight. It would arrive on the opening day of the second season of Chicago's world's fair, the Century of Progress Exposition. Ordinary Burlington trains took about 25 hours for the same trip.","The Zephyr left Denver at just after 7 o'clock in the morning. Track workers guarded crossings along the route, and crowds gathered at stations to watch it flash past. On board were Ralph Budd, the train's builder Edward Budd, reporters, railway staff and a few lucky members of the public. There was even a mascot: a small donkey, called a burro, named Zeph, donated by a Denver newspaper. On one stretch the train touched about 112.5 mph (181 km/h).","At 8:09 that evening it arrived in Chicago, 13 hours and 5 minutes after leaving Denver, nearly two hours ahead of schedule. Its average speed over the whole journey was about 77 mph (124 km/h). It then glided onto the stage at the world's fair to cheering crowds. Newspapers across the country celebrated the 'Dawn-to-Dusk' run. A steam train could not have done it without stopping again and again for water and coal; the Zephyr's diesel just kept going.","The Zephyr went into regular service and became famous, even starring in a Hollywood film. Other railways rushed to build their own streamliners, and soon trains with names like the City of Salina and the Flying Yankee were zooming across America. The original Zephyr, later called the Pioneer Zephyr, is preserved today at the Museum of Science and Industry in Chicago, where visitors can walk through it."]},{"heading":"Steam's Last Giants","paragraphs":["Steam engineers did not give up without a fight. In fact, some of the most amazing steam locomotives ever built appeared at the very moment diesels were starting to win. It was as if steam wanted to show off one last time.","In Britain the designer Nigel Gresley built streamlined express engines for the London and North Eastern Railway, with smooth, wedge-shaped casings. On 3 July 1938 one of them, Mallard, ran down a long slope called Stoke Bank near Grantham with driver Joseph Duddington and fireman Thomas Bray on the footplate. It reached 126 mph (203 km/h), a world speed record for steam that has never been beaten. Some experts think the speed it held steadily was a little lower, about 124 mph, but either way it was a stunning run, and Mallard now rests at the National Railway Museum in York.","In America, steam went big rather than fast. The Union Pacific Railroad had a problem: its freight trains had to climb the Wasatch Mountains between Ogden, Utah, and Green River, Wyoming. Ordinary locomotives needed help from extra 'helper' engines on the steep grades. So the railway asked the American Locomotive Company (ALCO) in Schenectady, New York, to build a monster. The first of these arrived in 1941. While No. 4000 was being built, a worker chalked the words 'Big Boy' on the front, and the nickname stuck.","Big Boy was so long that its frame had to bend in the middle. It was an articulated locomotive, meaning it had two sets of driving wheels, each with its own cylinders, so the engine could snake around curves. Its wheel arrangement was 4-8-8-4: four small wheels at the front, two groups of eight big driving wheels, and four small wheels under the cab. The engine alone weighed around 345 tonnes, and with its huge tender it stretched about 40 metres, longer than three buses parked end to end. A mechanical stoker, a kind of screw conveyor, fed coal into its huge firebox, because no human fireman could have shovelled fast enough.","Twenty-five Big Boys were built: twenty in 1941 and five more in 1944, during the Second World War, when railways were carrying enormous amounts of war supplies. They hauled long freight trains for nearly two decades. The last Big Boy run in regular service took place on 21 July 1959. Eight survive, and one of them, No. 4014, was restored to working order in 2019 for the 150th anniversary of the first transcontinental railroad. Today it still steams across the American West on special tours, drawing huge crowds.","Other countries built their own last great steam engines too. Britain's final steam locomotive built for British Railways, a heavy freight engine named Evening Star, was completed in 1960. But by then everyone could see where the future lay."]},{"heading":"Why the Railways Switched","paragraphs":["If steam engines could be so fast and so strong, why did railways replace them? The answer comes down to money, time and hard work.","First, there was fuel. As you saw when we climbed inside a steam locomotive, a typical steam engine turned only about 5 to 10 percent of its coal's energy into pulling power. A diesel-electric locomotive typically turned roughly 30 to 40 percent of its fuel's energy into useful work, several times better. That meant far less fuel for the same job.","Second, there was water. Steam engines drank enormous amounts of it, so railways had to build water towers every few dozen miles. In the dry deserts of the American West, finding clean water was a real headache, and hard minerals in the water built up inside boilers like scale inside a kettle. Diesels needed no water for their boilers, because they had none.","Third, there was maintenance. A steam locomotive needed hours of preparation each day. Someone had to light the fire, sometimes many hours before departure, clean out ash, oil dozens of moving parts, and regularly wash out the boiler. Steam engines spent a large part of their lives in workshops. Diesels spent much more time actually out on the line earning money. They could be refuelled quickly from tanks and left idling for hours without anyone tending them.","Fourth, there were crews. With multiple-unit control, one driver could command three, four or more diesel units at the front of a heavy train. When steam railways needed more power, they added another locomotive with another crew. Over thousands of trains a year, that difference added up to huge savings.","Diesels were also cleaner to work around. Steam crews breathed smoke and coal dust, and steam trains blackened stations, tunnels and the clothes of passengers. Diesels still produced exhaust, but far less soot than a coal fire.","In the United States, the turning point came at the end of the 1930s. General Motors' Electro-Motive Division built a four-unit freight diesel called the FT and sent it on a demonstration tour of American railways beginning in 1939. It hauled heavy freight trains over mountain routes and impressed railway bosses everywhere. After the Second World War, orders poured in. In 1949 the same company launched a simple, practical locomotive called the GP7, a 'general purpose' engine that could do almost any job, and versions of it soon filled railway yards across the country.","The switch was astonishingly fast. According to railway records, steam's share of the US locomotive market fell from about 30 percent in 1945 to about 2 percent in 1948. By the mid-1950s American railways had retired around 90 percent of their steam engines."]},{"heading":"The Fires Go Out","paragraphs":["On the big American railways, mainline steam had almost entirely disappeared by around 1960. The Norfolk and Western Railway, a coal-carrying line that built its own excellent steam engines and stayed loyal to them longer than most, finally gave in at the end of the 1950s. A few small railways kept old steam engines working a little longer, but the era was over.","Britain was slower. In 1955 British Railways announced a huge Modernisation Plan to bring in diesel and electric trains, yet it kept building some steam engines until 1960, and many early diesels were unreliable. Then the change sped up. Engine sheds closed one by one, and railway fans rushed around the country with cameras and notebooks to record the last steam trains in their area.","The final scheduled steam-hauled passenger trains on British Railways' standard-gauge network ran on 3 August 1968, in north-west England around Preston, Liverpool and Manchester. One week later, on 11 August 1968, British Railways ran a farewell special from Liverpool to Carlisle and back. Tickets cost 15 guineas, a lot of money at the time, so the train became known as the Fifteen Guinea Special. Four different locomotives took turns pulling it, including the famous express engine Oliver Cromwell. Thousands of people lined the tracks to watch it go by. The very next day, British Railways banned steam locomotives from its main lines.","Steam lasted much longer in some other parts of the world, where coal was cheap and workers' wages were low. India ran its last scheduled broad-gauge steam train in December 1995, though steam still climbs into the hills on the Darjeeling Himalayan Railway. China built new main-line steam locomotives until 1988, and its last mainline steam service ended in 2005.","Yet steam never completely died. Volunteers rescued hundreds of old locomotives from scrapyards. Today heritage railways in Britain, America, Australia and many other countries run steam trains for visitors, so a child in the 2020s can still smell coal smoke and hear the chuff of a working steam engine."]},{"heading":"Hard Times: Cars, Planes and Cuts","paragraphs":["Diesels made trains cheaper to run, but railways faced an even bigger challenge: people were finding other ways to travel. After the Second World War, more and more families bought cars. Lorries (trucks) carried goods from door to door. In 1956 the United States began building the Interstate Highway System, a vast network of fast, multi-lane roads paid for mostly by the government. Two years later, big jet airliners such as the Boeing 707 began flying passengers across the country in a few hours.","Passenger trains could not keep up. In 1945 railways carried about 74 percent of America's commercial intercity passenger travel (counted in passenger-miles); by 1957 the figure had fallen to about 32 percent. The length of passenger routes shrank from about 107,000 miles in 1958 to about 49,000 miles in 1970. Private railway companies were losing money on almost every passenger train and wanted to stop running them.","To save America's passenger trains from disappearing completely, Congress passed the Rail Passenger Service Act, which President Richard Nixon signed on 30 October 1970. It created a new national company to run intercity passenger trains, called Amtrak. When Amtrak began operating on 1 May 1971, it kept only about half of the routes that had been running the day before: 184 out of 366. Amtrak still runs today, while freight companies own most of the tracks.","Britain faced the same crisis. By 1961 British Railways was losing about 300,000 pounds every day. The government asked a businessman and scientist named Richard Beeching to fix it. On 27 March 1963 he published a report called The Reshaping of British Railways. It found that many country branch lines and small stations carried very few passengers and freight, and it recommended closing 2,363 stations and roughly 5,000 miles of railway.","Most, though not all, of these closures went ahead, along with some lines that were not even on Beeching's list. The busiest year was 1964, when about 1,000 miles of route closed. Over the following years Britain lost thousands of miles of railway and well over 2,000 stations. Some towns were left without any train service at all. The 'Beeching cuts' are still argued about today. Some people say they saved the railway from bankruptcy; others say they went too far and that many lines would be useful now.","Interestingly, some of those lines have come back. In 2015 about 35 miles of the old Waverley Route south of Edinburgh reopened as the Borders Railway, and other stations have been reopened too. Many closed branch lines were rescued by volunteers and now run as heritage railways."]},{"heading":"Boxes on Rails: Freight Fights Back","paragraphs":["Just when railways seemed old-fashioned, a humble metal box gave freight trains a brand-new purpose. On 26 April 1956 an American trucking businessman named Malcolm McLean sent the ship Ideal X from Newark, New Jersey, to Houston, Texas, carrying 58 big metal containers. The idea was simple: instead of loading thousands of separate sacks, barrels and crates by hand, pack goods into strong, standard-sized boxes that cranes could lift straight from a ship onto a lorry or a train.","In 1968 the International Organization for Standardization began publishing standard container sizes, so a box packed in China could fit on a ship, a train or a truck anywhere in the world. Railways loved it. In 1977 the first railway wagon designed to carry containers stacked two high was delivered in the United States, and in 1984 the first train made up entirely of 'double-stack' wagons set off from Los Angeles across the country towards New Jersey. One train could now carry hundreds of containers across a continent, pulled by a few diesel-electric locomotives working together with one crew.","Today, long container trains rumble across North America, Europe, India and China, and some run all the way from China to Europe. Freight railways became one of the cheapest ways to move goods over land, thanks to the same old secret: steel wheels rolling on steel rails need very little energy.","Still, by the early 1960s passenger trains in many countries looked tired and slow compared with shiny cars and jet planes. Many people thought the age of the passenger train was ending. Then, in October 1964, Japan unveiled a gleaming blue-and-white train with a rounded nose that looked as if it had come straight from the future."]}],"deepDive":"Why did diesel-electric traction beat steam so decisively, when steam engines could still be faster and, in the case of Big Boy, enormously strong? Historians of technology mostly point to economics rather than performance. A steam locomotive is an external combustion engine: fuel burns in a firebox, heats water in a boiler, and only then does the steam push pistons. Each stage leaks heat, and much of the energy leaves with the exhaust steam up the chimney, so overall thermal efficiency was usually only around 5 to 10 percent. A diesel is an internal combustion engine that burns its fuel inside the cylinder at very high compression (typically 15:1 to 23:1), and diesel-electric locomotives typically delivered roughly 30 to 40 percent of the fuel's energy as useful work. Yet fuel was not the whole story, because coal was often cheaper than oil. The bigger savings came from 'availability', the fraction of time a locomotive was ready to work. Steam engines needed daily fire-cleaning, frequent boiler wash-outs, and heavy overhauls, while diesels could run for long periods between servicing. Railways also closed hundreds of water towers, coaling stations and engine sheds, and shed large numbers of jobs, which made dieselisation a painful time for railway workers. Multiple-unit control meant one crew could run several units, a direct saving in wages. There are debates too. Some engineers argue that late steam designs, such as André Chapelon's rebuilt locomotives in France, showed steam's efficiency could have been improved much further, and that the change was partly driven by fashion and by diesel builders' heavy marketing, including General Motors' famous FT demonstration tour. In Britain, historians debate whether the 1955 Modernisation Plan was rushed, since it ordered many untested diesel designs that later proved unreliable. The Beeching report remains controversial: defenders note that many lines lost large sums and carried very few passengers, while critics argue that it judged branch lines in isolation, ignoring the passengers they fed onto main lines, and that cheaper ways of running them were never properly tried. Ironically, rising traffic and some reopened lines since the 1990s suggest that not every closure was wise.","funFact":"When the Burlington Zephyr made its record non-stop run from Denver to Chicago in 1934, it carried a mascot on board: a small burro (donkey) named Zeph.","check":{"q":"In a diesel-electric locomotive, what actually turns the wheels?","a":"Electric traction motors, powered by a generator that the diesel engine spins","wrong":["The diesel engine's pistons, connected straight to the wheels by rods","Steam from a boiler heated by the diesel engine","A huge battery charged overnight at the station"]},"sources":[{"title":"Rudolf Diesel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rudolf_Diesel"},{"title":"Diesel engine","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Diesel_engine"},{"title":"Diesel locomotive","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Diesel_locomotive"},{"title":"Pioneer Zephyr","publisher":"Griffin Museum of Science and Industry, Chicago","url":"https://www.griffinmsi.org/explore/whats-here/exhibits/pioneer-zephyr"},{"title":"Pioneer Zephyr","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pioneer_Zephyr"},{"title":"DRG Class SVT 877 (Flying Hamburger)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/DRG_Class_SVT_877"},{"title":"Union Pacific Big Boy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Union_Pacific_Big_Boy"},{"title":"Beeching cuts","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Beeching_cuts"}],"photos":[{"src":"img/deep/railways/17-1.jpg","alt":"The stainless-steel Pioneer Zephyr diesel streamliner, number 9900, in a 1930s Budd Company photo.","file":"Pioneer Zephyr.JPG","url":"https://commons.wikimedia.org/wiki/File:Pioneer_Zephyr.JPG","author":"Edward Budd Company, Philadelphia.","license":"Public domain"},{"src":"img/deep/railways/17-2.jpg","alt":"Union Pacific Big Boy No. 4014, the giant steam locomotive, puffing out of Las Vegas in 2019.","file":"Union Pacific Big Boy 4014 Departing Las Vegas, NV, October 8th, 2019.jpg","url":"https://commons.wikimedia.org/wiki/File:Union_Pacific_Big_Boy_4014_Departing_Las_Vegas,_NV,_October_8th,_2019.jpg","author":"Fan Railer","license":"CC BY-SA 4.0"},{"src":"img/deep/railways/17-3.jpg","alt":"Portrait photograph of Rudolf Diesel, inventor of the diesel engine.","file":"Rudolf Diesel.jpg","url":"https://commons.wikimedia.org/wiki/File:Rudolf_Diesel.jpg","author":"Unknown photographer","license":"Public domain"}],"words":4098},{"n":18,"title":"Bullet Trains","when":"1964 – today","summary":"In 1964 Japan opened a brand-new railway with sleek trains that zoomed along at 210 km/h, faster than any regular train before. People called them bullet trains. Soon France, Germany, Spain and China built their own super-fast trains, and engineers dug amazing tunnels under the sea and through the mountains.","sections":[{"heading":"A Crowded Country and a Bold Old Man","paragraphs":["Picture Japan in the 1950s. The country was recovering from the terrible destruction of the Second World War, and its factories were growing fast. Most of its people and industry were squeezed into a narrow strip along the Pacific coast, between Tokyo and Osaka. The old railway joining them, the Tōkaidō Main Line, was one of the busiest in the world, and it was jammed. Trains crawled along tracks built to a narrow gauge of 1,067 mm (3 ft 6 in), which made them less stable at high speed than trains on wider track. The line could not carry many more passengers or much more freight.","Japan's railway planners had dreamed of something better before. In 1939 they had drawn up plans for a fast new line, and newspapers nicknamed the proposed trains dangan ressha, which means 'bullet train'. War stopped the project. But the name was never forgotten.","In 1955 a 71-year-old man named Shinji Sogō became president of Japanese National Railways, or JNR. Many people thought he was too old for the job, but Sogō was full of energy and determined to build a completely new railway. Instead of squeezing more trains onto the old narrow track, he wanted a separate, wider-gauge line built only for fast passenger trains. Many experts thought the idea was foolish. Airliners and motorways were the future, they said, and railways were finished.","Sogō needed a brilliant engineer, so he brought back Hideo Shima, who had designed steam locomotives for Japan's railways and had left JNR a few years earlier. Shima was born in Osaka in 1901 and had studied mechanical engineering at Tokyo Imperial University. Years before, he had suggested a radical idea: instead of one heavy locomotive pulling the whole train, put electric motors under many of the carriages. This 'distributed power' would spread the weight more evenly, reduce the pounding on the track and let the train accelerate and brake more smoothly. It became a key feature of the bullet train.","Building the new line was a gigantic job. Construction began on 20 April 1959. The route needed thousands of bridges and many tunnels, and it had to cope with a country shaken by frequent earthquakes. Japan asked the World Bank, an international lender, for help, and in the early 1960s received a loan of 80 million US dollars, much less than the railway had hoped for and only a small slice of the total cost. To persuade the government to support the project, Sogō is often said to have presented a lower cost estimate than he expected, knowing that once the work had begun, nobody would want to stop it halfway.","The costs did rise far above the original budget. In 1963, before the line even opened, both Sogō and Shima were forced to resign. Shima's career was far from over, though. In 1969 he became head of Japan's new space agency, NASDA, and helped develop its rockets."]},{"heading":"1 October 1964: The Future Arrives","paragraphs":["Early on the morning of 1 October 1964, two gleaming trains set off at the same moment, one from Tokyo and one from Osaka. The Tōkaidō Shinkansen was open. The name Shinkansen simply means 'new trunk line' in Japanese, but the rest of the world soon called the trains bullet trains.","The timing was perfect. Nine days later, on 10 October, the Tokyo Olympic Games opened, the first Olympics ever held in Asia. Visitors from all over the world arrived to find a country that had rebuilt itself after the war, and a train that seemed to belong to the 21st century.","The first trains are known as the 0 Series. They were painted ivory white with a blue stripe, and their rounded noses were shaped a little like the front of an airliner. Every carriage had its own electric motors, following Shima's distributed power idea. The trains were designed to cruise at up to 210 km/h (130 mph), far faster than any regular train service in the world at that time. The line was about 515 km long, running from Tokyo to Shin-Ōsaka.","At first the railway ran a little cautiously while its brand-new track settled. The fastest service, called Hikari, meaning 'light', took 4 hours between Tokyo and Osaka. The stopping service, called Kodama, meaning 'echo', took 5 hours. By November 1965 the Hikari had been speeded up to 3 hours 10 minutes. The best express on the old line had needed more than six hours.","Passengers flocked to the new trains. About 100 million people had ridden the Tōkaidō Shinkansen by 1967, less than three years after it opened. By 2012 it had carried about 5.3 billion passengers, roughly three people for every four alive on the whole planet at that time. Daily ridership grew from about 61,000 in 1964 to more than 450,000 by 2016.","The original 0 Series trains served for 35 years before the last ones left the Tōkaidō line in 1999. Today the line's trains run at up to 285 km/h, and at the busiest times as many as 17 trains an hour leave Tokyo for the west. Japan kept extending its Shinkansen network north and south, to Hokkaido, Kyushu and the coast of the Sea of Japan, so that it now stretches roughly 3,000 km."]},{"heading":"The Secrets of Speed","paragraphs":["You might think that to make a train go faster, you just need a bigger engine. In fact, high-speed rail is a whole system, and every part had to be rethought.","First, the track. The Shinkansen runs on its own dedicated lines, separate from slow local and freight trains. It uses standard gauge, 1,435 mm, the same gauge that George Stephenson chose for his railways, rather than Japan's usual narrow gauge. The curves are very wide and gentle, because a train taking a sharp curve at high speed would push outward with huge force, uncomfortable for passengers and hard on the rails. There are no level crossings where roads cross the line; every road passes over or under it on a bridge. Much of the line runs on viaducts and embankments, with long tunnels through hills, so the track stays as straight and level as possible.","Second, the power. A train cruising at 200 km/h or more needs a great deal of energy, far more than it could carry in a fuel tank without becoming much heavier. So high-speed trains are electric. A high-voltage overhead wire, called the catenary, runs above the track, and pantographs on the roof press gently against it to collect electricity. That electricity drives traction motors spread along the train.","Third, the shape. At high speed, the biggest enemy is the air. Air resistance increases with the square of the speed: go twice as fast and the air pushes back about four times as hard. So bullet trains have smooth sides and streamlined noses. In Japan the nose has another job. When a fast train bursts into a narrow tunnel, it squeezes the air in front of it like a piston in a syringe, sending a pressure wave racing ahead. When that wave reaches the far end, it can burst out with a loud boom, a problem called 'tunnel boom'. That is one reason newer Shinkansen trains have very long, carefully sculpted noses, some of them more than 15 metres long, which ease into the tunnel gradually.","Fourth, the signals. Ordinary trains rely on signals beside the track. But at over 200 km/h, a driver would have only a split second to see a signal, and it would take several kilometres to stop. So the Shinkansen showed signal information inside the driver's cab, on the dashboard. This is called cab signalling. Even more important was automatic train control, or ATC. Electrical signals sent through the rails tell the train the maximum safe speed for each section of track. If the driver goes too fast, the ATC system applies the brakes automatically.","Finally, there is the people side: careful timetables, strict maintenance and constant inspection. Overnight, when no passenger trains run, special inspection trains and maintenance crews check the track and wires so that everything is perfect for the morning. In Japan the yellow track-inspection train is nicknamed Doctor Yellow, and spotting it is said by fans to bring good luck."]},{"heading":"Safe, Punctual and Earthquake-Ready","paragraphs":["Speed is impressive, but what has made the Shinkansen truly famous is how safe and reliable it is. In more than 60 years, carrying over 10 billion passengers, the Shinkansen has had no passenger deaths caused by its trains derailing or colliding in normal service. That is an astonishing record for any form of transport, let alone one that runs at nearly 300 km/h through one of the most earthquake-prone countries on Earth.","That does not mean nothing has ever gone wrong, and it is important to be accurate. On 23 October 2004 a powerful earthquake struck the Chūetsu region of Niigata Prefecture. A Jōetsu Shinkansen train called Toki 325 was travelling at speed near Nagaoka when the shaking hit, and eight of its ten cars came off the rails. Amazingly, none of the 154 passengers was killed or injured. Afterwards, engineers fitted new anti-derailment guides to the tracks to help keep wheels close to the rails even if a train is knocked sideways. In 2013 another train on the Akita Shinkansen line derailed in a blizzard, again with no injuries to passengers. Sadly, there have been a few deaths and injuries in other ways, such as a passenger who was caught in a closing door and dragged along a platform, which is why platform staff now watch the doors carefully.","How do you protect a train from earthquakes? Japan built a network of seismometers, instruments that detect ground shaking, along its lines and coasts. Earthquakes send out different kinds of waves. The first, faster waves are usually gentle; the slower waves that follow cause most of the damage. Since 1992 a warning system known as UrEDAS has been able to sense the first waves and automatically cut power to trains and apply their brakes, often seconds before the strongest shaking arrives. Seconds matter: a train braking early is travelling much more slowly when the ground starts to sway. Newer trains have also been made lighter and given stronger brakes so that they stop sooner.","Then there is punctuality, meaning being on time. On the Tōkaidō Shinkansen, the average delay per train is measured in seconds rather than minutes. JR Central, the company that runs the line, reported an average delay of only about 12 seconds per train in the 2019 financial year, even counting delays caused by storms and earthquakes. Train crews and station staff work to a precise timetable, and cleaning teams can tidy an entire train in just a few minutes while it waits at the terminus.","Winter weather is another enemy. Near Maibara, where snow often falls on the Tōkaidō line, sprinklers spray water onto the tracks to stop snow from piling up and freezing onto trains. On the snowy Jōetsu line in the mountains, even stronger sprinklers and special concrete slab track help trains keep running through snow two or three metres deep."]},{"heading":"Europe Joins the Race","paragraphs":["Japan's success made the rest of the world sit up. France was next. French engineers at first built an experimental train powered by gas turbines, a type of engine similar to those on jet aircraft. This prototype, TGV 001, reached 318 km/h in December 1972. But in 1973 the world was hit by an oil crisis, when the price of oil soared. Fuel-hungry gas turbines suddenly looked like a bad bet, and France had plenty of electricity from its power stations. So the production trains were made electric.","TGV stands for Train à Grande Vitesse, French for 'high-speed train'. Before opening, a test train reached 380 km/h on 26 February 1981, a new world record. Then, on 27 September 1981, the first TGVs began carrying the public on a new high-speed line between Paris and Lyon. TGV carriages share their wheel sets: instead of each coach having two sets of wheels of its own, the ends of neighbouring coaches rest on the same bogie. This articulated design makes the train lighter and helps it stay upright and in line even if it derails, one reason TGVs have not had a passenger death in an accident on their high-speed lines in normal service for more than four decades. On 28 November 2003 the TGV network carried its billionth passenger.","The French loved breaking records. In 1990 a TGV reached 515.3 km/h. Then, on 3 April 2007, a specially modified train nicknamed V150 roared along the new LGV Est line east of Paris. It had extra-large wheels, extra power, and the voltage in the overhead wire was raised from the usual 25,000 volts to 31,000 volts. The wire was also pulled tighter, so that the pantograph would not set up waves in it at such tremendous speed. The train reached 574.8 km/h (357 mph). That is still the world speed record for a train running on ordinary steel wheels and rails. At that speed you could travel from London to Paris in well under an hour.","Germany followed with its InterCityExpress, or ICE. An experimental version set a world record of 406.9 km/h on 1 May 1988, and regular ICE services began on 2 June 1991, linking Hamburg with Frankfurt and Munich. Germany's high-speed story also includes a tragedy. On 3 June 1998 an ICE train crashed near the village of Eschede after a tiny fatigue crack caused the steel tyre of one of its wheels to break apart. The train derailed at a switch and hit a road bridge, and 101 people died. Investigators found that the wheel design had not been properly tested for repeated stress. Germany quickly replaced those wheels with solid one-piece wheels and changed its safety rules, lessons that helped make high-speed rail safer worldwide.","High-speed trains changed the way people chose to travel. When the AVE first opened, its non-stop trains covered the Madrid to Seville route in 2 hours 45 minutes, and by 1994, running at up to 300 km/h, the fastest trains took about 2 hours 20 minutes. Journeys like that are short enough that, once you count the time spent getting to an airport, checking in and waiting at the gate, the train often wins. On routes such as Paris to Lyon and Madrid to Seville, many travellers who once flew switched to the train, and airlines cut their flights.","Spain opened its first high-speed line, called AVE, in April 1992, just in time for the world's fair Expo 92 in Seville. The line ran about 472 km from Madrid to Seville. Spain's older railways used a broad 'Iberian' gauge, wider than most of Europe, but the new line was built to standard gauge so that it could one day connect to the rest of Europe. Today Spain has one of the largest high-speed networks in the world, and other countries, including Italy, Belgium, the Netherlands, South Korea, Taiwan and Turkey, have joined the high-speed club too."]},{"heading":"Under the Sea and Through the Alps","paragraphs":["Fast trains need straight, level tracks, and sometimes the only way to get them is to go underground. The late 20th century became an age of record-breaking railway tunnels.","Japan led again. Its main island, Honshu, is separated from the northern island of Hokkaido by the stormy Tsugaru Strait. In 1954 a typhoon sank the ferry Tōya Maru in the strait, and about 1,430 people died. The disaster convinced the government that a fixed link was needed. Work on the Seikan Tunnel began in 1971. Workers battled flooding and crumbling rock, and 34 of them died during construction. When the tunnel opened in March 1988, it was 53.85 km long, with about 23.3 km running beneath the seabed. Its track lies around 240 metres below sea level. Since 2016 Shinkansen trains have run through it on the way to Hokkaido.","Between Britain and France, people had dreamed of a tunnel under the English Channel since Napoleon's time. Finally, in the late 1980s, eleven giant tunnel boring machines started chewing through a layer of soft rock called chalk marl, which is easy to dig yet fairly waterproof. At the peak of construction about 15,000 people worked on the project. On 1 December 1990 British and French workers broke through and shook hands deep beneath the sea. The Channel Tunnel actually consists of three tunnels: two for trains and a smaller service tunnel between them for maintenance and emergencies. It is about 50.5 km long, and its 37.9 km undersea section is the longest of any tunnel in the world, reaching about 75 metres below sea level.","Queen Elizabeth II and French President François Mitterrand opened the tunnel on 6 May 1994. In November 1994 Eurostar passenger trains began running through it, linking London with Paris and Brussels. It cost far more than planned, about 80 percent over budget, but it changed travel between Britain and mainland Europe for good.","Then came the mountains. Switzerland sits in the middle of the Alps, and lorries carrying goods between northern and southern Europe were clogging its mountain roads. In 1992 Swiss voters approved a plan to build new flat railway routes through the Alps. The centrepiece was the Gotthard Base Tunnel. Instead of climbing up the mountains and spiralling down the other side, like the old Gotthard railway of 1882, trains would pass right through the base of the mountains.","Digging began in 1999. In places the tunnel lies about 2,450 metres beneath the mountain peaks above, and the rock was so hot that the tunnels had to be cooled for workers. The eastern tube broke through on 15 October 2010. Sadly, nine workers died during construction. The tunnel was opened on 1 June 2016 and began regular service that December. At about 57 km long, it is the longest railway tunnel in the world, and its highest point is only about 549 metres above sea level, making it the first flat route through the Alps. Passenger trains can pass through at up to 200 km/h."]},{"heading":"China's Giant Leap","paragraphs":["The most dramatic high-speed story of all began in 2008. On 1 August that year, a week before the Beijing Olympics opened, China opened a high-speed line between Beijing and the port city of Tianjin. It offered the first commercial train service in the world scheduled to run at 350 km/h (217 mph). Passengers loved it: the short Beijing to Tianjin line alone carried more than 41 million riders in its first two years.","China had studied the world's best high-speed trains and arranged to build versions of them at home, using designs from Japan's Kawasaki, Germany's Siemens, France's Alstom and Canada's Bombardier. Chinese engineers soon developed their own models. In June 2011 a line opened between Beijing and Shanghai, China's two biggest cities.","The fast growth brought a hard lesson. On 23 July 2011 two high-speed trains collided on a viaduct near the city of Wenzhou after signalling failures during a thunderstorm. Officially, 40 people died. The government paused approvals of new lines and reduced top speeds on many routes while safety was reviewed. From 2017 new Chinese-designed trains called Fuxing, meaning 'rejuvenation', brought 350 km/h running back to several major lines.","After that, construction went on at an astonishing pace. By 2020 China had about 37,900 km of high-speed railway, and by the early 2020s it had more than 40,000 km, more than the rest of the world combined. The network has since passed about 50,000 km, roughly two-thirds of all the high-speed track on Earth. Gleaming stations as big as airports have been built in city after city, and on busy holidays such as the Lunar New Year, hundreds of millions of journeys are made on China's railways.","From Japan's first bullet train in 1964 to China's vast network today, high-speed rail has shown that trains are not old-fashioned at all. Yet even the fastest steel wheel has a limit. At extreme speeds, wheels and rails wear quickly, the pantograph struggles to stay in contact with the wire, and the train needs huge power just to push the air aside. So engineers have asked a daring question: if wheels have a speed limit, what if a train had no wheels touching the track at all?"]}],"deepDive":"High-speed rail is usually defined as passenger service at about 250 km/h or more on newly built lines, or about 200 km/h on upgraded older lines. Why not simply run trains faster on old tracks? The physics of curves explains much of it. A train on a curve needs a sideways (centripetal) force equal to its mass times speed squared divided by the curve's radius, so doubling speed needs a curve four times as wide to keep the same comfort and the same force on the rails. Tilting the track (cant) helps, but only up to a limit, because slow trains on the same track would then lean inwards uncomfortably. That is a strong argument for dedicated passenger-only lines like the Shinkansen. Air resistance is the other wall: drag grows roughly with the square of speed, so the power needed to overcome it grows roughly with the cube. Going from 300 to 360 km/h needs about 70 percent more power just for the air. The 2007 V150 record at 574.8 km/h needed extra-large wheels, boosted voltage and specially tensioned catenary, conditions no commercial service could sustain cheaply, which is why most high-speed trains cruise at 300 to 350 km/h. Debates continue about cost and value. Supporters point to big cuts in short-haul flights where fast trains compete: when a train journey takes under about three to four hours, many travellers switch from planes, as happened between Madrid and Seville and between Paris and Lyon. Critics point to huge construction costs and debts, cost overruns from the Tōkaidō line to the Channel Tunnel and Britain's HS2, and some lightly used lines. China's boom has been especially debated: its national railway operator carries large debts, and some economists question whether every line will repay its cost, while others argue that faster connections between cities bring wider economic and environmental benefits that ticket sales alone do not capture. Safety lessons have shaped the whole field: the Eschede disaster changed wheel design and testing, and the Wenzhou collision led China to review signalling. Historians also note that the Shinkansen's success came from an integrated system, combining track, trains, signalling, maintenance and timetables, rather than from any single invention.","funFact":"The nickname 'bullet train' is older than the Shinkansen itself: it translates dangan ressha, a name Japanese newspapers gave to a planned fast railway back in 1939.","check":{"q":"On what date did Japan's first Shinkansen line, the Tōkaidō Shinkansen, open?","a":"1 October 1964","wrong":["27 September 1981","1 August 2008","6 May 1994"]},"sources":[{"title":"Tōkaidō Shinkansen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/T%C5%8Dkaid%C5%8D_Shinkansen"},{"title":"Shinkansen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shinkansen"},{"title":"Hideo Shima","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hideo_Shima"},{"title":"TGV world speed record","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/TGV_world_speed_record"},{"title":"TGV","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/TGV"},{"title":"Channel Tunnel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Channel_Tunnel"},{"title":"Gotthard Base Tunnel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gotthard_Base_Tunnel"},{"title":"High-speed rail in China","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/High-speed_rail_in_China"}],"photos":[{"src":"img/deep/railways/18-1.jpg","alt":"A blue-and-white 0 Series Shinkansen bullet train, the original 1964 design, at the National Railway Museum in York.","file":"0 Series Shinkansen NRM.jpg","url":"https://commons.wikimedia.org/wiki/File:0_Series_Shinkansen_NRM.jpg","author":"FairlieGood","license":"CC BY 4.0"},{"src":"img/deep/railways/18-2.jpg","alt":"The special TGV \"V150\" racing at about 574 km/h on the LGV Est during its 2007 world speed record run.","file":"TGV World Speed Record 574 km per hour (cropped).jpg","url":"https://commons.wikimedia.org/wiki/File:TGV_World_Speed_Record_574_km_per_hour_(cropped).jpg","author":"Alain Stoll","license":"CC BY-SA 2.0"},{"src":"img/deep/railways/18-3.jpg","alt":"A Swiss passenger train leaving the south portal of the Gotthard Base Tunnel, the world's longest railway tunnel.","file":"Zugsausfahrt GBT Süd-Portal.jpg","url":"https://commons.wikimedia.org/wiki/File:Zugsausfahrt_GBT_S%C3%BCd-Portal.jpg","author":"Bundesamt für Verkehr","license":"Public domain"}],"words":3732},{"n":19,"title":"Maglev and the Trains of Tomorrow","when":"1934 – the future","summary":"Some trains have no wheels touching the track at all. Super-strong magnets lift them up and push them along, so they float and zoom like flying trains. In Japan one floating train went 603 km/h, faster than any other train ever!","sections":[{"heading":"A Train With Nothing Underneath","paragraphs":["Imagine standing on a platform at Longyang Road station in Shanghai. A long white train with a pointed nose slides in so quietly that you hear the doors more than the train. You step aboard, sit down, and a screen above the door starts counting up the speed: 100 km/h, 200, 300... Outside, apartment blocks and farm fields smear into stripes of colour. Yet something is missing. There is no clackety-clack of wheels over rail joints, no rumble from below. That is because this train has no wheels touching the track at all. It is floating about a centimetre above its guideway, held up and pushed along by magnets.","This kind of train is called a maglev, short for 'magnetic levitation'. To levitate means to float in the air without being held up by anything you can see. For about 400 years, from horse-drawn wagons on wooden rails to the TGV's record of 574.8 km/h, every railway in this story worked the same basic way: a wheel rolled along a rail. Maglev throws away the wheel. It is the biggest change to the basic idea of a railway since the very beginning.","Why would anyone want to get rid of wheels? In Part 18 we saw that steel wheels on steel rails are wonderfully efficient, but at very high speeds they run into trouble. The wheels and rails wear down, the train shakes, the overhead wire and the pantograph must stay in perfect contact, and the grip between a smooth wheel and a smooth rail limits how hard the train can speed up and slow down. Engineers began to dream of a train that never touched the ground. No contact means no wheel wear, no rolling friction and far less vibration. In this part we meet the floating trains, the people who dreamed them up, and the cleaner, smarter railways of tomorrow."]},{"heading":"How Magnets Can Lift a Train","paragraphs":["You already know two big facts about magnets. Opposite poles (north and south) pull towards each other, and matching poles (north and north, or south and south) push each other away. Maglev engineers use exactly these two forces. But there is a catch: the little magnets on your fridge are far too weak, and there is a famous rule in physics, worked out by the British mathematician Samuel Earnshaw in 1842, which shows that you cannot make an object float steadily using fixed, ordinary magnets alone. It will always wobble off to one side and fall or snap into place. So real maglev trains need powerful electromagnets or superconducting magnets, careful electronic control, and a powered guideway. There is no free floating.","An electromagnet is a coil of wire that becomes a magnet when electricity flows through it. Turn the current up and the magnet gets stronger; turn it down and it gets weaker; switch it off and the magnetism disappears. That on-off, stronger-weaker control is the secret of the first kind of maglev, called electromagnetic suspension, or EMS for short.","In an EMS train, such as Germany's Transrapid and the Shanghai Maglev, the bottom of the train wraps around the edges of a T-shaped guideway like a hand curling under the edge of a table. Electromagnets on the curled-under part sit beneath a steel rail and pull upwards towards it. This attraction lifts the whole train. Left alone, the magnet would keep pulling until it slammed into the rail, so sensors measure the gap thousands of times every second and a computer adjusts the current to keep the gap steady at about 10 millimetres, roughly the thickness of a pencil. If the gap shrinks, the current drops; if it grows, the current rises. The train is always very slightly falling and being caught again, far too fast for any passenger to feel. A big advantage of EMS is that it works even when the train is standing still.","The second kind of maglev, used by Japan's SCMaglev, is called electrodynamic suspension, or EDS. It uses pushing rather than pulling, and it relies on a clever trick of nature. When a strong magnet moves quickly past a loop of metal wire, it makes an electric current flow in the loop, and that current turns the loop into a magnet that pushes back. The faster the train moves, the stronger the push. Japan's trains carry superconducting magnets: coils cooled with liquid helium to about minus 269 degrees Celsius, just four degrees above the coldest temperature possible. At that temperature the coils lose all electrical resistance, so a huge current can flow round and round without fading, making magnets far stronger than any ordinary electromagnet.","Along the walls of the Japanese guideway are rows of figure-of-eight coils. As the train's magnets rush past, currents flow in these coils, pushing the train up and pulling it towards the centre. Once the train passes about 150 km/h, it rises roughly 10 centimetres, the width of your hand, above the guideway. Below that speed the push is not strong enough, so the train rolls on rubber tyres, a bit like an aeroplane taking off from a runway and then folding up its wheels.","Floating is only half the job. A maglev also has to move forwards. For this, engineers use a linear motor. Picture an ordinary electric motor, the kind that spins inside a fan. Now imagine slicing it open and unrolling it flat, so that instead of a spinning ring of electromagnets you have a long straight line of them. In a maglev, this flattened motor is built into the guideway itself, sometimes for hundreds of kilometres. Electricity is switched through the coils in a carefully timed pattern, creating a travelling wave of magnetism that runs along the track. The magnets on the train are dragged along by this wave, like a surfer riding a wave towards the beach. Make the wave travel faster and the train speeds up; run it backwards and the same motor becomes a powerful brake. Because the motor is in the track, the train itself carries no engine at all."]},{"heading":"The Dreamers: Kemper and Laithwaite","paragraphs":["The idea of a floating train is much older than the trains themselves. One of its first serious champions was Hermann Kemper, a German engineer born in 1892 in the small village of Nortrup in Lower Saxony. Kemper is said to have started thinking about magnetic levitation in the 1920s, at a time when most German trains were still pulled by steam. In 1933 he built a working electrical circuit that could keep an object hovering using electromagnetic attraction, adjusting the magnet to stop it crashing upwards or dropping away. This was the key problem that every later EMS maglev would have to solve.","On 11 August 1934, Kemper applied for a German patent, a legal document that protects an inventor's idea. Its long German title described a 'suspension railway with wheelless vehicles' floating along iron rails, guided by magnetic fields. The patent was granted and published in 1937. Kemper even imagined vehicles inside tubes with the air pumped out, reaching enormous speeds, an idea that would return decades later. A research job and a test track of about 20 km were planned, but the Second World War stopped the project in 1943. Kemper's ideas lay mostly forgotten until the late 1960s, when German companies began developing the Transrapid on the basis of his concept. He lived to see it: in 1972 he received one of Germany's highest honours, and he died in 1977. Today he is often called the 'father of maglev'.","In Britain, another engineer approached the problem from a different direction. Eric Laithwaite was born in 1921 in Atherton, Lancashire. After serving in the Royal Air Force during the Second World War, he studied electrical engineering at the University of Manchester. There, in the late 1940s, he became fascinated by the linear induction motor, the 'unrolled' electric motor described in the last section. People had sketched linear motors before, but Laithwaite built full-size working models and spent his career showing what they could do.","In 1964 Laithwaite became professor of heavy electrical engineering at Imperial College London, and he was a brilliant explainer who gave the Royal Institution Christmas Lectures for young people. In his laboratory he built a 'magnetic river', a strip of coils over which a flat piece of metal floated and was swept along with nothing touching. It looked so magical that it appeared in the James Bond film The Spy Who Loved Me.","Laithwaite's linear motors were chosen for Britain's Tracked Hovercraft project, a train-like vehicle meant to float on a cushion of air and be pushed along by a linear motor at up to about 400 km/h. A test track was built in Cambridgeshire, but the government cancelled the project in the early 1970s before it could be tested at full speed. Even so, his work on linear motors helped inspire maglev research around the world, and he too is sometimes nicknamed the 'father of maglev'. Fair credit means saying both men matter: Kemper showed how a vehicle could hover on controlled magnets, and Laithwaite showed how a linear motor could push it along."]},{"heading":"From an Airport Shuttle to Shanghai","paragraphs":["The world's first maglev to carry ordinary passengers every day was not a super-fast express. It was a little shuttle at Birmingham Airport in England. Its technology came from experiments at British Rail's research laboratory in Derby, and it was built by a group of British companies for the local council. On 16 August 1984 it opened, running on a raised concrete track about 600 metres long between the airport terminal and Birmingham International railway station.","The Birmingham maglev was gentle rather than thrilling. Its small, boxy cars floated about 15 millimetres above the track and took roughly 90 seconds for the trip, reaching a top speed of only a few tens of kilometres per hour. For travellers carrying suitcases it was simply a handy, quiet people mover, and many of them probably never realised they were floating. It ran for eleven years. But its electronics were one of a kind, spare parts became hard to find, and breakdowns grew more common. The last service ran on 18 June 1995. In 2003 a cable-pulled shuttle called the Air-Rail Link opened on the same raised track. One of the old maglev cars is now kept at the Locomotion railway museum in Shildon, County Durham, not far from where the Stockton and Darlington Railway began in 1825.","Meanwhile, Germany was working on something much faster: the Transrapid, an EMS maglev designed to float between cities at hundreds of kilometres per hour. In the early 1980s a test loop more than 30 km long was built in Emsland in north-west Germany, where Transrapid trains ran at over 400 km/h and visitors could buy tickets to ride.","The Emsland track also brought a tragedy. On 22 September 2006, near the town of Lathen, a Transrapid test train carrying visitors and staff ran into a maintenance vehicle that had been left on the guideway. Twenty-three people died. Investigators found the cause was human error in the safety checks, not a failure of the floating technology itself, but the accident badly hurt public confidence. A planned maglev link to Munich Airport was cancelled in 2008 because its costs had soared, and the Emsland test track closed in 2011. Germany, the country that had invented much of maglev, never built a maglev line of its own for everyday passengers.","German maglev did find a home, but on the other side of the world. In the early 2000s, China decided to link the city of Shanghai with its new Pudong International Airport using Transrapid technology, made by a partnership of the German companies Siemens and ThyssenKrupp. The line was built on a raised concrete guideway about 30 km long, from Longyang Road station, where passengers can change onto the Shanghai Metro, to the airport.","On 31 December 2002, the line was inaugurated by the leaders of China and Germany, Premier Zhu Rongji and Chancellor Gerhard Schröder. Regular service followed in 2003, with full commercial service from the start of 2004. It was the first high-speed maglev in the world to carry paying passengers every day, and it remains the only Transrapid line ever built for everyday passengers. It cost roughly 10 billion yuan, more than a billion US dollars at the time.","For years the Shanghai Maglev was the fastest passenger train in regular service anywhere. It reached 431 km/h on each trip, covering the 30 km in about 7 minutes 20 seconds. A taxi on the same route could easily take half an hour or more in traffic. During a test run on 12 November 2003, a Shanghai maglev train reached 501 km/h. Many passengers photograph the speed display when it shows 431.","In 2021 the operators lowered the top speed to 300 km/h, reportedly to save energy and wear, so a trip now takes about 8 minutes 10 seconds. That is still astonishingly fast for a ride to the airport. But notice something important. The Shanghai Maglev is a short shuttle between one city station and one airport. It was meant as a showcase, and it was never extended into the long intercity lines its supporters hoped for. To understand why, we need to look at Japan, and then at money."]},{"heading":"Japan's 603 km/h Flying Train","paragraphs":["Just two years before the first Shinkansen opened in 1964, engineers at Japanese National Railways were already dreaming of what might come after it. In 1962 they began researching linear motor trains, with a goal of linking Tokyo and Osaka, more than 500 km apart, in about one hour. Their first successful run on a short track came in 1972. In 1977 they opened a 7 km test track at Miyazaki on the southern island of Kyushu, and later the much longer Yamanashi test line west of Tokyo, whose first 18.4 km section opened in 1997. It was later extended to 42.8 km, much of it in tunnels through the mountains.","This Japanese system, now called SCMaglev and developed by the railway company JR Central with the Railway Technical Research Institute, uses the superconducting magnets and figure-of-eight coils described earlier. Its trains roll on rubber tyres when starting and stopping, then lift about 10 centimetres into the air once they pass about 150 km/h. Because the gap is so large compared with German maglev, the guideway does not have to be built quite so precisely, and the trains are less affected by small movements caused by earthquakes, a serious concern in Japan.","The Yamanashi test line has seen a series of world records. In December 2003 a test train called the MLX01 reached 581 km/h. Then, on 21 April 2015, a seven-car L0 Series train carrying engineers reached 603 km/h, which is 375 mph. That is the fastest speed ever reached by any train, with or without wheels. At that speed you would travel the length of a football pitch in well under a second. It also beat the French TGV's wheel-on-rail record of 574.8 km/h from 2007, though remember that the TGV record was set on ordinary steel rails.","The L0 Series is meant for a real railway: the Chūō Shinkansen, a new line between Tokyo and Osaka. Its first section, from Shinagawa in Tokyo to Nagoya, is about 286 km long, and roughly nine-tenths of it will be in tunnels, including a long tunnel deep under the Southern Japanese Alps. Trains are planned to run at up to 505 km/h, cutting the Tokyo to Nagoya trip to about 40 minutes and Tokyo to Osaka to about 67 minutes. Construction began on 17 December 2014.","JR Central hoped to open the Nagoya section in 2027. Then came a problem that had nothing to do with magnets. Shizuoka Prefecture, under which the tunnel passes, worried that digging could drain water from the Ōi River that its farms and towns depend on, and in 2020 it refused permission to start tunnelling there. The opening is now expected no earlier than the mid-2030s, and the cost has grown to more than 9 trillion yen. Even a futuristic railway still has to be agreed to by real communities."]},{"heading":"Why Maglev Is Still So Rare","paragraphs":["If maglev is so fast and smooth, why are there only a handful of maglev lines in the world? The answer comes down to a few stubborn problems.","The first is cost. A maglev guideway is not a pair of rails on sleepers and gravel. It is a precisely built concrete or steel beam packed with electromagnets, coils, sensors and power equipment, and for a high-speed line it must be almost perfectly straight and smooth, usually raised on pillars or hidden in tunnels. The motor, remember, is in the track, so every kilometre of guideway is part of a giant machine. Building costs have often been tens of millions of US dollars per kilometre, and big projects tend to grow far more expensive than first planned, as Munich and the Chūō Shinkansen both showed.","The second problem is that maglev cannot join the existing railway network. A Shinkansen train can, at least in principle, use the same kind of steel rails as a slower train, and in France a TGV can leave its high-speed line and run on old tracks into the heart of Paris. A maglev train cannot run on any ordinary track at all, and an ordinary train cannot use a maglev guideway. Every station, depot and branch must be built new. Switching a maglev from one guideway to another is also harder: instead of moving a short piece of rail at the points, engineers must bend or slide a whole heavy section of guideway beam.","The third problem is that floating does not remove the biggest force at high speed. Above about 300 km/h, most of the energy a fast train uses goes into pushing air out of the way, not into fighting friction at the wheels. Air resistance grows very quickly as speed rises, so a maglev at 500 km/h needs a lot more power than a bullet train at 300 km/h.","Meanwhile, ordinary high-speed rail kept getting better. Steel wheels on steel rails proved perfectly happy at 300 to 350 km/h, fast enough to beat planes on many trips. For most countries, extending a proven wheel-on-rail network has been a safer bet than building a separate maglev system. Maglev works and holds the speed record; it is just very hard to make it worth the money."]},{"heading":"Hype Versus Reality: The Hyperloop","paragraphs":["Dreams of racing through tubes are old. Around 1800 the English inventor George Medhurst suggested moving goods by air pressure through pipes, and in the early 1900s the rocket pioneer Robert Goddard and others sketched 'vactrains' in tubes with the air pumped out. Hermann Kemper imagined something similar in the 1930s.","On 12 August 2013, the businessman Elon Musk published a paper describing his own version, which he called the Hyperloop. Passengers would ride in small pods inside a long steel tube with most of the air removed, so there would be very little air resistance. The paper suggested pods could reach about 1,200 km/h and link Los Angeles and San Francisco in about half an hour, and claimed it could be built far more cheaply than California's planned high-speed railway. Musk did not build it himself; he invited others to try.","Many did. The best funded was a company founded in 2014 that became known as Hyperloop One, and for a few years Virgin Hyperloop, after Richard Branson's Virgin Group invested. It raised hundreds of millions of dollars and built a 500-metre test tube called DevLoop in the Nevada desert near Las Vegas. On 8 November 2020, two of its employees became the first people to ride in a hyperloop pod, reaching 172 km/h. That is fast for a 500-metre track, but slower than an ordinary regional train.","Then reality caught up. Engineers and transport experts had warned from the start that the cost estimates were far too low. Building hundreds of kilometres of perfectly straight, airtight tube is enormously expensive. Keeping a near-vacuum along the whole route takes powerful pumps. And there were hard safety questions: what happens if a tube cracks, the power fails, or passengers need to get out halfway along? In February 2022 the company gave up on carrying passengers and turned to freight, cutting about half its staff. It shut down completely on 31 December 2023. Several other hyperloop companies have also closed.","The honest answer today: no passenger hyperloop has ever entered service anywhere. It is a good lesson for young inventors. An exciting video is the easy part; making something safe, affordable and reliable enough for millions of people to trust every day is the real invention."]},{"heading":"Cleaner, Smarter Trains for a Warming Planet","paragraphs":["The trains of tomorrow will not only be about speed. Burning coal, oil and gas releases carbon dioxide, a gas that traps heat and is warming the planet, and here trains have a huge advantage. Using UK government figures, the research website Our World in Data estimates that a national rail journey in Britain produces around 35 grams of carbon dioxide (and similar gases) per passenger per kilometre, compared with about 170 grams for an average petrol car and 246 for a domestic flight. The electric Eurostar comes to only about 4 grams. Exact numbers depend on how full the train is and how the electricity is made, but per passenger an electric train is almost always far cleaner than a car or a plane.","The biggest step is electrification: putting up overhead wires or third rails so trains can run on electricity, which can come from wind, solar, hydro or nuclear power. Around a third of the world's railway route length is electrified. Some countries have gone much further: India has electrified almost its entire broad-gauge network, while China has electrified most of its main lines. Electric trains have another trick called regenerative braking. When the driver brakes, the traction motors work backwards as generators, turning the train's movement back into electricity and feeding it into the wires for other trains to use.","Stringing wires over quiet country lines can cost too much, so engineers are trying other ideas. Battery trains charge up under the wires and then run on their batteries for the unwired stretch; Japan began running one, the EV-E301, in 2014. Hydrogen trains carry hydrogen gas and use a fuel cell, a device that combines hydrogen with oxygen from the air to make electricity, with water as the only exhaust. On 16 September 2018, the world's first hydrogen-powered passenger trains, the Alstom Coradia iLint, entered service in Lower Saxony in northern Germany, on the line linking Buxtehude, Bremervörde, Bremerhaven and Cuxhaven. They can travel about 600 to 800 km on a tank and reach 140 km/h. Hydrogen is still expensive to make cleanly, so in some places battery trains are proving the cheaper choice. Railways are testing both to see which wins.","Trains are also getting smarter. The world's first driverless urban railway, the Port Liner in Kobe, Japan, opened on 5 February 1981, followed by Lille's VAL metro in France in 1983. Today many metros, from Copenhagen to Vancouver and Delhi, run with no driver on board at all, letting trains run closer together and more often.","Signalling is changing too. In the old block system from Part 14, a train had to wait until a whole fixed section ahead was empty. Modern systems, such as Europe's ETCS, talk to trains by radio and tell the driver or computer exactly how far it is safe to go; some use a 'moving block', a safe bubble of space that travels with each train. More trains can then share the same tracks safely.","Look back down the long line of track and see how far we have come: from horses plodding along wooden rails at Wollaton, to Trevithick's puffing engine creeping through Wales at about 5 mph, to trains that float on magnets at 603 km/h and others that run on sunshine, wind and water. Each step built on the one before it. Now it is time for the final stop, where we stand back, look at the whole journey, and ask what comes next."]}],"deepDive":"Why does a maglev need clever electronics or supercooled magnets? Earnshaw's theorem (1842) shows that no arrangement of fixed magnets and charges can hold an object in stable balance in all directions. Engineers get round it in two ways. Electromagnetic suspension (EMS), used by Transrapid and the Shanghai line, uses attraction, which is naturally unstable: the closer the magnet gets to the rail, the harder it pulls. So a feedback loop measures the roughly 10 mm gap thousands of times a second and adjusts the current, much like you balancing a broom on your hand. Electrodynamic suspension (EDS), used by Japan's SCMaglev, relies on Faraday's law of induction: moving magnets induce currents in passive coils in the guideway, and by Lenz's law those currents oppose the motion that created them, producing lift and centring forces. Because the effect depends on speed, EDS needs wheels below about 150 km/h, and it also creates magnetic drag that is largest at low speed. Its niobium-titanium superconducting coils must be kept near 4 kelvin (about minus 269 degrees Celsius) with liquid helium; researchers have tested 'high-temperature' superconductors that can be cooled more cheaply. The energy debate is subtle. Maglev removes rolling resistance and wheel wear, but at high speed aerodynamic drag dominates. Drag force rises with the square of speed, and the power needed to overcome it rises roughly with the cube, so going from 300 to 500 km/h needs about 4.6 times as much power just for the air. Supporters answer that maglev can still use less energy per passenger than a plane over the same distance, and that its very fast trips could replace many short flights, as the Chūō Shinkansen hopes to do between Tokyo and Osaka. Critics point to huge construction costs, tunnels and incompatibility with existing networks, and argue the same money buys far more ordinary rail. Hyperloop tried to defeat air drag by removing the air, but historians of technology note a familiar pattern: bold promises, low early cost estimates and attractive videos, followed by the hard engineering of vacuum seals, thermal expansion of steel tubes, emergency exits and passenger comfort. Hyperloop One shut down in 2023, and no passenger hyperloop has ever operated. For now, the most powerful 'technology of tomorrow' for railways may be the least glamorous: electrification, better signalling and running more trains on tracks that already exist.","funFact":"In 2010 one of the retired cars from Birmingham's 1984 airport maglev was sold on eBay, and after the first buyer failed to pay it was resold for just 100 pounds.","check":{"q":"What speed did Japan's L0 Series SCMaglev reach on 21 April 2015, the fastest any train has ever gone?","a":"603 km/h (375 mph)","wrong":["431 km/h (268 mph)","574.8 km/h (357 mph)","1,200 km/h (760 mph)"]},"sources":[{"title":"Maglev","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maglev"},{"title":"Hermann Kemper","publisher":"Wikipedia (German)","url":"https://de.wikipedia.org/wiki/Hermann_Kemper"},{"title":"Birmingham Maglev","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Birmingham_Maglev"},{"title":"Shanghai maglev train","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shanghai_maglev_train"},{"title":"SCMaglev","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SCMaglev"},{"title":"Chūō Shinkansen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chūō_Shinkansen"},{"title":"Hyperloop One","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hyperloop_One"},{"title":"Which form of transport has the smallest carbon footprint?","publisher":"Our World in Data","url":"https://ourworldindata.org/travel-carbon-footprint"}],"photos":[{"src":"img/deep/railways/19-1.jpg","alt":"The white Shanghai Maglev train gliding along its concrete guideway beside Pudong International Airport.","file":"A maglev train coming out, Pudong International Airport, Shanghai.jpg","url":"https://commons.wikimedia.org/wiki/File:A_maglev_train_coming_out,_Pudong_International_Airport,_Shanghai.jpg","author":"User Alex Needham (own photography) on en.wikipedia","license":"Public domain"},{"src":"img/deep/railways/19-2.jpg","alt":"Japan's L0 Series SCMaglev, with its very long pointed nose, on the Yamanashi test line.","file":"Series L0.JPG","url":"https://commons.wikimedia.org/wiki/File:Series_L0.JPG","author":"Saruno Hirobano","license":"CC BY-SA 3.0"},{"src":"img/deep/railways/19-3.jpg","alt":"The low-speed maglev shuttle at Birmingham Airport, England, running on its raised track in the 1980s.","file":"Birmingham International Maglev.jpg","url":"https://commons.wikimedia.org/wiki/File:Birmingham_International_Maglev.jpg","author":"MaltaGC","license":"CC BY-SA 3.0"}],"words":4412},{"n":20,"title":"End of the Line? The Big Picture","when":"Then, now and next","summary":"We have ridden from horses on wooden rails all the way to floating magnet trains. Railways changed where people live, what time our clocks say and how we go on holiday. Now it's your turn to imagine the trains of the future!","sections":[{"heading":"The Whole Journey in One Ride","paragraphs":["Imagine a magic train that can travel through time as well as space. You climb aboard, the doors close, and the window becomes a screen showing 400 years of railway history rushing past. Let us take one last ride down the whole line before we reach the end of the track.","First stop: the 1500s, deep in a mine in central Europe, where miners push little carts along wooden planks, just as Georgius Agricola drew them in his book De re metallica in 1556. A few decades later, around 1603 to 1604, Huntingdon Beaumont lays the Wollaton Wagonway in Nottinghamshire, and soon horses are pulling coal wagons along wooden rails all over the coalfields around Newcastle. Wooden rails give way to iron, and in 1803 the Surrey Iron Railway opens as a public horse railway anyone can pay to use.","The window fills with steam. On 21 February 1804 Richard Trevithick's locomotive puffs along the Penydarren tramroad in South Wales, the first known steam locomotive to haul a load on rails, crawling at about 5 miles per hour. Salamanca, Puffing Billy and George Stephenson's Blücher follow in the coal mines. On 27 September 1825 the Stockton and Darlington Railway opens, the first public railway to use steam locomotives. Four years later, in October 1829, Robert and George Stephenson's Rocket wins the Rainhill Trials, and on 15 September 1830 the Liverpool and Manchester Railway opens as the first true intercity railway, worked entirely by steam.","Now the train races across oceans and continents. Railway Mania grips Britain in the 1840s. In America, Peter Cooper's Tom Thumb loses its race with a horse in 1830, but steam soon wins the bigger contest. On 10 May 1869 the Golden Spike ceremony at Promontory Summit, Utah, joins the first transcontinental railroad, built in the west mostly by Chinese immigrant workers. Canada's last spike follows in 1885, and the Trans-Siberian Railway stretches about 9,289 km across Russia by 1916.","The scenery changes faster. Clocks across Britain switch to railway time; on 18 November 1883, the 'Day of Two Noons', North American railroads adopt standard time zones. George Westinghouse's air brakes and Eli Janney's couplers make trains safer. Underground, London's Metropolitan Railway opens in 1863, and electric tube trains follow in 1890. Diesel streamliners such as the Burlington Zephyr arrive in the 1930s, Mallard sets the steam speed record of 126 mph in 1938, and by the 1960s steam is fading from main lines.","Then, on 1 October 1964, a sleek blue-and-white Shinkansen glides out of Tokyo, and the age of high-speed rail begins. The TGV, ICE, Eurostar and China's vast network follow. Finally, the window shows a train with no wheels at all: Japan's SCMaglev floating through a mountain tunnel at 603 km/h on 21 April 2015. From about 5 mph in 1804 to over 600 km/h in 2015, a speed increase of roughly 75 times, in a little over 200 years. That is the end of the timeline. But it is not the end of the line."]},{"heading":"Three Big Ideas That Never Changed","paragraphs":["Locomotives went from wood-fired puffers to floating magnets. Carriages went from open wagons with no roofs to air-conditioned double-deckers with Wi-Fi. Yet under all those changes, three big ideas stayed almost exactly the same for about 400 years. They are the real secret of the railway.","The first idea is a smooth, guided track. A road lets a vehicle go anywhere, but that freedom costs a lot: the driver must steer every second, the surface must be wide, and the wheels sink into bumps and mud. A railway gives up that freedom. The vehicle can only go where the track leads. In return, the track can be made smooth and strong, the wheels are steered automatically by their coned treads and flanges, and many vehicles can be joined into one long train following exactly the same path. The miners pushing carts along planks in Agricola's woodcuts and the Shinkansen driver watching the signal screen in his cab are using the same basic idea.","The second idea is low friction. A hard steel wheel on a hard steel rail squashes only a tiny amount where the two touch, a contact patch about the size of a small coin. A rubber tyre on a road squashes much more, and that squashing wastes energy. As a result, the rolling resistance of a train wheel is several times lower than that of a car tyre. Maglev took this idea to its extreme by getting rid of rolling friction altogether.","The third idea follows from the first two: you can pull a huge weight with very little energy. On a good track, a single horse could pull many times more than it could on a muddy road, which is why the first wagonways were built at all. Today a single freight train can carry as much as hundreds of lorries. In 2001, in the Pilbara region of Western Australia, the mining company BHP ran one of the heaviest and longest trains ever recorded: 682 wagons of iron ore, about 7.35 km long and weighing nearly 100,000 tonnes, pulled by eight diesel-electric locomotives and driven by one person.","Even the width of the track remembers the past. The standard gauge of 4 ft 8½ in (1,435 mm) came from the colliery wagonways of north-east England that George Stephenson knew as a young engine-wright. The wagonways used about 4 ft 8 in; Stephenson used that width at Killingworth and on the Stockton and Darlington, then added an extra half inch on the Liverpool and Manchester to help wheels round curves, and other builders copied it. A popular story claims the gauge comes straight from the width of Roman chariots, but that is a myth: historians trace it to the wagonways, whose width in turn suited a horse walking between the rails. After Britain's Gauge Act of 1846 and the spread of British-built engines around the world, standard gauge became the most common gauge on Earth. Today more than half of the world's railway lines, roughly 55 to 60 percent, use it, including most high-speed lines. Other countries chose different widths, such as India's broad gauge of 1,676 mm, which is one reason a train cannot simply drive from one country's network onto another's."]},{"heading":"How Railways Built the Modern World","paragraphs":["Railways did not just move people faster. They changed how the whole world worked, and you can still see their fingerprints almost everywhere you look.","They shaped cities. Before railways, most people lived within walking distance of their work. Trains let cities spread out into suburbs, with workers commuting in each morning and home each evening, as we saw with London's Metropolitan Railway. Whole towns, such as Crewe and Swindon in England, grew up around railway workshops. In North America, towns were founded along new lines, and places the railway passed by often shrank. Grand stations like London's St Pancras, New York's Grand Central and Mumbai's Chhatrapati Shivaji Maharaj Terminus became the cathedrals of a new age.","They changed time itself. As we discovered in Part 13, before railways each town kept its own local Sun time. Railways needed one shared time to run safely and keep timetables, so they created railway time in Britain and standard time zones in North America in 1883. Governments followed later. Every time you check the time on a phone and it matches everyone else's, you are using an idea that trains made necessary.","They transformed trade and food. Coal, iron, grain, cattle, timber and factory goods could cross whole continents cheaply. Fresh milk, fish and fruit reached cities before they spoiled, and refrigerated wagons carried meat across America. Newspapers and letters travelled overnight. Prices for many goods fell, and farmers and factories could sell to far-away customers.","They invented holidays and day trips for ordinary people. Thomas Cook's first excursion on 5 July 1841 carried about 500 people from Leicester to Loughborough, and soon seaside resorts like Blackpool and Brighton were packed with families who arrived by train. Travel, once a luxury for the rich, became something working families could enjoy.","They created big business. A railway needed far more money than any one person had, so companies sold shares to thousands of investors, which helped shape modern stock markets. Running a railway also required timetables, accounts, standard parts, uniforms, rules and managers in charge of huge numbers of workers. Many ideas about how large organisations are run were first worked out by railway companies.","And they inspired other inventions. The electric telegraph grew up alongside the tracks, sending signals and time checks down the line. Railway engineering pushed forward iron and steel bridges, tunnelling, air brakes, electric motors and safety systems. Even painters, songwriters and storytellers were inspired, from J. M. W. Turner's painting Rain, Steam and Speed to countless train songs and the adventures of Thomas the Tank Engine."]},{"heading":"Remembering the Costs Honestly","paragraphs":["A good historian tells the whole story, not just the exciting parts. Railways brought enormous benefits, but they also came at a real cost, and many of the people who paid it were not the ones who grew rich.","Think first of the workers. In Britain, gangs of labourers called navvies dug the cuttings and tunnels by hand, with picks, shovels, gunpowder and wheelbarrows, often living in rough camps. On America's first transcontinental railroad, thousands of Chinese immigrants did most of the dangerous work for the Central Pacific, blasting tunnels through the granite of the Sierra Nevada in deep snow, and they were paid less than white workers. Irish immigrants and former soldiers laid track for the Union Pacific. Similar stories were repeated in Canada, Russia, Africa and Asia. Many workers died from explosions, rockfalls, cold and disease. Because records were incomplete, nobody knows exactly how many, but it was certainly hundreds or more on some lines.","Think of the peoples whose lands the railways crossed. In North America, the railroads brought settlers, soldiers and hunters deep into the homelands of Native American nations. Treaties were broken, land was taken, and the vast bison herds that many Plains nations depended on were slaughtered until they almost disappeared. In India, the first railways were planned mainly to serve the interests of the British colonial rulers, carrying raw materials to ports and troops where they were needed, although Indians later made the railways part of their own national life.","Think of the accidents. Boilers exploded, bridges collapsed, and trains collided. The Tay Bridge disaster of 1879 and the Armagh crash of 1889 were terrible tragedies. But each disaster taught a hard lesson, and engineers and lawmakers responded with better bridges, continuous automatic brakes, interlocking signals, the block system and, today, computer train protection. The result is one of the great safety stories of modern times: per kilometre travelled, a passenger today is much safer on a train than in a car.","Think, too, of pollution. Steam locomotives filled cities and tunnels with smoke and soot, and burning coal released carbon dioxide that is still warming the planet. And when cars and lorries took over in the twentieth century, closures such as Britain's Beeching cuts left many towns without the railway they had relied on. Remembering all of this honestly does not mean railways were bad. It means that every great invention has winners and losers, and that the choices people make about how to build and use it really matter."]},{"heading":"Railways Today: Bigger Than Ever","paragraphs":["You might think trains belong in history books. In fact, railways today are busier than at almost any time in their history. The world has well over a million kilometres of railway lines, enough to wrap around the Earth more than 30 times. The United States has the largest network, more than 200,000 km, most of it carrying freight. China comes next, followed by Russia and India.","Some numbers are almost too big to imagine. In the year 2023 to 2024, Indian Railways carried about 6.9 billion passengers, close to one journey for every person on Earth, and moved about 1.6 billion tonnes of freight. It employs more than 1.2 million people, making it one of the largest employers in the world. In Tokyo, Shinjuku Station is listed by Guinness World Records as the busiest railway station on the planet; in 2018 an average of about 3.6 million people passed through it every day, using dozens of platforms and well over 200 exits.","Freight trains are giants too. In North America, ordinary freight trains often stretch more than a kilometre and a half, and some intermodal trains, carrying shipping containers stacked two high, are over 5 km long. In Australia's Pilbara region, iron ore trains about 2.8 km long carry ore from desert mines to the coast day and night. Because one crew and a few locomotives can move thousands of tonnes, trains are one of the cheapest and lowest-carbon ways to move heavy goods over land.","High-speed rail keeps growing. China alone has built more high-speed railway than the rest of the world put together, while Europe, Japan, South Korea, Morocco, Saudi Arabia and Indonesia all run trains at 300 km/h or close to it. Many cities are building new metros and tram lines, and countries hoping to cut carbon emissions are electrifying old routes and encouraging people to take the train instead of short flights. Rail still carries only about 8 percent of the world's passenger and freight transport, so there is plenty of room to grow.","Even old ideas are coming back. Sleeper trains, where passengers go to bed in one city and wake up in another, had been disappearing across Europe as cheap flights spread. Then, from December 2016, the Austrian railway company ÖBB began building up its Nightjet network, and new night trains now link cities such as Vienna, Munich, Zurich, Hamburg, Rome and Venice. Many travellers choose them because a night on a train produces far less carbon dioxide than a flight and saves the cost of a hotel. In a way, it is a return to the great sleeping cars of George Pullman's day, only quieter, cleaner and powered by electricity."]},{"heading":"Keepers of the Flame: Heritage Railways","paragraphs":["Even though mainline steam ended in many countries by the 1960s, steam engines have not disappeared. All over the world, volunteers keep old railways running so that people can still hear the chuff of the blastpipe and smell the coal smoke.","The very first railway saved by volunteers was the Talyllyn Railway in Wales, a little narrow-gauge line only 2 ft 3 in (686 mm) wide, which runs about 11.7 km from Tywyn on the coast into the mountains. It opened to passengers in 1866 to carry slate and people. By 1950 it was worn out and about to close, so a group led by the author Tom Rolt formed a society, and in 1951 volunteers took it over. It became the first railway in the world preserved by volunteers. Two of its original locomotives, Talyllyn and Dolgoch, are still steaming, though many of their parts have been replaced over the years. One of the volunteers was the Reverend W. Awdry, who based the Skarloey Railway in his Railway Series books, the stories that gave us Thomas the Tank Engine, on the Talyllyn.","Today Britain alone has well over a hundred heritage railways, and there are many more around the world, from the Durango and Silverton in Colorado to steam lines in Germany, India and Australia. The Middleton Railway in Leeds, where Salamanca began work in 1812, still runs trains. Museums preserve the stars of our story: Puffing Billy and Rocket in Britain's national collections, Mallard in the National Railway Museum collection, and the 1804 Penydarren engine remembered in a working replica.","Some fans have gone even further and built brand-new steam locomotives. The A1 Steam Locomotive Trust spent from 1994 to 2008 and about 3 million pounds, raised largely from supporters, building Tornado, a new express engine based on an old design that had been entirely scrapped. It was the first new steam locomotive built for Britain's main line since 1960, and on 12 April 2017 it reached 100 mph on the East Coast Main Line. These volunteers prove that the railway is not just a machine. It is something people love."]},{"heading":"A Railway Record Book","paragraphs":["Before we reach the final platform, here is a record book to keep, gathering some of the most remarkable numbers from our whole journey. Each one stands for real people who planned, built, drove or rode the trains.","The oldest surviving railway bridge is the Tanfield Arch in County Durham, built in 1725 to 1727 for horse-drawn coal wagons, about a century before the first public steam railway. The oldest surviving steam locomotive is Puffing Billy, built at Wylam Colliery around 1813 to 1814 and now kept at the Science Museum in London. The first known regular fare-paying passenger railway service began on the Swansea and Mumbles Railway in 1807, with horses doing the pulling.","The longest railway line in the world is the Trans-Siberian, about 9,289 km from Moscow to Vladivostok, covering a seven-hour difference in clock time; riding the whole way takes about a week. The longest railway tunnel is the Gotthard Base Tunnel under the Swiss Alps, about 57 km long, opened in 2016. The longest bridge of any kind is a railway viaduct: the Danyang to Kunshan Grand Bridge on China's Beijing to Shanghai high-speed line, about 164 km long, completed in 2010 and opened in 2011. And the highest railway in the world, the Qinghai to Tibet line, climbs to about 5,072 metres at the Tanggula Pass, so high that carriages carry extra oxygen for passengers.","For speed, the fastest steam locomotive is still Mallard, at 126 mph (203 km/h) on 3 July 1938. The fastest wheel-on-rail train is the French TGV that reached 574.8 km/h on 3 April 2007. The fastest train of any kind is Japan's L0 Series SCMaglev at 603 km/h on 21 April 2015. Just as impressive in a different way, the Shinkansen has carried billions of passengers since 1964 without a single passenger death from a derailment or collision in normal service.","For size and busyness, one of the heaviest trains ever run was BHP's 682-wagon iron ore train of 2001, nearly 100,000 tonnes. The busiest station is Shinjuku in Tokyo. The biggest high-speed network, by far, is China's. And the oldest railway still in use is hard to name exactly, because so many lines have been rebuilt, but the Middleton Railway in Leeds claims to be the oldest continuously working railway in the world, running since 1758 under a law passed by Parliament.","Records are fun, but notice what they really show. Almost every one was beaten by someone building on the work of others: Rocket on Puffing Billy, the Shinkansen on a century of electric trains, the TGV and SCMaglev on the Shinkansen. No great invention is the work of one genius alone."]},{"heading":"Your Turn: The Railways of 2100","paragraphs":["Now it is your turn to be the engineer. Remember how each great step in this story began: with someone looking at a problem and thinking, 'There must be a better way.' Huntingdon Beaumont wanted to move coal more cheaply. Trevithick wanted an engine strong enough to replace horses. The Stephensons wanted one reliable enough to run a railway. Westinghouse wanted to stop trains crashing. Hideo Shima wanted trains fast enough to change a whole country.","So what problems will the railways of 2100 need to solve? Here are a few to think about. How could trains run on 100 percent clean energy, even on remote lines with no wires? How could we build new lines without spending enormous sums, digging up homes or harming rivers, as the Chūō Shinkansen's long arguments showed? How could a train make a long journey feel as quick and comfortable as a short one, with room to sleep, work or play? How could freight move from ship to train to doorstep without a single lorry? How could trains stay safe in a world of stronger storms, floods and heatwaves that bend rails? And how could railways reach the places that still have none?","Try sketching your answer. You might design a solar-powered sleeper train, an automatic freight pod that drives itself the last mile, a station that is also a park, or something nobody has thought of yet. Write down how it works, what it would cost, who would use it and what could go wrong. Every real inventor in these 20 parts had to answer those same questions, and many of them got it wrong several times before they got it right.","The railway began with a simple wish: to make a heavy load easier to move. That wish turned wooden planks into iron rails, rails into a worldwide network, and a crawling 5 mph puffer into a floating train at 603 km/h. Somewhere, right now, the next great journey is waiting to be invented, and the person who invents it might be the one reading these words."]}],"deepDive":"Why has the railway lasted 400 years when so many technologies vanished? Physics is a big part of the answer. The rolling resistance coefficient of a steel wheel on a steel rail is typically about 0.001 to 0.002, meaning a force of only about 1 to 2 kilonewtons keeps a 100-tonne load rolling on level track; for a car tyre on asphalt the figure is roughly 0.01 or more, five to ten times higher. Trains also benefit from running in a line: each vehicle shelters in the slipstream of the one ahead, so a long train has far less air drag per tonne than the same goods spread across many lorries. Gentle gradients matter just as much; climbing a 1 percent slope adds a force equal to 1 percent of the train's weight, many times its rolling resistance, which is why railway builders spent fortunes on cuttings, embankments and tunnels. Historians debate how much railways actually mattered to economic growth. In a famous 1964 study, the economist Robert Fogel argued that if the United States had relied on canals and wagons instead, its national income in 1890 would have been only a few percent lower; he later shared a Nobel Prize in economics in part for such work. Other historians reply that railways' biggest effects, on standard time, large corporations, national markets, finance and the opening of the interior, cannot be captured by such a calculation. Similar arguments surround railways and empire: in India, scholars have shown that railways cut famine deaths by moving grain and lowering price differences between regions, while also serving colonial power and drawing wealth out of the country. Today's debates are about the future. Supporters of high-speed rail point to lower carbon emissions per passenger and the ability to replace short flights; critics point to enormous construction costs and say buses, better local services or electrifying existing lines may give more benefit per pound or dollar. Statistics also show why railways are trusted: in Europe, passenger rail has a fatality rate per passenger-kilometre many times lower than cars. The railway's long life suggests a lesson for inventors: technologies that rest on deep physical advantages, and that can keep absorbing new ideas such as steam, electricity, diesel, computers and magnets, can stay useful for centuries.","funFact":"On 21 June 2001 the mining company BHP ran a single iron ore train in Western Australia that was about 7.35 km long, with 682 wagons and eight locomotives, and it was driven by just one person.","check":{"q":"Where did the standard gauge of 4 ft 8½ in (1,435 mm) really come from?","a":"The colliery wagonways of north-east England that George Stephenson used","wrong":["The width of Roman chariots","The width of the Shinkansen trains in Japan","A law passed by the United States in 1918"]},"sources":[{"title":"Standard-gauge railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Standard-gauge_railway"},{"title":"List of countries by rail transport network size","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/List_of_countries_by_rail_transport_network_size"},{"title":"Indian Railways","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Indian_Railways"},{"title":"Shinjuku Station","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shinjuku_Station"},{"title":"Longest trains","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Longest_trains"},{"title":"Talyllyn Railway","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Talyllyn_Railway"},{"title":"LNER Peppercorn Class A1 60163 Tornado","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/LNER_Peppercorn_Class_A1_60163_Tornado"},{"title":"Rail transport","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rail_transport"}],"photos":[{"src":"img/deep/railways/20-1.jpg","alt":"Talyllyn Railway's Dolgoch, one of the oldest working steam locomotives, being prepared at Tywyn Wharf in Wales.","file":"Talyllyn Railway No. 2 \"Dolgoch\" - August 2012 - 02.jpg","url":"https://commons.wikimedia.org/wiki/File:Talyllyn_Railway_No._2_%22Dolgoch%22_-_August_2012_-_02.jpg","author":"Nigel Hoult","license":"CC BY 2.0"},{"src":"img/deep/railways/20-2.jpg","alt":"The brand-new steam locomotive 60163 Tornado hauling a main-line charter train near Flax Bourton, England.","file":"Flax Bourton railway station MMB 31 Tornado 60163.jpg","url":"https://commons.wikimedia.org/wiki/File:Flax_Bourton_railway_station_MMB_31_Tornado_60163.jpg","author":"mattbuck (category)","license":"CC BY-SA 3.0"},{"src":"img/deep/railways/20-3.jpg","alt":"A 2.6-kilometre-long Fortescue iron ore train crossing the Turner River in the Pilbara, Western Australia.","file":"FMG Iron Ore Train -2008.JPG","url":"https://commons.wikimedia.org/wiki/File:FMG_Iron_Ore_Train_-2008.JPG","author":"Geez-oz","license":"CC BY-SA 3.0"}],"words":3855}],"words":81158};
